INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'У име Аллаха, Милостивог, Самилосног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, 'Сва хвала припада Аллаху, Господару свих светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Милостивом, Самилосном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'Владару Судњега дана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'Само Тебе обожавамо и само од Тебе помоћ тражимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Упути нас на прави пут;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'На пут оних којима си благодати Своје даровао, а не на пут оних на које си се расрдио, нити оних који су залутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Елиф Лам Мим [1]', '[1] Ова самостална слова на почетку овог поглавља упућују на чудесну природу Кур''ана. Незнанобошци су били изазвани да напишу нешто слично Кур''ану, па нису могли да му се супротставе, иако је Кур''ан састављен од ових слова која сачињавају арапски језик. Неспособност Арапа да смисле било шта слично њему – иако су себе сматрали најречитијим народом – указује на то да је Кур’ан Божија објава.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Ова Књига - у коју нема сумње - упута је богобојазнима', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'онима који у невидљиви свет верују и који молитву обављају и удељују од онога чиме смо их Ми опскрбили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'и онима који верују у оно што је објављено теби и што је објављено пре тебе, и који у Будући свет чврсто верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Њима је Господар њихов на прави пут указао и то су они који су успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Онима који не верују заиста је свеједно упозоравао ти њих или не упозоравао, они неће да верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Аллах је запечатио срца њихова и уши њихове, а пред очима њиховим је застор; њих чека патња огромна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'Има људи који говоре: "Верујемо у Аллаха и Последњи дан", а они нису верници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'Они мисле да варају Аллаха и оне који верују, а никог осим себе они не варају, али то не осећају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'У њиховим срцима је болест и Аллах им повећава ту болест. Њих чека болна патња због тога што су лагали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Када им се каже: "Не правите неред на Земљи!" Одговарају: "Ми само ред успостављамо!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Напротив! Они су уистину прави смутљивци, али то не опажају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Када им се каже: "Верујте као што ови људи верују!" Они одговарају: "Зар да верујемо као што малоумници верују!?" А заиста они су малоумници, али они то не знају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'Када сусретну оне који верују, говоре: "Верујемо!" А чим остану насамо, са сотонама својим, говоре: "Ми смо с вама. Ми им се само изругавамо."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, 'Аллах се њима изругава и оставља их да у својој арогантности лутају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'То су они који су заблуду узели уместо Упуте, али им њихова трговина неће донети добити, јер они Упуту нису следили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Они су слични ономе који потпали ватру, а када она осветли оно што је око њега, Аллах им одузме светло и остави их у тминама, па ништа не виде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, 'Они су глуви, неми и слепи, па не могу да се поврате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Или су слични онима који за време силног пљуска са неба, услед мрака, грмљавине и муња, због громова затискују уши прстима бојећи се смрти. А Аллах обухвата невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Муња само што их не заслепи: кад год им осветли - они крену, а чим их тами препусти - застану! А да Аллах хоће, Он би им одузео и слух и вид. Аллах, уистину, све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'О људи, обожавајте Господара свог, Који је створио вас и оне пре вас, да бисте се сачували.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, 'Који вам је Земљу постељом, а небо здањем учинио; Који с неба спушта воду и с њом изводи плодове, опскрбу вашу. Зато не приписујте Аллаху друга божанства, а знате то.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'А ако сумњате у оно што смо Ми објавили Нашем слуги Мухаммеду, саставите ви једно поглавље слично томе и позовите и божанства ваша, изузев Аллаха, ако истину говорите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Па ако то не учините, а сигурно нећете учинити, онда се чувајте ватре чије ће гориво бити људи и камење; која је припремљена за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'А обрадуј оне који верују и добра дела чине да њима припадају рајске баште кроз које реке теку! Кад год буду опскрбљени каквим плодом, рећи ће: "Овим смо и пре били опскрбљени!" А биће им давани плодови само њима слични! У њима ће они супруге очишћене имати и у њима ће вечно боравити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Заиста се Аллах не устручава да за пример наведе комарца или нешто изнад њега; они који верују - па они знају да је то Истина од Господара њиховог; а они који не верују говоре: "Шта то Аллах хоће овим примером?" Тиме Он даје да многи у заблуду скрену, а многе на Прави пут упућује, а тиме на странпутицу скреће само развратнике;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, 'Оне који крше обавезу према Аллаху након што је прихваћена и прекидају оно што је Аллах наредио да се одржава и неред на Земљи праве; то су прави губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Како не верујете у Аллаха, ви који сте били мртви па вас је Он оживео, затим ће вас усмртити, затим поново оживети, потом ћете Њему бити враћени?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'Он вам је све на Земљи створио, затим се на небо усмерио, и као седам небеса га уредио; Он све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'А када Господар твој рече анђелима: "Ја ћу на Земљи намесника поставити!" Они упиташе: "Зар ћеш на Земљи поставити онога који ће на њој неред ширити и крв пролевати?! А ми Тебе славимо захваљујући Ти и светост Теби призивамо." Он рече: "Ја, заиста, знам оно што ви не знате."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'И Он поучи Адама свим називима, а онда их предочи анђелима и рече: "Кажите Ми имена њихова, ако истину говорите!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, '"Узвишен си Ти!" Рекоше они, "ми знамо само оно чему си нас Ти поучио! Засигурно си Ти Свезнајући и Мудри."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, '"О Адаме", рече Он, "саопшти им називе њихове!" И када им он саопшти називе њихове, Аллах рече: "Зар вам нисам рекао да само Ја знам тајне небеса и Земље и да само Ја знам оно што показујете и што кријете?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'А кад рекосмо анђелима: "Поклоните се Адаму! Они се поклонише сви изузев Сотоне." Он одби и узохоли се, а био је неверник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'И Ми рекосмо: "О Адаме, настаните се ти и супруга твоја у Рају и једите у њему где год желите, али се овоме дрвету не приближавајте да не постанете неправедни."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Али, Сотона их наведе на грех због дрвета и изведе их из Раја у којем су били. Ми рекосмо: „Сиђите!, једни другима ћете бити непријатељи. До одређеног времена на Земљи је ваше боравиште и неко време уживања."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'И Адам прими неке речи од Господара свога, па му Он опрости; Он је, заиста, Онај Који стално прима покајања, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Ми рекосмо: "Силазите из њега сви! Од Мене ће вам Упута долазити, а они који Упуту Моју буду следили, ничега се неће бојати, нити ће за било чим туговати."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'А они који не буду веровали и доказе и речи Наше буду порицали биће становници Ватре; у њој ће вечно остати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'О синови Израиљеви, сетите се благодати Мојих које сам вам подарио, и испуните завет који сте Ми дали, па ћу и Ја испунити Свој завет који сам вам дао! И само од Мене страхујте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'И верујте у оно што сам објавио потврђујући да је истинито оно што ви имате и не будите први који у то не верују! Не продајте речи Моје за нешто што сасвим мало вреди и само се Мене бојте!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'И не мешајте Истину са неистином, и не скривајте Истину кад је знате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'Молитву обављајте, и обавезну милостињу дајте и заједно са онима који молитву обављају и ви обављајте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'Зар од других тражите да добро чине док при томе себе заборављате, а ви Књигу читате? Зар се опаметити нећете!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Помозите се стрпљењем и молитвом, а то је, заиста, тешко, осим понизнима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, 'онима који су уверени да ће се срести са Господаром својим и да ће се Њему вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'О синови Израиљеви! Сетите се благодати Мојих које сам вам подарио и то што сам вас над другим народима био одликовао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'И бојте се Судњег Дана када нико ни за кога ништа неће моћи да учини, и када ничије посредовање неће да се прихвати, и када ни од кога откуп неће да се прими и када нико никоме у помоћ неће да притекне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, 'И када смо вас избавили од фараонових људи који су вас најгорим мукама мучили: мушку вам децу клали, а женску у животу остављали - то је било велико искушење од Господара вашег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'И када смо због вас море раставили па вас спасили, а фараонове људе, пред вашим очима потопили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'И када смо са Мојсијем, четрдесет ноћи, сусрет одредили, ви сте, након што вас је напустио, неправду чинећи, теле почели да обожавате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Потом смо вам, и после тога, опростили, да бисте захвални били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, 'И када смо дали Мојсију Књигу и оно што раздваја Истину од неистине, да бисте се правим путем упутили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'И када је Мојсије свом народу рекао: „Народе мој, ви сте заиста себи неправду учинили узевши теле; зато се Створитељу своме покајте и између вас преступнике смрћу казните! То вам је код вашег Створитеља боље, па ће покајање да вам прихвати. Заиста Он стално прима покајања, Милостиви.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'И када сте ви казали: "Мојсије, ми ти нећемо веровати све док Аллаха јасно не видимо!" Па вас је, док сте гледали, страшна казна обузела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Затим смо вас после смрти ваше оживели, да бисте захвални били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'И од облака смо вам хладовину начинили и ману и препелице вам слали. "Једите лепа јела, којима вас опскрбљујемо!" Они Нама нису неправду нанели, него су сами себи неправду чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'И када смо казали: "Уђите у овај град и једите што год хоћете! На капију уђите клањајући се и кажите: ''Опрости!'' Па ћемо вам опростити грехе ваше, а онима који чине добра дела даћемо и више."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Онда су они који су неправду учинили заменили речи другим које им нису речене, па смо Ми на оне који су неправду учинили с неба казну спустили, зато што су грешници били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'И када је Мојсије за народ свој молио воду, Ми смо рекли: „Удари својим штапом по камену!“ Из њега је проврело дванаест извора, и сви људи су знали из којег ће извора да пију. „Једите и пијте из Аллахове опскрбе и не чините зло по Земљи правећи неред.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'И када сте рекли: „Мојсије, ми не можемо више једну исту храну да једемо. Зато, моли за нас Господара свог да нам подари од онога што Земља рађа: од поврћа и краставаца, пшенице, сочива и црвеног лука!“ Он је рекао: „Зар да оно што је боље замените оним што је лошије?! Идите у Мисир имаћете оно што тражите!“ И понижење и беда их је снашла и на себе навукоше гнев Аллахов, зато што у Аллахове доказе нису веровали и зато што су посланике бесправно убијали, зато што су непослушни били и све границе зла прелазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Оне који верују, и оне који су били јевреји, хришћани и сабејци, а који су веровали у Аллаха и Судњи дан и добра дела чинили - заиста чека награда код њиховог Господара; за њих нема страха и они неће да тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, 'И када смо од вас завет узели и брдо Синај изнад вас подигли: „Снажно прихватите оно што смо вам дали и нека вам је на уму оно што је у Књизи, да бисте се сачували.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Затим сте одустали, и да није било Аллахове дарежљивости према вама и милости Његове, ви бисте, уистину, међу губитницима били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Вама је познато шта се догодило онима од вас који су суботу оскрнавили, па смо им Ми казали: "Будите мајмуни презрени!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'То насеље смо учинили опоменом оближњим насељима, а поуком за богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'И када Мојсије рече народу своме: "Аллах вам, заиста, наређује да краву закољете", они упиташе: "Збијаш ли то ти с нама шалу?" А он рече: "Аллаху се утичем од тога да незналица будем!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, 'Они рекоше: „Замоли за нас Господара свог да нам појасни каква треба да буде!“ „Он каже“, одговори он, „да крава не сме да буде ни стара, ни млада, него између тога, средње доби, па учините то што вам је заповеђено!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, '„Замоли за нас Господара свог“, рекоше они, „да нам објасни какве боје треба да буде!“ „Он каже“, рече он, „да треба да буде светложуте боје, да се свиди онима који је виде.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, '"Замоли за нас Господара свога", рекоше они, "да нам објасни каква још треба бити, јер нама краве изгледају сличне, а ми ћемо њу, ако Аллах да, сигурно да пронађемо."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, '"Он каже", рече он, "да крава не сме бити исцрпљена орањем земље и натапањем усева; треба бити без икакве мане и белега." "Е, сад си казао истину!" Рекоше они, па је заклаше, и једва то учинише.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'И када сте једног човека убили, па се о њему препирати почели, Аллах је дао да изађе на видело оно што сте били сакрили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, 'Па смо Ми рекли: "Ударите га једним њеним делом!" И ето, тако Аллах мртве враћа у живот и пружа вам доказе Своје, да бисте схватили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'Али су ваша срца, после тога, постала тврда као камена стена или још тврђа. А има стена из којих реке избијају; а има, заиста, стена које пуцају и из којих излази вода, а има их заиста, и које се од страха пред Аллахом руше. А Аллах не занемарује оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Зар се надате да ће они (Јевреји) да вам поверују, а неки од њих су Аллахов говор слушали, а затим би га, након што су га схватили, свесно изврнули?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Када сретну оне који верују, говоре: "Ми верујемо!" А чим се осаме једни с другима, кажу: "Зар ћете им казивати оно што је Аллах вама објавио, па да им то буде доказ против вас пред Господаром вашим? Зар се нећете опаметити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'А зар они не знају да Аллах зна и оно што крију и оно што показују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'Неки од њих су неписмени и не познају Књигу, него само гаталице. Они само нагађају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'А тешко онима који својим рукама пишу књигу, а затим говоре: „Ово је од Аллаха“, да би за то извукли ништавну корист. И тешко њима због онога што њихове руке пишу, и тешко њима што на тај начин зарађују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, 'Они говоре: "Горећемо у ватри само неколико дана." "Реци: "Да ли сте за то од Аллаха добили обећање, јер Аллах неће прекршити Своје обећање, или Аллаху приписујете оно што не знате?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, 'Напротив! Они који буду зло чинили и греси их њихови буду са свих страна сустигли, становници Ватре ће они да буду и у њој ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'А они који буду веровали и добра дела чинили, они ће становници Раја бити; у њему ће вечно боравити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'И када смо од потомака Израиљевих узели завет да ћете једино Аллаха да обожавате, и родитељима, и ближњима, и сирочадима, и сиромасима доброчинство да чините, а људима лепе речи да говорите; и молитву да обављате и обавезну милостињу да дајете, ви сте се затим, изузев мало вас, окрећући завет изневерили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'И када смо од вас завет узели да крв једни другима нећете пролевати и да једни друге из домова ваших нећете изгонити, ви сте то прихватили и то посведочили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Након тога, ви ипак једни друге убијате, а поједине од вас и из завичаја њихових протерујете, помажући се против њих, уз грех и насиље, а ако вам дођу као заробљеници, ви их откупљујете. А забрањено вам је да их изгоните! Зар ви у један део Књиге верујете, а други негирате?! Онога од вас који тако ради стићи ће на овоме свету понижење, а на Судњем дану биће стављен на најтеже муке. А Аллах, заиста, није немаран према ономе што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'То су они који су живот на овоме пролазном свету заменили за Будући свет; зато им патња олакшана неће бити, нити ће им се у помоћ притећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'И Ми смо Мојсију Књигу дали и после њега, једног за другим, посланике слали. И Исусу, сину Маријином, јасне смо доказе дали и Духом Благословљеним (анђелом Гаврилом) смо га помогли. И кад год вам је који посланик донео оно што није годило душама вашим, ви сте се узохолили, па сте неке у лаж угонили, а неке убијали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, 'Они говоре: "Наша срца су обложена!" А није тако, него је Аллах њих проклео због неверовања њиховог, а мало је њих који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'И када им је дошла Књига од Аллаха која потврђује истинитост онога што они имају, а још од пре су помоћ против неверника молили, и када им је дошло оно што им је познато као истина, они у то не повероваше. Па нека Аллахово проклетство стигне невернике!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'Јадно је то за шта су се продали, да негирају оно што Аллах објављује, само из злобе што Аллах, из доброте Своје шаље Објаву ономе коме Он хоће од слугу Својих; па су на себе гнев за гневом навлачили! А невернике чека патња понижавајућа!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'А када им се каже: "Верујте у оно што Аллах објављује!" Они одговарају: "Ми верујемо само у оно што је нама објављено", и неће да верују у оно што се објављује после, а то је Истина, која потврђује да је истинито и оно што они имају. Реци: "Па зашто сте још раније Аллахове веровеснике убијали, ако сте верници били?!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'И Мојсије вам је јасне доказе био донео, па сте, ипак, након што вас је оставио, неправду чинећи, теле за обожавање прихватили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'И када смо од вас Завет ваш примили и брдо изнад вас подигли: „Чврсто прихватите оно што вам дајемо и слушајте!“, они су одговорили: „Чујемо, али нећемо да послушамо!“, јер су њихова срца, због неверовања, теле присвојила. Реци: „Ружно је то на шта вас ваше веровање наводи, ако сте уопште верници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'Реци: "Ако је код Аллаха Рај осигуран само за вас, мимо осталог света, онда смрт пожелите, ако истину говорите?!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'А неће је они никада пожелети због онога што чине, а Аллах добро зна неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'И видећеш сигурно да више жуде за животом од других људи, па чак и од идолопоклоника; сваки од њих би волео да поживи хиљаду година, мада га то, и када би толико дуго живео, не би од казне удаљило. Аллах добро види оно што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'Реци: "Онај ко је непријатељ анђелу Гаврилу, нека зна да он Аллаховом дозволом теби на срце ставља Кур'' ан потврдујући истинитост онога од пре, као путоказ и радосну вест верницима."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Ко је непријатељ Аллаху, Његовим анђелима и Његовим посланицима и анђелу Гаврилу и анђелу Михаилу - па, Аллах је, заиста, непријатељ онима који не верују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'А Ми теби јасне доказе објављујемо, у које једино тешки грешници неће да верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Зар сваки пут када неку обавезу преузму, део њих је одбаци?! Напротив, већина их не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, 'А када им је од Аллаха Посланик дошао, потврђујући да је истинито оно што већ имају, део оних којима је Књига дата Аллахову Књигу одбацују, као да не знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'И поведоше се за оним што су ђаволи о Соломуновој владавини лажно казивали. А Соломун није био неверник, него су ђаволи неверници. Они уче људе враџбини и ономе што је било надахнуто двојици анђела Харуту и Маруту, у Вавилону. А њих двојица никога нису учили док му не би казали: „Ми само искушавамо, па ти не буди неверник!“ И људи су од њих двојице учили како ће мужа од жене да раставе, али они нису могли никоме без Божје дозволе да науде. Учили су оно што ће да им наштети и од чега користи неће имати, иако су знали да онај ко то себи у замену за веровање купи, на Будућем свету никаквог удела неће имати. А заиста је јадно оно за шта су се продали, када би само они то знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'А да су они веровали и чували се забрањеног, па сигурно награда од Аллаха боља је - само да су то они знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'О ви који верујете, не говорите: "Ра''ина!" Него реците "Унзурна (Погледај нас, обрати пажњу на нас)!" И слушајте. А невернике чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Не воле они који не верују међу следбеницима Књиге а ни идолопоклоници, да се вама од Господара вашег било какво добро објави. Аллах Својом милошћу одликује кога хоће, и Аллах је поседник доброте величанствене.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Који год кур''ански одломак заменимо, или га забораву препустимо, Ми бољи од њега или сличан њему донесемо. Зар ти не знаш да Аллах све може?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Зар ти не знаш да небеско и земаљско царство припада Аллаху и да, осим Аллаха, ни заштитника ни помагача немате?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Зар да тражите од свог посланика, као што су пре од Мојсија тражили?! А ко веровање замени неверовањем, тај је с Правог пута залутао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Многи следбеници Књиге би волели, из своје личне злобе, да вас, након вашег веровања, у невернике врате, након што им је Истина постала јасна. Али, ви опростите и преко тога пређите, док Аллах Своју одлуку не донесе. Аллах, заиста, над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'И молитву обављајте и обавезну милостињу дајте, а за добро које за себе припремите наћи ћете награду код Аллаха, јер Аллах добро види оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, 'Они говоре: "У Рај неће ући нико осим онај ко буде Јевреј или хришћанин!" То су пусте жеље њихове. Реци: "Дајте свој доказ, ако истину говорите!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, 'А није тако! Ономе ко се буде Аллаху предао и уз то добра дела чинио, припада награда код Господара његовог; такви се неће ничега бојати, нити ће за било чим туговати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'Јевреји говоре: „Хришћани нису на правом путу!“, а хришћани кажу: „Јевреји нису на правом путу!“, а они читају Књигу. Тако готово истим речима говоре они који не знају. Аллах ће на Судњем дану да им пресуди у ономе о чему су се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Има ли већег неправедника од онога који брани да се у Аллаховим џамијама име Његово спомиње и који ради на томе да се оне опустоше?! Такви би требало да у њих само са страхом улазе. Они ће на овоме свету понижење доживети, а на другом свету их чека казна велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'Аллаху припадају и исток и запад; куда год се окренете, тамо је Аллахово лице. Аллах је, заиста, неизмерно дарежљив и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, 'Неверници говоре: "Аллах је себи дете узео." Узвишен нека је Он! Напротив, Њему припада све што је на небесима и на Земљи и Њему се све покорава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, 'Он је Створитељ небеса и Земље, а када нешто одреди, Он само каже: "Буди!" - И то бива.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'А они који не знају, говоре: "Требало би да Аллах с нама разговара, или да нам какав доказ дође!" Тако су готово истим речима говорили и они пре њих; срца су им слична! А Ми доказе објашњавамо људима који чврсто верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Ми смо те (Мухаммеде), заиста, послали са Истином, као доносиоца радосних вести и онога који опомиње, и ти нећеш да будеш питан за оне који ће бити у Паклу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Ни Јевреји, ни хришћани неће бити тобом задовољни све док не будеш следио њихову веру. Реци: "Аллахова Упута је Права упута!" А ако би се ти повео за жељама њиховим, након знања које си добио, од Аллаха те нико не би могао заштитити, нити ти помоћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Они којима смо објавили Књигу, па је читају онако како треба, то су они који у њу верују. А они који у њу не буду веровали, то су сигурни губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'О синови Израиљеви, сетите се благодати Мојих које сам вам даровао, и када сам вас над осталим народима одликовао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'И бојте се Дана када нико ни за кога ништа неће моћи учинити, када се ни од кога откуп неће примати, када се ничији заговор неће користити, и када никоме нико неће у помоћ притећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'И када је Аврама његов Господар са неколико заповеди на искушење ставио, па их је он потпуно извршио, Аллах је рекао: „Учинићу да ти будеш људима вођа.“ Он је упитао: „А и неки из мог потомства?“ Одговорио му је: „Обећање Моје не обухвата неправеднике!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'И када Ми Кабу учинисмо уточиштем и сигурним местом за људе: „Нека вам место на којем је Аврам стајао буде простор где ћете молитву да обављате!“ И Авраму и Јишмаелу смо наредили: „Храм Мој очистите за оне који га буду обилазили, који буду ту боравили и молитву обављали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'А када је Аврам замолио: "Господару мој, учини ово место сигурним боравиштем и снабдиј плодовима становнике његове, оне између њих који буду у Аллаха и Последњи дан веровали!" Он је рекао: "Ономе који не буде веровао, даћу да неко време ужива, а онда ћу га присилити да у патњу ватрену уђе. А ужасно је то коначно одредиште!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'И док су Аврам и Јишмаил темеље Кабе подизали, молили су: "Господару наш, прими то од нас, Ти си, уистину, Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, 'Господару наш, учини нас двојицу муслиманима - Теби преданим, а и у потомству нашем нека буде заједница Теби предана, покажи нам обреде наше и опрости нам! Ти, заиста, стално примаш покајања, Милостиви!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'Господару наш, пошаљи међу њих посланика, једнога од њих, који ће им речи Твоје казивати, Књизи и мудрости их поучити и очистити их! Ти си, заиста, Силни и Мудри!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Ко други веру Аврамову избегава до онај који не држи до себе!? Ми смо њега на овоме свету одабрали, па ће он и на другом свету бити међу добрима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'Када је њему Господар његов рекао: "Предан буди!" Он је одговорио: "Ја сам предан Господару светова."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'И Аврам је, као и Јаков, то синовима својим заповедио: „Синови моји, Аллах вам је веру одабрао, и нипошто немојте да умрете другачије осим као муслимани .“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Зар сте били присутни када је Јакову смртни час дошао?! Кад је он синове своје упитао: „Кога ћете, након мене, да обожавате?" Одговорили су: „Обожаваћемо Бога твог, Бога твојих отаца Аврама, Јишмаела и Исака, Бога Јединог! И ми се само Њему предајемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Тај је народ прошао; њему припада оно што је заслужио, а вама што сте заслужили, и ви нећете бити питани за оно што су они радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, 'Они говоре: „Будите јевреји, односно хришћани, бићете на Правом путу!“ Ти реци: „Не, ми смо следбеници Аврама правоверника. Он није био идолопоклоник.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, 'Реците: "Ми верујемо у Аллаха и у оно што се објављује нама, и у оно што је објављено Авраму, и Јишмаилу, и Исаку, и Јакову, и потомцима," и у оно што је дато Мојсију и Исусу, и у оно што је дато веровесницима од Господара њиховог; ми не правимо никакве разлике међу њима и ми смо Њему предани."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Па, ако они буду веровали у оно у шта ви верујете, на Правом су путу; а ако се окрену, они су онда раскол починили. Аллах ће те сигурно од њих заштитити. Он је Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, '"Аллахове вере се држите! Зар има лепше вере од Аллахове?! Ми се само Њему покоравамо."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, 'Реци: "Зар с нама о Аллаху расправљате, а Он је и наш и ваш Господар! Нама припадају наша дела, а вама ваша дела! А ми смо према Њему искрени."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Како можете да говорите да су Аврам, Јишмаил, Исак, Јаков и потомци његови били јевреји или хришћани? Реци: "Знате ли боље ви или Аллах?" Зар је ико већи неправедник од онога који скрива сведочанство Истине добивене од Аллаха! А Аллах није немаран према ономе што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Тај је народ прошао; њему припада оно што је заслужио, а вама што сте заслужили, и ви нећете бити питани за оно што су они радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'Рећи ће неки људи кратке памети: „Шта их је одвратило од њиховог правца током молитве, према којем су се окретали?“ Реци: „Аллаху припадају и исток и запад; Он упућује на Прави пут онога кога Он хоће.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'И тако смо вас учинили умереном заједницом, како бисте сведочили о другим људима, и како би Посланик о вама сведочио. И Ми смо променили правац према којем си се током молитве окретао само да бисмо знали оне који следе Посланика у односу на оне који не верују, јер то је заиста било тешко свима, осим онима које је Аллах упутио на Прави пут. А Аллах неће да дозволи да пропадну ваше молитве. Аллах је, заиста, према људима милосрдан и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Ми видимо како окрећеш лице своје према небу и Ми ћемо сигурно да те окренемо према правцу који ти желиш; па, окрени лице своје према Часном храму! И где год били, лице своје окрените према њему. Заиста, они којима је дата Књига знају да је то истина од њиховог Господара. А Аллах није немаран према ономе шта они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, 'И када би ти онима којима је дата Књига све доказе донео, они опет неће да прихвате твој правац, као што ни ти нећеш да прихватиш њихов правац, нити ће ико од њих да прихвати правац другога. А ако би се ти за њиховим жељама повео након што ти је дошло знање, тада би сигурно међу неправедницима био.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Они којима смо дали Књигу препознају Посланика као што синове своје знају, али неки од њих, заиста, свесно истину прикривају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Истина је од Господара твога, па зато никако не буди од оних који сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'Свако има свој правац према којем се окреће, па се такмичите у добру! Ма где били, Аллах ће да вас све сабере. Аллах, заиста, над свиме има моћ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'И из свакога места у које дођеш, ти лице своје у правцу Часног храма окрени; то је, заиста, Истина од Господара твога; Аллах није немаран према ономе што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'И из сваког места у које дођеш, ти своје лице према Часном храму окрени!; И где год се налазили, ви своја лица према њему окрећите, да људи не би имали шта да вам приговоре, осим оних међу њима који су неправедни. Њих се не бојте, него се Мене бојте, да бих благодат Своју према вама употпунио и да бисте били на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'И тако смо вам Ми једнога од вас као посланика послали да вам Наше речи и доказе казује, и да вас очисти, и да вас Књизи и мудрости подучи, и да вас оно што нисте знали научи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Зато се сетите Мене (покорношћу), и Ја ћу вас да се сећам (опраштањем)! И захваљујте Ми, и немојте Ми незахвални бити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'О ви који верујете, тражите себи помоћ у стрпљивости и молитви! Аллах је, заиста, уз стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'И не кажите за оне који су на Аллаховом путу погинули: "Мртви су!" Не, они су живи, али ви то не осећате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'Ми ћемо вас у искушење доводити, мало страхом и гладовањем, и губљењем иметка, живота и летине. А ти обрадуј стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'Оне који, када их каква невоља задеси, само кажу: "Ми смо, заиста, Аллахови и Њему ћемо се, сигурно, вратити."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'То су они којима припадају благослови од Господара њиховог и милост; они су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, '"Сафа и Мерва су, заиста, Аллахова часна места. Зато онај који Кабу ходочасти или Умру обави, не ради никакав преступ да се креће између њих. А онај који драге воље учини какво добро дело, па Аллах је заиста благодаран и све зна."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'Оне који буду скривали јасне доказе које смо Ми објавили, и Прави пут након што смо га у Књизи људима означили, Аллах ће да их прокуне, а проклеће их и они који имају право да проклињу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'Изузети ће да буду само они који се покају и поправе, и то јавно испоље; таквима ћу Ја да опростим, а Ја сам Онај који прима покајања, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Заиста, онима који не верују и који као неверници умру, следи проклетство Аллахово, проклетство анђела и свих људи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'У њему ће вечно да остану, а патња њихова неће да им се смањује, нити ће да им се шта одлаже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'А ваш Бог један је Бог; нема бога осим Њега, Свемилосног, Милостивог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'У стварању небеса и Земље, у смени ноћи и дана, у лађи која морем плови сa корисним товаром за људе и у води коју Аллах сa неба спушта, па тако земљу враћа у живот након њене замрлости, по којој је расејао разноразна жива бића, у усмеравању ветрова и облацима који између неба и Земље лебде - има, заиста, знакова за оне који разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'Има људи који поред Аллаха друге, као једнаке Њему, прихватају; воле их као што се Аллах воли! Али, они који верују, још више Аллаха воле! А да знају они који су неправду чинили - када казну доживе, да ће видети да моћ сва Аллаху припада и да Аллах страховито кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'Када се они за којим су се други поводили одрекну оних који су их следили и казну буду искусили, и када им се свака могућност спасења прекине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'Тада ће следбеници њихови рећи: "Да нам је само да се на тренутак вратимо, па да се и ми њих одрекнемо као што су се они нас одрекли!" Ето, тако ће Аллах њима показати погубним дела њихова и они никада неће из Пакла изаћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'О људи, једите од онога што има на Земљи, што је дозвољено и лепо, и не следите ђавоље стопе! Он вам је, заиста, непријатељ очевидни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'Он вас навраћа на грех и разврат, и да о Аллаху говорите оно што не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'А када им се каже: "Следите оно што је Аллах објавио!" - Они одговарају: "Не, него ћемо да следимо оно на чему смо наше претке затекли." Зар и онда када им преци нису ништа схватали, нити су били на Правом путу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Они који не верују слични су ономе који виче, али сам не чује ништа осим зов и запомагање; они су глуви, неми и слепи и они ништа не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'О ви који верујете, једите добра којим смо вас опскрбили и захваљујте Аллаху, ако, заиста, само Њега обожавате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'Он вам, заиста, забрањује: стрв, крв, свињско месо и оно што је принесено као жртва у нечије друго име, а не у Аллахово. А ономе који буде приморан, не својом вољом и не претерујући, није му грех. Аллах је, заиста, Онај Који опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'Заиста, они који скривају оно што је Аллах у Књизи објавио и то продају за нешто што мало вреди - они у стомаке своје само ватру трпају; на Судњем дану Аллах неће ни да их ослови, нити ће да их очисти; њима припада патња болна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'То су они који уместо Упуте изабрали заблуду, а уместо опроста патњу; како ли су само они неосетљиви на претњу Ватром?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, 'То је тако, јер Аллах је објавио Књигу с истином, а они који се о Књизи разилазе заиста су у расколу великом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Није честитост у томе да окрећете лица своја према истоку и западу; честити су они који верују у Аллаха, и у Будући свет, и у анђеле, и у књиге, и у веровеснике, и који од иметка, иако им је драг, дају рођацима, и сирочадима, и сиромасима, и путницима, и просјацима, и за откуп из ропства, и који молитву обављају и обавезну милостињу дају, и који обавезу своју, када је преузму, испуњавају, нарочито они који су издржљиви у неимаштини, и у болести, и у боју љутом. Они су искрени верници, и они се Аллаха боје и ружних поступака клоне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'О ви који верујете! Прописује вам се одмазда за убијене: слободан за слободног, роб за роба, и женско за женско. А онај коме род убијеног опрости, нека они великодушно поступе, а нека им он доброчинством узврати. То је олакшање од вашег Господара и милост. А ко насиље и после тога изврши, њему следи болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, 'У одмазди вам је живот, о разумом обдарени, да бисте се сачували.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Када неко од вас на самрти буде, па оставља какво добро, прописано вам је да, на леп и праведан начин, родитељима и ближњима опоруку пренесете, што је обавеза богобојазних.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Онај ко је измени, након што чује како гласи, грех за то пада на оне који је мењају. А Аллах, заиста, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Па ко се боји погрешке или грешног поступка опоручиоца, па то ваљано између оних којих се опорука тиче поправи, није згрешио! Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'О ви који верујете! Прописује вам се пост, као што је прописан онима пре вас, да бисте се греха сачували.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, 'Одређен број дана; а ономе од вас који је болестан или на путу буде, да напости толико других дана. Онима који га тешко подносе, откуп је да сиромашног нахране. А ко драге воље удели више, за њега је боље. А боље вам је да постите, кад бисте само знали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, 'У рамазану је почело објављивање Кур''ана, који је путоказ људима, јасан доказ Правог пута и разликовања добра од зла. Ко од вас у том месецу буде код куће, нека пости, а ко буде болестан или се на путу задеси, нека исти број дана напости. Аллах жели да вам олакша, а не да вам отежа, и да одређени број дана испуните и да Аллаха величате јер вас је упутио, па да захвални будете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'А када те слуге Моје за Мене упитају, Ја сам, сигурно, близу: одазивам се молби молитеља када Ме замоли. Зато, нека се и они Мени одазову и нека верују у Мене, како би исправним путем кренули.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Дозвољава вам се да у ноћима поста имате однос са женама вашим; оне су одећа ваша, а ви сте одећа њихова; Аллах зна да сте сами себе обмањивали, па је прихватио покајање ваше и опростио вам; зато се сада састајте с њима и жудите за оним што вам је Аллах одредио; једите и пијте све док будете могли да разликујете белу нит од црне нити зоре, а потом употпуните пост, до ноћи. Са женама немојте да имате односе док сте у осами у богомољама; то су Аллахове границе и не приближујте им се; тако Аллах у речима и доказима Својим обзнањује прописе људима, како би се причували.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Не једите имовину једни другима на непоштен начин и не спорите се због ње пред судијама како бисте с грехом, свесно, део имовине других људи узели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, 'Питају те о млађацима. Реци: "Они су људима ознаке за време и ходочашће." Не исказује се честитост у томе да са задње стране у куће улазите, него је честитост у томе да се Аллаха бојите. У куће улазите на врата њихова и Аллаха се бојте да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'И борите се на Аллаховом путу против оних који се боре против вас, али не прелазите границе. Заиста Аллах не воли оне који прелазе границе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'И убијајте их где год их стигнете, и истерајте их одакле су они вас истерали! А смутња је тежа од убијања! И не борите се против њих код Часног храма док вас они ту не нападну. Ако вас ту нападну, онда их убијајте! Таква је казна за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Ако престану, па Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'И борите се против њих док смутња не нестане и док вера не буде само Аллаху исказивана. Па, ако се окане, онда непријатељство престаје, а једино против насилника остаје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Свети месец је за свети месец, а и у светињама је дозвољена одмазда: онима који вас нападну, узвратите истом мером и Аллаха се бојте; знајте да је Аллах уз богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'И трошите иметак на Аллаховом путу, и сами себе у пропаст не бацајте, и добро чините; Аллах, заиста, воли доброчинитеље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Хаџ и Умру ради Аллаха употпуните! А ако будете спречени, онда жртвенице које сте у могућности закољите, а главе своје не бријте све док жртвенице не стигну до места свога! А онај од вас који се разболи или има нешто на глави што га мучи па се обрије, нека се постом или добровољном милостињом или жртвеницом искупи! Када будете сигурни, онај ко буде обављао Умру уз ходочашће, нека закоље жртвеницу до које може да дође! А онај ко не нађе, нека три дана пости у данима ходочашћа и седам дана по повратку, то је пуних десет дана. То важи за оног чија породица не живи у границама Часног храма. И бојте се Аллаха и знајте да Он жестоко кажњава!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Хаџ је у познатим месецима, па онај ко се обавеже у току њих да обави хаџ не може да има интимни однос, нити грехе да чини, нити да се препире у току ходочашћа. А за добро које учините Аллах зна. За пут се опскрбите, а најбоља је опскрба богобојазност! И Мене се бојте о ви разумом обдарени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, 'Није вам грех да од Господара свога тражите неко добро. А када пођете с Арефата, Аллаха спомињите код часних места; спомињите Га и славите јер вас је Он упутио, а заиста сте пре тога у заблуди били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, 'Затим крените одакле крећу остали људи и од Аллаха опрост молите. Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'А када завршите обреде ваше, Аллаха спомињите као што спомињете претке ваше, па и више од тога! Има људи који говоре: "Господару наш, дај Ти нама на овоме свету!" А на другом свету неће имати никаквог удела!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'А има и оних који говоре: "Господару наш, дај нам добро и на овом свету и на Будућем свету и сачувај нас патње у Паклу!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'Таквима припада удео који су заслужили! Аллах заиста брзо своди рачуне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'И Аллаха спомињите у данима одређеним! А ономе ко пожури, па то учини у два дана, није грех, као што није грех ни ономе који још остане, ако је богобојазан. Бојте се Аллаха, и знајте да ћете сви пред Њим бити сакупљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'Има људи, попут оног чије те речи о животу на овом свету одушевљавају и који се позива на Аллаха као сведока за оно што је у његовом срцу, а најљући су противници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Чим се неки од њих окрене од тебе, крене неред по Земљи да прави, уништава усеве и стоку. А Аллах не воли неред!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'А када му се каже: "Аллаха се бој!" Он се онда поноси гресима. Па довољан му је Пакао, а то је, заиста, грозно боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'Има људи који се жртвују у тежњи за задовољством Аллаховим. А Аллах је милосрдан према слугама Својим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'О ви који верујете, уђите у Ислам потпуно и не идите стопама ђавољим; он вам је, заиста, непријатељ отворени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'А ако посрнете, након што су вам дошли јасни докази, онда знајте да је Аллах, заиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Чекају ли они да им Аллах дође у тминама облака, и анђели, и да буде свему крај?! А Аллаху се све враћа!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Упитај синове Израиљеве колико смо им јасних доказа дали! А они који замењују благодат Аллахову која им је дошла, па Аллах, заиста, страховито кажњава!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Неверницима се живот на овоме свету чини лепим и они се ругају онима који верују. А они који су се Аллаха бојали и греха клонили, на Судњем дану биће изнад њих! Аллах даје у обиљу ономе коме Он хоће, без рачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'Сви људи су сачињавали једну заједницу, па је Аллах слао веровеснике да доносе радосне вести и опомену, и по њима је слао Књигу са Истином, да се по њој суди људима у ономе у чему су се они разилазили. А повод неслагању је била међусобна завист, баш од стране оних којима је дата, и то када су им већ били дошли јасни докази; и онда би Аллах, вољом Својом, упутио вернике да схвате праву истину о ономе у чему се нису слагали. А Аллах указује на прави пут ономе коме Он хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Зар мислите да ћете ући у Рај, а још нисте искусили оно што су искусили они који пре вас нестадоше?! Њих је погађала неимаштина и болест, и толико су бивали узнемиравани да би и посланик и они који су с њим веровали, говорили: "Када ће доћи Аллахова помоћ!?" Ето, Аллахова помоћ је, заиста, близу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, 'Питају те, шта да уделе? Реци: "Оно што будете уделили од добра нека припадне родитељима и рођацима, и сирочади, и сиромасима, и путницима намерницима; а за добро које чините Аллах сигурно добро зна."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'Прописана вам је борба, а то вам је мрско! Можда нешто не волите, а то је добро по вас; можда нешто волите, а то је зло по вас! Аллах зна, а ви не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'Питају те о светом месецу, о ратовању у њему! Реци: „Ратовање у њему је велики грех; али, одвраћање од Аллаховог пута и неверовање у Њега, и одвраћање од Часног храма и изгоњење становника његових, још је већи грех код Аллаха. А смутња је гора од убијања! Они ће непрестано да се боре против вас док вас не одврате од ваше вере, ако буду могли! А они међу вама који од вере своје отпадну и као неверници умру - њихова дела биће поништена на овом свету, а и на Будућем. Они ће становници Ватре да буду и тамо ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'Заиста, они који верују, и који се иселе и на Аллаховом путу боре, они желе милост Аллахову. А Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'Питају те о опојним пићима и коцки! Реци: „У њима је велики грех, а има и неких користи људима; само је грех већи од њихове користи!“ Питају те, шта да удељују! Реци: „Вишак!“ Ето, тако вам Аллах прописе објашњава да бисте размислили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'и о овом свету и о Будућем. И питају те о сирочади! Реци: "Унапредити њихов иметак је боље!" А ако будете с њима заједно живели, па то су браћа ваша! Аллах зна разлику између покварењака и доброчинитеља! Да је Аллах хтео, могао је прописати оно што вам је тешко! Он је, заиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'Не жените се незнанобошкињама док вернице не постану; уистину је робиња - верница боља од незнанобошкиње, макар вам се она и свидела! Не удајте вернице за незнанобошце док не постану верници; јер уистину је роб - верник бољи од незнанобошца, макар вам се и допадао. Они позивају у Ватру, а Аллах позива Рају и опросту, дозволом Својом, и појашњава људима речи и доказе Своје, да би се присећали и поуку примили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'И питају те о месечном прању! Реци: "То је непријатност!" Зато, немојте да имате однос са женама за време месечног прања, и не прилазите им док се не очисте! А када се очисте, онда им прилазите онако како вам је Аллах наредио! Аллах, заиста, воли оне који се кају и воли оне који се чисте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Жене ваше су њиве ваше, и ви њивама својим прилазите како хоћете! А припремите нешто и за душе своје! И бојте се Аллаха и знајте да ћете се с Њим сусрести! А ти обрадуј вернике!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'И нека вам заклетва Аллахом не буде препрека да добро чините, да се Аллаха бојите и људе мирите. А Аллах све чује и све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Аллах неће да вас казни ако се неопрезно закунете, али ће да вас казни за оно што с предумишљајем срца ваших урадите. Аллах опрашта грехе и не жури с казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Они који се закуну да се неће приближавати женама својим, сачекаће четири месеца! Па ако им се врате, Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'А ако одлуче да се раставе, па Аллах, заиста, све чује и све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Разведене жене нека чекају три месечна прања; и није им допуштено да крију оно што је Аллах створио у материцама њиховим, ако у Аллаха и у Будући свет верују! Мужеви њихови имају право да их, док оне чекају, поврате, ако желе помирење. Оне имају исто толико права колико и дужности; треба да их изврше лепо и по пропису. А мушкарци су над њима за један степен! Аллах је, заиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Развод може бити два пута, након чега се она, или лепо и праведно задржава, или јој се уз доброчинство последњи развод даје! А вама није допуштено да узимате било шта од онога што сте им даровали, осим ако се њих двоје плаше да Аллахове прописе неће да извршавају. А ако се бојите да њих двоје Аллахове прописе неће да извршавају, онда им није грех да се она откупи. То су Аллахове границе, па их не прекорачујте! А они који Аллахове границе прекорачују, то су прави неправедници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'А ако је опет разведе, она му није након тога допуштена све док се не уда за другог мужа. Па ако је и он разведе, онда њима двоје није грех да се једно другом врате, ако мисле да ће Аллахове прописе извршавати. То су Аллахове границе које Он објашњава људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Када разведете супруге, па оне испуне свој разводни рок, тада их, или лепо и праведно задржите, или уз доброчинство отпремите! И не задржавајте их наносећи им штету, а онај ко тако поступи, учинио је себи неправду! Не поигравајте се Аллаховим прописима и сетите се благодати Аллахове према вама и то што вам је објавио Књигу и мудрост којом вас саветује! Аллаха се бојте и знајте да Аллах све зна!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'А када разведете супруге, па испуне свој разводни рок, не ометајте их да се удају за мужеве своје, када се сложе да лепо живе! Овим се саветују они међу вама који верују у Аллаха и Последњи дан. Тако вам је чедније и честитије. А Аллах зна, а ви не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'Мајке нека доје своју децу пуне две године, ако желе да дојење буде потпуно! Очеви су дужни да их хране и одевају на леп и уобичајен начин. Нико се не задужује изнад могућности својих: мајка не сме да наштети оцу детета због детета свога, а ни отац мајци детета због детета свога! Наследник има исте обавезе. Зато, ако њих двоје на леп начин и по договору одлуче да одбију дете од дојења, нису грешни! А ако зажелите својој деци да нађете дојиље, није вам грех ако им, како је уобичајено, дате оно што хоћете да дате. Бојте се Аллаха и знајте да Аллах добро види шта радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'Они од вас који умру остављајући супруге своје, њихове супруге дужне су чекати четири месеца и десет дана. И када оне испуне прописани рок, ви не сносите грех за оно што оне лепо и по пропису ураде. А Аллах у потпуности зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'И није вам грех ако тим женама на знање дате да ћете ви да их запросите, или ако то у душама својим кријете. Аллах зна да ћете на њих да мислите, али им потајно ништа не обећавајте, него им само што је дозвољено говорите. И не одлучујте се на брак пре него што прописано време за чекање не истекне; и имајте на уму да Аллах зна шта је у душама вашим, па Га се причувајте, и знајте да Аллах, заиста, опрашта грехе и не жури с казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Није вам грех ако жене пустите пре него што у интимни однос с њима ступите, или пре него што им венчани дар одредите. И лепо их и по пропису дарујте, имућан према свом стању, а сиромашан према свом; то је дужност онима који желе добро да чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'А ако их пустите пре него што сте у однос с њима ступили, а већ сте им венчани дар одредили, оне ће задржати половину онога што сте одредили, осим ако се одрекну или се одрекне онај који одлучује о склапању брака; а ако се ви одрекнете - то је ближе богобојазности! И не заборавите да једни према другима добри будете! Аллах, заиста, добро види шта ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Чувајте молитве, нарочито молитву у средини дана, и пред Аллахом понизно стојте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'Ако се будете бојали, онда молитву обављајте ходајући или јашући! А када будете сигурни, спомињите Аллаха онако како вас је Он научио ономе што нисте знали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'Они међу вама којима се примиче смрт, а који иза себе остављају супруге, треба да им опоруком, унапред за годину дана, одреде издржавање и да се оне не удаљују из куће. А ако је саме напусте, ви не сносите грех за оно што оне лепо и по пропису са собом учине. А Аллах је силан и мудар!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'Разведеним женама припада отпремнина у складу с прописом и на леп начин, и то је обавеза богобојазних.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'Аллах вам тако објашњава прописе Своје, да бисте размислили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Зар не знаш за оне који су из страха од смрти из земље своје побегли, а било их је на хиљаде, па им је Аллах рекао: "Помрите!" А после их је оживео. Аллах је, заиста, дарежљив према људима, али већина људи не захваљује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'И борите се на Аллаховом путу и знајте да Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Ко је тај који ће Аллаху леп зајам дати, па да му га Он многоструко врати, Аллах ускраћује и обилно даје, и Њему ћете се вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Зар не знаш када су прваци синова Израиљевих, након Мојсија, казали своме веровеснику: "Постави нам краља да се на Аллаховом путу боримо!" "Можда се ви нећете борити, ако вам борба буде прописана?'''' Рече он. "Зашто да се не боримо на Аллаховом путу?'''' Рекоше. "А ми смо из земље наше прогнани и од синова наших одвојени!" А када им борба би прописана, они, осим неколицине, окренуше се. А Аллах добро зна неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, '„Аллах вам је Саула за владара одредио“, рече им њихов веровесник. „Одакле да нам он буде владар када смо ми пречи од њега да владамо? Њему ни велико богатство није дато!“, рекоше они. „Заиста је Аллах њега да влада вама изабрао“, рече он, „и великим знањем и телесном снагом га обдарио. Аллах даје власт коме Он хоће. Аллах је неизмерно дарежљив и све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, '„Заиста, знак његове власти“, рече им веровесник њихов, „биће ковчег који ће да вам стигне. У њему ће да буде смирај за вас од вашег Господара, и остатак онога што су Мојсије и Арон оставили. Носиће га анђели. У томе је, заиста, знак за вас, ако сте верници!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'И кад Саул изађе с војском, рече: "Аллах ће сигурно да вас стави на искушење једном реком, па ко се напије из ње, није мој, а ко се не напије, он је мој, изузев ако шаком захвати гутљај!" И они се, осим неколицине, напише, а кад је они који су с њим веровали пређоше, неки рекоше: "Ми данас не можемо изаћи на крај с Голијатом и војском његовом." Они који су чврсто веровали да ће сусрести Аллаха, рекоше: "Колико су пута малобројне чете савладале многобројне чете Аллаховом дозволом." А Аллах је са стрпљивима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'И када изиђоше пред Голијата и његову војску, они рекоше: "Господару наш, надахни нас издржљивошћу и учврсти ноге наше и помози нам против народа који не верује!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'И они их, Аллаховом дозволом, поразише, и Давид уби Голијата, и Аллах му подари власт и мудрост, и научи га ономе чему је Он хтео. А да Аллах људе не сузбија једне другима, на Земљи би заиста неред настао! Али, Аллах је дарежљив свим световима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'То су Аллахове речи и докази, које Ми теби истинито казујемо. А ти си, заиста, један од посланика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'Неке од тих посланика одликовали смо више него друге. Са некима од њих је Аллах говорио, а неке је за више степени уздигао. А Исусу, Маријином сину, смо јасне доказе дали и светим Духом (анђелом Гаврилом) га помогли. Да је Аллах хтео, они се не би међусобно после њих убијали, када су им јасни докази већ дошли, али они су се разишли, неки од њих су веровали, а неки су порицали. А да је Аллах хтео, они се не би међусобно убијали! Али, Аллах ради оно што Он жели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'О ви који верујете, удељујте од онога чиме вас Ми опскрбљујемо, пре него што дође Дан када неће да буде ни откупа, ни пријатељства, ни посредништва! А неверници су прави неправедници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Аллах је, нема бога осим Њега, Живи и Самоопстојећи Одржаватељ! Не обузима Га ни дремеж ни сан! Његово је оно што је на небесима и на Земљи! Ко може пред Њим да се заузима без Његовог допуштења?! Он зна шта је било пре и шта ће да буде после њих и они не могу да обухвате од Његовог знања осим колико Он жели. Његов Курсиј обухвата и небеса и Земљу и Њему није тешко да их одржава! Он је Свевишњи и Величанствени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, '„Нема присиле у веру, Прави пут се јасно разликује од заблуде! Онај ко не верује у лажна божанства а верује у Аллаха, држи се за најчвршћу везу, која неће да се прекине. А Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Аллах је заштитник оних који верују, изводи их из тмина на светло, а онима који не верују заштитници су лажна божанства, одводе их са светла у тмине! То су становници Ватре и у њој ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Зар не знаш за оног који се с Аврамом о његовом Господару препирао, којем је Аллах царство дао?! Кад Аврам рече: „Господар мој је Онај Који живот и смрт даје!“ Он одговори: „Ја живот и смрт дајем!“ Аврам рече: „Аллах чини да Сунце излази с истока, па учини ти да изађе са запада!“ И неверник се збуни. А Аллах, заиста, неправеднике не упућује на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Или за онога који је, пролазећи поред једног насеља које је било до темеља порушено и пусто, повикао: „Како ће Аллах да оживи ове што су помрли?!“ И Аллах га мртвим учини стотину година, а затим га оживи и упита: „Колико си остао?“ Он рече: „Остао сам дан или део дана!“ Тада му рече: „Не, остао си стотину година! Погледај јело своје и пиће своје, није се покварило! А погледај и магарца свога, то смо урадили да те учинимо знаком за људе, а погледај и кости, како их састављамо, а онда месом облажемо!“ И када њему би јасно, повика: „Ја знам да Аллах, заиста, над свиме има моћ!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'А када Аврам рече: „Господару мој, покажи ми како оживљујеш мртве?“ Он рече: „Зар не верујеш?!“ „Свакако, верујем“, одговори он, „али да ми се срце смири!“ Затим му рече: „Па, онда, узми четири птице, исеци их, па по један њихов део стави на сваки брежуљак. Затим их позови, доћи ће ти журећи! Знај да је Аллах, заиста, силан и мудар.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Пример оних који своју имовину троше на Аллаховом путу сличан је зрну из којега никне седам класова, а у сваком класу по стотину зрна. А Аллах повећава коме Он хоће. Аллах је неизмерно дарежљив и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Онима који троше богатства своја на Аллаховом путу, а онда оно што потроше не пропрате приговорима и увредама, припада награда њиховог Господара. За њих нема страха нити ће они да тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'Лепа реч и опрост вреднији су од милостиње попраћене вређањем. А Аллах није ни о коме завистан и благ је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'О ви који верујете, не кварите милостиње своје приговорима и увредама, као што то чини онај који богатство своје троши да би се људима показао, а не верује у Аллаха и Будући свет. Његов пример је као пример глатке стене на којој има земље, па је погоди велики пљусак и оголи је. Они немају никакве користи од онога што су стицали. А Аллах не упућује на Прави пут људе који не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Они који троше своје богатство у жељи за Аллаховим задовољством и сигурни су у награду за то, слични су башти на узвишици на којој се излила обилна киша, па даје двоструки род! А ако се на њу не излије обилна киша, опет буде росе! Аллах добро види шта ви радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Да ли би ико од вас волео да поседује башту пуну палми и грожђа, кроз коју реке теку и у којој има разноразних плодова, а да је остарео и да има нејаку децу, а да је онда ватрена олуја задеси и она изгори?! Тако вам Аллах објашњава Своје речи и знакове, да бисте размислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'О ви који верујете, удељујте од лепих ствари које сте стекли, и од онога што смо вам Ми из Земље извели! Не издвајајте оно што не вреди да бисте то уделили, када ни сами то не бисте примили, осим затворених очију! И знајте да је Аллах, заиста, Независтан и Хваљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Ђаво вас плаши сиромаштвом и наводи вас на зло, а Аллах вам обећава опрост и награду. Аллах је неизмерно дарежљив и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'Он даје мудрост коме хоће, а ономе коме је мудрост дата, дато је велико добро! А само разумом обдарени се присећају и поуку примају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'За све што потрошите или се заветујете Аллах сигурно зна! А неправедницима нема помагача!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Ако јавно дајете милостињу то је лепо, али је за вас боље ако то прикријете и дате сиромасима, и Он ће да покрије нека ваша лоша дела. А Аллах добро зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Што се тиче њихове упуте, не зависи то од тебе, јер Аллах изводи на Прави пут кога Он хоће. Добро које уделите у вашу је корист, а оно што уделите, делите само у жељи за Аллаховим Лицем и задовољством. А оно што од добара уделите, то ће да вам буде надокнађено и неће вам неправда бити учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, 'То припада сиромасима који су изнемогли на Аллаховом путу, па не могу да путују по земљи; онај ко их не зна мисли да су имућни због њихове суздржаности. Познаћеш их по њиховом изгледу, јер они не досађују људима просећи. А за оно што од добара поделите, Аллах, заиста, добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Онима који деле имовину своју ноћу и дању, тајно и јавно, припада награда код њиховог Господара. И за њих нема страха, нити ће они да се жалосте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Они који се хране каматом дићи ће се из својих гробова баш као они које је ђаво додиром избезумио. То је зато што су говорили: „Трговина је, заиста, исто што и камата!“ А Аллах је дозволио трговину, а забранио је камату. Ономе до кога допре поука од његовог Господара, па се тога окани, припада оно што је пре стекао а његов је случај препуштен Аллаху. Они, пак, који опет то учине, биће становници Ватре у којој ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Аллах уништава камату, а умножава милостињу. Аллах не воли ниједног неверника, грешника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'Заиста ће они који верују, и добра дела чине, и молитву обављају, и обавезну милостињу дају, имати награду код свога Господара. За њих нема страха и они не треба да тугују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'О ви који верујете, бојте се Аллаха и од остатка камате одустаните, ако сте прави верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Ако то не учините, наговештава вам се рат од Аллаха и Његовог Посланика! А ако се покајете, припадају вам главнице имовина ваших; нећете неправду да учините, нити ће вама неправда да буде учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'А ако је дужник у невољи, онда причекајте док му буде лакше; а да то поклоните као милостињу боље вам је, када бисте само знали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'И бојте се Дана у коме ћете да будете враћени Аллаху, затим ће свакоме бити дато оно што је заслужио. И никоме неправда неће да буде учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'О ви који верујете, када један од другога позајмљујете до одређенога рока, запишите то. Нека један писар између вас то праведно напише и нека се писар не сустеже да напише онако како га је Аллах подучио. Нека он пише, а нека му дужник казује! Нека се боји Аллаха, Господара свога, и нека ништа не изостави од тога. А ако је дужник умно ограничен или слаб, или ако није у стању да казује, онда нека казује његов старатељ и то праведно. И узмите два сведока између вас, па ако не нађете два мушкарца, онда једног мушкарца и две жене са којима сте као сведоцима задовољни. Ако једна од њих две погрешно шта каже, нека је друга подсети. И нека се сведоци не устежу, ако буду позвани, да дођу. Нека вам не буде мрско да то запишете са роком враћања, био дуг мали или велики! То вам је код Аллаха исправније и за сведочење јаче, и боље да не бисте сумњали, изузев ако је реч о свакодневној трговини коју обављате међу вама, јер онда вам није грех да то не запишете. Узмите сведоке и када купопродају закључујете, и нека не буде оштећен ни писар ни сведок. А ако их оштетите, онда је то ваш грех. И бојте се Аллаха и Аллах ће да вас подучи! Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Ако сте на путу и не нађете писара, онда нека се узме залог. А ако један другоме нешто поверите, нека онај коме је поверено, то поверење испуни и нека се боји Аллаха, свога Господара! И не скривајте сведочење, јер ко га сакрије, његово срце је, заиста, грешно. А Аллах добро зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'Аллаху припада све што је на небесима и што је на Земљи. Показивали ви шта је у душама вашим или скривали, Аллах ће за то да вас пита, па ће да опрости коме хоће, а да казни кога хоће. А Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Посланик верује у оно што му се објављује од његовог Господара, а и верници, сваки од њих верује у Аллаха, и анђеле Његове, и Књиге Његове, и посланике Његове: „Ми међу посланицима Његовим не правимо разлику!“ И говоре: „Чујемо и покоравамо се! Молимо Те за опрост, Господару наш, а код Тебе је коначно одредиште!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Аллах сваку особу обавезује само онолико колике су њене могућности; у њену корист је добро које учини, а на њену штету је зло које уради. Господару наш, немој да нас казниш ако заборавимо или ненамерно погрешимо! Господару наш, не оптерети нас бременом као што си оптеретио оне пре нас! Господару наш, не оптерећуј нас оним за шта немамо снаге! Преко наших греха пређи, опрости нам и смилуј нам се! Ти си наш Господар, па нас помози против народа који не верује!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Елиф Лāм Мим [1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Аллах, осим Кога другог бога нема, Живи је и Самоопстојећи Одржаватељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'Он теби објављује Књигу са Истином, која потврђује претходне, а објавио је и Тору и Јеванђеље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, 'још пре као путоказ људима, а објавио је и оно што раставља истину од заблуде (Кур''ан). Онима који у Аллахове речи и знакове не верују, припада тешка патња, а Аллах је силан и жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Аллаху, заиста, ништа није скривено, ни на Земљи, ни на небу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'Он је Онај Који вас обликује у материцама како Он хоће; нема другог бога осим Њега, Силног и Мудрог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'Он је Онај Који ти објављује Књигу у којој су речи јасне; оне су матица Књиге; и друге које нису сасвим јасне. Они у чијим је срцима изопаченост следе оне које нису сасвим јасне у тежњи за смутњом и својевољним тумачењем. А тумачење њихово зна само Аллах. А они који су у знање дубоко проникли, кажу: „Ми у то верујемо; све је то од нашег Господара.“ А поуку примају само они разумом обдарени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, '"Господару наш, не допусти срцима нашим да скрену, када си нам већ на Прави пут указао, и даруј нам Своју милост; Ти си, уистину, Онај Који обилно дарује!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'Господару наш, Ти ћеш, заиста, сакупити људе на Дан у који нема сумње! Аллах, заиста, не крши обећање Своје!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Онима који не верују, код Аллаха сигурно неће користити имеци њихови, а ни деца њихова, и они ће бити гориво за Ватру.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, 'Као што су то и фараонови људи, и они пре њих који су знакове наше лажним сматрали, па их је Аллах због греха њихових казнио. А Аллах жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Реци онима који не верују: „Бићете побеђени и у Паклу окупљени, а ужасно је то боравиште!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'Ви сте имали знак у двема групама које су се сукобиле: једној која се борила на Божјем путу, и другој, неверничкој. Они су их видели двоструко бројнијим од себе. А Аллах Својом помоћи подржава кога Он хоће! То је, заиста, поука за оне који су разборити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'Људима је улепшана љубав према страстима, женама, синовима, гомилама злата и сребра, расним коњима, стоци и њивама! То су ужици овосветског живота, а најлепше је место повратка код Аллаха!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'Реци: „Хоћете ли да вас обавестим шта је боље од тих уживања?“ Они који се Аллаха буду бојали и греха клонили, имаће код Господара свог рајске баште кроз које реке теку, у којима ће да бораве вечно, и супруге чисте, и Аллахово задовољство. Аллах добро види Своје слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'То су они који говоре: "Господару наш, ми заиста верујемо, па опрости нам грехе наше и сачувај нас патње у Ватри!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, 'Стрпљиви, и искрени, и послушни Аллаху, и који удељују од богатства, и који у свитање зоре моле за опрост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Аллах сведочи да нема другог бога осим Њега, а и анђели и учени, поступајући праведно. Нема бога осим Њега, Силног и Мудрог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Једина вера код Аллаха је, заиста, ислам! А они којима је дата Књига подвојили су се баш онда када им је дошло знање, и то из међусобне злобе. А онај ко не верује у Аллахове речи и доказе - па, Аллах, заиста, брзо своди рачуне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Ако се они буду препирали са тобом, реци: „Ја сам само Аллаху предан, као и они који ме следе!“ И упитај оне којима је дата Књига и неписмене: „Да ли сте примили ислам?“ Па ако приме ислам, онда су они на Правом путу, а ако одбију, твоје је једино да обзнаниш. А Аллах добро види Своје слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Онима који не верују у Аллахове речи и доказе и који неоправдано убијају веровеснике, и убијају оне који траже да се поступа по правди према људима, наговести болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'То су они чија су дела безвредна и на овом и на Будућем свету, и њима нико неће моћи да помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Зар не видиш оне којима је дат удео у Књизи?! Позивају да им се по Аллаховој Књизи суди, а затим се неки од њих, окрећући се од тога, удаљавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'То је зато што они говоре: „Ватра нас неће дотаћи више од неколико дана!“ - А лажи које измишљају у њиховом веровању обмањују их.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'А шта ће да буде када их сакупимо оног Дана у који нема сумње, и када свако добије оно што је заслужио? А неће им неправда бити учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, 'Реци: „Moj Аллаху! Који сву власт имаш! Ти власт дајеш коме желиш, а одузимаш је од кога Ти желиш! Ти уздижеш кога желиш, а понижаваш кога желиш! У Твојој руци је добро! Ти, заиста, над свиме имаш моћ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Ти уводиш ноћ у дан и уводиш дан у ноћ! Живо изводиш из мртвог и мртво изводиш из живог! Ти опскрбљујеш кога желиш, без икаквог рачуна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'Нека верници за присне пријатеље и заштитнике не узимају невернике мимо верника, а ко то чини, са Аллахом нема ништа! Учините то само ако се тиме од њих штитите! Аллах вас на Себе упозорава, а код Аллаха је коначно одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'Реци: „Скривали ви оно што је у грудима вашим или показивали, Аллах то зна. Он зна све што је на небесима и што је на Земљи. Аллах над свиме има моћ!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'Онога дана када свако угледа пред собом добро које је урадио, а и зло исто тако, пожелеће да је између њих и њега велика удаљеност. А Аллах вас на Себе упозорава и Аллах је милосрдан према Својим слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'Реци: „Ако ви волите Аллаха, онда мене (Мухаммеда) следите, и вас ће Аллах да воли и грехе ће да вам опрости! А Аллах опрашта грехе и милостив је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'Реци: „Покоравајте се Аллаху и Посланику Мухаммеду!“ А ако се они окрену, Аллах, заиста, не воли невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Заиста је Аллах одабрао Адама, и Ноја, и Аврамову породицу, и Јоакимову породицу над другим световима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'као потомство, једне од других. Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, 'Када Јоакимова жена рече: „Господару мој, ово што је у стомаку мом ја заиста заветујем Теби на службу, па прими то од мене, Ти си, заиста, Свечујући и Свезнајући.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'А након што је родила, она рече: „Господару мој, родила сам женско!“- А Аллах најбоље зна шта је она родила. “А мушко није као женско. Дала сам јој име Марија. Ја њу и њено потомство стављам под Твоју заштиту од проклетог ђавола.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Па је њен Господар лепо примио, и учинио је да лепо израсте и да се о њој брине Захарија. Кад год би јој Захарија у храм ушао, код ње би храну нашао. „Одакле ти ово, Марија?“ Питао би он, а она би одговорила: „То је од Аллаха!“ Аллах, заиста, опскрбљује кога хоће, без икаквог рачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'Ту Захарија замоли свога Господара: „Господару мој, подари ми од Себе честитог потомка, Ти заиста молбу чујеш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'И док се он, стојећи у храму, молио, анђели га позваше и рекоше: „Аллах те радује Јахјом (Јованом) који ће да верује у речи Аллахове, прваком, чедним човеком и веровесником, потомком честитих!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, '„Moj Господару“, рече он, „одакле ћу ја да имам сина када ме је старост достигла, а и жена ми је нероткиња?“ „Ето тако“, рече Он, „Аллах чини шта Он хоће.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, '„Moj Господару “, замолио је Захарија, „дај ми неки знак!“ „Знак ће да ти буде“, рече, „што три дана са људима нећеш да говориш, осим знаковима! И много спомињи Господара свога и хвали Га крајем дана и рано ујутру.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'И када анђели казаше: „Марија, тебе је, заиста, Аллах одабрао и учинио чистом! Он те је над женама свих светова одабрао!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, '„Марија, буди скрушена и покорна Господару своме, и ничице падај, и са онима који молитву обављају и ти обављај!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'То су неке од вести о ономе што није докучиво чулима, а које ти објављујемо. Ти ниси био међу њима када су пера своја побацали да би видели који ће о Марији да се брине, а ниси био међу њима ни када су се препирали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'И када анђели рекоше: „Марија, Аллах те радује сином који је речју Његовом створен, чије је име Месија Исус, Маријин син, угледан и на овом и на Будућем свету и један од Аллаху блиских!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, 'Он ће да говори људима и у колевци, и као одрастао, и он је један од добрих!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, 'Она рече: „Господару мој, како ћу ја да имам дете када ме мушкарац није додирнуо?!“ „Ето, тако“, рече, „Аллах ствара шта Он жели. Када нешто одреди, Он само каже: ''Буди!'' И то буде.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, 'Он ће да га подучи Књизи и мудрости, и Тори и Јеванђељу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'И послаће га као посланика Израиљевим синовима: „Донео сам вам знак од вашега Господара: обликоваћу вам од иловаче нешто попут птице, и у њу ћу да дувнем, па ће, Аллаховом дозволом, да буде птица; и излечићу слепог од рођења и губавог, и оживљаваћу мртве Аллаховом дозволом; и казиваћу вам шта једете и шта у домовима вашим чувате. У свему томе има доказа за вас, ако верници будете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'Потврђујући тако истинитост Торе, објављене пре мене, и допуштајући нешто што вам је било забрањено, ја вам доносим доказ од вашега Господара. Па, бојте се Аллаха, а мени будите покорни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Аллах је заиста и мој и ваш Господар и само Њега обожавајте. То је Прави пут!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'И када је Исус осетио да они не верују, рекао је: „Ко су помагачи моји на путу према Аллаху?“ „Ми смо Аллахови помагачи“, рекоше ученици, „ми у Аллаха верујемо, а ти буди сведок да смо ми Аллаху предани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, 'Господару наш, ми верујемо у оно што си Ти објавио, ми Посланика следимо, па упиши нас међу сведоцима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'А они су лукавство смишљали, па је и Аллах њима лукавство приредио. А Аллах најбоље лукавство приређује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, 'И када Аллах рече: „Исусе, Ја ћу да ти узмем душу и ка Себи да те уздигнем! Очистићу те од неверника, и учинићу да они који те исправно следе буду изнад оних који не верују до Судњег дана. Затим ћете Мени да се вратите, па ћу Ја да пресудим о ономе у чему сте се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Што се тиче оних који не верују, њих ћу на страшне муке да ставим на овом свету и на Будућем, и они неће имати помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'А онима који буду веровали и чинили добра дела, Он ће пуну награду да подари. А Аллах не воли неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Ово што ти казујемо јесу докази и Опомена савршена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Пример Исусов заиста је код Аллаха исти као и пример Адамов: од прашине га је створио, а затим му рекао: „Буди!“ И он би!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Истина је од Господара твога, па зато никако не буди од оних који сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'А онима који са тобом о Њему буду расправљали, након што ти је дошло знање, реци: „Дођите, позваћемо наше синове и ваше синове, и наше жене и ваше жене, а доћи ћемо и ми и ви, па ћемо да се прокунемо и Божје проклетство на оне који лажу да призовемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'Ово је, заиста, истинито казивање, и нема бога осим Аллаха! А Аллах је заиста Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'А ако се они окрену, па Аллах, заиста, добро зна смутљивце.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'Реци: „О ви којима је дата Књига, дођите да се окупимо уз речи које ми и ви узајамно делимо: да никога осим Аллаха не обожавамо, да Му у обожавању ништа не придружујемо, и да једни друге, поред Аллаха, боговима не сматрамо!“ Па, ако се они окрену, ви реците: „Будите сведоци да смо ми муслимани!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'О ви којима је дата Књига, зашто се препирете о Авраму када су Тора и Јеванђеље објављени после њега!? Зар ви не разумете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Ето, ви расправљате о ономе о чему имате неко знање, али зашто расправљате о ономе о чему немате никаквог знања? А Аллах зна, а ви не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'Аврам није био ни јевреј ни хришћанин, већ прави верник, Аллаху предан. Он није био од оних који другима дају место које само припада Аллаху.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'Заиста су Авраму најближи људи они који су га следили, и овај Веровесник и они који верују. А Аллах је заштитник верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'Неки којима је дата Књига волели би да вас одведу на странпутицу. Али они не одводе у заблуду никога другог до себе, а да то и не осећају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'О ви којима је дата Књига, зашто у Аллахове речи и доказе не верујете, а сведоци сте да су Истина!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'О ви којима је дата Књига, зашто Истину неистином заогрћете, и кријете Истину, а ви је знате!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Неки којима је Књига дата говоре: "Верујте у оно што је објављено онима који верују, у почетку дана, а пореците то на крају дана, не би ли и они своју веру напустили!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, 'И верујте и поверавајте се само ономе ко следи вашу веру!“ Ти реци: „Заиста је права упута Аллахова упута!“ И говоре: „Не верујте и не поверавајте се икоме, па да некоме буде дато као што је дато вама или да има доказ пред вашим Господаром!“ Реци: „Заиста је свако добро у Аллаховој руци и Он то даје коме Он жели!“ А Аллах је неизмерно дарежљив и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Он Своју милост даје коме хоће. Аллах је поседник великог добра.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Има оних којима је дата Књига који ће да ти врате ако им повериш товар блага, а има их који неће да ти врате ако им повериш и само један динар, осим ако га од њих не будеш стално потраживао. То је зато јер они говоре: „Нама није грех у ономе што учинимо неписменима“, и о Аллаху говоре лажи, а знају истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Међутим, ко обавезу своју испуњава и греха се клони, па Аллах, заиста, воли богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Заиста, они који за обавезу своју према Аллаху и заклетве своје купују нешто што мало вреди, на Будућем свету никаквог удела неће да имају. Аллах са њима неће да говори, нити ће на њих да погледа на Судњем дану, нити ће да их очисти. Њима припада болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Једна њихова група увија своје језике читајући Књигу, да бисте ви помислили да је то из Књиге, а то није из Књиге. И говоре: „То је од Аллаха!“ А то није од Аллаха. И говоре о Аллаху лажи, а знају то.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Није примерено човеку да му Аллах да Књигу, и мудрост, и веровесништво, а затим да говори људима: „Мене обожавајте, а не Аллаха!“ Него: „Будите учени и побожни, зато што Књизи подучавате и што је и сами проучавате!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Он вам не наређује да анђеле и веровеснике сматрате божанствима. Зар да вам наређује неверовање, након што сте постали Њему предани?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'И када је Аллах од веровесника чврсто обећање узео: „Кад год да вам подарим Књигу и мудрост, затим вам дође посланик који потврђује да је истина оно што ви имате, да ли бисте сигурно у њега веровали и помогли га?!“ И рече: „Да ли потврђујете и прихватате обавезу према Мени?“ „Потврђујемо!“ Одговорише. „Будите онда сведоци!“ Рече Он, „а и Ја са вама сведочим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'А они који се и после тога окрену, заиста су то неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Зар поред Аллахове вере желе неку другу, када се Њему предају, милом или силом, и они на небесима и на Земљи, и Њему ће враћени бити?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, 'Реци: „Ми верујемо у Аллаха и у оно што је објављено нама, и што је објављено Авраму, и Јишмаелу, и Исаку, и Јакову и потомцима, и у оно што је дато Мојсију и Исусу и веровесницима од њиховог Господара; ми никакву разлику између њих не правимо, и ми смо предани Њему.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'А онај ко жели неку другу веру поред ислама, неће му бити примљена, и он ће на другом свету да буде међу губитницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'Како Аллах да упути на Прави пут народ који не верује након што је поверовао и посведочио да је Посланик истина, и јасни докази су му дошли!? Аллах неће да упути на Прави пут неправедни народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'А то су они чија је казна проклетство од Аллаха и анђела и свих људи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'У њему ће вечно да остану, а патња њихова неће да им се смањује, нити ће да им се шта одлаже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Изузетак су они који се покају после тога и поправе, а Аллах је, заиста, Онај Који опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'Заиста, онима који постану неверници, након што су веровали, затим постану још већи неверници, покајање неће бити примљено и они су сигурно залутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Заиста, ниједном од оних који нису веровали, а који умру као неверници, неће бити прихваћено да се откупе па макар то било сво благо на Земљи. Њима припада патња болна и они неће имати никаквог помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Нећете постићи добро све док не будете делили од онога што вам је драго. А шта год да уделите, Аллах то добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'Свака храна била је дозвољена Израиљевим синовима, осим оне коју је Израиљ сам себи забранио пре него што је Тора била објављена. Реци: „Донесите Тору и читајте је, ако говорите истину!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'А они који о Аллаху износе лажи и после тога, они су, заиста, неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'Реци: „Аллах говори истину!“ И следите Аврамову веру, који је био прави верник. Он није спадао у оне који поред Аллаха друге обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Прва богомоља подигнута за људе јесте она у Бекки, благословљена је и путоказ световима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'У њој су очигледна знамења, место на којем је стајао Аврам. И онај ко уђе у њу, биће сигуран. Да ходочасти Кабу, ради Аллаха, дужан је свако ко буде у могућности до ње да дође. А ко не верује - па, Аллах је, заиста, независан од светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, 'Реци: „О следбеници Књиге, зашто не верујете у Аллахове речи и доказе? Аллах је сведок свега што радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'Реци: „О следбеници Књиге, зашто онога који верује од Аллахове вере одвраћате, желећи да је искривите, а сведоци сте да је истина!? А Аллах није немаран према ономе што радите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'О ви који верујете, ако се будете покоравали једној групи оних којима је дата Књига, они ће, након што сте прихватили праву веру, поново да вас врате у невернике!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'А како да не верујете када вам се казују Аллахове речи и кад је међу вама Његов Посланик?! А ко се чврсто држи Аллаха, он је на Прави пут упућен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'О ви који верујете, бојте се Аллаха истинском богобојазношћу и нипошто не умирите осим као муслимани!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Сви се чврсто држите за Аллахово уже и не разједињујте се! И сетите се благодати Аллахове према вама, када сте били непријатељи, па је Он ујединио ваша срца и постали сте, Његовом милошћу, браћа! И били сте на ивици ватрене јаме, па вас је Он спасио од ње. Тако вам Аллах објашњава речи и доказе Своје да бисте се исправним путем упутили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'И нека међу вама буде група људи која позива на добро и наређује добро и одвраћа од зла. То су они који су успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'И не будите као они који су се разјединили и разишли, након што су им Јасни докази већ дошли! Њима припада патња велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'На Дан Судњи када ће нека лица да побеле, а нека да поцрне. Онима чија лица буду поцрнела биће речено: „Зар сте постали неверници након вашег веровања?! Па искусите патњу зато што нисте веровали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'А они чија лица побеле, биће у Аллаховој милости, они ће у њој вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'То су Аллахове речи које теби истинито казујемо. А Аллах не жели да било коме учини неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'Аллаху припада све што је на небесима и што је на Земљи, и Аллаху се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Ви сте најбољи народ који се икада појавио: тражите да се чини добро, а одвраћате од зла, и верујете у Аллаха! А када би следбеници Књиге веровали, било би боље за њих; међу њима има верника, али – већина њих су неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Они не могу да вам науде, осим да вас узнемире. Ако вас нападну, даће се у бег, и после им нема помоћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'Ма где се нашли, они су понижени, осим ако су под Аллаховом заштитом и заштитом других људи. Они су заслужили Аллахову срџбу и беда је пала на њих, зато што у речи и доказе Аллахове нису веровали и што су веровеснике бесправно убијали, зато што су Аллаху били непокорни, и што су прешли сваку границу у грешењу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Нису сви они исти! Међу онима којима је дата Књига има исправних, који по целу ноћ уче Аллахове речи и падају Му ничице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Они верују у Аллаха и Будући свет, наређују да се чине добра дела, а одвраћају од злих, и журе да чине добро. Они су међу добрима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Какво год добро да ураде, неће да им буде занегирано, а Аллах добро зна оне који се Њега боје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Заиста, оне који не верују од Аллаха неће да одбране њихова богатства, нити њихова деца; они ће да буду становници Ватре, у њој ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Пример онога што они у овосветском животу уделе сличан је леденом ветру који погоди усеве људи који су сами себи неправду учинили, па их уништи. Њима Аллах није неправду учинио, него је они сами себи чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'О ви који верујете, не узимајте за блиске пријатеље и заштитнике друге мимо вас, јер други вам желе пропаст, једва чекају да допаднете мука! Мржња избија из њихових уста, док је оно што крију њихове груди још горе. Ми вам износимо доказе, ако разумете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'Ето, ви њих волите, а они вас не воле, а ви верујете у све Књиге. Када вас сретну, они говоре: „Верујемо!“ А чим се насамо нађу, од злобе према вама гризу врхове прстију. Реци: „Умрите од муке!“ Аллах, заиста, добро зна шта је у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Ако вас задеси какво добро, то их озлоједи; а задеси ли вас каква невоља, обрадују јој се. Ако се будете стрпили и будете били богобојазни, њихово лукавство нимало неће да вам науди. А Аллах, заиста, обухвата све што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'И сети се када си поранио и породицу своју оставио, да верницима одредиш места за борбу. А Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, 'Када две ваше групе готово не узмакоше, а Аллах је њихов заштитник. И само на Аллаха нека се ослоне верници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Аллах вас је и на Бедру помогао, када сте били малобројни! Зато се Аллаха бојте, да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, 'Када си ти рекао верницима: „Зар вам није довољно да вас ваш Господар помогне са три хиљаде послатих анђела?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Свакако! Ако будете стрпљиви и богобојазни; и ако вас они нагло нападну, ваш Господар ће да вам пошаље помоћ од пет хиљада обележених анђела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'То је Аллах учинио само да вас обрадује и да се тиме ваша срца смире. А помоћи нема осим од Аллаха, Силног и Мудрог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'И да уништи један део неверника, или да их осрамоти, па да се разочарани врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'Ништа не зависи од тебе: било да им Он прими покајање, или да их казни, јер они су, заиста, неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'Аллаху припада све што је на небесима и што је на Земљи! Он прашта коме Он хоће, а на муке ставља кога Он хоће. А Аллах грехе опрашта и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'О ви који верујете, не једите камату више пута удвостручену, и бојте се Аллаха да бисте били спашени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'И чувајте се Ватре која је припремљена за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'И покоравајте се Аллаху и Посланику како би вам била милост указана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, 'И пожурите опросту вашег Господара, и Рају широком као небеса и Земља, припремљеном за богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, 'За оне који удељују, и када су у обиљу и када су у оскудици, који срџбу своју савлађују и људима опраштају. А Аллах воли доброчинитеље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, 'И за оне који, када учине нешто лоше, или себи учине неправду, сете се Аллаха и опрост за грехе своје замоле. А ко опрашта грехе, ако не Аллах?! И за оне који у греху свесно не устрају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'То су они чија је награда опрост њиховог Господара, и баште кроз које теку реке, где ће вечно да остану. Дивне ли награде за оне који тако поступају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Пре вас су многи народи били и нестали. Зато, путујте по Земљи и гледајте како су завршили они који су истину порицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'То је објашњење људима, и упута и поука за оне који се боје Аллаха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'Не клоните духом, и не жалостите се! Ви ћете да победите, ако верници будете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Ако вас ране спопадну - па сигурно су такве ране и друге спопале, и те дане победе Ми наизменице дајемо људима, да би Аллах указао на оне који верују, и одабрао неке од вас који су животом посведочили. А Аллах не воли неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'И да би вернике очистио, а невернике уништио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Зар мислите да ћете да уђете у Рај, а да Аллах не укаже на оне међу вама који се боре, и на оне који су стрпљиви?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Ви сте прижељкивали смрт пре него што сте се са њом суочили, па сте је, ето, видели и у њу сте гледали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Мухаммед је само посланик, а и пре њега је било посланика. Ако би он умро, или био убијен, зар бисте се ви назад вратили?! Онај ко се врати назад, Аллаху неће ништа да науди, а Аллах ће захвалне да награди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Ниједна особа неће да умре без Аллаховог одређења, часа суђеног. Ко жели награду на овоме свету, даћемо му дeо награде који заслужује, а ко жели награду на Будућем свету, даћемо му део награде који заслужује. А захвалне ћемо да наградимо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'А колико је било веровесника уз које су се бројни побожни људи борили, па нису клонули због онога што би их задесило на Аллаховом путу, нити су посустајали, нити су се предавали?! А Аллах воли стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Они нису говорили ништа друго него: „Господару наш, опрости нам грехе наше и претеривање у поступцима нашим, учврсти наше кораке и помози нам против народа неверничког.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Па им је Аллах дао награду на овом свету и још лепшу награду на Будућем свету, а Аллах воли доброчинитеље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'О ви који верујете, ако се будете покоравали онима који не верују, вратиће вас уназад па ћете да постанете губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Заиста, само Аллах је ваш заштитник и Он је најбољи помагач.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'Ми ћемо да улијемо страх у срца оних који не верују, зато што придружују Аллаху оно о чему Аллах није спустио никакав доказ; Ватра је њихово боравиште, а грозно је боравиште неправденика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Аллах је већ потврдио Своје обећање, када сте их ви уништавали, Његовом дозволом, док нисте неуспех доживели и око наредби се разишли, и непокорни били, након што вам је показао шта волите: неки од вас желе овај свет, а други будући! Онда вас је Он одвојио од њих, како би вас искушао! И опростио вам је; а Аллах је према верницима неизмерно добар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, 'Када сте се удаљавали пењући се и не обазирући се ни на кога, док вас је Посланик звао иза ваших леђа, Аллах вас је казнио невољом на невољу, како не бисте туговали за оним што вам је измакло нити због онога што вас је задесило. А Аллах у потпуности зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Затим вам је, после невоље, спустио спокојство, сан који је неке од вас обузео, док су се други бринули само о себи, мислећи о Аллаху оно што није истина, паганским мислима. Говорили су (лицемери): „Имамо ли ми ишта у свему овом?“ Реци: „Одредба у потпуности припада само Аллаху!“ Они у себи крију оно што теби не показују. И говорили су: „Да смо ишта у овоме имали, не бисмо овде изгинули!“ Реци: „И да сте у кућама својим били, опет би они којима је прописано да погину изашли на места своје погибије, да Аллах искуша шта је у вашим грудима и да испита шта је у вашим срцима! А Аллах добро зна шта је у грудима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'Оне од вас који су узмакли на дан када су се две групе сукобиле, заиста је ђаво навео да посрну због нечег од онога што су пре згрешили. А Аллах им је већ опростио, Аллах, заиста, грехе опрашта и не жури са казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'О ви који верујете, не будите као они, који не верују и који говоре за браћу своју, када се на пут по свету отисну или се у борбу дају: „Да су били са нама, не би умрли, нити би погинули!“ Јер, Аллах тиме чини тугу у њиховим срцима, а Аллах даје и живот и смрт. Он добро види оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'А ако ви на Аллаховом путу погинете или умрете, па Аллахов опрост и милост су бољи од онога што они гомилају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'И било да умрете или погинете, ви ћете пред Аллахом сигурно да будете сакупљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, 'Са Аллаховом милошћу ти си благ према њима; а да си груб и тврдог срца, сигурно би се разбежали на све стране од тебе. Зато им праштај и моли да им буде опроштено, и договарај се са њима. А када се одлучиш, ослони се на Аллаха; Аллах, заиста воли оне који се ослањају на Њега.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Ако вас Аллах помогне, нико вас победити не може; а ако вас напусти, па ко је тај који, осим Њега, може да вам помогне?! Зато, на Аллаха нека се ослањају верници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Није могуће да Веровесник шта утаји! А онај ко шта утаји, доћи ће на Судњи дан са тим што је утајио. Затим ће свакоме у потпуности да буде дато оно што је заслужио, и никоме неће да буде учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Зар је онај који је следио Аллахово задовољство исти као онај који је навукао Аллахову срџбу и чије пребивалиште је Пакао?! А ужасно је то коначно одредиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Они су код Аллаха на различитим степенима и Аллах добро види шта они раде!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Аллах је вернике даровао Својом милошћу када им је послао Посланика између њих, да им казује Његове речи, да их очисти, и да их подучи Књизи и мудрости, иако су пре били у очигледној заблуди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'Зар нисте рекли, када вас је невоља снашла коју сте ви њима двоструко нанели: „Одакле сада ово?“ Реци: „То је од вас самих!“ Аллах, заиста, над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'Оно што вас је задесило када су се две групе сукобиле, било је Аллаховом дозволом, и да би указао на оне ко су верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'И да би указао ко су лицемери. Њима је речено: „Дођите, борите се на Аллаховом путу, или се браните!“ А они су казали: „Да знамо да ће да буде борбе, ми бисмо вас следили.“ Тога дана они су били ближи неверовању него веровању. Својим устима су говорили оно што није било у њиховим срцима! А Аллах најбоље зна што они крију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, 'Онима који се нису борили, а о браћи својој су говорили: "Да су нас послушали, не би изгинули!" Реци: "Од себе смрт одагнајте, ако истину говорите!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Никако не сматрај мртвима оне који су погинули на Аллаховом путу. Не, они су живи и опскрбљени су код свога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Радосни су због онога што им је Аллах дао из Свога обиља, и весели због оних који им се још нису придружили, за које неће да буде никаквог страха и који ни за чим неће да тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'Они се радују Аллаховој благодати и доброти, и томе што Аллах неће да допусти да пропадне награда која припада верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, 'Онима који су се одазвали Аллаху и Посланику и након задобијених рана, онима између њих који су добро чинили и богобојазни били - припада велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, 'Онима којима се - када су им људи рекли: „Непријатељи се окупљају због вас, па их се пазите!“- Веровање повећало, па су казали: „Нама је довољан Аллах, а диван је Он Заштитник.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'Па су се вратили са Аллаховим благодатима и обиљем; никакво их зло није задесило. Следили су Аллахово задовољство, а Аллах је поседник великог добра.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'То вас само ђаво плаши својим присталицама, па их се не бојте, него се бојте Мене, ако сте верници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Нека те не жалосте они који срљају у неверовање. Они нимало не могу да науде Аллаху. Аллах неће да им учини било какво добро на Будућем свету и њима припада велика патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'Они који су веровање за неверовање продали, Аллаху неће ништа да науде. Њима припада болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Нека неверници никако не мисле да је добро за њих то што им дајемо дуг живот. Ми им дајемо дуг живот само због тога како би огрезли у греху и њима припада понижавајућа патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'И не може да буде да Аллах вернике остави у стању у којем сте ви, док лоше од добрих не одвоји. И не може да буде да вам Аллах открије оно што је недокучиво чулима, него Он бира кога хоће од Својих посланика. Зато, верујте у Аллаха и Његове посланике, а ако будете веровали и бојали се Аллаха и чували се греха, вама припада велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Нека они који шкртаре у ономе што им Аллах из Свога обиља даје, никако не мисле да је то за њих добро. Напротив, то је за њих зло. На Судњем дану биће им омотано око врата оно чиме су шкртарили. А Аллаху припада наследство небеса и Земље и Аллах добро зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Аллах је чуо речи оних који су говорили: „Аллах је сиромашан, а ми смо богати!“ Ми ћемо да забележимо оно што су они говорили као и то што су без оправдања веровеснике убијали. И рећи ћемо: „Искусите казну у Огњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'То је због дела ваших руку, а Аллах, заиста, не чини неправду Својим слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, 'Онима који говоре: „Аллах је од нас узео обавезу да не верујемо ниједном посланику док не принесе жртву коју ће да прогута ватра!“ Реци: „И пре мене су вам посланици са јасним доказима долазили, а и са тим о чему говорите. Па зашто сте их, онда, убијали - ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'А ако те буду лажљивцем сматрали, па и пре тебе су лажљивцима сматрани посланици који су доносили Јасне доказе и списе и Књигу светиљку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Свака особа ће смрт да окуси, а само на Судњем дану ћете у потпуности да добијете ваше заслуге. Па ко буде удаљен од Ватре и уведен у Рај, успео је. А живот на овом свету само је варљиво наслађивање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'Ви ћете сигурно да будете искушавани у вашим имецима, и у вашим животима, а слушаћете многе неугодности од оних којима је пре вас дата Књига и од незнанобожаца. А ако будете стрпљиви и Аллаха се бојали, па то, заиста, у највећа дела спада.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'А кад је Аллах узео обавезу од оних којима је дата Књига да ће то сигурно људима да објашњавају и да ништа из ње неће да крију, они су је иза леђа својих бацили, продајући је за нешто безвредно. А ружно ли је оно што за то купују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Никако не мисли за оне које радује то што су урадили и који воле да буду похваљени и за оно што нису учинили - никако не мисли да ће се сачувати патње. Њима припада болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'Аллаху припада власт на небесима и на Земљи и Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'У стварању небеса и Земље, и у измени ноћи и дана, заиста су знакови за разумом обдарене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, 'који Аллаха спомињу стојећи, седећи и лежећи на својим боковима, и размишљају о стварању небеса и Земље. „Господару наш, Ти ово ниси створио узалуд! Узвишен си Ти и сачувај нас од патње у Ватри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, 'Господару наш, онога кога Ти будеш у Ватру бацио, већ си га понизио, а неправедницима неће да буде помагача!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'Господару наш, ми смо чули гласника који позива вери: "Верујете у вашег Господара!" Па смо поверовали! Господару наш, опрости нам грехе, и покриј наше лоше поступке, и усмрти нас са честитима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'Господару наш, дај нам оно што си нам обећао преко Својих посланика и не понизи нас на Судњем дану! Ти, заиста, не кршиш Своје обећање!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'И њихов Господар им се одазва: „Ниједном између вас који добро чини, био мушкарац или жена, дела нећу да поништим; ви сте једни од других. Онима који се иселе и који буду из својих домова прогнани, и који буду мучени на Моме путу, и који се буду борили и погинули, сигурно ћу лоша дела да покријем и сигурно ћу да их уведем у рајске баште, кроз које реке теку. Награда је то од Аллаха, а код Аллаха је награда најлепша.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Нека те никако не обмањује то што они који не верују свуда по свету незахвално богатством располажу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, 'Кратко уживање, а затим Пакао ће бити њихово боравиште; а ужасно је то пребивалиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Али, онима који се Господара свога боје припадају рајске баште кроз које теку реке; у њима ће вечно да остану, Аллах ће да их почасти. А оно што је код Аллаха, боље је за честите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Има и оних којима је дата Књига који верују у Аллаха и у оно што је вама објављено, и у оно што је њима објављено, који су понизни Аллаху и не продају Аллахове речи за нешто безвредно. Њима припада награда њиховог Господара, а Аллах ће, заиста, брзо да сведе рачун.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'О ви који верујете, будите стрпљиви и издржљиви, устрајно бдијте и бојте се Аллаха, да бисте успели!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'О људи, бојте се Господара свога, Који вас је створио од једне особе (Адама), и од те особе пар створио, а од њих двоје многе мушкарце и жене расејао. Бојте се Аллаха, чијим именом једни друге молите, и чувајте родбинске везе. Аллах вас, заиста, надзире.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'И сирочадима имовине њихове дајте, не подмећите лоше за добро, и имовине њихове са имовинама вашим не трошите! То је, заиста, велики грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Ако се бојите да према сиротим женама нећете да будете праведни, онда се жените оним женама које су вам драге и допуштене, са по две, са по три или са по четири. А ако страхујете да нећете да будете праведни, онда само са једном, или са оним које поседујете. Тако ћете се најлакше неправде сачувати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'И драга срца женама њихове дарове дајте; па ако вам оне драга срца нешто од тога поклоне, то са пријатношћу и угодношћу трошите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'И онима који немају довољно разума иметке, које вам је Аллах поверио на управљање, не уручујте, него их њима опскрбите и обуците. И лепе речи им говорите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'И проверавајте сирочад док не стасају за брак, па ако се уверите да су зрели, уручите им њихове имовине. И не трошите их расипнички и у журби, пре него што одрасту. Ко је имућан нека се суздржи, а ко је сиромашан, нека троши онолико колико је неопходно. А када им имовину уручујете, то учините у присуству сведока; а доста је што ће пред Аллахом да се полаже рачун.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'Мушкарцима припада део онога што оставе родитељи и родбина, а и женама припада део од онога што оставе родитељи и родбина. Било тога мало или много, део је обавезан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'А када деоби присуствују рођаци, сирочад и сиромаси, опскрбите их делом тога, и лепе речи им реците.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'И нека се прибојавају, као кад би сами иза себе оставили нејаку децу за коју страхују, и нека се боје Аллаха и нека говоре праведно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Заиста, они који неправедно троше имовине сирочади, у своје стомаке стављају ватру и они ће у Огњу да горе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, 'Аллах вам налаже, у вези са вашом децом, да мушком следује колико за два женска детета. А ако буде више од двоје женске деце, њима припадају две трећине онога што је оставио, а ако је само једна, припада јој половина. А родитељима, свакоме посебно, припада шестина од онога што је умрли оставио, ако има деце. А ако не буде имао деце, и наследе га родитељи, онда његовој мајци припада трећина. А ако има браће и (или) сестара, онда његовој мајци припада шестина пошто се изврши опорука коју је оставио, или подмири дуг. Ви не знате ко вам је пречи и битнији, родитељи ваши или синови ваши. То је Божја заповед, а Аллах, заиста, све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'Вама припада половина онога што оставе супруге ваше, ако не буду имале деце; а ако буду имале деце, вама припада четвртина онога што оне оставе, пошто се изврши опорука коју оставе, или подмири дуг; њима припада четвртина онога што ви оставите, уколико не будете имали деце, а ако будете имали деце, њима припада осмина онога што ви оставите након што се изврши опорука коју оставите, или подмири дуг. А ако се мушкарац или жена, који немају ни деце ни родитеље, буду наслеђивали и буду имали брата или сестру (по мајци), онда ће свако од њих двоје да добије шестину; ако их буде више, они онда заједнички учествују у трећини, пошто се изврши опорука која је остављена, или подмири дуг, не оштећујући тиме било кога. То је Аллахова заповед, а Аллах све зна и не жури са казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'То су Аллахови прописи, а онога ко се покорава Аллаху и Његовом Посланику Он ће увести у рајске баште кроз које реке теку и у којима ће вечно да остану. То је велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'А онога ко буде непокоран Аллаху и Његовом Посланику, па буде прелазио преко Његових граница, Аллах ће увести у Ватру у којој ће вечно да остане; таквом припада понижавајућа патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'За оне жене из ваше породице које прељубу почине, тражите да посведоче четворица између вас, па ако посведоче против њих, држите их у кућама све док их смрт не умори или док им Аллах неки пут не нађе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'А оно двоје који то учине, изгрдите их, па ако се покају и поправе, онда их на миру оставите. Аллах, заиста, стално прима покајања и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Аллах прима само покајање оних који учине какво лоше дело из незнања, а потом се убрзо покају. Њима ће Аллах да опрости, а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Нема покајања онима који чине лоша дела све док им се не приближи смрт, па онда говоре: „Сад се, заиста, кајем!“ Нити за оне који умру као неверници. Њима смо болну патњу припремили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'О ви који верујете, не дозвољава вам се да жене преко воље њихове у наслеђе узимате и да им потешкоће причињавате са намером да нешто од онога што сте им дали присвојите, осим ако буду учиниле очигледни разврат. Према њима се лепо опходите. А ако према њима не осетите жељу, па могуће је да не волите нешто у чему је Аллах велико добро дао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'Ако хоћете једну супругу да замените другом, и једној од њих сте дали благо, не узимајте ништа од тога. Зар да то узимате чинећи потвору и очигледни грех?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'А како бисте могли то да узмете, када сте једно са другим били интимни и кад су оне од вас узеле чврсту обавезу!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'И не жените се онима које су оженили очеви ваши након онога што је било - то су били разврат, смутња и ружан пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Забрањују вам се мајке ваше, и кћери ваше, и сестре ваше, и сестре очева ваших, и сестре мајки ваших, и братичне ваше и сестричне ваше, и помајке ваше, које су вас дојиле, и сестре ваше по млеку, и мајке супруга ваших, и пасторке ваше које се налазе под вашим скрбништвом од супруга ваших с којим сте имали интимне односе; ако с њима нисте имали интимне односе, онда вам није грех; и супруге ваших рођених синова, и да две сестре саставите, осим што је раније било! Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'И забрањују вам се удате жене, осим оне које су у вашем власништву. То вам је Аллахов пропис! А остале су вам дозвољене, ако желите да им венчане дарове дате и да се њима ожените, а не да чините блуд! А супругама вашим са којима имате брачне односе дајте венчане дарове као што је прописано. И није вам грех ако се, после одређеног венчаног дара, са њима нагодите. Аллах, заиста, све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'А онај међу вама који није довољно имућан да се ожени слободном верницом - ето му оне вернице које су у вашем власништву - а Аллах најбоље зна веровање ваше - једни сте од других. И жените се њима уз одобрење њихових власника, и дајте им венчане дарове како је лепо и уобичајено, ако су чедне, а нису прељубнице, нити тајне љубавнице. А ако оне буду удате, па почине разврат, нека буду кажњене половином казне прописане за слободне жене. То је за онога од вас који се боји разврата, а боље вам је да се суздржите, а Аллах грехе опрашта и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Аллах жели да вам објасни и упути вас путевима којима су ишли они пре вас, и да вам опрости. Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Аллах жели да вам опрости, а они који се за страстима својим поводе желе да далеко скренете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Аллах жели да вам олакша, а човек је створен слаб.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'О ви који верујете, једни од других на недозвољен начин имања не присвајајте, осим трговином уз обострани пристанак, и сами себе не убијајте. Аллах је, заиста, према вама милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Онога који то учини неправедно и насилно, Ми ћемо у Ватру да бацимо, а то је Аллаху лако.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Ако се будете клонили великих греха који су вам забрањени, Ми ћемо да покријемо ваша лоша дела и у дивно место ћемо да вас уведемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'И не пожелите оно чиме је Аллах неке од вас одликовао над другима: мушкарцима припада удео за оно што зараде, а женама удео за оно што оне зараде. И молите Аллаха за Његово обиље! Аллах, заиста, све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'За све смо одредили наследнике у ономе што оставе родитељи и рођаци, а онима са којима сте везани уговором дајте њихов део! Аллах је, заиста, свему сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Мушкарци су надређени и старају се о женама зато што је Аллах одликовао једне над другима и зато што они троше своја богатства. Због тога су честите жене послушне и за време мужевљевог одсуства чувају оно што је Аллах одредио да се чува. Оне чије непослушности се бојите ви посаветујте, затим напустите њихове постеље, а након тога и ударите! Ако вам постану послушне, не чините им ништа лоше. Аллах је, заиста, узвишен и велик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'А ако се бојите раздора између њих двоје, онда пошаљите једног судију из његове, а једног из њене породице. Ако они желе измирење, Аллах ће да их помири; Аллах је, заиста, свезнајући и све у потпуности зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'Аллаха обожавајте и ништа Му у обожавању не придружујте, а родитељима чините добро, и рођацима, и сирочадима, и сиромасима, и ближњем комшији, и даљњем комшији, и другу поред себе, и путнику, и ономе који је у вашем поседу. Аллах, заиста, не воли оне који се охоле и хвалишу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'То су они који шкртаре и заповедају другима да буду шкрти, и који крију оно што им је Аллах из Свога обиља даровао, а Ми смо неверницима припремили понижавајућу патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'И они који троше имовине своје претварајући се пред људима, а у Аллаха и Будући свет не верују. А коме је ђаво друг, зао му је друг.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'А шта би им било да у Аллаха и Последњи дан верују и да од онога што им је Аллах дао удељују?! А Аллах о њима све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Заиста Аллах ни трунку неправде не чини, па ако то буде добро дело, Он ће да га умногостручи и подариће велику награду од Себе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'А шта ће тек да буде када из свакога народа доведемо сведока, а и тебе Мухаммеде доведемо да о овима сведочиш?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'Тог дана ће пожелети они који нису веровали и који су се против Посланика Мухаммеда дизали да земља над њима буде поравнана, а од Аллаха ниједну реч неће моћи да сакрију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'О ви који верујете, не приступајте пијани молитви, док не будете знали шта говорите, нити када сте нечисти од интимног односа, осим као пролазници (кроз џамију), све док се не окупате. А ако сте болесни, или на путу, или ако је неко од вас дошао из нужника, или ако сте имали однос са супругама, а не нађете воду, онда длановима чисту земљу дотакните и лица своја и руке своје потарите. Аллах је, заиста, Онај Који стално грехе поништава и опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Зар не видиш како они којима је дат удео у Књизи купују заблуду и желе да ви са Правог пута скренете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Аллах најбоље познаје непријатеље ваше; Аллах је довољан заштитник и Аллах је довољан помагач.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Онима који су јеврејство прихватили, који изврћу смисао речи говорећи: „Чујемо, али се не покоравамо!“ И: „Слушај, дабогда не чуо!“ И: „Чувај нас!“ Преврћући језицима својим и хулећи веру, боље би било и исправније да кажу: „Слушамо и покоравамо се!“ И: „Слушај!“ И: „Погледај на нас!“ Али, Аллах је њих због неверовања њиховог проклео и мало ко од њих верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'О ви којима је дата Књига, верујте у ово што објављујемо потврђујући оно што већ имате, пре него што црте лица избришемо и вратимо их назад, или их прокунемо као што смо проклели оне који нису поштовали суботу, а Аллахова заповест бива извршена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Аллах, заиста, неће да опрости идолопоклонство, а опростиће све мимо тога, коме Он хоће! А онај ко другог поред Аллаха обожава, чини потвору и велики грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Зар не видиш оне који себе сматрају чистим од греха?! Међутим, Аллах чисти од греха кога хоће и никоме неће, ни колико трун неправде да се учини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Погледај како измишљају лаж о Аллаху! То је Аллаху довољно као јасан грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Зар не видиш оне којима је дат удео у Књизи како у магију и лажна божанства верују, а онима који не верују говоре: „Ови су на исправнијем путу од оних који верују.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'То су они које је Аллах проклео, а онај кога је Аллах проклео такав нема помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Да можда они немају какав удео у власти?! А да имају, они људима ништа не би ни колико трун дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'И зар људима завиде на ономе што им је Аллах дао из обиља свога?! А Ми смо Аврамовим потомцима дали Књигу и мудрост, и дали смо им велику власт.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Па, било их је који су веровали, а било је и оних који су од тога људе одвраћали. А Пакао је довољан као ужарени огањ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Заиста, оне који не верују у речи и доказе Наше Ми ћемо у Ватру бацити, па када год им се коже испеку, заменићемо их другим кожама, како би патњу осетили. Аллах је, доиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'А оне који верују и чине добра дела Ми ћемо да уведемо у рајске баште кроз које теку реке. Тамо ће заувек да остану и супруге очишћене у њима ће да имају; и у велику хладовину ћемо да их уведемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'Аллах вам, заиста, наређује да послове од поверења дате онима којима заслужују, а када људима судите - да праведно судите. Савет Аллахов је, уистину, диван и Аллах је, заиста, Свечујући и Свевидећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'О ви који верујете, покоравајте се Аллаху и покоравајте се Посланику и надлежнима између вас. А ако се у нечему не слажете, обратите се Аллаху и Посланику, ако верујете у Аллаха и Последњи дан. Тако је боље и лепше поступити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Зар не видиш оне који тврде да верују у оно што је објављено теби и у оно што је објављено пре тебе како желе да им се пред лажним судијом суди, иако им је наређено да у њега не верују?! А ђаво само жели да их у велику заблуду одведе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'И када им се каже: „Приступите овоме што је Аллах објавио и приступите Посланику“, видиш лицемере како се од тебе сасвим окрећу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'А шта ће тек да буде када их погоди невоља због дела њихових руку, па ти дођу заклињући се Аллахом: „Ми смо само хтели да добро и право поступимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'То су они за које Аллах зна шта је у срцима њиховим, па окрени се од њих и саветуј их, и реци им оно што ће да их дотакне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'А ми нисмо ниједног посланика послали, осим да би му се покоравало уз Аллахово одобрење. А да ти они дођу када сами себи учине неправду и замоле Аллаха да им опрости, па да и Посланик замоли да им се опрости, они би видели да Аллах, заиста, прима покајање и да је милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'И, тако Ми Господара твога, они неће да верују све док за судију у међусобним споровима тебе не прихвате, а потом у душама својим не осете тегобу због онога што си одредио и сасвим се не покоре!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'И да смо Ми њима прописали: „Да сами себе поубијају!“ Или: „Да се иселе из свога завичаја!“ Мало ко од њих би то учинио! А када би поступили онако како им се саветује, било би им боље и у вери чвршће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'И тада бисмо им Ми, од Нас, велику награду дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'И на Прави пут бисмо их упутили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Они који су покорни Аллаху и Посланику Мухаммеду биће у друштву оних које је Аллах благословио: веровесника, оних који срцем искрено и у потпуности верују, оних који су својим животима посведочили на Аллаховом путу и честитих људи, а дивно ли је то друштво!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'То обиље је од Аллаха и довољно је што Аллах све то добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'О ви који верујете, будите опрезни и идите у борбу у групама, или одједном сви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'Међу вама има, заиста, оних који ће да оклевају, па ће, ако вас погоди невоља, такав да каже: „Сам Аллах ме благословио што са њима нисам био.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'А ако вас од Аллаха добро задеси, он ће, као да између вас и њега није било пријатељства, сигурно да каже: „Камо среће да сам са њима био, велики плен бих добио!?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, 'И нека се зато на Аллаховом путу верници боре против оних који живот на oвом свету купују за живот на Будућем свету, а онога ко се бори на Аллаховом путу, па погине или победи, Ми ћемо, сигурно, великом наградом да наградимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Шта је са вама па се не борите на Аллаховом путу за немоћне; за мушкарце, жене и децу који говоре: „Господару наш, избави нас из овог града чији су становници насилници, одреди нам заштитника и дај нам помагача!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'Они који верују боре се на Аллаховом путу, а они који не верују боре се на ђавољем путу. Зато се борите против ђавољевих штићеника, а ђавоље лукавство, заиста, је слабо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Зар ниси видео оне којима је речено: „Суздржите се од борби, већ молитву обављајте и милостињу дајте.“ А када им би прописана борба, одједном се група њих побоја људи, као што се Аллаха боји, или још више, и рекоше: „Господару наш, зашто си нам борбу прописао? Да си нам то до одређеног времена одложио!?“ Реци: „Уживање на овом свету је кратко, а онај свет је бољи за богобојазне.“ А вама, ни колико трун, неправда неће да буде учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, 'Где год били, стићи ће вас смрт, па макар били и у високим кулама! Ако их задеси какво добро, они кажу: „То је од Аллаха!“ А ако их задеси какво зло, они говоре: „То је због тебе (Мухаммеде)!“ Реци: “Све је од Аллаха!“ Па шта је са овим људима?! Они као да не разумеју шта им се говори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Добро које те човече задеси, то је од Аллаха, а зло које те задеси, то је од тебе. А Ми смо те Мухаммеде као посланика послали људима, а Аллах је довољан сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Ко се покори Посланику, покорио се и Аллаху, а ко се окрене, па Ми те нисмо послали да им чувар будеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, 'Они лицемери говоре: “Покоравамо се!“ А када од тебе оду, неки од њих смишљају ноћу другачије него што ти говориш. Аллах записује оно што они смишљају ноћу. Зато се окрени од њих и у Аллаха се поуздај, а довољан је заштитник Аллах!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'А зашто они не размишљају о Кур''ану? Јер, да је он од некога другог, а не од Аллаха, они би у њему нашли многе противречности.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'А када им дође нешто што се односи на сигурност или страх, они то разгласе. А да то препусте Посланику или својим претпостављеним, то би сигурно од њих сазнали они који то испитују. А да није Аллахове доброте према вама и Његове милости, ви бисте, осим неколицине, ђавола следили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Зато се бори на Аллаховом путу, не обавезујући осим себе, а вернике подстичи. Аллах ће да заустави силу оних који не верују, а Аллах је од њих силнији и казне Његове су строжије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Ко се буде залагао за добро, и он ће да има удео у томе, а ко се буде залагао за зло, и он ће да има удео у томе. А Аллах над свим надзире.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Када поздрављени будете, на лепши начин узвратите, или исто отпоздравите, а Аллах, заиста, све обрачунава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Аллах, осим Кога другог истинског бога нема, сигурно ће да вас сакупи на Судњем дану, у што нема нимало сумње, а чији је говор истинитији од Аллаховог?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'Зашто се подвајате када су у питању лицемери које је Аллах вратио у неверство због онога што су сами заслужили? Зар желите на Прави пут да упутите оне којима је Аллах дао да су у заблуди?! А коме Аллах да па је у заблуди, ти му нећеш наћи Пут!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'Они би волели да и ви не верујете као што они не верују, па да будете једнаки. Зато, између њих не узимајте пријатеље док се не иселе на Аллаховом Путу. А ако се окрену, онда их хватајте и убијајте где год их нађете и између њих пријатеље и помагаче не узимајте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Осим оних који се склоне код народа са којим ви имате уговор, или дођу код вас, јер им је тешко да се боре против вас или свога рода. А да Аллах хоће, он би их окренуо против вас, па би се против вас борили! Ако вас они оставе на миру и не боре се против вас, него вам понуде мир, онда вам Аллах не даје право да их нападате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'Ви ћете налазити друге који желе бити сигурни од вас и народа свог, па када год буду враћени у смутњу, они јој се још више предају. Ако се они не окане вас, и не понуде вам мир, и ако вас се не клоне, онда их хватајте и убијајте где год стигнете, а Ми смо вам за борбу против њих јасан доказ дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'Верник не може да убије верника осим грешком, а ко убије верника грешком, он мора да ослободи роба верника, и да преда крварину његовој породици, осим ако они то опросте. Ако он припада народу који вам је непријатељ, а верник је, он мора да ослободи једног роба верника! Ако, пак, припада народу са којим имате споразум, тада мора да плати крварину његовој породици и да ослободи роба верника! Ко то не нађе, обавезан је да пости два месеца узастопно, кајући се Аллаху. А Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'А ко намерно убије верника, казна му је Пакао у којем ће вечно да остане. На њега се Аллах расрдио и проклео га, а још му је и патњу велику припремио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'О ви који верујете, када кренете у бој на Аллаховом путу, све добро проверите и ономе ко вам назове поздрав мира немојте рећи: „Ти ниси верник!“ У жељи за пролазним добрима овосветског живота, јер код Аллаха су многа добра. Такви сте и ви били раније, па вам је Аллах даровао Своју милост. Зато, све добро проверите, а Аллах, заиста, добро зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Верници који се не боре, осим оних који су неспособни, не могу да се изједначе са онима који се боре на Аллаховом путу својим имецима и својим животима. Оне који се боре својим имецима и својим животима Аллах је одликовао за степен над онима који се не боре, и свима Аллах обећава лепу награду. А Аллах је борце, у односу на оне који се не боре, одликовао великом наградом;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'положајем код Њега, опростом и милошћу, а Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Заиста ће анђели, када буду узимали душе онима који су према себи учинили неправду, да питају: „Шта је било са вама?“ А они ће да одговоре: „Били смо немоћни на Земљи.“ „Зар Аллахова Земља није пространа и зар нисте могли некуда да се иселите?“ Рећи ће им они. Зато ће њихово пребивалиште да буде Пакао, а лоше је то коначно одредиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Изузетак су немоћни мушкарци, и жене, и деца, који не могу да се снађу и који не могу да пронађу излаз.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Аллах ће њима да опрости; Аллах стално брише грехе и опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Ко се исели на Аллаховом путу, на Земљи ће да нађе много места и обиља! А онај ко напусти свој дом, исељавајући се ради Аллаха и Његовога Посланика, па га стигне смрт, од Аллаха ће да добије награду. Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Када путујете по Земљи, није вам грех да молитву скратите ако се бојите да ће неко зло да вам учине неверници, јер неверници су вам, заиста, отворени непријатељи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Када ти будеш међу њима и будеш их предводио у молитви, нека једна група са тобом клања и нека своје оружје узму; и док буду лицем на тло, нека други буду иза вас, а онда нека дође друга група која није клањала и нека са тобом клањају, али нека држе оружје своје и нека опрезни буду. Неверници једва чекају да ви занемарите оружје своје и опрему своју, па да на вас сви одједном навале. А ако вам буде сметала киша или будете болесни, није вам грех да оружје своје одложите, али, опрезни будите. Аллах је, заиста, неверницима припремио понижавајућу патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'А када молитву завршите, Аллаха спомињите, и стојећи, и седећи, и лежећи на боковима. А када будете сигурни, молитву обављајте у потпуности; молитва је, уистину, обавезна верницима у одређеним временским периодима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'И немојте да малаксате трагајући за непријатељем; ако ви трпите бол, трпе и они бол као и ви, а ви се још од Аллаха надате ономе чему се они не надају. Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Ми теби објављујемо Књигу с Истином, да људима судиш онако како ти Аллах показује па не буди бранилац издајицама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'И Аллаха моли за опрост; Аллах, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'И не заузимај се за оне који сами себе изневеравају, Аллах, заиста, не воли онога који је издајник грешник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'Они се крију од људи, а не крију се од Аллаха, а Он је са њима и када ноћу смишљају речи којима Он није задовољан. А Аллах све што они раде, обухвата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'Ето, ви се заузимате за њих у животу на овом свету, а ко ће да се за њих заузима пред Аллахом на Судњем дану, или ко ће да им буде заступник?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Ко учини какво зло, или према себи учини неправду, а затим Аллаха замоли да му опрости, наћи ће да Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Ко уради грех, на своју штету га је урадио, а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Ко почини преступ или грех, а потом за то оптужи недужног човека, натоварио је на себе и клетву и очигледни грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Да није Аллахове доброте и Његове милости према теби, једна група њих би настојала да те заведе, али они само себе заводе, а теби не могу ништа да науде. Аллах теби објављује Књигу и мудрост и подучава те ономе што ниси знао и Аллахово добро према теби је огромно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'Нема добра у многим њиховим говорима, осим у говору оног ко тражи да се милостиња удељује, или добро чини, или успоставља мир међу људима. Ономе ко то чини из жеље за Аллаховим задовољством, Ми ћемо велику награду да дамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'А онога ко се супротстави Посланику, након што му јасно буде показан Прави пут, и следи пут који није пут верника, пустићемо да чини шта је наумио, и бацићемо га у Пакао, а лоше је то коначно одредиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Аллах, заиста, неће да опрости да се Њему ишта у обожавању придружује, а коме хоће опростиће све осим тога; онај ко Аллаху ишта у обожавању придружује - заиста је далеко залутао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'Они мимо Аллаха само женске кипове призивају, а не призивају другог до Сотону пркосног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Аллах га је проклео, а он је казао: „Ја ћу сигурно да преотмем за себе одређени део Твојих слугу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'И сигурно ћу да их наводим у заблуду, и сигурно ћу лажним надама да их мамим, и заповедићу им сигурно да уши стоци режу, и сигурно ћу да им наредим да Аллахова створења мењају!“ А ко Сотону, уместо Аллаха, прихвати за заштитника, он је на очигледном губитку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'Он им празна обећања даје и лажним надама их мами. А оно што им Сотона обећава само је обмана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'То су они чије је пребивалиште Пакао, и они из њега неће спаса наћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'А оне који верују и чине добра дела Ми ћемо да уведемо у рајске баште кроз које теку реке, и у којима ће вечно да остану. Аллахово обећање је истинито, а чије су речи од Аллахових истинитије?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, 'То неће бити ни по вашим жељама, ни по жељама следбеника Књиге; онај који ради зло, биће за то кажњен и неће наћи, мимо Аллаха, ни заштитника ни помагача,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'а онај који чини добро, био мушкарац или жена, а верник је, ући ће у Рај и никоме ни колико трун неправде неће бити учињено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'А ко је боље вере од онога ко преда себе Аллаху, а притом је доброчинитељ и следи веру Аврама монотеисте?! А Аллах је узео Аврама за пријатеља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'Аллахово је све што је на небесима и што је на Земљи. Аллах све обухвата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Они траже од тебе прописе о женама. Реци: „Аллах ће да вам објасни прописе о њима и о ономе што вам се чита у Књизи о женама - сиротицама, којима не дајете оно што им је прописано, а не желите да се њима ожените, и о нејакој деци, и о томе да према сирочадима праведно поступате. А Аллах сигурно зна за добро које учините.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Ако се нека жена плаши мужеве мржње или избегавања, онда се они неће огрешити ако се међусобно нагоде, а нагодба је боља. Људске душе склоне су похлепи. И ако ви будете лепо поступали и Аллаха се бојали - па Аллах у потпуности зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Ви нећете моћи потпуно једнако да поступате према супругама својим ма колико то желели. И немојте према некој сасвим нагињати па да неку учините као да је без мужа, а неразведена. А ако се поправите и Аллаха бојите, па Аллах, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'А ако се њих двоје ипак раставе, Аллах ће, из обиља Свога, да их учини независним. Аллах је неизмерно дарежљив и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'Аллахово је оно што је на небесима и оно што је на Земљи. Ми смо онима којима је дата Књига пре вас, а и вама, већ заповедили да се бојите Аллаха. А ако не будете веровали, па, уистину, Аллахово је оно што је на небесима и оно што је на Земљи, Аллах је независтан и хваљен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'Аллахово је све оно што је на небесима и на Земљи, и Аллах је као заштитник довољан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'Ако Он хоће, вас ће уклонити, о људи, а друге ће довести! Он је у могућности да то учини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Онај који жели награду на овом свету, па код Аллаха је награда и овога и онога света; Аллах је Свечујући и Свевидећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'О ви који верујете, будите увек праведни, сведочите ради Аллаха, па макар то било против вас самих, или родитеља и родбине. Свеједно био онај о коме сведочите богат или сиромах, па Аллах је пречи њима! И не следите страсти, како не бисте били неправедни. А ако будете криво сведочили или сведочење избегавали, па Аллах, заиста, у потпуности зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'О ви који верујете, верујте у Аллаха и Његовог Посланика, и у Књигу коју Он објављује Своме Посланику и у књиге које је објавио пре. А онај који не буде веровао у Аллаха, и у Његове анђеле, и у Његове књиге, и у Његове посланике, и у Последњи дан - далеко је залутао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'Онима који су били верници, а затим постали неверници, па опет постали верници и поново постали неверници, и појачали неверовање, Аллах, заиста, неће да опрости и неће да им укаже на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'Болну патњу навести лицемерима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, 'који присно пријатељују с неверницима, мимо верника! Зар од њих траже моћ, а сва моћ припада само Аллаху?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'Он вам је већ у Књизи објавио: „Када чујете да су Аллахове речи предмет порицања и изругивања, не седите са онима који то чине док не ступе у други разговор, иначе, бићете као они.“ Аллах ће, сигурно, да састави у Пакао све лицемере и невернике,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, 'оне који ишчекују шта ће да буде са вама. Па ако вам Аллах дарује победу, они говоре: „Зар нисмо били уз вас“, а ако срећа послужи невернике, онда говоре њима: „Зар нисмо могли да вас победимо, и зар вас нисмо одбранили од верника?!“ На Судњем дану Аллах ће свима да вам пресуди! А Аллах неће да пружи прилику неверницима да униште вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Лицемери, заиста, настоје да преваре Аллаха, а Он ће њих да надмудри. Када устају да молитву обављају, мрзовољно се дижу и приказују се свету, а Аллаха само мало спомињу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Колебају се између веровања и неверовања, нити су са овима нити са онима. А ономе коме Аллах да па је у заблуди нећеш наћи пут ка Упути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'О ви који верујете, не узимајте за заштитнике и пријатеље невернике уместо верника! Зар хоћете да пружите Аллаху очигледан доказ против себе?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Лицемери ће, заиста, да буду на самом дну Пакла и ти нећеш да им нађеш помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Осим оних који се покају и поправе и који чврсто Аллаха прихвате и веру своју у Аллаха искрено испоље, они ће да буду са верницима, а Аллах ће, сигурно, верницима велику награду да подари.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Зашто би вас Аллах кажњавао ако будете захваљивали и веровали!? Аллах је захвалан и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Аллах не воли да се о злу гласно говори, то може само онај коме је учињена неправда. А Аллах је Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Било да ви добро дело учините јавно, или га сакријете, или неправду опростите - па Аллах стално брише грехе и свемоћан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Они који у Аллаха и Његове посланике не верују и желе да између Аллаха и Његових посланика у веровању направе разлику, па говоре: „У неке верујемо, а у неке не верујемо“, и желе да између тога некакав став заузму,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'они су заиста прави неверници, а Ми смо неверницима припремили понижавајућу патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'А оне који у Аллаха и Његове посланике верују и ниједног од њих не издвајају - Он ће, сигурно, да награди. А Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'Они којима је дата Књига траже од тебе да им са неба спустиш Књигу. Па од Мојсија су тражили и више од тога, кад су рекли: „Покажи нам Аллаха!“ Па их је, због неправде њихове, муња погодила. После су, када су им очигледни докази показани, теле за божанство прихватили, али смо и то опростили, а Мојсију смо против њих очигледан доказ дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'И изнад њих смо брдо дигли, због завета који су дали, и рекли смо им: „На капију погнутих глава уђите!“ И још смо рекли: „Суботу не скрнавите!“ И од њих смо чврсто обећање узели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Зато што су завет прекршили и што у Аллахове речи и доказе нису поверовали, што су без разлога веровеснике убијали и што су говорили: „Наша срца су окорела“, Аллах је, због неверовања, њихова срца запечатио, па их само мало верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'И због њиховог неверовања и због изношења тешке клевете против Марије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'И због речи њихових: „Ми смо убили Месију, Исуса, Маријиног сина, Аллаховог посланика.“ А нису га убили, ни распели, већ им се причинило. Они који су се о њему у мишљењу разишли, заиста су у сумњи у погледу њега; о томе ништа поуздано не знају, само се за нагађањем поводе; а сигурно је да га нису убили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'већ га је Аллах уздигао Себи. А Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'И нема ниједног следбеника Књиге који, пре његове смрти, неће у њега како треба да поверује, а на Судњем дану он ће против њих да сведочи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'И због неправде Јевреја Ми смо им нека лепа јела забранили, која су им била дозвољена, и због тога што су многе од Божјег пута одвраћали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'И зато што су узимали камату, а било им је забрањено, и зато што су туђе богатство узимали на недозвољен начин. А за невернике међу њима Ми смо припремили болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Али они међу њима који су у знање дубоко проникли, и верници који верују у оно што се објављује теби Мухаммеде и у оно што је објављено пре тебе, нарочито они који молитву обављају и они који обавезну милостињу дају и у Аллаха и Последњи дан верују - њима ћемо сигурно велику награду да дамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Ми објављујемо теби као што смо објављивали Ноју и веровесницима после њега, објављивали смо Авраму, и Јишмаелу и Исаку и Јакову и потомцима, и Исусу, и Јову, и Јони, и Мојсију, и Арону, и Соломону, а Давиду смо дали Псалме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'и послали смо посланике о којима смо ти пре казивали и посланике о којима ти нисмо казивали. А Аллах је сигурно са Мојсијем разговарао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, 'Послали смо посланике који су радосне вести и опомене доносили, да људи после посланика не би имали никаквог оправдања пред Аллахом. А Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Аллах сведочи да је истина оно што ти објављује, објављује га Својим знањем, а и анђели сведоче. А довољан је Аллах као сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Заиста, они који не верују и који друге од Аллаховог пута одвраћају, далеко су залутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Онима који не верују и који чине неправду, Аллах, заиста, неће да опрости и неће на пут да их упути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'осим на пут у Пакао, у којем ће вечно и заувек да остану; то је Аллаху лако.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'О људи, Посланик вам је већ донео Истину од вашег Господара; зато, верујте - боље вам је! А ако не будете веровали - па заиста је Аллахово све што је на небесима и на Земљи. Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'О ви којима је дата Књига, не застрањујте у свом веровању и о Аллаху говорите само истину! Месија, Исус, Маријин син, само је Божји посланик, и створен је речју Његовом, коју је Марији доставио, и живот му дао; зато верујте у Аллаха и Његове посланике и не говорите: „Тројица су!“ Престаните, боље вам је! Заиста је једини бог само Аллах, Узвишен нека је Он, зар да има дете?! Његово је оно што је на небесима и оно што је на Земљи, и Аллах је свима довољан заштитник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Месија се неће устегнути да призна да је Аллахов слуга, па ни анђели, Њему блиски. А оне који се буду устезали да само Њега обожавају, и оне који се буду охолили, Аллах ће да сакупи пред Собом...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'Вернике који су добра дела чинили Он ће према заслузи да награди и још ће, из обиља Свога, више да им подари; а оне који су надмени били и охолили се – ставиће на болне муке и они неће да нађу себи, мимо Аллаха, ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'О људи, Доказ вам је већ стигао од вашег Господара и Ми смо вам објавили Кур''ан - Јасно Светло.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Оне који буду у Аллаха веровали и чврсто Га се држали Он ће сигурно да уведе у милост Своју и благодат и Правим путем ће Себи да их упути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Они траже од тебе тумачење. Реци: „Аллах ће да вам каже пропис о ономе ко нема ни родитеља ни деце: ако неко умре и не буде имао детета, а има сестру, њој припада половина његове оставштине, а он ће да наследи њу ако она не буде имала дете; а ако су две сестре, њима припадају две трећине његове оставштине. А ако су они браћа и сестре, онда ће мушки део наследства да буде једнак износу два дела женског. То вам Аллах објашњава, да не залутате. А Аллах све добро зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'О ви који верујете, испуњавајте уговорене обавезе! Дозвољава вам се стока, али не она која ће да вам буде споменута; док обреде ходочашћа обављате није вам дозвољено да ловите. Уистину, Аллах прописује шта Он хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'О ви који верујете, не скрнавите Аллахове обреде ходочашћа, ни свети месец, ни жртвенице, нарочито оне огрлицама обележене, ни оне људе који су кренули ка часној Каби желећи од Господара свога обиље и задовољство. А када обреде ходочашћа обавите, онда ловити можете. И нека вас мржња коју према неким људима носите, зато што су вам спречили приступ Часној џамији, никако не наведе да неправедни будете! Потпомажите се у доброчинству и богобојазности, а не потпомажите се у греху и скрнављењу правде и бојте се Аллаха; Аллах, заиста, страшно кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'Забрањене су вам угинуле животиње, и крв, и свињско месо, и она животиња која је заклана у нечије друго а не у Аллахово име, и која је удављена и убијена; и која је стрмоглављена, и рогом убодена, или од звери начета, осим ако сте је преклали, и која је на жртвеницима жртвована, и забрањује вам се гатање стрелицама. То је непослушност. Данас су неверници изгубили сваку наду да ћете ви да отпаднете од своје вере, зато се не бојте њих, већ се бојте Мене. Данас сам вам веру вашу усавршио и благодат Своју према вама употпунио и задовољан сам да вам Ислам буде вера. А ко год буде приморан на то, када влада глад, без намере да учини грех, па Аллах је, заиста, Опроститељ греха, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'Питају те шта им је дозвољено. Реци: „Дозвољена су вам лепа јела и оно што улове животиње које сте лову подучили, од онога чиме вас је Аллах научио. Једите оно што вам оне ухвате и спомените Аллахово име при томе, и бојте се Аллаха; Аллах, заиста, брзо своди рачуне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'Данас вам се дозвољавају сва лепа јела; и јела оних којима је дата Књига дозвољена су вам, и ваша су јела њима дозвољена, и честите жене вернице, и честите кћери оних којима је дата Књига пре вас, када им венчане дарове њихове подарите са намером да се њима ожените, а не да са њима блуд чините и да их за прилежнице узимате. А онај ко негира прописе вере - узалуд ће да му буду његова дела, и он ће, на оном свету, да буде међу губитницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'О ви који верујете, када хоћете да обавите молитву, лица своја и руке своје до иза лактова оперите, а главе своје потарите, и ноге своје до иза чланака оперите. Ако сте имали интимни однос, онда се окупајте; а ако сте болесни, или на путу, или ако сте извршили природну потребу, или ако сте имали однос са супругама, а не нађете воду, онда својим рукама чисту земљу дотакните и њима преко својих лица и својих руку пређите. Аллах не жели да вам причини потешкоће, већ жели да вас учини чистим и Своју благодат да вам употпуни, да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'И сетите се Аллахове благодати којом вас је обасуо и завета којим вас је обавезао, кад сте рекли: „Слушамо и покоравамо се! „И бојте се Аллаха! Заиста, Аллах добро зна све што је у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'О ви који верујете, извршавајте дужности према Аллаху, и праведно сведочите. Нека вас мржња коју према неким људима носите никако не наведе да будете неправедни! Будите праведни, то је најближе богобојазности, и бојте се Аллаха. Аллах, заиста, у потпуности зна оно што чините.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Аллах је онима који верују и добра дела чине обећао опрост и награду велику;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'А они који не верују и поричу речи и доказе Наше биће становници Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'О ви који верујете, сетите се Аллахове благодати према вама када су неки људи хтели да вас се дочепају, а Он је задржао њихове руке. И бојте се Аллаха, и нека се верници поуздају само у Аллаха!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Аллах је прихватио завет Израиљевих синова - а између њих смо били поставили дванаест старешина - и Аллах је рекао: „Ја сам, заиста, са вама! Ако будете молитву обављали и обавезну милостињу давали, и ако будете у посланике Моје веровали, помагали им и драге воље зајам давали Аллаху, сигурно ћу да прекријем ваша лоша дела и увешћу вас у рајске баште кроз које реке теку. А онај међу вама који ни после тога не буде веровао - скренуо је са правог Пута.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Али, зато што су прекршили свој завет, Ми смо их проклели и њихова срца смо учинили окрутним. Они су уклањали речи са места на којима су биле, а запоставили су добар део онога чиме су били опомињани. И ти ћеш, осим у случају мало њих, непрестано да наилазиш на њихово вероломство, али ти пређи преко тога и опрости им! Аллах, уистину, воли оне који чине добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'И од оних који говоре: „Ми смо хришћани.“ Ми смо завет прихватили, али су и они запоставили део онога чиме су били опомињани, зато смо међу њима убацили непријатељство и мржњу до Судњег дана; а Аллах ће сигурно да их обавести о ономе што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'О ви којима је дата Књига, дошао вам је Наш Посланик да вам укаже на много шта што ви из Књиге кријете, а преко много чега ће и да пређе. А од Аллаха вам долази светлост и Књига јасна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Њоме Аллах упућује на путеве спаса оне који настоје да стекну Његово задовољство и изводи их, дозволом Својом, из тмина на светло и упућује их на прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Неверници су они који говоре: „Заиста је Аллах Месија Маријин син!“ Реци: „Ко може да спречи Аллаха да, ако хоће, уништи Месију, Маријиног сина, и његову мајку, и све оне који су на Земљи?“ Аллахова је власт на небесима и на Земљи и на ономе што је између њих; Он ствара шта хоће, и Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Јевреји и хришћани кажу: „Ми смо деца Аллахова и Његови миљеници.“ Реци: „Па зашто вас Он кажњава због ваших греха?“ А није тако! Ви сте као и остали људи које Он ствара: коме хоће Он ће да опрости, а кога хоће Он ће да подвргне патњи. Аллахова је власт на небесима и на Земљи и на ономе што је између њих, и код Њега је коначно одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'О ви којима је дата Књига, дошао вам је Наш Посланик, након што је неко време прекинуто слање посланика, да вам објасни, да не бисте рекли: „Није нам долазио ни онај који доноси радосне вести ни онај који упозорава!“ Па, дошао вам је, ето, онај који доноси радосне вести и који упозорава. А Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'А кад Мојсије рече свом народу: „О народе мој, сетите се Аллахове благодати према вама када је неке од вас учинио веровесницима, и када вас је учинио владарима, и дао вам оно што није дао ниједном народу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, '„О народе мој, уђите у благословљену земљу коју вам је Аллах доделио, и не посрћите назад па да се вратите као губитници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Они рекоше: „О Мојсије! У њој је немилосрдан народ и ми у њу нећемо да уђемо док год они из ње не изађу; па, ако они из ње изађу, ми ћемо онда сигурно да уђемо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'Два човека која су се бојала Аллаха и којима је Он даровао Своју благодат - рекоше: „Навалите на њихову капију, па кад кроз њу прођете, бићете сигурно победници; а у Аллаха се поуздајте, ако сте верници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, '"О Мојсије", рекоше они, "док год су они у њој, ми нећемо у њу да улазимо! Идите ти и Господар твој па се борите, а ми одавде нећемо да се померимо!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, '„Мој Господару“, рече Мојсије, „ја осим себе имам моћ само над својим братом; зато пресуди између нас и грешних људи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, '„Четрдесет година они ће земљом да лутају“, рече Он, „јер ће Света земља да им буде забрањена, а ти не тугуј за грешним народом.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'И испричај им вест о двојици Адамових синова, онако како је било, кад су њих двојица жртву принели, па је од једног била примљена а од другог није, па је он рекао: „Сигурно ћу да те убијем!“ А први рече: „Аллах прима само од оних који су богобојазни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'И кад би ти пружио своју руку према мени да ме убијеш, ја не бих пружио своју према теби да те убијем. Заиста се ја бојим Аллаха, Господара светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Ја желим да ти понесеш и мој и свој грех и да будеш становник у Ватри. А она је казна за све неправеднике."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'И душа га наведе да убије брата свога, па га он уби и постаде један од губитника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Аллах је онда послао једног гаврана да копа по земљи да би му показао како да закопа мртво тело свога брата. Рече: „Тешко мени, зар и ја не могу, као овај гавран, да закопам мртво тело свог брата!“ И поче да се каје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'Због тога смо Ми прописали Израиљевим синовима: ако неко убије некога који није убио никога, или онога који на Земљи неред не чини, као да је све људе поубијао; а ако неко буде узрок да се нечији живот сачува, као да је свим људима живот сачувао. Наши су им посланици доносили јасне доказе, али су многи од њих, и после тога, заиста, на Земљи све границе зла прелазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Казна за оне који се против Аллаха и Његовог Посланика боре и који неред на Земљи чине јесте: да буду убијени, или разапети, или да им се унакрст одсеку руке и ноге, или да буду прогнани из земље. То им је понижење на овом свету, а на оном свету их чека велика патња,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'али не и за оне који се покају пре него што их се домогнете. И знајте да Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'О ви који верујете, Аллаха се бојте и тражите оно што ће да вас приближи Њему, и на Његовом путу се борите да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Заиста, кад би све оно што је на Земљи било у поседу неверника, и још толико, и кад би хтели тиме да се откупе од патње на Судњем дану, не би им било примљено. Њих чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Зажелеће они да изађу из Ватре, али из ње им неће бити изласка, и њих чека непрестана патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, 'Крадљивцу и крадљивици одсеците шаку, нека им то буде казна за оно што су учинили и опомена од Аллаха! Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'А ономе ко се после своје неправде покаје и поправи се - Аллах ће сигурно да опрости. Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Ти сигурно знаш да само Аллах има власт на небесима и на Земљи. Он патњи подвргава онога кога хоће, а прашта ономе коме хоће. Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'О Посланиче, нека те не забрињавају они што неверовање брзо испољавају, они који устима својим говоре: „Верујемо“, а срцем не верују, и Јевреји, који измишљотине много слушају и који туђе речи радо прихватају, а теби не долазе; који изврћу смисао речи и говоре: „Ако вам се овако пресуди, онда пристаните на то, а ако вам се не пресуди, онда немојте да пристанете!“ А ономе коме Аллах жели заблуду, ти, у односу на Аллаха, не можеш ништа да му помогнеш. То су они чија срца Аллах не жели да очисти; њих на овом свету чека понижење, а на Будућем свету огромна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, 'Они много слушају лажи и много оно што је забрањено једу; па ако ти дођу, ти им или пресуди или се окрени од њих; ако се окренеш од њих, они не могу нимало да ти науде. А ако им будеш судио, суди им право. Заиста, Аллах воли праведне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'А откуд да они траже од тебе да им судиш кад имају Тору, у којој су Аллахови прописи? Они ни после твоје пресуде не би били задовољни, и они нису верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Ми смо објавили Тору у којој је упута и светло. По њој су Јеврејима судили веровесници који су били послушни Аллаху, и побожни људи, и учени, од којих је тражено да чувају Аллахову књигу, и они су над њом бдели. Зато се, кад будете судили, не бојте људи, већ се бојте Мене, и не замењујте Моје речи за нешто што мало вреди! А они који не суде према оном што је Аллах објавио, они су, заиста, неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Ми смо им у њој прописали: глава за главу, и око за око, и нос за нос, и уво за уво, и зуб за зуб, и за ране је одмазда, а онај ко од одмазде одустане, биће му то искупљење од греха. Они који не суде према ономе што је Аллах објавио, заиста, су неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'После њих смо Исуса, Маријиног сина, послали, који је признавао Тору објављену пре њега, а њему смо дали Јеванђеље, у коме је била упута и светло, и да потврди Тору, објављену пре њега, у којој је, такође, била упута и поука богобојазнима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'и следбеницима Јеванђеља смо били наредили да суде према ономе што је објавио Аллах у њему. Они који нису судили према ономе што је објавио Аллах - заиста су према Аллаху непокорни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'А теби објављујемо Књигу, са Истином, да потврди књиге објављене пре и да над њима бди. И ти им суди према ономе што објављује Аллах и не поводи се за њиховим прохтевима, и не одступај од Истине која ти долази; свима вама смо закон и правац прописали. А да је Аллах хтео, Он би вас учинио следбеницима једног верозакона, али, Он хоће да вас искуша у ономе што вам прописује, зато се такмичите ко ће више да учини добра; Аллаху ћете сви да се вратите, па ће о ономе у чему сте се разилазили да вас обавести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'И суди им према ономе што објављује Аллах и не поводи се за њиховим прохтевима, и причувај их се да те не одврате од нечега што ти Аллах објављује. А ако се окрену, ти онда знај да Аллах жели да их казни због неких њихових греха. А многи људи су, заиста, грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Зар они да траже да им се као у паганско доба суди!? А ко је од Аллаха бољи судија народу који чврсто верује?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'О ви који верујете, не узимајте за заштитнике и присне пријатеље Јевреје и хришћане! Они су сами себи заштитници и пријатељи! А њихов је и онај међу вама који их за заштитнике и пријатеље прихвати; Аллах, уистину, неће да упути на прави пут људе неправденике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'Зато ти видиш оне чија су срца болесна како журе да са њима склопе партнерство, говорећи: „Бојимо се да нас каква невоља не задеси.“ А Аллах ће сигурно победу или нешто друго од Себе дати, па ће они, због онога што су крили у својим душама, да се кају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'А они који верују рећи ће: „Јесу ли то они који су се заклињали Аллахом, својом најјачом заклетвом, да су, заиста, са вама?“ Дела њихова биће поништена, и они ће да буду губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'О ви који верујете, ако неко од вас од своје вере отпадне - па, Аллах ће сигурно уместо њих да доведе људе које Он воли и који воле Њега, према верницима понизне, а према неверницима поносите; они ће да се боре на Аллаховом путу и неће да се боје ничијег прекора. То је Аллахов дар који Он даје коме хоће - а Аллах је неизмерно дарежљив и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Ваши су заштитници само Аллах и Његов Посланик и верници који понизно обављају молитву и дају обавезну милостињу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Онај ко за заштитника узме Аллаха и Посланика Његовог и вернике - па, Аллахова страна ће, свакако, да победи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'О ви који верујете, не узимајте за заштитнике и пријатеље оне који узимају вашу веру за подсмех и забаву, били то они којима је пре вас дата Књига, или били неверници - и Аллаха се бојте ако сте верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'И кад позивате на молитву, и то узимају за подсмех и забаву, зато што су они људи који не разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'Реци: „О ви којима је дата Књига, зар да нас осуђујете зато што верујемо у Аллаха и у оно што нам се објављује, и у оно што је објављено пре, а већина вас сте непокорни према Аллаху!?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'Реци: „Хоћете ли да вам кажем ко су гори од њих и које ће Аллах још теже да казни? Они које је Аллах проклео и на које се расрдио и учинио од њих мајмуне, и свиње, и оне који су обожавали ђавола - њих чека најгоре место и они су најдаље одлутали са Правог пута.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'А када вам долазе, они говоре: „Верујемо!“ Али они долазе као неверници, а такви и одлазе, а Аллах добро зна оно што они крију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'Видиш многе од њих како срљају у грехе и насиље и како узимају оно што је забрањено; ружно ли је то како поступају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'Требало би да их честити и учени људи одвраћају од лажног говора и забрањеног јела; ружно ли је то како поступају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Јевреји говоре: „Аллахова рука је стиснута!“ Стиснуте биле њихове руке и проклети били због тога што говоре! Напротив, обе Његове руке су пружене, Он удељује колико хоће. А то што ти објављује твој Господар појачаће код многих од њих осионост и неверовање. Ми смо убацили међу њима непријатељство и мржњу све до Судњег дана. Кад год покушају да потпале ратну ватру, Аллах је угаси. Они настоје да на Земљи праве смутњу, а Аллах не воли смутљивце.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'А да они којима је дата Књига верују и чувају се, Ми бисмо прешли преко њихових ружних поступака и сигурно бисмо их увели у рајске баште уживања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Да се они придржавају Торе и Јеванђеља и онога што им објављује њихов Господар, имали би опскрбу од онога што је изнад њих и од онога што је испод њихових ногу. Има их и постојаних, али ружно је оно што већина њих ради.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'О Посланиче, казуј оно што ти се објављује од твога Господара – ако не учиниш, онда ниси доставио Његову посланицу - а Аллах ће од људи да те штити. Аллах, заиста, неће да упути на Прави пут народ који не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'Реци: „О ви којима је дата Књига, ви нисте ни на чему ако се не будете придржавали Торе и Јеванђеља и онога што вам објављује ваш Господар. А то што ти објављује твој Господар појачаће, уистину, код многих од њих осионост и неверовање, али ти не очајавај због народа који не верује.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Они који су веровали, и они који су били Јевреји, и сабијци, и хришћани, они који су у Аллаха и у онај свет веровали и чинили добра дела – они уистину неће ничега да се боје и ни за чим они неће да тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Ми смо од Израиљевих синова узели завет и слали смо им посланике. Кад год би им који посланик донео оно што није годило њиховим душама, једне су у лаж угонили а друге убијали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, 'Мислили су да неће на муке да буду стављени, па су били и слепи и глуви, и онда кад је Аллах примио њихово покајање, многи од њих су опет били и слепи и глуви; а Аллах добро види оно шта они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Неверници су они који говоре: „Аллах је, заиста, Месија, Маријин син!“ А Месија је говорио: „О Израиљеви синови, обожавајте Аллаха, и мог и вашег Господара!“ Ко другом место које припада само Аллаху даје, Аллах ће улазак у Рај да му забрани и боравиште његово ће да буде Пакао; а неправедницима нико неће моћи да помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Неверници су они који говоре: „Аллах је, заиста, један од тројице!“ А само је један Бог! И ако се не окане онога што говоре, несносна патња ће, заиста, да стигне сваког од њих који остане неверник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Зашто се они не покају Аллаху и не замоле Његов опрост, а Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Месија, Маријин син, само је посланик, и пре њега су долазили и одлазили посланици, а његова мајка је искрено срцем веровала; и обоје су храну јели. Погледај како им Ми износимо јасне доказе, и погледај, затим, њих како се одмећу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'Реци: „Зар поред Аллаха обожавате нешто што не може да вам нанесе никакву штету, нити да вам прибави неку корист? А Аллах је, заиста, Свечујући и Свезнајући.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'Реци: „О ви којима је дата Књига, не застрањујте у своме веровању, супротно истини, и не поводите се за прохтевима људи који су још давно залутали, и многе су у заблуду одвели, и сами су скренули са правог пута.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'Језиком Давида и Исуса, Маријиног сина, проклети су они Израиљеви синови који нису веровали - зато што су били непокорни и увек су границе прелазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'Једни друге од зла која су чинили нису одвраћали. Ружно ли је, заиста, то како су поступали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'Ти видиш многе од њих како пријатељују са незнанобошцима. Ружно је, заиста, оно што припремају сами себи: да се Аллах на њих расрди и да у патњи остану вечно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'А да верују у Аллаха и Веровесника и у оно што се њему објављује, они са њима не би пријатељивали, али многи од њих су непокорни према Аллаху.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'Ти ћеш сигурно да нађеш да су онима који верују најљући непријатељи јевреји и незнанобошци; и свакако ћеш да нађеш да су верницима најближи пријатељи они који говоре: „Ми смо хришћани“, зато што међу њима има свештеника и монаха и што се они не охоле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, 'Када слушају оно што се објављује Посланику, видиш како им лију сузе из очију јер знају да је то Истина, па говоре: „Господару наш, ми верујемо, па упиши и нас међу оне који су посведочили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Зашто да не верујемо у Аллаха и у Истину која нам долази, када жудимо да Господар наш и нас уведе са добрим људима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'И Аллах ће, због онога што говоре, да им као награду подари рајске баште, кроз које теку реке, у којима ће вечно да бораве; а то ће да буде награда за све оне који чине добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'А они који не верују и поричу речи и доказе Наше - биће становници Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'О ви који верујете, не забрањујте себи оно што је лепо, што је Аллах дозволио, и не прелазите Аллахове границе! Заиста Аллах не воли оне који прелазе Његове границе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'И једите оно што вам даје Аллах, што је дозвољено и лепо; и бојте се Аллаха, у Којег верујете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Аллах неће да вас казни ако се ненамерно закунете, али ће да вас казни ако се намерно закунете. Откуп за прекршену заклетву је: да десет сиромаха нахраните уобичајеном храном којом храните своју децу, или да их обучете, или да ослободите роба ропства. А онај ко не буде могао - нека пости три дана. Тако се откупљујте за своје заклетве када се закунете; и о заклетвама својим брините се! Ето, тако вам Аллах објашњава Своје прописе, да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'О ви који верујете, опојна пића и коцка и кипови и стрелице за гатање одвратно су, Сотонино дело; зато се тога клоните, да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Сотона жели помоћу опојних пића и коцке да међу вама унесе непријатељство и мржњу и да вас одврати од сећања на Аллаха и обављања молитве. Па, хоћете ли да се оканите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'И будите послушни Аллаху и будите послушни Посланику и опрезни будите! А ако се окренете, онда знајте да је Наш Посланик дужан само да јасно обзнани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'Онима који верују и чине добра дела нема никаквог греха у ономе што су појели и попили пре забране, ако се клоне онога што им је забрањено и ако верују и чине добра дела, затим се боје Аллаха и верују и онда се греха клоне и чине добро. А Аллах воли оне који другима чине добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'О ви који верујете, Аллах ће да вас доводи у искушење са дивљачи која ће да буде надохват ваших руку и ваших копаља, да Аллах укаже на оног који Га се боји кад га нико не види. А онога ко и после тога учини насиље, чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'О ви који верујете, не убијајте дивљач док сте у одећи ходочашћа! Ономе од вас ко то намерно учини казна је да једну домаћу животињу, чију ће вредност да процене двојица ваших праведних људи, као жртву принесе код Ка''бе, или да се искупи тиме што ће, равно томе, да нахрани сиромахе или да пости, да би осетио погубност свог поступка. А Аллах је већ опростио оно што је било. Онога ко то опет уради - Аллах ће да казни. Аллах је силан и строг.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Вама се допушта да у мору ловите и да улов једете, да се њиме ви и путници користите, а забрањује вам се да на копну ловите док обреде ходочашћа обављате. И бојте се Аллаха, пред Којим ћете да будете сабрани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Аллах је учинио да Ка''ба, Света кућа, буде људима темељ сигурности и унапређења живота, а тако и свети месеци и жртвенице, нарочито оне огрлицама означене. То је зато да знате да Аллах зна оно што је на небесима и оно што је на Земљи, и да Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Знајте да Аллах строго кажњава, али и да опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Посланику је једино дужност да објави, а Аллах зна и оно што јавно чините и оно што сакријете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'Реци: „Није исто оно што је забрањено и оно што је дозвољено“, иако те изненађује мноштво онога што је забрањено. Зато се Аллаха бојте, о ви који разум имате, да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'О ви који верујете, не запиткујте о ономе што ће да вам причини непријатности ако вам буде објашњено; а ако будете питали за то док буде објављиван Кур''ан, биће вам објашњено; оно раније Аллах вам је већ опростио. А Аллах опрашта грехе и не жури са казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Неки су људи пре вас питали за то, па после у то нису поверовали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'Аллах није прописао ни бехиру ни саибу ни василу а ни хама; то они који не верују говоре о Аллаху лажи, и већина њих не разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'А када им се каже: „Приступите ономе што објављује Аллах, и приступите Посланику!“ Они одговарају: „Довољно нам је оно што смо од наших предака запамтили.“ Зар и ако њихови преци нису ништа знали и ако нису били на Правом путу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'О ви који верујете, брините се о себи; ако сте на Правом путу, неће вам наудити онај који је залутао! Аллаху ћете сви да се вратите и Он ће да вас обавести о ономе што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'О ви који верујете, када вам се приближи смрт, приликом давања опоруке нека вам посведоче двојица праведних од вас, или нека друга двојица, који нису ваши – ако сте на путу, а појаве се знаци смрти. А ако посумњате, задржите их после обављене молитве и нека се закуну Аллахом: „Ми заклетву ни за какву цену нећемо да продајемо, макар се радило и о каквом рођаку и сведочење које је Аллах прописао нећемо да ускратимо, јер бисмо тада заиста били грешници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'А ако се дозна да су њих двојица згрешила, онда ће њих да замене друга двојица од оних којима је нанесена штета, и нека се закуну Аллахом: „Наше заклетве су сигурно веродостојније од њихових заклетви, ми се нисмо криво заклели, јер бисмо тада, заиста, међу неправедницима били.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Тиме ће да буде најближе исправном сведочењу, и да се не плаше да ће њихове заклетве другим заклетвама да буду побијене. И бојте се Аллаха и слушајте! А Аллах неће да упути на Прави пут непокорне људе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, 'На дан када Аллах сакупи посланике и упита: „Како су вам се одазивали?“ Они ће да кажу: „Ми знања немамо; заиста Ти добро знаш све што је чулима недокучиво.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, 'Кад Аллах каже: „О Исусе, Маријин сине, сети се благодати Моје према теби и твојој мајци када сам те Духом благословљеним (анђелом Гаврилом) помогао па си са људима, у бешици и као зрео човек, разговарао; и када сам те научио писмености и мудрости, и Тори и Јеванђељу; и када си, Мојом дозволом, од блата нешто попут птице обликовао и у њу удахнуо, и када је она, Мојом дозволом, постала птица; и када си, Мојом дозволом, од рођења слепог и губавог излечио; и када си, Мојом дозволом, дизао мртве; и када сам од тебе одбио Израиљеве синове, кад си им ти донео јасне доказе, па су они међу њима који нису веровали - повикали: „Ово није ништа друго до јасна враџбина“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'и када Сам апостолима наредио: „Верујте у Мене и Мог Посланика“, они су одговорили: „Верујемо, а Ти буди сведок да смо муслимани."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'А када апостоли рекоше: „О Исусе, Маријин сине, може ли твој Господар трпезу са неба да нам спусти?“ Он рече: „Бојте се Аллаха, ако сте верници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, 'Ми желимо, рекоше они, са ње да једемо и да срца наша буду смирена и да се уверимо да си нам истину говорио, и да будемо они који ће о њој да сведоче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Исус, Маријин син, рече: „О Аллаху, Господару наш, спусти нам са неба трпезу да нам буде празник, и првима од нас и онима каснијим, и Твој знак , и опскрби нас, а Ти си Опскрбитељ најбољи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Аллах рече: „Ја ћу, заиста, да вам је спустим, али ћу оне међу вама који и после буду порицали да подвргнем патњи каквом никога међу световима нећу да мучим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'А када Аллах каже: „О Исусе, Маријин сине, јеси ли ти говорио људима: '' Прихватите мене и моју мајку као два бога уз Аллаха!''“ Он ће да каже: „Узвишен си Ти од тога! Мени не приличи да говорим оно што немам право. Ако сам ја то говорио, Ти то већ знаш; Ти знаш шта је у мени, а ја не знам шта је у Теби; Ти, заиста, добро знаш оно шта је чулима недокучиво.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'Ја сам им само говорио оно што си им Ти наредио: „Обожавајте Аллаха, и мог и вашег Господара!“ И ја сам био њима сведок док сам био међу њима, а кад си ме Ти к Себи узео, Ти си их једини надзирао; Ти над свиме надзиреш."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Ако их подвргнеш патњи, слуге су Твоје, а ако им опростиш, па, уистину си Ти Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Аллах ће рећи: „Ово је Дан у коме ће искренима да буде од користи њихова искреност; њима ће рајске баште, кроз које теку реке, да припадну; у њима ће да остану вечно и довека. Аллах ће њима задовољан да буде, а и они Њим. То ће да буде велики успех.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'Аллахова је власт на небесима и на Земљи и над оним што је на њима; Он над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'Сва хвала нека је Аллаху Који је створио небеса и Земљу и дао тмине и светло, али и поред тога они који не верују - друге изједначују са својим Господарем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'Он вас је створио од земље и рок одредио, а код Њега је и рок утврђени, а ви и поред тога сумњате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Он је Аллах на небесима и на Земљи, Он зна и што кријете и што показујете, и Он зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'А њима не дође ниједан доказ од њиховог Господара а да се од њега не окрену.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Они су занегирали Истину када им је дошла, али њима ће сигурно да стигну вести о ономе чему су се ругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Зар они не знају колико смо Ми нараштаја пре њих уништили, којима смо на Земљи дали могућности какве вама нисмо дали и којима смо слали обилату кишу и учинили да реке поред њих теку, па смо их, због њихових греха, уништавали, и друге нараштаје, после њих, стварали?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'А и да ти Мухаммеде спустимо Књигу на папиру и да је они рукама својим опипају, опет би они који не верују казали: „Ово заиста није ништа друго до јасна враџбина.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'И још говоре: „Зашто му није послат анђео?!“ А да анђеле пошаљемо, ствар би завршена била, и не би им било дато више времена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'А да га анђелом учинимо, опет бисмо га као човека створили и опет бисмо им учинили нејасним оно што им није јасно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Посланицима су се и пре тебе ругали, па је оне који су им се ругали стигло баш оно чему су се ругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'Реци: „Путујте по Земљи, затим погледајте како су завршили они који су посланике сматрали лажним!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, 'Упитај: „Чије је све оно што је на небесима и на Земљи?“ И одговори: „Аллахово!“ Он је Себи одредио да буде милостив. Он ће да вас сакупи на Судњем дану, у то нема никакве сумње. Они који су себе упропастили, па - они не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'Њему припада све што постоји у ноћи и дану; Он је Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'Реци: „Зар да узмем за заштитника неког другог поред Аллаха Који је небеса и Земљу, без претходног примера створио?! Он храни, а не бива храњен!“ Реци: „Мени је наређено да будем најпреданији и најпокорнији“, и никако не буди један од оних који друге поред Аллаха обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, 'Реци: „Ако будем непослушан Господару свом, ја се плашим патње на Великом дану.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'А онај ко буде поштеђен казне тога дана, Он му се смиловао, и то је очигледни успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'Ако те Аллах неком невољом погоди - па, нико осим Њега не може да је отклони; а ако ти какво добро подари - па, Он над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'А Он је Свепотчинитељ изнад слугу Својих, и Он је Мудри, Онај Који све у потпуности зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'Реци: „Чије је највеће сведочанство?“ И одговори: „Аллахово, Он ће између мене и вас да буде сведок. А мени се овај Кур''ан објављује да упозоравам њиме вас и оне до којих он допре. Зар ви, заиста, тврдите да поред Аллаха има и других богова?“ Реци: „Ја не тврдим.“ Реци: „Он је Једини Бог, и ја немам ништа са тиме што ви Њему друге у обожавању придружујете.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Они којима смо дали Књигу познају Посланика као што познају своје синове; они који су себе упропастили, па – они не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Има ли већег неправедника од онога који о Аллаху говори лажи или не признаје Његове речи и доказе?! Неправедници заиста неће успети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'А на Дан када их све сакупимо, а затим упитамо оне који су друге обожавали поред Аллаха: „Где су вам божанства ваша која сте сматрали боговима?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Неће никакво оправдање да им преостане осим да кажу: „Аллаха нам, Господара нашег, ми нисмо друге обожавали поред Аллаха.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Видиш ли како ће они себе у лаж да утерају, а неће им бити оних божанстава које су измислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Има оних који долазе да те слушају, али Ми смо на њихова срца ставили засторе, да Кур''ан не би разумели, и учинили их глувим, па и ако би све доказе видели, опет у њих не би поверовали. А када ти долазе да расправљају са тобом, говоре они који не верују: „То су само измишљотине древних народа.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Они забрањују да се верује у Кур''ан, и сами се од њега удаљавају, и сами себе упропашћавају, а да и не примећују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'А да ти је да видиш како ће, кад пред Ватром буду задржани, да кажу: „Да нам је да се поново вратимо (у прошли живот), па да не поричемо речи нашег Господара и да постанемо верници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Не, напротив! Њима ће да постане очигледно оно што су пре крили; а када би се поново вратили, опет би наставили да раде оно што им је било забрањено, јер они су, заиста, лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'И говоре: „Нема живота осим на овом свету и ми нећемо да будемо оживљени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'А да ти је видети како ће, када пред својим Господарем буду заустављени и кад их Он упита: „Зар ово није истина?“ Одговорити: „Јесте, тако нам Господара нашег!“ А и како ће Он рећи: „Искусите онда патњу због тога што нисте веровали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Они који не верују да ће стати пред Аллахом настрадаће кад им изненада дође Час оживљења, и рећи ће: „О жалости наше, шта смо све пропустили на Земљи!“ И грехе ће своје да носе на леђима, а ужасно је оно што ће носити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Живот на овом свету је људима само игра и забава, а Будући свет је, заиста, бољи за оне који настоје да се сачувају. Зар не разумете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, 'Ми знамо да тебе заиста жалости оно што они говоре. Они, уистину, не сматрају да си лажов, него неправедници поричу Аллахове речи и доказе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'И посланици су пре тебе сматрани лажним, па су трпели то што су их у лаж утеривали и мучили, све док им не би дошла Наша помоћ - а нико не може да замени Аллахове речи - а до тебе су већ дошле неке вести о посланицима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Ако је теби тешко то што се они окрећу од истине, онда, ако можеш, потражи какав отвор у Земљи или какве мердевине за небо, па им донеси други знак?! Да Аллах хоће, Он би их све на правом путу сакупио; зато, никако не буди од оних који не знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Одазваће се једино они који слушају. А Аллах ће да оживи умрле; затим ће Њему сви да се врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, 'Они говоре: „Зашто му не буде спуштен од његовог Господара какав знак.“ Реци: „Аллах је, заиста, у стању да спусти знак, али већина њих не зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Нема ниједног живог бића које по Земљи ходи, нити птице која на крилима својим лети, а да нису заједнице попут вас. У Књизи Ми ништа изоставили нисмо - а на крају, сви ће пред својим Господарем да буду сакупљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'А они који речи и доказе Наше поричу глуви су и неми, у мраку су. Онога кога хоће - Аллах скрене на странпутицу, а ономе коме хоће - подари да буде на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'Реци: „Кажите ви мени, ако истину говорите, кад би вам дошла Аллахова казна, или када би вам дошао Судњи час, да ли бисте иког другог призивали осим Аллаха?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Напротив, Њега бисте само молили да, ако хоће, отклони од вас оно за шта сте Га позивали, а не би вам ни на уму пали они које сте Му у обожавању придруживали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'А посланике смо слали и народима пре тебе и те народе неимаштином и болешћу кажњавали, не би ли се покајали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'Па зашто се нису понизно молили када би им дошла Наша казна?! Али, срца њихова остајала су окорела, а Сотона им је приказао лепим оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'И када би заборавили оно чиме су опомињани, Ми бисмо им капије свега отворили; а када би се обрадовали ономе што им је дато, изненада бисмо их казнили и они би, одједном, изгубили сваку наду,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'и до задњег би био искорењен народ који је чинио неправду; па нека је хваљен Аллах, Господар светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'Реци: „Кажите ви мени, ако би вам Аллах одузео ваш слух и ваш вид и запечатио ваша срца, који би вам бог, осим Аллаха, то вратио?!“ Погледај како доказе и знакове излажемо, а они се опет окрећу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'Реци: „Кажите ви мени, ако би вас скривено или очигледно, стигла Аллахова казна, зар би ико други осим неправедних људи настрадао?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Ми шаљемо посланике само зато да доносе радосне вести и да опомињу; нека се зато они који верују и чине добра дела ничега не боје и ни за чим нека не тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'А оне који су доказе и речи Наше порицали стићи ће казна зато што су били грешни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'Реци: „Ја вам не кажем: ''Код мене су Аллахове ризнице'', нити: ''Ја знам оно што је чулима недокучиво'', нити вам кажем: ''Ја сам заиста анђео'', већ ја следим само оно што ми се објављује.“ Реци: „Зар су исто слепац и онај који види?! Зашто не размислите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'И упозоравај Кур''аном оне који страхују што ће пред својим Господарем да буду сакупљени, када осим Њега ни заштитника ни заговорника неће имати, да би се Аллаха бојали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'И не одбијај од себе оне који се ујутру и навече Господару своме моле у жељи за Његовим лицем; ти нећеш за њих да одговараш, а ни они неће за тебе да одговарају, јер би ти, ако би их одбио, неправедник био.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'И тако Ми једне другима искушавамо да би неверници казали: „Зар су то они, међу нама, којима је Аллах, милост указао?!“ А зар Аллах најбоље не познаје захвалне?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'А када ти дођу они који у речи Наше верују, ти реци: „Мир вама! Ваш Господар је сам Себи одредио да буде милостив: Ако неко од вас учини неко ружно дело из незнања, па се после покаје и поправи - па, Аллах, заиста, опрашта грехе и милостив је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Тако Ми подробно излажемо доказе и знакове, да би очигледан био пут којим иду грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, 'Реци: „Мени је забрањено да обожавам оне које ви, поред Аллаха, молите.“ Реци: „Ја се не поводим за вашим жељама, јер бих тада залутао и не бих био међу упућеним.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'Реци: „Ја сам заиста на јасној упути мог Господара, а ви је поричете. Није у мојој власти оно што ви пожурујете; пита се само Аллах, Он суди по правди и Он је Судија најбољи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'Реци: „Да је у мојој власти оно што пожурујете, између мене и вас би било свршено, а Аллах најбоље зна неправеднике.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, 'У Њега су кључеви онога што је чулима недокучиво, само их Он зна, и Он једини зна шта је на копну и шта је у мору, и ниједан лист не опадне а да Он за њега не зна; и нема зрна у тамама Земље нити ичег свежег нити ичег сувог, а да није у Јасној књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'Он вас ноћу умртвљује, а зна и шта сте преко дана урадили, затим вас дању буди, како би рок који је свакоме одређен, прошао. На крају, Њему ћете да се вратите и Он ће да вас обавести о ономе шта сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'Он је изнад слугу Својих, Свепотчинитељ, и шаље вам анђеле чуваре; а кад неком од вас дође смрт, анђели изасланици Наши му без оклевања узму душу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Они ће, после, Аллаху да буду враћени, своме истинском Заштитнику. Само Њему припада суд, и Он ће најбрже обрачун да сведе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'Реци: „Ко вас из страхота на копну и на мору избавља када му се и јавно и тајно понизно молите: ''Ако нас Он из овога избави, сигурно ћемо да будемо захвални!''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'Реци: „Аллах вас избавља из тих и из сваке невоље, па ви опет Њему друге придружујете у обожавању.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'Реци: „Он је у стању да пошаље против вас казну изнад ваших глава или испод ваших ногу, или да вас подели у странке и учини да искусите силу једни других. Погледај само како Ми подробно излажемо доказе и знакове, како би људи схватили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Твој народ пориче Кур'' ан, а он је Истина. Реци: „Ја нисам задужен да Упуту прихватите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'сваки наговештај има своје време, и ви ћете знати."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Када видиш оне који задиру лажима у Наше речи и ругају се, ти се од њих окрени све док други говор не започну. А ако те ђаво наведе да заборавиш, онда, након што се сетиш, не седи са људима неправедницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Они који се боје Аллаха неће за такве рачун полагати, али су дужни опомињати не би ли се оканили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Остави оне који узимају веру своју као игру и забаву, и које је обмануо живот на овом свету, а опомињи Кур''аном да нико, због онога што ради, не би страдао, јер осим Аллаха – ни заштитника ни посредника неће да имају и од таквог никаква откупнина неће да се прими. Они ће, због онога што су радили, да буду држани у патњи; њих чека пиће од кључале воде и болна патња, зато што нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'Реци: „Зар да, поред Аллаха, молимо оне који не могу да нам прибаве никакву корист ни да отклоне неку штету, па да будемо враћени својој прошлости, а Аллах нас је већ упутио, и да будемо као онај кога су на Земљи завели ђаволи па ништа не зна, а кога другови његови зову на Прави пут: ''Дођи нама!''“ Реци: „Заиста је Аллахова упута – истинска упута, и нама је наређено да се Господару светова предамо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'и да молитву обављамо и да се Њега бојимо;“ Он је Тај пред Којим ћете да будете сакупљени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'и Он је Тај Који је створио небеса и Земљу са истином. Чим Он за нешто каже: „Буди!“ - Оно буде; Његова реч је истина; само ће Он да има власт на Дан када се дуне у рог; Он зна оно што је чулима недокучиво и оно што је видљиво; Он је Мудри и све у потпуности зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, 'А кад Аврам рече своме оцу Тераху: „Зар кипове сматраш боговима?! Уистину, видим да сте и ти и твој народ у очигледној заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Ми показасмо Авраму царство небеса и Земље да би постао од оних који чврсто верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'И кад наступи ноћ, он угледа звезду и рече: "Ово је Господар мој!" А пошто зађе, рече: "Не волим оне који залазе!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'А кад угледа Месец како излази, рече: „Ово је мој Господар!“ А пошто зађе, он рече: „Ако ме Господар мој не упути, бићу сигурно један од људи који су залутали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'А кад угледа Сунце како се рађа, он узвикну: „Ово је мој Господар, ово је веће!“ А пошто зађе, он рече: „Народе мој, ја заиста немам ништа са тиме што ви Њему придружујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Ја окрећем лице своје, као прави верник, према Ономе Који је небеса и Земљу, без претходног примера, створио; ја не спадам у незнанобошце!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'И народ се његов са њим расправљао. „Зар да са мном о Аллаху расправљате, а Он је мене упутио?“ Рече он. „Ја се не бојим оних које ви Њему придружујете, осим ако мој Господар одреди нешто. Господар мој знањем својим обухвата све. Зашто не размислите и поуку не прихватите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'А како да се ја бојим лажних божанстава, када се ви не бојите што поред Аллаха обожавате оне за које вам Он није никакав доказ спустио? Па ко од нас више сигурност заслужује, ако знате?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'Само они који верују и веровање своје са неправдом не мешају биће уистину сигурни: они су упућени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'То је Наш чврст доказ који смо дали Авраму против његовог народа. Ми на више степене уздижемо оне које хоћемо. Твој Господар је, уистину, мудар и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'И Ми смо му даровали Исака и Јакова; и сваког упутисмо - а Ноја смо још пре упутили - и од потомака његових Давида, и Соломуна, и Јова, и Јосифа, и Мојсија, и Арона - ето, тако Ми награђујемо оне који добра дела чине;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'и Захарија, и Јована, и Исуса, и Илију - сви су они били међу честитима', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, '– и Јишмаела, и Јелисеја и Јону и Лота - и свима смо предност над осталим световима дали –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'И неке њихове претке и њихове потомке и њихову браћу - одабрали смо их и на Прави пут им указали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'То је Аллахова упута којом Он упућује оне које жели од слугу Својих. А да су они поред Аллаха друге обожавали, сигурно би пропало оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'То су они којима смо Ми дали Књигу и мудрост и веровесништво. Па ако они у то не верују, Ми смо то поверили људима који то не негирају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Њих је Аллах упутио, и зато следи њихов пут. Реци: „Ја од вас не тражим награду за Кур''ан, он је само поука световима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Они не познају Аллаха како треба, кад говоре: „Ниједном човеку Аллах није ништа објавио!“ Реци: „А ко је објавио Књигу коју је донео Мојсије као светло и упуту људима, коју на листове стављате и показујете, а много и кријете, и подучени сте ономе што ни ви ни преци ваши нисте знали?“ Реци: „Аллах!“ Затим их остави, нека се лажима својим забављају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'А ова Књига, коју објављујемо, благословљена је, она потврђује оне пре ње и да упозориш Мекку мајку градова и све око ње. А они који у Будући свет верују - верују и у њу и о молитвама својим брину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Ко је већи неправедник од онога који лажи о Аллаху износи или који говори: „Објављује ми се“, а ништа му се не објављује, или који каже: „И ја ћу рећи исто онако као што Аллах објављује.“ А да ти је да видиш неправеднике у смртним мукама, када анђели буду испружили своје руке према њима: „Спасите се ако можете! Од сада ћете неиздржљивом казном да будете кажњавани зато што сте о Аллаху износили оно што није истина и што сте се према доказима и речима Његовим охоло понашали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, 'А доћи ћете нам појединачно, онакви какве смо вас први пут створили, напустивши добра која смо вам били даровали. Ми не видимо са вама заговараче ваше за које сте сматрали да их Аллаху треба придружити у обожавању, покидане су везе међу вама и оставили су вас они за које сте тако тврдили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Заиста Аллах чини да се распукне зрно и кошпица. Он изводи живо из мртвог, и Он изводи мртво из живог; то вам је, ето, Аллах, па куда се онда одмећете!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, 'Он чини да зора свиће, Он је ноћ одредио за починак, а Сунце и Месец за рачунање времена; то је одредба Силног и Свезнајућег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'Он вам је створио звезде да се по њима у мраку управљате, на копну и мору. Ми смо образложили речи и доказе људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'Он вас је створио од једног човека, а затим вам следи боравиште и спремиште. Ми смо образложили речи и доказе људима који разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'Он спушта воду са неба, па Ми онда чинимо да помоћу ње ничу све врсте биља и да из њега израста зеленило, а из њега класје густо, и из палми, из заметка њихових, гроздови које је лако убрати, и вртови лозом засађени, и нарочито маслине и нар - обоје, и слично и различито. Посматрајте, зато, плодове њихове кад се тек појаве и кад зру. У томе су, заиста, докази за људе који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'И учинили су духове божанствима поред Аллаха, а Он је њих створио, и измислили су, не знајући шта говоре, да Аллах има синове и кћери. Узвишен је Он и врло високо изнад онога како Га они описују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, 'Он је Створитељ небеса и Земље, без претходног примера. Откуд Њему дете кад нема жене?! Он све ствара, и само Он све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, 'То вам је Аллах, ваш Господар, нема другог бога осим Њега, Створитељ свега; зато Њега обожавајте; Он над свиме бди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, 'Погледи до Њега не могу да допру, а Он до погледа допире; Он је Добростив и све у потпуности зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'Од Господара вашег дошли су вам јасни докази, па онај ко их прихвати, у своју корист то чини, а онај ко остане на то слеп, на своју је штету слеп; а ја нисам тај који вас надзире.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'И ето, тако Ми излажемо доказе да би они казали: „Ти си то учио“, и да бисмо то објаснили људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Ти следи оно што Господар твој објављује, другога бога осим Њега нема, а окрени се од незнанобожаца!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Да Аллах хоће, они не би друга божанства обожавали, а Ми тебе нисмо учинили да над њима бдиш нити си ти за њих задужен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'И не вређајте оне којима се они, поред Аллаха, моле, да не би и они, неправедно и не мислећи шта говоре, Аллаха вређали. Као и њима, тако смо сваком народу поступке њихове лепим представљали. Они ће, на крају, своме Господару да се врате, па ће Он о оном што су радили да их обавести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'Они се заклињу Аллахом, најјачом заклетвом, да ће, ако им дође какво знамење, сигурно због њега верници да постану. Реци: „Сва су знамења само код Аллаха!“ А да ли ви мисилите, да би они, када би им она дошла, верници постали?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'А ми њихова срца и њихове очи окрећемо, па неће да верују као што нису веровали ни први пут, и остављамо их да у осионости својој сметени лутају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Кад бисмо им анђеле послали, и кад би им мртви проговорили, и кад бисмо пред њима све доказе сабрали - они, опет, не би веровали, осим ако би Аллах хтео, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'Тако смо сваком веровеснику непријатеље одређивали, ђаволе у виду људи и духова, који су једни другима говорили украшене беседе да би их обманули; а да је твој Господар хтео, они то не би учинили; зато ти остави њих, и оно што измишљају;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'и да би срца оних који у онај свет не верују била склона томе и задовољна тиме, и да би починили грехе које су починили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, 'Зар да поред Аллаха тражим другог судију, кад вам Он подробно објављује Књигу?! А они којима смо дали Књигу добро знају да Кур''ан објављује твој Господар са истином, зато ти никако не сумњај!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Речи Господара твога врхунац су истине и правде; Његове речи нико не може да промени и Он је Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'Ако би се ти покоравао већини оних који живе на Земљи, они би те од Аллаховог пута одвратили; они се само поводе за претпоставкама, и само лажи измишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Заиста Господар твој најбоље зна оне који су скренули са Његовог пута и Он најбоље зна оне који су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Зато, једите оно при чијем је клању споменуто Аллахово име, ако у Његове речи и доказе верујете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'А зашто да не једете оно при чијем је клању споменуто Аллахово име кад вам је Он објаснио шта вам је забранио, осим кад сте присиљени. Многи, према прохтевима својим, немајући за то никакав доказ, заводе друге у заблуду. Уистину, Господар твој најбоље зна оне који границе прелазе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Оканите се и јавног и тајног грешења! Они који греше сигурно ће да буду кажњени за оно што су згрешили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Не једите оно при чијем клању није споменуто Аллахово име; то је, уистину, непослушност! А ђаволи, заиста, наводе штићенике своје да се са вама расправљају, па ако бисте им се покорили - и ви бисте тада, сигурно, незнанобошци постали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Зар је онај који је био у заблуди, а кога смо Ми оживели и дали му светло помоћу којег се међу људима креће, као онај који је у тминама из којих не излази? А неверницима је улепшано то што раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Исто тако, Ми учинимо да у сваком насељу великаши постану грешници и да у њему смишљају лукавства, али они само против себе смишљају лукавства, а да и не примећују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'А када им какав знак дође, они говоре: „Ми нећемо да верујемо све док се и нама не да нешто слично ономе што је дато Аллаховим посланицима.“ А Аллах најбоље зна коме ће да повери Своје посланство. Грешнике ће сигурно да задеси понижење код Аллаха и стићи ће их велика патња зато што су сплеткарили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Ономе кога Аллах жели да упути, Он његово срце према исламу расположи, а ономе коме хоће да подари да је у заблуди, Он срце његово тесним и стегнутим учини, као кад чини напор да на небо узлети. Ето, тако Аллах учини да нечисто овлада над онима који не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Ово је прави пут Господара твога, а Ми смо образложили речи и доказе људима који размишљају и поуку примају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'Њих чека Кућа спаса код Господара њиховог; Он ће бити заштитник њихов због онога што су чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'А на Дан када Он све сакупи: „О ђавоља скупино, ви сте многе људе завели!“ „Наш Господару“, рећи ће људи, штићеници њихови, „ми смо једни другима били од користи и стигли смо до рока нашег који си нам Ти одредио!“ „Ватра ће да буде ваше пребивалиште.“ Рећи ће Аллах. „У њој ћете вечно да останете, осим ако Аллах другачије не одреди.“ Господар твој је, заиста, мудар и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'Тако исто Ми препуштамо власт једним неправедницима над другима због онога што су зарадили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, 'О скупе џински и људски, зар вам из редова ваших нису долазили посланици који су вам речи и доказе Моје казивали и упозоравали вас да ћете да дочекате овај ваш дан? Они ће рећи: „Да, ми сведочимо против себе.“ Њих је живот на Земљи био обмануо и они ће сами против себе да посведоче да су били неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Тако је, јер твој Господар није уништавао насеља због њихове неправде, без претходне опомене њиховим становницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'Свима ће да припадне награда или казна, према томе како су поступали, а Господар твој није немаран према оном шта су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Господар твој је независан и милостив. Ако хоће, уклониће вас, и после вас довешће оне које Он хоће, као што је од потомства других народа вас створио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Оно што вам се претећи обећава заиста ће да дође и ви нећете моћи да умакнете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'Реци: „О народе мој, чини све што можеш, чинићу, уистину, и ја; а ви ћете сигурно да сазнате кога чека срећан крај!“ Неверници сигурно неће успети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Они одређују Аллаху део летине и део стоке, коју је Он створио, па говоре: „Ово је за Аллаха“, тврде они, „а ово за божанства наша!“ Међутим, оно што је намењено њиховим божанствима не стиже Аллаху, док оно што је одређено за Аллаха стиже божанствима њиховим!? Како ружно они суде!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Многим незнанобошцима су исто тако њихови ђаволи убијање властите деце лепим приказали, да би их упропастили и да би их у вери њиховој збунили. А да је Аллах хтео, они то не би чинили. Зато, остави и њих и њихове измишљотине!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Они говоре: „Ова стока и плодови су забрањени, смеју да их једу само они којима ми дозвољавамо“, тврде они, „а ово је стока чије је јахање забрањено.“ Има стоке приликом чијег клања не спомињу Аллахово име, измишљајући о Њему лажи. А Он ће због онога што измишљају, да их казни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Они говоре: „Оно што је у утробама ове и ове стоке дозвољено је само нашим мушкарцима, а забрањено је нашим женама. А ако се плод изјалови, онда су у томе судионици.“ Аллах ће за неистине које причају да их казни, заиста је Он Мудри и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Губитници су они који из лакомислености и не знајући шта раде децу своју убијају и који оно чиме их је Аллах опскрбио забрањеним сматрају, измишљајући лажи о Аллаху. Они су залутали и они не знају шта раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'Он је Тај Који ствара винограде, подупрте и неподупрте, и палме и усеве различитог укуса, и маслине и шипке - обоје, и слично и различито; једите плодове њихове кад плод подаре, и уделите на дан жетве и бербе оно на шта други право имају, и не расипајте, јер Он, заиста, не воли расипнике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'Ствара и стоку која терет носи и ону од које је простирка; једите део онога чиме вас опскрбљује Аллах, а не следите ђавоље стопе, заиста вам је он отворени непријатељ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, 'и то осам животиња у пару: пар оваца и пар коза. Реци: „Да ли је Он забранио мужјаке или женке, или оно што се налази у утробама женки? Обавестите ме поуздано, ако је истина то шта говорите“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'и пар камила и пар говеда. Реци: „Да ли је Он забранио мужјаке и женке и оно што се налази у утробама женки? Да ли сте ви били присутни кад вам је Аллах то прописао?“ Има ли онда већег неправедника од онога који, не знајући истину, измишља лажи о Аллаху да би људе у заблуду довео? Аллах сигурно неће да упути на Прави пут људе који су неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'Реци: „Ја не видим у овоме што ми се објављује да је икоме забрањено да једе ма шта друго осим угинуле животиње, или крви која истиче, или свињског меса, то је, заиста, погано, или што је као вид непослушности заклано у нечије друго, а не у Аллахово име.“ А буде ли ко приморан, не желећи то и не претерујући у томе, па твој Господар је, заиста, Опроститељ греха, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'Јеврејима смо све животиње које имају копита или канџе забранили, а од говеда и брава њихов лој, осим оног са леђа или са црева, или оног помешаног са костима. Тиме смо их због њихове неправде казнили; и Ми, заиста, говоримо истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'А ако ти они не буду веровали, ти реци: „Господар ваш је поседник неизмерне милости, али казне Његове не бивају поштеђени људи грешници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Говориће они који су Аллаху друге у обожавању придруживали: „Да је Аллах хтео, ми не бисмо Аллаху придруживали бога, а ни преци наши, нити бисмо ишта забрањеним учинили.“ Тако су и они пре њих порицали, све док Нашу казну нису искусили. Реци: „Имате ли ви какав доказ, да нам га изнесете? Ви се само за претпоставкама поводите и ви само неистину говорите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'Реци: "Аллах има потпун доказ, и да Он хоће, све би вас на Прави пут упутио!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'Реци: „Доведите своје сведоке који ће да посведоче да је Аллах то забранио!“ Па ако они посведоче, ти немој да им поверујеш и не поводи се за страстима оних који Наше речи и доказе сматрају лажним и који у онај свет не верују и који друге Господару своме у обожавању приближавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'Реци: „Дођите да вам кажем шта вам Господар ваш прописује: да Му ништа у обожавању не придружујете, да родитељима добро чините, да децу своју због неимаштине не убијате, Ми и вас и њих хранимо, не приближујте се неваљалштинама, биле јавне или тајне; не убијајте оног кога је Аллах забранио да се убије, осим када то правда захтева; то вам Он заповеда, да бисте разумели.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'И не приближавајте се имовини сирочета, осим на најлепши начин, све док пунолетно не постане, и меру и вагу праведно напуните; Ми никога преко његове могућности не задужујемо; и кад говорите, по правди говорите, па макар се тицало и сродника, и обавезе према Аллаху испуњавајте, ето, то вам Он заповеда да бисте се присетили и поуку примили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'И зато што је ово Мој прави пут, њега се држите и друге путеве не следите, па да вас одвоје од Његовог пута; то вам Он наређује, да бисте се сачували.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Ми смо Мојсију дали Књигу да учинимо потпуном благодат ономе који ће према њој да поступа и као објашњење свему и упуту и милост, да би они поверовали да ће пред својим Господаром да стану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'А ова је Књига коју објављујемо благословљена, зато је следите и Аллаха се бојте, да би вам милост била указана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, 'И зато, да не кажете: „Књига је објављена двема заједницама пре нас, али ми не знамо да је читамо као они.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'И да не кажете: „Да је Књига објављена нама, боље бисмо се од њих држали Правог пута.“ Па објављује вам се, ето, од Господара вашег јасан доказ и упута и милост. И има ли, онда, већег неправедника од онога који Аллахове речи и доказе не признаје и од њих одвраћа?! А Ми ћемо тешком муком да казнимо оне који од Наших знакова одвраћају, зато што то стално чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'Зар они чекају да им анђели дођу, или да им Господар твој дође, или неки предзнаци од твога Господара?! Онога дана када неки предзнаци од твога Господара дођу ниједном човеку неће да користи то што ће тада да верује, ако пре није веровао, или ако није као верник какво добро урадио. Реци: „Само ви чекајте, и ми ћемо, заиста, да чекамо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Заиста, са онима који су своју веру разделили и у странке се поделили ти немаш ништа! Њихов случај припада Аллаху. Он ће, потом, о ономе што су радили да их обавести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Ко год уради добро дело, биће десетороструко награђен; а ко год уради лоше дело, биће само према заслузи кажњен, и неће неправда да им буде учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'Реци: „Мене је Господар мој на Прави пут заиста упутио, у праву веру, веру правоверника Аврама, а он није био од оних који су друге поред Аллаха обожавали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'Реци: „Молитва моја, и обреди моји, и живот мој, и смрт моја заиста су ради Аллаха, Господара светова,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'Нико осим Њега не заслужује да буде обожаван; то ми је наређено и ја сам најпреданији и најпокорнији Аллаху.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'Реци: „Зар да за Господара тражим неког другог осим Аллаха, кад је Он Господар свега?!“ Што год ко уради, себи уради, и сваки грешник само ће своје бреме да носи. На крају, Господару своме ћете да се вратите и Он ће о ономе у чему сте се разилазили да вас обавести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'Он чини да једни друге на Земљи смењујете и Он вас по положајима једне изнад других уздиже, да би вас искушао у ономе што вам даје. Твој Господар, заиста, брзо кажњава, али Он, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Елиф Лам Мим Сад.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, 'Ово је Књига која ти се спушта – па нека ти у грудима не буде никакве тегобе због ње - да њоме упозораваш, и да верницима буде опомена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Следите оно што вам се од вашег Господара објављује и поред Њега не узимајте друге као заштитнике! А како ви мало поуку примате?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Колико смо Ми само насеља разорили; а казна им је Наша долазила ноћу или дању кад би прилегли?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'А њихово признање, када би им дошла Наша казна, биле су само речи: ’Заиста смо били неправедници!’', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'И сигурно ћемо питати оне којима смо слали посланике, а питаћемо, заиста, и посланике,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'Па ћемо им, сигурно, казивати по знању Нашем, све што о њима знамо, а Ми нисмо одсутни били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'Вагање тога дана биће праведно: они чија добра дела буду тешка, они ће успети;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'а они чија добра дела буду лака, они ће, зато што су према Нашим речима и доказима били неправедни, да настрадају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Ми смо вас сместили на Земљи и на њој све што вам је потребно за живот дали. А како ви мало захваљујете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Ми смо вас створили и онда вам облик дали, а после смо анђелима казали: „Поклоните се Адаму!“ Па се сви поклонише, осим Сотоне, он није био међу онима који су се поклонили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, '„Шта те је навело да се не поклониш кад сам ти наредио?“ Упита Он. „Ја сам бољи од њега; мене си створио од ватре, а њега од иловаче.“ Одговори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, '„Онда силази из Раја.“ Рече Аллах. „Није ти дозвољено да се у Рају охолиш; силази, ти си, заиста, међу презреним!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, '„Дај ми времена до дана њиховог проживљења!“ Замоли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, '"Даје ти се времена!" Рече Он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, '„Као што си ме у заблуду завео“, рече, „тако ћу и ја људе на Твом Правом путу сигурно да пресрећем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'па ћу, заиста, и спреда, и страга, и здесна, и слева да им прилазим, и Ти ћеш да установиш да већина њих неће да буде захвална!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, '„Излази из њега, покуђен и понижен!“ Рече Он. „Тобом и свима који се за тобом буду поводили заиста ћу Пакао да напуним!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, '„А ти, о Адаме, и супруга твоја у Рају станујте и одакле год хоћете једите, само се овом дрвету не приближавајте, да не будете неправедници!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'И ђаво поче да их навраћа да би им открио њихова стидна места, која су им скривена била, и рече: „Ваш Господар вам забрањује ово дрво само зато да не бисте постали анђели или да не бисте постали бесмртни“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, 'и заклињаше им се: „Ја сам вам, заиста, искрени саветник!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'И на превару их заведе. А кад они оно дрво пробаше, указаше им се њихова стидна места и они по себи рајско лишће да стављају почеше. „Зар вам то дрво нисам забранио?“ Зовну их њихов Господар. „И казао вам: ''ђаво вам је, збиља, отворени непријатељ.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, '„Господару наш“, рекоше они, „сами смо себи неправду учинили, и ако нам Ти не опростиш и не смилујеш нам се, сигурно ћемо да настрадамо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, '„Силазите!“ Рече Он. „Једни другима бићете непријатељи! На Земљи ћете да боравите и до одређеног времена ћете да уживате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, '„На њој ћете да живите, на њој ћете да умирете и из ње ћете да будете проживљени“, рече Он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'О синови Адамови, дали смо вам одећу која ће да покрива ваша стидна места, а и раскошна одела, али, одећа богобојазности, то је оно најбоље. То су неки Аллахови знаци да би се они присетили и прихватили поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'О синови Адамови, нека вас никако не заведе ђаво као што је извео из Раја ваше родитеље, скинувши са њих одећу да би им показао њихова стидна места! Он вас, заиста, види; он и његове војске, одакле ви њих не видите. Уистину, Ми смо учинили да ђаволи буду заштитници онима који не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'А када ураде неко гнусно дело, говоре: „Затекли смо наше претке да то раде, а и Аллах нам је то заповедио.“ Реци: „Аллах не заповеда да се раде гнусна дела! Зашто о Аллаху говорите оно што не знате?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'Реци: „Господар мој наређује праведност. И обраћајте се само Њему кад год обављате молитву, и молите се искрено Му веру исповедајући! Као што вас је први пут створио, тако ће поново да вас оживи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'Он једне на Прави пут упућује, а други, са правом, заблуду заслужују, јер они, уместо Аллаха, заиста ђаволе за заштитнике узимају и мисле да су упућени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'О синови Адамови, кад год пођете на молитву лепо се обуците. И једите и пијте, само не претерујте; Он, заиста, не воли оне који претерују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, 'Реци: „Ко је забранио Аллахове украсе које је Он за слуге Своје створио, и укусна јела?“ Реци: „То је за вернике на овом свету, а на оном свету су само за њих.“ Ето, тако Ми темељно излажемо доказе људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'Реци: „Господар мој забрањује гнусна дела, и јавна и тајна, и грехе, и бесправну употребу силе, и да Аллаху у обожавању придружујете оне за које Он никакав доказ није објавио, и да о Аллаху говорите оно што не знате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Сваки народ има свој рок, и када дође њихов рок, неће моћи ни за трен један ни да га одложе ни убрзају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'О синови Адамови, кад вам између вас буду долазили посланици који вам казују речи Моје - онда за оне који се буду чували и чинили добра дела нема страха нити ће за било чим да тугују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'А они који не буду веровали и речи и доказе Наше буду порицали биће становници Ватре; у њој ће вечно остати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Има ли, онда, већег насилника од онога који о Аллаху говори лажи или пориче Његове доказе и знакове? Такви ће да добију све оно што им је записано. Али, када им Наши изасланици дођу да им узму душе, упитаће их: „А где су они које сте, уместо Аллаха, обожавали?“ „Изгубили су нам се“, одговориће, и сами против себе ће посведочити да су били неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, 'Рећи ће Он: „Улазите у Ватру са заједницама духова и људи које су пре вас биле и нестале!“ И кад год нека заједница уђе, проклињаће ону себи сличну - за којом се у неверство повела. А кад се сви у њему сакупе, тада ће они из каснијих заједница рећи за оне из првих: „Господару наш, ови су нас одвели у заблуду, зато им дај двоструку патњу у Ватри!“ „За све ће да буде двострука!“ Рећи ће Он, „али ви не знате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'А они из претходних заједница рећи ће онима из каснијих: „Ви немате никакве предности над нама! Зато искусите патњу за оно што сте радили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Заиста, онима који Наше речи и доказе буду порицали и према њима се буду охоло односили - небеске капије се неће отворити, нити ће они у Рај да уђу све док се камила кроз иглене уши не провуче! Ето тако ћемо Ми преступнике да казнимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'Од паклене ватре ће лежаји, а и покривачи, изнад њих да им буду. Ето, тако ћемо Ми насилнике да казнимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'Они који буду веровали и чинили добра дела - а Ми никог не задужујемо мимо његових могућности, биће становници Раја, у њему ће вечно да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'Из њихових груди ћемо злобу да одстранимо; испред њих ће реке да теку, и они ће говорити: „Хваљен нека је Аллах, Који нас је на Прави пут упутио; ми не бисмо на Правом путу били да нас Аллах није упутио, посланици нашег Господара истину су доносили“, и довикнуће им се: „Тај сте Рај у наследство добили за оно што сте чинили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'И становници Раја дозиваће становнике Ватре: „Ми смо нашли да је истинито оно што нам је обећао наш Господар, да ли сте и ви нашли да је истинито оно што је вама ваш Господар претећи обећао?“ „Јесмо!“ Одговориће. А онда ће један гласник међу њима да викне: „Нека Аллахово проклетство на насилнике остане,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, 'који су од Аллаховог пута одвраћали и настојали да га искриве, и који у Будући свет нису веровали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Између њих биће преграда, а на врховима биће људи који ће сваког по његовом обележју да познају. И они ће становницима Раја, пре него што у њега уђу, да кажу: „Мир над вама!“ А то ће силно да желе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Када им погледи скрену према становницима Ватре, узвикнуће: „Наш Господару, не дај нам да будемо са људима насилницима!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'Они који ће да буду по врховима бедема зовнуће невернике које ће по обележју њиховом да познају, и рећи ће: „Није вам користило ваше мноштво и то што сте се охоло држали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, 'Зар ово нису они за које сте се заклињали да Аллахова милост неће да их стигне? Уђите у Рај, никаквог страха за вас неће да буде и ни за чим ви нећете да тугујете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'И становници Ватре дозиваће становнике Раја: „Поспите на нас воду или нешто од онога што вам је Аллах подарио!“ А они ће рећи: „Аллах је, заиста, то неверницима забранио“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, 'онима којима су веру своју за забаву и игру узели и које је живот на Земљи био обмануо. Зато ћемо данас Ми њих да заборавимо, као што су заборављали да ће на овај Дан пред Нама стати и зато што су Наше речи и доказе порицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'А Ми смо им донели Књигу коју смо по Нашем знању објаснили, да буде упута и милост људима који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Чекају ли они да се то обистини? Онога дана када се обистини, рећи ће они који су је пре били заборавили: „Истину су посланици нашег Господара доносили! Да нам је какав заговорник, па да се за нас заузме или да нам је да будемо враћени па да поступамо другачије него што смо пре поступали!“ Али, они су сами себе упропастили, и изгубиће им се они које су измишљали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'Заиста је ваш Господар Аллах Који је небеса и Земљу у шест дана створио, а затим се над Престољем узвисио. Он тамом ноћи дан прекрива и она га у стопу прати, а Сунце и Месец и звезде покоравају се Његовој наредби. Само Он располаже стварањем и одлучивањем! Узвишен нека је Аллах, Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Понизно се молите и у себи своме Господару, Он, заиста, не воли оне који прелазе границу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'И не правите неред на Земљи, када је на њој ред успостављен, а Њему се молите са страхом и надом; милост је Аллахова, заиста, близу оних који чине добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'Он је Тај Који шаље ветрове као радосну вест Своје милости; а кад они покрену тешке облаке, Ми их пошаљемо према мртвом пределу, па на њега кишу спустимо и учинимо да уз њену помоћ расту плодови сваковрсни; тако ћемо и мртве да оживимо да бисте се присетили и прихватили поуку!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'У плодном пределу расте биље уз допуштење његовог Господара, а у неплодном тек са муком. Ето, тако Ми, на разне начине, излажемо знакове људима који захваљују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Ми смо Ноја послали његовом народу, па им је он говорио: „О народе мој, Аллаха обожавајте, ви другог бога осим Њега немате! Ја се, заиста, бојим за вас патње на Великом дану!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Главешине његовог народа одговарали су: „Ми сматрамо да си ти, заиста, у потпуној заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, 'А он рече: „О народе мој, нисам ја ни у каквој заблуди, него сам посланик Господара светова;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'достављам вам посланице свога Господара и саветујем вас; ја од Аллаха знам оно што ви не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'Зар вам је чудно што вам поука од вашег Господара долази по човеку, једном од вас, да вас упозорава, да бисте се бојали Аллаха и да бисте били помиловани?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Али, они су га сматрали лажним, па смо спасили њега и оне који су били уз њега у лађи, а оне који у Наше речи и доказе нису веровали - потопили. Уистину, они су били прави слепци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'А народу Аду посласмо њиховог брата Ебера. Он је говорио: „О народе мој, Аллаха обожавајте, ви другог бога осим Њега немате, зар нећете да се сачувате?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Главешине његовог народа, који нису веровали, одговарали су: „Ми сматрамо да си ти, заиста, у лудилу и ми мислимо да си, заиста, лажов.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, 'А он рече: „О мој народе, није у питању никакво лудило, него сам посланик Господара светова;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'и достављам вам посланице свога Господара, и ја сам вам искрени саветник.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'Зар вам је чудно што вам поука од вашег Господара долази по човеку, једном између вас, да вас опомиње? Сетите се да вас је Он учинио наследницима Нојевог народа и створио вас крупне грађе. И нека су вам зато увек на уму Аллахове благодати, да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'Они су говорили: „Зар си нам дошао зато да само Аллаха обожавамо, а да напустимо оне које су преци наши обожавали? Учини да нас снађе то чиме нам претиш, ако је истина то што говориш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, '„Већ вас је снашла казна и гнев вашег Господара!“ Говорио је он. „Зар са мном да се препирете о некаквим називима којима сте их ви и преци ваши назвали, а о којима Аллах никакав доказ није објавио? Зато чекајте, и ја ћу са вама сигурно да чекам!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Ми смо из милости Наше њега и оне који су били уз њега спасили, а до последњег смо истребили оне који Наше доказе нису признавали и који нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, 'А народу Семуду смо његовог брата Салаха послали. „О мој народе“, говорио је он, „обожавајте Аллаха, ви другог бога осим Њега немате! Ево вам знак вашег Господара: ова Аллахова камила за вас је знак. Пустите је нека пасе по Аллаховој земљи и не злостављајте је да вас болна казна не би снашла!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, '„И сетите се да вас је Он учинио наследницима Ада, и да вас је Он на Земљи настанио: у равницама њеним палате градите, а у брдима куће клешете. И нека су вам увек на уму Аллахове благодати, и не чините зло по Земљи правећи неред!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'А главешине његовог народа, они који су се охолили, упиташе потлачене, оне међу њима који су веровали: „Верујете ли ви да је Салаха послао његов Господар?“ „Ми, уистину, верујемо у све оно што је по њему послато“, одговорише они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, '„А ми, заиста, не верујемо у то у шта ви верујете“, рекоше они који су били охоли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'И заклаше они камилу, и заповед Господара свога не послушаше и рекоше: „О Салахе, учини да нас снађе то чиме нам претиш, ако си од посланика!?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'И задеси их страшан потрес и они у земљи својој освануше мртви, непомични.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, 'А он их напусти и рече: „О мој народе, пренео сам вам посланицу свога Господара и саветовао сам вас, али ви не волите оне који саветују.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'И спомени Лота када рече своме народу: „Зашто чините разврат који нико међу свим световима пре вас није чинио?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Ви заиста страсно прилазите мушкарцима, уместо женама. Штавише, ви сте народ који све границе прелази!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'А одговор његовог народа био је једино то што рекоше: „Истерајте их из вашег насеља, они су, заиста, људи чистунци!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'И Ми смо њега и породицу његову спасили, осим његове жене; она је остала са онима који су казну искусили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'И на њих смо кишу грумења спустили, па погледај како су преступници скончали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, 'А и у Медјен - посласмо њиховог брата Јофора. „О мој народе“, говорио је он, „Аллаха обожавајте, ви немате другог бога осим Њега! Јасан доказ од вашег Господара вам је дошао, зато исправно мерите, и не закидајте људе ни у чему, и не реметите ред на Земљи кад је већ на њој успостављен ред. То је боље за вас, ако сте верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'И не постављајте заседе на путу, претећи и одвраћајући од Аллаховог пута оне који у Њега верују, желећи пут заблуде. И сетите се да вас је било мало и да вас је Он умножио, а погледајте како су скончали они који су неред правили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'И ако једни од вас верују у оно што је по мени послато, а други не верују, па причекајте док нам Аллах не пресуди, а Он је најбољи судија!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Главешине његовог народа, они који су били охоли, рекоше: „Или ћемо ми, о Јофоре, и тебе и оне који са тобом верују из нашег насеља да истерамо, или ћете да се вратите у нашу веру!“ „Зар и против наше воље?“ Рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, '„Ако бисмо се вратили у вашу паганску веру након што нас је Аллах из ње избавио, изнели бисмо лаж на Аллаха. Ми не треба да се у њу враћамо, осим ако то жели Аллах, наш Господар. Наш Господар Својим знањем све обухвата; на Аллаха се ослањамо! Господару наш, Ти пресуди нама и нашем народу, по правди, Ти си Судија најбољи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'А главешине његовог народа, они који нису веровали, рекоше: „Ако пођете за Јофором, бићете сигурно изгубљени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'И задеси их потом страшан потрес и они освануше у земљи својој мртви, непомични.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Они који су сматрали Јофора лажовом, као да никад нису у њој ни били; они који су сматрали Јофора лажовом, они су били прави губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, 'А он их напусти и рече: „О мој народе, пренео сам вам посланице свога Господара и саветовао вас, па зашто да тугујем за неверничким народом?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'И Ми ниједног веровесника у неко насеље нисмо послали, а да његове становнике болешћу и неимаштином нисмо казнили да би се искрено покајали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'После бисмо зло заменили добрим док се не би умножили и казали: „Задесили су и наше претке и неимаштина и благостање!“ И тада бисмо их изненада казнили, а они казну ни предосетили не би.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'А да су становници насеља веровали и били богобојазни, Ми бисмо им благослове и са неба и из земље слали, али, они су порицали, па смо их кажњавали због оног што су чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'А зар су становници насеља сигурни да Наша казна неће да их снађе ноћу док буду спавали?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Или, зар су становници насеља сигурни да Наша казна неће да их снађе дању док се буду забављали?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Зар они мисле да су сигурни од Аллахове казне? Само народ губитнички је уверен да је сигуран од Аллахове казне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Зар није јасно онима који наслеђују Земљу након претходних њених становника да ћемо и њих, ако будемо хтели, због њихових греха да казнимо или да им срца запечатимо, па неће моћи да чују савет и опомену?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'О тим насељима Ми ти неке догађаје казујемо. Њихови посланици доносили су им јасне доказе, али они нису поверовали зато што ни пре нису веровали. Ето, тако је Аллах запечатио срца неверника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'А Ми нисмо нашли да се већина њих завета држи, а установили смо да су већина њих, заиста, грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Затим смо, после њих, послали Мојсија са Нашим речима и доказима фараону и његовим главешинама, али они у њих нису поверовали, па погледај како су скончали они који су неред чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'И Мојсије рече: „О фараоне, ја сам, уистину, посланик Господара светова!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, '„Дужност ми је да о Аллаху само истину кажем. Донео сам вам јасан доказ од вашег Господара, зато пусти да иду са мном синови Израиљеви!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, '„Ако си донео какав доказ“, рече, „покажи га, ако си од оних који истину говоре.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'И он баци свој штап - кад он права змија;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'и извади своју руку, и она за присутне постаде бела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Главари фараоновог народа повикаше: „Овај је, заиста, вешт чаробњак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, 'Он хоће да вас изведе из земље ваше, па шта предлажете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, '„Задржи њега и његовог брата“, рекоше, „а пошаљи у градове сакупљаче,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'пред тобом ће све веште чаробњаке да доведу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'И фараону чаробњаци дођоше. „Да ли ћемо, заиста, награду да добијемо ако будемо победници?“ Упиташе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, '„Да.“ Рече, „и бићете, заиста, међу мени блискима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, '„О Мојсије“, рекоше онда, „хоћеш ли ти, или ћемо ми да бацимо?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, '“Баците ви.“ Рече он. И кад они бацише, очи људима зачараше и јако их престрашише, и враџбину велику приредише.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'И Ми наредисмо Мојсију: „Баци свој штап!“ И он одједном прогута све оно чиме су они обманом били извели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'И тако је истина на видело изашла и показало се да је било лажно оно што су они приредили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'и ту су они били побеђени и постадоше понижени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, 'И чаробњаци падоше ничице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, '„Ми верујемо у Господара светова.“ Повикаше,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, '„Господара Мојсијевог и Ароновог!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, '„Зар да му поверујете пре него што вам ја дозволим!“ Викну фараон.“ Ово је, уистину, сплетка коју сте претходно у граду смислили да бисте из њега становнике његове извели. Знаћете ви!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, '„Пресећи ћу вам, сигурно, руке ваше и ноге ваше унакрст, а онда ћу све сигурно да вас разапнем!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'А они рекоше: „Ми ћемо, заиста, нашем Господару да се вратимо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, '„Ти нам замераш само то што смо у доказе нашег Господара поверовали кад су нам дошли. Господару наш, обаспи нас стрпљивошћу и учини да као предани верници умремо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'А главешине фараоновог народа рекоше: „Зар ћеш да оставиш Мојсија и његов народ да неред по Земљи прави и да тебе и божанства твоја напусти?“ Он рече: „Убијаћемо њихову мушку децу, а женску ћемо да им остављамо у животу; ми, уистину, владамо над њима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Мојсије рече своме народу: „Молите Аллаха да вам помогне и будите стрпљиви, Земља је, заиста, Аллахова. Он је даје у наслеђе коме Он хоће од Својих слуга; а леп исход припада богобојазнима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, '„Злостављани смо.“ Рекоше они, „пре него што си нам дошао, а и након што си дошао!“ А Мојсије рече: „Можда ће ваш Господар да уништи вашег непријатеља, а вас наследницима на Земљи да учини, да би видео како ћете да поступите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'И Ми смо казнили фараонов народ гладним годинама и оскудицом у плодовима, да би се присетили и поуку узели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'И кад би им наишло добро, они би говорили: „Ово смо заслужили“, а кад би их снашла каква невоља, злослутњу су налазили у Мојсију и онима који су са њим веровали. Али не! Њихова је злослутња од Аллаха била, само што већина њих није знала!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'И говорили су: „Какав год да нам доказ донесеш да нас њиме опчараш, ми нећемо да ти верујемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Па Ми на њих посласмо и поплаву, и скакавце, и крпеље, и жабе, и крв - све јасне знакове, али су се они охолили, јер су народ зликовачки били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'И кад би их задесила патња, говорили би: „О Мојсије, моли се за нас своме Господару - онако како ти је Он наредио. Ако нас ослободиш патње, ми ћемо заиста да верујемо и са тобом ћемо сигурно да пошаљемо синове Израиљеве.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'И након што бисмо их патње ослободили, до времена до кога им је било одређено да је подносе, они би, одједном, обећање прекршили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'И онда их Ми казнисмо и у море их потописмо, јер су порицали Наше знакове и према њима су били равнодушни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'а потлаченом народу смо дали у наслеђе источне и западне крајеве земље коју смо благословили, и лепе речи твога Господара синовима Израиљевим су биле испуњене - зато што су трпели, а са земљом сравнисмо оно што су фараон и његов народ били саградили и оно што су увис подизали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'И Ми синове Израиљеве преведосмо преко мора, па они наиђоше на народ који је био привржен обожавању својих кипова. „О Мојсије“, рекоше, „направи и ти нама бога као што и они имају богове!“ „Ви сте, уистину, народ који не зна!“ Рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Заиста ће да буде поништено оно у шта су били огрезли и бескорисно ће да им буде оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, 'Он рече: „Зар да вам, поред Аллаха, тражим другог бога, а Он вас је над свима другима одликовао?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, 'И пошто смо вас Ми избавили од фараонових људи, који су вас најгором муком мучили: вашу мушку децу су убијали, а женску су вам у животу остављали - то је био спас од вашег Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Ми одредисмо да час сусрета са Мојсијем буде кад се напуни тридесет ноћи, и допунисмо их још са десет, па се време које је одредио његов Господар испуни за четрдесет ноћи. А Мојсије је био казао своме брату Арону: „Замени ме у моме народу, и уређуј ствари и не следи путеве смутљиваца!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'И кад Нам дође Мојсије у одређено време, и када му Господар проговори, он рече: „Господару мој, укажи ми се да Те видим!“ „Нећеш да Ме видиш“, рече, „али погледај у оно брдо, па ако оно остане на своме месту, видећеш Ме!“ И кад се његов Господар откри оном брду, Он га са земљом сравни, а Мојсије изгуби свест и стровали се. Чим се освести, рече: „Узвишен си Ти! Кајем Ти се, ја сам најчвршћи верник!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, '„О Мојсије“, рече Он, „ Ја сам те, заиста, одабрао изнад осталих људи Својом посланицом и Својим те говором учинио одабраним. Оно што ти дајем прихвати и захвалан буди!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'И Ми смо му написали на плочама поуку за све, и објашњење за све. Прихвати их снажно, а народу свом заповеди да се придржава онога што је у њима на најлепши начин. А показаћу вам и станиште грешника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Одвратићу од Својих знамења оне који се, без икаквог основа, на Земљи охоле. И какав год доказ они виде, неће у њега да верују; ако виде Прави пут - неће као пут да га прихвате, а ако виде странпутицу – као пут ће да је прихвате. То је зато што знакове Наше поричу и што су према њима равнодушни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Дела ће да буду поништена онима који поричу Наше речи и доказе и сусрет на Будућем свету. Зар ће да буду другачије кажњени него како су радили?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'И народ Мојсијев, после његовог одласка, изради од свог накита кип телета које је рикало и које су за божанство прихватили. Зар нису видели да им оно не говори и да их правим путем не води? Они га прихватише и посташе неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Након што се горко покајаше и увидеше да су залутали, они рекоше: „Ако нам се наш Господар не смилује и ако нам не опрости, сигурно ћемо да будемо међу губитницима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'А кад се Мојсије, срдит и бесан, врати своме народу, повика: „Како сте тако ружно поступили после мог одласка! Зар сте убрзали наредбу свога Господара?!“ И испусти плоче, и свога брата за косу дохвати и поче да га вуче себи. „О сине моје мајке“, рече Арон, „мој народ ме је слабим сматрао и умало ме није убио; немој да ми се свете душмани и не убрајај мене у народ неправедни.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, '„Мој Господару“, замоли Мојсије, „опрости мени и моме брату и учини да будемо под окриљем Твоје милости, Ти си међу милостивима најмилостивији!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Оне који су теле прихватили стићи ће заиста срџба њиховог Господара и понижење још на овом свету. Тако Ми кажњавамо оне који кују лажи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'А они који раде лоша дела, па се после покају и постану верници – па, Господар твој, после тога, сигурно, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'И када Мојсијева срџба прође, он узе плоче на којима је била исписана упута и милост за оне који од Господара свога страхују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'И Мојсије одабра из свога народа седамдесет људи да у одређено време стану пред Нама. А кад их задеси потрес па су сви помрли, он рече: „Господару мој, да си хтео, могао си и њих и мене да уништиш још пре. Зар да нас уништиш због онога што су урадили наши безумници? То је само Твоје искушење којим Ти, кога хоћеш, скрећеш на странпутицу, а кога хоћеш, упућујеш на Прави пут; Ти си наш Господар, па нам опрости и смилуј нам се! А Ти си Опроститељ најбољи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, '„И подари нам добро на овом свету, и на оном свету - ми се, уистину, Теби враћамо!“ „Својом Казном Ја кажњавам кога хоћу“, рече Он, „а милост Моја обухвата све; даћу је онима који се буду греха клонили и давали обавезну милостињу, и онима који у Наше речи и доказе буду веровали“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, '„онима који ће да следе Посланика, Веровесника, који неће да зна ни да чита ни да пише, којег они код себе, у Тори и Јеванђељу, налазе записаног, који ће од њих да тражи да чине добра дела, а од одвратних да одвраћа, који ће лепа јела да им дозволи, а ружна забрани, који ће да их терета и тешкоћа које су они имали ослободи. А они који у њега буду веровали, који га буду подржавали и помагали и светло по њему послато следили - они ће сигурно успети.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'Реци: „О људи, ја сам заиста свима вама Аллахов посланик, власт Његова је и на небесима и на Земљи; нема другог бога осим Њега, Он даје живот и смрт, и зато верујте у Аллаха и Његовог Посланика, веровесника, који не зна да чита и да пише, који верује у Аллаха и Његове речи; њега следите - да бисте били упућени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'У Мојсијевом народу има заједница људи који се упућују Истином и који према њој праведно суде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'И Ми смо их поделили у дванаест племена, и Мојсију смо објавили, кад му је његов народ затражио воду: „Удари штапом својим по стени!“ И из ње је дванаест врела проврело, свако племе је знало врело из којег ће да пије. И Ми смо им од облака правили хлад и давали смо им ману и препелице: „Једите оно лепо чиме вас опскрбљујемо!“ Они нису Нама учинили неправду, него сами себи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'А када им је било речено: „Населите се у овом насељу и једите одакле хоћете и реците: ''Опрости! '' А на капију уђите погнутих глава“, опростићемо вам ваше грехе, а онима који чине добра дела даћемо и више.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Онда су они међу њима који учинише неправду заменили другом речју реч која им је била речена, и Ми смо на њих са неба спустили казну зато што су чинили неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'И упитај их о насељу које се налазило поред мора кад су кршили прописе о суботи: када су им рибе, на очиглед, долазиле док су светковали суботу, а кад нису светковали оне им нису долазиле. Ето, тако смо их у искушење доводили зато што су били грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, 'А кад неки од њих рекоше: „Зашто опомињете народ који ће Аллах да уништи или да га на тешке муке стави?“ Они одговорише: „Да бисмо се пред вашим Господаром оправдали и да би се они тога клонили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'И када заборавише оно чиме су били упозоравани, Ми избависмо оне који су одвраћали од неваљалих дела, а неправеднике казнисмо тешком казном, зато што су стално били грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'И пошто су они бахато одбили да се окане онога што им је забрањивано, Ми смо им казали: „Постаните презрени мајмуни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'И Господар твој обзнани да ће да препусти власт над њима до Судњег дана неком ко ће да их тлачи тешком казном. Твој Господар, уистину, брзо кажњава, а Он, заиста, и опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'И Ми смо их по Земљи као народе расподелили: било је међу њима добрих, а и оних који то нису; искушавали смо их и у добру и у злу, како би се исправном путу вратили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'И после њих остале су генерације које су Књигу наследиле и које су узимале пролазна добра овог материјалног света, и говориле: „Биће нам опроштено!“ А ако би им опет допало шака тако нешто, опет би то прихватили. Зар од њих није узет завет у Књизи да ће о Аллаху само истину да говоре - а они читају оно што је у њој. Будући свет је бољи за оне који настоје да се сачувају; па зар не разумете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'А они који се чврсто држе Књиге и који обављају молитву - па, Ми, заиста, нећемо да допустимо да пропадне награда онима који чине добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'А када смо изнад њих подигли брдо, чинило се као облак, они су били уверени да ће на њих да падне. Прихватите снажно оно што смо вам дали, и нека вам је на уму оно што је у томе - да бисте се сачували!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'И кад је Господар твој од Адамових синова, из њихових кичми, извео њихово потомство и затражио од њих да посведоче против себе: „Зар нисам Ја ваш Господар?“ Они су одговарали: „Јеси, ми сведочимо“, и зато да на Судњем дану не кажете: „Ми о овоме нисмо ништа знали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, 'Или да не кажете: „Наши су преци пре нас друга божанства обожавали, а ми смо генерација после њих. Зар ћеш да нас казниш за оно што су лажљивци чинили?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'И тако Ми опширно износимо доказе, да би они дошли себи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, 'И кажи им вест о ономе коме смо дали Наше доказе, а који се од њих удаљио па га је ђаво достигао, па постаде од залуталих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'А да смо хтели, могли смо тиме да га узвисимо, али се он приклонио овом свету и за својом страшћу кренуо. Његов случај је као случај пса; ако га потераш, он исплаженог језика дахће, а ако га се оканиш – он опет дахће. Такви су људи који Наше речи и доказе сматрају лажним; зато, казуј догађаје да би они размислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Лош су пример људи који не признају Наше речи и доказе, они неправду чине сами себи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Кога Аллах упути на Прави пут - биће на Правом путу, а кога на странпутицу скрене - па такви су прави губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Ми смо за Пакао многе духове и људе створили; они срца имају - а њима не схватају, они очи имају - а њима не виде, они уши имају - а њима не чују; они су као стока, чак и гори - они су заиста немарни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'Аллах има најлепша имена и ви Га зовите тим именима, а клоните се оних који искрећу Његова имена; како буду радили, онако ће да буду кажњени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'А међу онима које стварамо има људи који друге упућују истини и који према њој праведно суде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'А оне који Наше речи и доказе поричу Ми ћемо мало - помало, а да они неће ни да знају, у пропаст да водимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'И даваћу им времена; замка је Моја, заиста чврста.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Па зашто они не размисле да Посланик који им је послат није луд; он је само јасни упозоритељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'И зашто они не размисле о царству небеса и Земље и о свему ономе што је Он створио, и да им се, можда, крај примакао? Па у који ће говор, ако не у Кур''ан, да верују?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Кога Аллах на странпутицу скрене, нико не може да га упути на Прави пут! Он ће да их остави да у осионости својој лутају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'Питају те о Смаку света, када ће да се догоди. Реци: „То зна једино мој Господар, Он ће у одређено време да га открије, а тежак ће да буде небесима и Земљи, сасвим неочекивано ће да вам дође.“ Питају те као да ти о њему нешто знаш. Реци: „То зна само Аллах, али већина људи не зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'Реци: „Ја не могу да прибавим ни самом себи неку корист, ни да отклоним од себе какву штету; бива онако како хоће Аллах. А када бих знао оно што је недокучиво чулима, стекао бих многа добра, а зло би било далеко од мене; ја само доносим опомене и радосне вести људима који верују.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'Он је Тај Који вас је од једног човека створио - а од њега је жену његову створио да се уз њу смири. И када је он са њом прилегао, она је занела лако бреме и носила га; а кад јој је оно отежало, њих двоје су замолили Аллаха, свога Господара: „Ако нам подариш здравог потомка, бићемо, заиста, међу оним захвалним!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'И кад им је Он даровао здравог потомка, њих двоје су изједначили друге са Њим у ономе што им Он даје, а Аллах је врло високо изнад оних које Њему у обожавању придружују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Зар да Њему придружују божанства, она која не могу да створе ништа, и која су сама створена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'и који не могу да им помогну нити могу себи да помогну?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'А ако их замолите да вас на Прави пут упуте, неће вам се одазвати; исто вам је позивали их или ћутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'Они којима се ви, поред Аллаха, молите, заиста су слуге, као и ви. Па, ви их молите, и нека вам се одазову ако истину говорите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Имају ли они ноге да на њима ходају, или руке да њима прихватају, имају ли очи да њима гледају, или уши да њима чују? Реци: „Зовите своја божанства, па смислите против мене какво хоћете лукавство, и не одуговлачите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Мој је, заиста, заштитник Аллах Који Књигу објављује и Он се брине о доброчинитељима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'А они којима се ви, поред Њега, молите, не могу ни вама, а ни себи да помогну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'А кад их замолите да вас упуте на прави пут, они не чују; видиш их као да те гледају, али они не виде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Ти оно лепо што чине прихвати! И тражи да се чине добра дела, а незналица се клони!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'А ако ђаво покуша да те наведе на зло, ти потражи уточиште код Аллаха, Он, уистину, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Заиста, они који се боје Аллаха, чим их додирне ђаволска саблазан, сете се, и постану разборити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'док ђавољеве поданике ђаволи подржавају у заблуди и никако не престају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Кад им не донесеш никакав знак, они говоре: „Зашто га сам не измислиш!“ Реци: „Ја следим само оно што ми мој Господар објављује.“ Ово су јасни докази од вашег Господара и упута и милост за људе који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'А кад се учи Кур''ан, ви га слушајте и ћутите - да би вам милост била указана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'И спомињи свога Господара у себи, понизно и са страхопоштовањем и не подижући јако глас - ујутро и навече, и не буди међу немарнима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Они који су код твога Господара заиста не зазиру да Га обожавају; само Њега хвале и само се Њему клањају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Питају те о плену. Реци: „Плен припада Аллаху и Посланику.“ Зато се бојте Аллаха и изгладите међусобне размирице, и покоравајте се Аллаху и Његовом Посланику, ако сте прави верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'Прави су верници само они чија се срца страхом испуне кад се Аллах спомене, а кад им се речи Његове казују, веровање им повећају и ослањају се само на свога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Они који обављају молитву и удељују део од онога што им Ми дајемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Они су, заиста, прави верници - њих код њиховог Господара чекају почасти, и опрост, и дивна опскрба.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, 'Тако је било и онда када те је Господар твој са правом извео из твога дома, а то једној групи верника није никако било по вољи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'Расправљали су са тобом о борби, након што је било очигледно да ће да победе, као да наочиглед своју смрт гоне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, 'И кад вам је Аллах обећао да ће да буде ваша једна од две скупине, а ви сте више волели да то буде она која није била наоружана. Аллах је хтео Својим речима да утврди Истину и да порази невернике до последњег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, 'Да Истину утврди и неистину уништи, макар то злочинцима не било по вољи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, 'И када сте од свога Господара затражили спас, Он вам се одазвао: „Послаћу вам у помоћ хиљаду анђела који ће једни за другим да долазе.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Аллах је то учинио да би вас обрадовао и да би се тиме ваша срца умирила; а победа је само од Аллаха, јер Аллах је заиста силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, 'Кад је Он учинио да вас сан, као спокојство од Њега, обузме и са неба вам кишу спустио да би вас њоме очистио, и да би од вас отклонио ђавољево узнемиравање, и да би учинио ваша срца јаким и да би њоме учврстио стопала.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, 'Кад је Господ твој надахнуо анђеле: „Ја сам са вама, па учврстите оне који верују! У срца неверника Ја ћу да улијем страх, па их ви по потиљцима ударите, и ударите их по свим деловима тела.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'То је зато што су се супротстављали Аллаху и Његовом Посланику; а онога ко се супротставља Аллаху и Његовом Посланику, Аллах ће, заиста, да казни страшно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, 'Казна вам је то, па је искусите, а невернике чека патња у Ватри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'О ви који верујете, када се сукобите са неверницима, а њих је много, леђа им не окрећите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Онај ко им тада окрене леђа, осим онај који се повуче са намером да се поновно бори или приступи другој чети, вратиће се натоварен Божјом срџбом; Пакао ће да буде његово пребивалиште, а ужасно је то крајње одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Њих нисте ви убијали, него Аллах; и ниси ти гађао, кад си гађао, него је Аллах гађао, да би вернике лепом кушњом искушао - Аллах, заиста, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Тако је то било, а заиста Аллах ослабљује сплетке неверника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, 'Ако сте се неверници молили да победите, па дошла вам је, ето, ''победа''! А да се оканите неверовања, било би вам боље! И ако се поново вратите, Ми ћемо поново да се вратимо, и нимало неће да вам користи ваш табор, ма колико био бројан, јер Аллах је, заиста, уз вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'О ви који верујете, покоравајте се Аллаху и Његовом Посланику, и не окрећите се од њега, а чујете га,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'и не будите као они који су рекли: „Чули смо!“- А не слушају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, 'Заиста, најгора бића код Аллаха су они који су глуви и неми на истину, који не разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Да Аллах зна да од њих може да буде икаквог добра, учинио би да чују, а да је учинио и да чују, они би се, опет, окрећући се од тога удаљили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'О ви који верујете, одазовите се Аллаху и Посланику кад од вас затражи да чините оно што вас оживљава; и нека знате да Аллах делује између човека и његовог срца, и да ћете сви да будете сакупљени пред Њим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'И чувајте се искушења која неће да погоде само оне међу вама који су чинили неправду, и знајте да Аллах страшно кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'И сетите се кад вас је било мало, кад сте на Земљи били потлачени - бојали сте се да вас људи не похватају, па вам је Он дао склониште и Својом помоћу вас ојачао и благодатима вас опскрбио да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'О ви који верујете, не изневеравајте Аллаха и Посланика и не проневеравајте оно што вам је дато на чување, а свесни сте да то радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'И нека знате да су ваша богатства и ваша деца само искушење, и да је само код Аллаха велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'О ви који верујете, ако се будете бојали Аллаха, Он ће способност да вам дарује да раздвајате истину од неистине и преко ваших ружних поступака ће да пређе и опростиће вам. А Аллахова је доброта неизмерна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'И кад су ти неверници правили замке да би те бацили у тамницу или да би те убили, или да би те прогнали; они су замке спремали па је и Аллах њима спремао замке, а Аллах спрема најбоље замке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Када им се уче Наше речи, говоре: „Већ смо чули! Да хоћемо, и ми бисмо рекли тако нешто; то су само измишљотине древних народа.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'А кад су они рекли: „Аллаху, ако је ово збиља Твоја истина, Ти пусти на нас камење са неба као кишу или нам пошаљи болну патњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Аллах их и није казнио док си ти био међу њима; и Аллах неће да их казни све док они моле за опрост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'А заслужују да их Аллах казни када бране другима приступ Часном храму, а они нису његови чувари. Чувари његови треба да буду само они који се боје Аллаха, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Њихова молитва поред Ка''бе своди се само на звиждање и пљескање рукама; зато искусите патњу јер не верујете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Заиста они који не верују троше своју имовину да би одвраћали од Аллаховог пута. Они ће тако да је троше, затим ће због тога да се кају и на крају ће да буду побеђени. А они који не буду веровали - у Пакао ће да буду скупљени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, 'да би Аллах одвојио добре од неваљалих и да би неваљале једне на друге наслагао, а онда их све у гомилу збио и у Пакао бацио. Они су заиста губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Реци онима који не верују: ако се окане неверовања, биће им опроштено оно што је било пре; а ако се не окане - па зна се шта је било са древним народима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'И борите се против њих док смутња не ишчезне и док само Божја вера не остане. Ако се они окане, па заиста Аллах добро види шта они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'А ако се окрену, знајте да је Аллах ваш заштитник, а диван је Он Заштитник и диван Помагач!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'И знајте да од свега што заплените у борби једна петина припада Аллаху и Посланику, и његовој родбини, и сирочади, и сиромасима, и путницима - намерницима, ако верујете у Аллаха и у оно што смо објавили Нашем Посланику на Дан раздвајања Истине од неистине, на дан кад су се сукобиле две војске - а Аллах над свим има моћ -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, 'када сте ви били у ближој страни долине, они у даљој страни долине, а каравана је била испод вас. И да сте се договарали о времену борбе, не бисте се договорили, али се она догодила да би Аллах дао да се испуни оно што је морало да се догоди, да неверник остане неверник после очигледног доказа, и да верник остане верник после очигледног доказа - а Аллах је, заиста, Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, 'Кад ти је Аллах у сну показао да је њих мало; а да ти је показао да их је много, ви бисте духом клонули и о борби се расправљали, али је Аллах указао спас. Он, заиста, добро зна шта скривају свачије груди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'А кад сте се сукобили, у вашим очима Он их је приказао у малом броју, а вас у њиховим очима такође у малом броју, да би Аллах дао да се испуни оно што је морало да се догоди - а Аллаху се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'О ви који верујете, кад се са неком четом сукобите, будите храбри и непрестано славите Аллаха, да бисте успели,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'и покоравајте се Аллаху и Његовом Посланику, и не препирите се да не бисте клонули и остали без борбеног духа; и будите стрпљиви, а Аллах је, заиста, уз стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'И не будите као они који су, да се покажу свету, надмено из свога града изашли да би одвраћали од Аллаховог пута, а Аллах обухвата оно што раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, 'И када им је ђаво њихове поступке представио лепим и рекао: „Нико данас не може да вас победи, и ја сам, уистину, ваш заштитник!“ - Онда се он, кад су се сукобила два противничка табора, уназад повукао, и рекао: „Ја, заиста, немам ништа са вама, ја видим оно што ви не видите, и ја се бојим Аллаха, а Аллах страшно кажњава.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, 'И сети се када су лицемери и они чија су срца болесна говорили: „Ове је обманула њихова вера!“ А онај ко се поузда у Аллаха – па Аллах је, заиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'А да си само видео кад су анђели узимали душе неверницима и по њиховим лицима их и страга ударали: „Искусите патњу у Огњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, 'То је оно што сте сами себи припремили, а Аллах, заиста, не чини неправду Својим створењима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, 'Тако је било и са фараоновим људима и онима пре њих - у Аллахове доказе нису веровали, па их је Аллах казнио због њихових греха. Аллах је, уистину, моћан и страшно кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'То је зато што Аллах неће да лиши благостања народ коме је благостање подарио - све док се он сам не промени - а Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, 'Тако је било са фараоновим људима и онима пре њих: знакове свога Господара нису признавали, па смо их Ми, због њихових греха, уништили, а фараонове људе смо потопили – сви су они били неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, 'Најгора бића код Аллаха су, заиста, они који поричу; они не верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, 'они са којима ти склапаш уговоре, па они сваки пут, не бојећи се Аллаха, крше свој уговор.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Ако се у борби сукобиш са њима, казни их тако да се због њих разбеже они који су иза њих, како би узели поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'И чим приметиш издајство код неког народа, ти њима уговор откажи – јер Аллах, уистину, не воли издајице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'И нека никако не мисле они који не верују да ће да се спасе; они, заиста, неће моћи да умакну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'И против њих припремите колико год можете снаге и коња за бој, да бисте тиме заплашили Аллахове и ваше непријатеље, и друге осим њих - ви их не познајете, Аллах их зна. Све што на Аллаховом путу потрошите биће вам надокнађено, и неће да вам буде учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Ако они буду склони миру, буди и ти склон и поуздај се у Аллаха, а Он је, уистину, Свечујући и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'А ако буду хтели да те преваре - па теби је, заиста, довољан Аллах; Он те подржава Својом помоћу и верницима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'и Он је сјединио њихова срца. Да си ти потрошио све оно што на Земљи постоји, ти не би сјединио њихова срца, али их је Аллах сјединио. Он је заиста силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'О Веровесниче, Аллах је довољан теби и верницима који те следе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'О Веровесниче, бодри вернике на борбу! Ако вас буде двадесет издржљивих, победићете две стотине; а ако вас буде стотину - победићете хиљаду оних који не верују, зато што су они људи који не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Сада вам Аллах даје олакшицу и зна да међу вама има слабости. Ако вас буде стотину издржљивих - победићете две стотине, а ако вас буде хиљаду - победићете, Аллаховом дозволом, две хиљаде. А Аллах је уз стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Ниједном веровеснику није било допуштено да држи заробљенике док не оствари победу на Земљи; ви желите пролазна добра овога света, а Аллах жели онај свет. Заиста је Аллах силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'Да није раније Аллахове одредбе, снашла би вас патња велика због онога што сте узели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Сада трошите оно што сте запленили као допуштено и лепо, и бојте се Аллаха; Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'О Веровесниче, реци онима који су као заробљеници пали у ваше руке: „Ако Аллах зна да у вашим срцима има било шта добро, даће вам боље од онога што вам је узето и опростиће вам, а Аллах опрашта грехе и милостив је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'А ако желе да те преваре, па они су и пре настојали Аллаха да варају и зато ти је Он омогућио да их победиш; а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'Заиста они који верују и исељавају се, и у борби на Аллаховом путу залажу своја богатства и своје животе, и они који пружају уточиште и помажу, они су једни другима заштитници. А онима који верују, а који се нису иселили, ви не можете, све док се не иселе, да будете заштитници. А ако вас замоле да им помогнете у вери, дужни сте да им притекнете у помоћ, осим против народа са којим о ненападању имате склопљен уговор. А Аллах добро види оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Неверници су једни другима заштитници. Ако не поступите тако, настаће смутња на Земљи и велики неред.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'Они који верују и иселе се, и боре се на Аллаховом путу, и они који пружају склониште и помажу - они су збиља прави верници - њих чека опрост и дивна опскрба.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'А они који касније верници постану, па се иселе и у борби заједно са вама учествују - они су ваши. А рођаци су, према Аллаховој Књизи једни другима пречи. Аллах, заиста, све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, 'Ово је обзнана о престанку заштите, од Аллаха и Његовог Посланика, оним незнанобошцима са којима сте закључили уговоре.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, '“Путујте по свету још четири месеца, али знајте да Аллаху нећете умаћи и да ће Аллах невернике осрамотити."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, 'Ово је и проглас од Аллаха и Његовог Посланика људима на највећи дан ходочашћа, да Аллах и Његов Посланик немају ништа са незнанобошцима, па ако се покајете - то је за вас боље, а ако се окренете знајте да Аллаху нећете да умакнете. А неверницима наговести болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Изузетак су незнанобошци са којима имате закључене уговоре које они нису ни у чему повредили, нити су помагали икога против вас, испоштујте уговоре са њима до договореног рока; Аллах заиста воли богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Када прођу свети месеци, онда убијајте незнанобошце где год их нађете, заробљавајте их, опседајте и дочекујте на сваком пролазу. Па ако се покају и буду обављали молитву и давали милостињу, оставите их на миру, а Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Ако те неки незнанобожац замоли за заштиту, ти га заштити да би саслушао Аллахове речи, а потом га отпреми на сигурно место за њега. То је зато што су они народ који не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Како незнанобошци могу да имају уговор са Аллахом и Његовим Послаником?! Могу да имају само они са којима сте уговор код Часног храма закључили; све док се они буду придржавали уговора, придржавајте се и ви, а Аллах, заиста, воли побожне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Како, када они, ако би вас победили, не би, кад сте ви у питању, поштовали ни сродство ни споразум? Они вам се умиљавају говором својих уста, али им се срца противе; већина њих су зликовци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'Они Аллахове речи замењују за оно што мало вреди, па одвраћају од Његовог Пута, заиста је ружно како поступају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'Ни сродство ни споразум, када је верник у питању, не поштују, и све границе зла прекорачују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Али ако се они буду покајали и обављали молитву и давали милостињу, браћа су вам по вери - а Ми речи и знакове објашњавамо људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'А ако прекрше заклетве након што са њима склопите уговоре, и ако буду вређали вашу веру, онда се борите против коловођа неверства - за њих, заиста, не постоје заклетве - како би се оканили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Зар нећете да се борите против људи који су прекршили своје заклетве, и настојали су да протерају Посланика и први су вас напали? Зар их се бојите? Прече је да се бојите Аллаха ако сте верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Борите се против њих, Аллах ће вашим рукама да их мучи и понизи, а вас ће да помогне против њих и залечиће груди верника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'и одстраниће срџбу из њихових срца. А Аллах ће да прими покајање од онога од кога Он хоће; Аллах све чује и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Зар мислите да ћете да будете остављени, а да Аллах не укаже на оне међу вама који се боре и који уместо Аллаха и Његовог Посланика и верника нису узели никога за присног пријатеља?! А Аллах у потпуности зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'Незнанобошци нису достојни да одржавају Аллахове куће, кад сами признају да су неверници. Њихова дела су поништена и вечно ће да остану у Ватри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Аллахове куће одржавају они који у Аллаха и у Будући свет верују и који обављају молитву и дају обавезну милостињу и који се не боје никога осим Аллаха, они су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Зар сматрате да је напајање ходочасника водом и одржавање Часног храма попут вредности оног који верује у Аллаха и у Будући свет и који се бори на Аллаховом путу? Нису они једнаки пред Аллахом, а Аллах неће да упути неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'Они који верују, и који се исељавају, и који се боре на Аллаховом путу, залажући своја богатства и своје животе на већем су степену код Аллаха; они су заиста успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Господар њихов им шаље радосни наговештај о Његовој милости и задовољству, и о рајским баштама у којима ће непрекидно да уживају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'У њима ће вечно да бораве. Уистину, код Аллаха је велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'О ви који верујете, не узимајте за присне пријатеље ни своје очеве ни своју браћу, ако више воле неверовање од веровања. А ко год од вас буде одржавао са њима присно пријатељство, па такви су прави неправедници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'Реци: „Ако су вам ваши очеви, и ваши синови, и ваша браћа, и ваше жене, и ваш род, и ваша имања која сте стекли, и трговачка роба за коју страхујете да неће да се прода, и ваше куће у којима се пријатно осећате - дражи од Аллаха и Посланика, и од борбе на Његовом путу, онда причекајте док Аллах Своју одлуку не донесе. А Аллах неће да упути грешнике.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Аллах вас је помагао на многим бојиштима, а и онога дана на Хунејну кад вас је занело ваше мноштво, али вам оно није било ни од какве користи, него вам је Земља, колико год да је била пространа, постала тесна, па сте се дали у бег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Затим је Аллах на Свог Посланика и на вернике спустио Свој смирај, и послао је војске анђела које ви нисте видели, и оне који нису веровали ставио је на муке; то је била казна за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Аллах је после тога оном коме је хтео опростио. А Аллах прашта и самилостан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'О ви који верујете, незнанобошци су сама поган и нека се, након ове године, више не приближују Часном храму Каби. А ако се бојите оскудице па Аллах ће да вас, ако хоће, учини богатим из Свога обиља. Аллах, заиста, све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Борите се против оних којима је дата Књига, а који не верују ни у Аллаха ни у онај свет, они не сматрају забрањеним оно што Аллах и Његов Посланик забрањују и не исповедају истинску веру - све док не дају главарину послушно и при том буду понизни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Јевреји говоре: „Узејр је Аллахов син“, а хришћани кажу: „Месија је Аллахов син.“ То су њихове речи, из њихових уста, опонашају речи претходних неверника - убио их Аллах! Куда се одмећу?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Они, поред Аллаха, боговима сматрају своје свештенике, и своје монахе и Месију, Маријиног сина. А наређено им је да обожавају само јединог Аллаха – нема истинског бога осим Њега. Узвишен је Он у односу на оне које Њему придружују у обожавању.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'Они желе да својим измишљотинама утрну Аллахово светло, а Аллах ће, свакако, да употпуни Своје светло, макар то неверници мрзели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'Он је послао Свог Посланика са упутом и правом вером, да би је уздигао изнад свих вера, макар то мрзели незнанобошци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'О ви који верујете, многи свештеници и монаси, заиста, једу туђу имовину на недозвољен начин и одвраћају од Аллаховог пута. Онима који злато и сребро гомилају и не троше га на Аллаховом путу - наговести болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'На дан кад се оно у ватри Пакла буде усијало па њиме њихова чела и њихове слабине и њихова леђа буду жигосана: „Ово је оно што сте за себе згртали, искусите зато казну за оно што сте гомилали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Број месеци код Аллаха, заиста, је дванаест, према Аллаховој Књизи, од дана када је небеса и Земљу створио, од којих су света четири. То је права вера. У њима не чините себи неправду! А борите се сви против незнанобожаца као што се сви они боре против вас, и знајте да је Аллах уз богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Премештање светих месеци само је додатно неверовање, чиме они који не верују бивају доведени у заблуду; једне године га проглашавају обичним, а друге године га сматрају светим, да би испунили број месеци које је Аллах учинио светим, па држе обичним оне које је Аллах учинио светим, њихови ружни поступци представљени су им као лепи. А Аллах неће да упути људе невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'О ви који верујете, зашто су неки од вас оклевали кад вам је било речено: „Крените у борбу на Аллаховом путу!“ Као да сте за земљу приковани? Зар вам је дражи живот на овом свету од оног света? А уживање на овом свету према оном свету је незнатно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Ако не будете ишли у бој, Он ће да вас стави на несносне муке и другим ће народом да вас замени, а ви нећете нимало да Му наудите. А Аллах има моћ над свим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Ако га ви не помогнете, па помогао га је Аллах онда кад су га они који не верују присилили да оде, кад је са њим био само његов друг, кад су њих двојица били у пећини, и кад је он казао свом другу: „Не брини, Аллах је са нама!“ Па је Аллах спустио Свој смирај на њега и помагао га војском коју ви нисте видели и учинио је да реч неверника буде доња, а Аллахова реч - она је горња. Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Крећите у бој, били слаби или снажни, и борите се на Аллаховом путу залажући своја богатства и своје животе! То вам је, да знате, боље!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, 'Да се радило о плену надохват руке и не толико далеком походу, лицемери би те сигурно следили, али им је пут изгледао далек. И они ће се Аллахом заклињати: „Да смо могли, заиста бисмо са вама пошли.“ Они упропаштавају сами себе, а Аллах, заиста, зна да су они лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, 'Нека ти Аллах опрости што си дозволио да изостану! Иначе би ти се открили они који говоре истину, а знао би и оне који лажу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Они који верују у Аллаха и у Будући свет неће да траже од тебе дозволу да се не боре залажући своја богатства и своје животе – а Аллах добро зна богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, 'Од тебе ће да траже дозволу само они који не верују у Аллаха и Будући свет, и чија се срца колебају, па су неодлучни у својој сумњи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Да су имали намеру да пођу, сигурно би за то припремили оно што је потребно, али Аллах није волео да у борбу пођу, па их је задржао и би им речено: „Останите са онима који остају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Да су пошли са вама, само би међу вама повећали раздор и брзо би међу вама убацили смутњу, а међу вама има и оних који их радо слушају. А Аллах добро зна неправеднике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'Они су и пре прижељкивали смутњу и смишљали су ти смицалице све док није дошла Истина и док није завладала Аллахова вера, а они то нису волели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Има их који говоре: „Дозволи ми и не доведи ме у искушење!“ Ето, баш су пали у искушење! А Пакао ће сигурно да обухвати невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Ако те задеси добро, то их ражалости, а кад те погоди несрећа - они говоре: „Ми смо и раније били опрезни“, и одлазе весели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, 'Реци: „Догодиће нам се само оно што нам Аллах одреди, Он је наш Господар, и нека се верници само у Аллаха поуздају!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'Реци: „Очекујете ли за нас шта друго већ једно од два добра?“ А ми очекујемо да вас Аллах Својом казном погоди, или да вас рукама нашим казни. Па чекајте! И ми ћемо, заиста, са вама да чекамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, 'Реци: „Трошили милом или силом, од вас неће да буде примљено; ви сте, заиста, људи грешници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'А милостиња њихова не може бити прихваћена јер не верују у Аллаха и Његовог Посланика, и зато што мрзовољно обављају намаз и само преко воље удељују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Нека те не одушевљавају њихове имовине, а ни њихова деца! Аллах хоће да их због њих казни на овом свету и да им душе, док су неверници, изађу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Они се заклињу Аллахом да су заиста ваши, а они нису ваши, него су кукавички народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Кад би нашли какво склониште, или какву пећину или јаму, они би тамо брзином побегли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Има их који ти приговарају због расподеле обавезне милостиње. Ако им се из ње да, задовољни су, а ако им се не да, одједном се разљуте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'А да су задовољни оним што им дају Аллах и Његов Посланик и да кажу: „Довољан нам је Аллах, Аллах ће нам дати из Свога обиља, а и Његов Посланик, и ми, заиста, за сусрет са Аллахом жудимо“.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Обавезна милостиња припада само сиромасима и невољницима, и онима који је сакупљају, и онима чија срца треба да се придобију, и за откуп из ропства, и презадуженима, и у сврхе на Аллаховом путу, и путнику намернику. Аллах је одредио тако! А Аллах је свезнајући и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Има их који узнемиравају Веровесника и говоре: „Он је као уво - верује у све што чује!“ Реци: „Он је као уво које чује оно што је добро по вас, верује у Аллаха и верује верницима, и милост је онима између вас који верују.“ А оне који Аллаховог Посланика узнемиравају чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Заклињу вам се Аллахом да бисте били задовољни, а прече би им било да Аллах и Његов Посланик буду њима задовољни, ако су верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Зар они не знају да онога који се супротставља Аллаху и Његовом Посланику чека ватра у Паклу, у којој ће да остану вечно? То је велико понижење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Лицемери се плаше да се верницима не објави поглавље које би открило оно што им је у срцима. Реци: „Само се ви ругајте.“ Аллах ће, заиста, на видело да изнесе оно чега се ви плашите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Ако их запиташ, они ће сигурно да кажу: „Ми смо само разговарали и забављали се.“ Реци: „Зар се нисте ругали Аллаху, Његовим речима, и Његовом Посланику?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Не правдајте се! Јасно је да сте постали неверници након што сте веровали. Ако некима од вас и опростимо, друге ћемо да казнимо зато што су били кривци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Лицемери и лицемерке слични су једни другима: траже да се раде неваљала дела, а одвраћају од добрих, и руке су им стиснуте, заборављају Аллаха, па је и Он заборавио њих. Лицемери су, заиста, прави неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Лицемерима и лицемеркама и неверницима Аллах је обећао ватру у Паклу, вечно ће у њој да бораве, довољна ће им она бити! Аллах их је проклео, и њих чека непрестана патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, 'Ви сте као и они пре вас. Они су били јачи од вас и више су имали блага и деце, и живели су слатким животом, а и ви живите слатким животом, исто онако, као што су живели они пре вас, и ви се упуштате у неваљалштине као што су се и они упуштали. То су они чија ће дела да буду поништена и на овом и на оном свету, и они су заиста губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Зар до њих није допрла вест о онима пре њих: о Нојевом народу, и о Аду, и о Семуду, и о Аврамовом народу, и о становницима Медјена, и о онима чија су насеља преврнута? Њихови Посланици су им доносили јасне доказе и Аллах им није учинио никакву неправду, него су они сами себи чинили неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'А верници и вернице пријатељи и заштитници су једни другима: траже да се раде добра дела, а одвраћају од неваљалих, и обављају молитву и дају милостињу, и покоравају се Аллаху и Његовом Посланику. То су они којима ће Аллах сигурно да се смилује. Аллах је, заиста, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Аллах је обећао верницима и верницама рајске баште, кроз које теку реке, у којима ће да бораве вечно, а дивног ли боравишта у еденским вртовима. А Аллахово задовољство веће је од свега тога: то ће, заиста, да буде велики успех!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'О Веровесниче, бори се против неверника и лицемера и буди строг према њима. Њихово пребивалиште биће Пакао, а ужасно је то крајње одредиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Лицемери се заклињу Аллахом да нису говорили, а сигурно су говорили речи неверства и показивали су да су неверници, након што су јавно ислам били примили, и хтели су да учине оно што нису успели. А приговарају само зато што их је Аллах, из Свог обиља, и Његов Посланик, учинили богатим. Па ако се покају, биће им добро, а ако се окрену, Аллах ће да их стави на болне муке на овом и на Будућем свету, а на Земљи ни заштитника ни помагача неће имати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Има их који су се обавезали Аллаху: „Ако нам из Свога обиља подари, удељиваћемо, заиста, милостињу и бићемо, заиста, добри.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'А кад им је Он дао из Свога обиља, они су у томе постали шкрти и окрећући се - од тога удаљили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'И надовезао им је Он на то и лицемерство у срцима све до дана када ће пред Њим да стану, а то је због тога што су изневерили оно што су обећали Аллаху, и зато што су стално лагали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Зар они не знају да Аллах зна оно што они у себи крију и оно о чему се сашаптавају и да Аллах зна све скривено?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, 'Оне који оговарају вернике, који добровољно дају милостињу, а ругају се и онима који је дају са муком – Аллах ће да извргне порузи, и њих чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'Молио ти опрост за њих или не молио, молио чак и седамдесет пута, Аллах неће да им опрости - зато што у Аллаха и Његовог Посланика не верују. А Аллах неће да упути непослушне људе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'Они који су изостали за Аллаховим Послаником веселили су се у својим кућама - мрско им је било да се боре на Аллаховом путу залажући своја богатства и своје животе, и једни другима су говорили: „Не крећите у бој по врућини“, реци: „Ватра у Паклу је још врелија!“ Само да су они схватили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'Нека се сад мало смеју, а дуго ће плакати, биће то казна за оно што су зарадили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'И ако те Аллах поново врати некима од њих, па те замоле да им допустиш да пођу са тобом у бој, ти им реци: „Никад са мном у бој нећете да идете и никада са мном против непријатеља нећете да се борите! Били сте задовољни што сте први пут изостали, зато останите са онима који ионако не иду у бој.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'И ниједном од њих, кад умре, немој да обавиш молитву, и немој да молиш за њега над његовим гробом. Они, у Аллаха и Његовог Посланика, заиста, нису веровали и као неверници они умиру.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Нека те не усхићују њихова богатства и њихова деца! Аллах жели да их њима на овом свету намучи и да им душе - док су неверници - изађу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'А када је објављено поглавље да у Аллаха верујете и да се заједно са Његовим Послаником борите, најбогатији од њих су затражили одобрење од тебе и рекли: „Остави нас да будемо са онима који не иду у бој!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Задовољавају се да буду са онима који не иду у бој, њихова срца су запечаћена, па они не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Али Посланик и они који верују са њим боре се залажући своја богатства и своје животе. Њима ће да припадне свако добро и они ће да успеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Аллах им је припремио рајске баште кроз које теку реке, у којима ће да бораве вечно. То је велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Долазили су и неки бедуини који су се извињавали и тражили су допуштење да не иду, и тако су изостали они који су лагали Аллаха и Његовог Посланика, а тешка патња погодиће оне међу њима који нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Неће да се огреше немоћни и болесни, и они који не могу да нађу средства за борбу, само ако су искрени према Аллаху и Његовом Посланику. Нема разлога да се ишта приговара онима који чине добра дела - а Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Ни онима којима си казао, кад су ти дошли да им даш животиње за јахање: „Не могу да нађем за вас животиње за јахање“, па су се вратили сузних очију, тужни што немају ништа што би утрошили за борбу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Заслужују казну они који од тебе траже дозволу да изостану из боја, а богати су. Задовољни су тиме да остану са онима који не иду у бој, а Аллах је запечатио њихова срца, па зато они не знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Кад се вратите међу њима, они ће да вам се правдају. Реци: "Немојте да се правдате, ми вам не верујемо, јер нас је Аллах о вама обавестио. А Аллах и Његов Посланик ће видети и ваша друга дела, а затим ћете бити враћени Ономе који невидљиви и видљиви свет зна, па ће вас Он обавестити о ономе што сте радили."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Кад се вратите међу њима, заклињаће вам се Аллахом, само да их пустите на миру, па пустите их. Они су, заиста, покварени и њихово пребивалиште биће Пакао, као казна за оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Они вам се заклињу зато да бисте били задовољни њима. Ако ви будете задовољни њима, Аллах сигурно није задовољан народом неверничким.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Бедуини су жешћи у неверовању и лицемерству, и најприличније је да не познају прописе које Аллах објављује Своме Посланику. А Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Има бедуина који оно што удељују сматрају наметом и једва чекају да вас стигну несреће - нека њих погоди несрећа, а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'А има бедуина који верују у Аллаха и у Будући свет и који сматрају да је оно што удељују пут да се Аллаху приближе и да заслуже Посланикове благослове. То им је, заиста, добро дело. Аллах ће да их обаспе Својом милошћу, Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Аллах је задовољан првим муслиманима, исељеницима из Мекке и становницима Медине, и свима онима који их следе радећи добра дела. А и они су задовољни Њиме. За њих је Бог припремио рајске баште, кроз које теку реке, и они ће вечно и заувек да бораве у њима. То је велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Међу бедуинима око вас има лицемера, а има их и међу становницима Медине, који су упорни у свом лицемерству - ти их не познајеш, али их Ми познајемо. Њих ћемо да ставимо на двоструке муке, а затим ће да буду враћени у велику патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'А има и других који су признали своје грехе, и који су помешали добра дела са лошим делима; њима ће Аллах да опрости - Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Прихвати од њиховог иметка милостињу, да их тиме очистиш од греха и учиниш их благословљеним, и помоли се за њих, молитва твоја ће, заиста, да их смири - а Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Зар не знају они да једино Аллах прима покајање од слугу Својих и да само Он прихвата милостињу, и да Аллах стално прима покајања, и да је Он Милостив?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'И реци: „Трудите се! Аллах ће да види ваш труд, а и Његов Посланик и верници, и ви ћете да будете враћени Ономе Који зна невидљиви и видљиви свет, па ће да вас обавести о ономе што сте радили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Има и других који су у неизвесности да ли ће Аллах да их казни или ће да им опрости. А Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'А они који су саградили џамију да би нанели штету, и оснажили неверовање, и унели раздор међу верницима, припремајући је за онога који се још пре борио против Аллаха и Његовог Посланика, сигурно ће се заклињати: „Ми смо желели само најбоље", а Аллах је сведок да су они сигурно лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Ти у њој немој никада да обавиш молитву! Џамија чији су темељи, већ од првог дана, постављени у страху од Аллаха, заиста више заслужује да у њој обавиш молитву. У њој су људи који воле често да се чисте, а Аллах воли оне који се много чисте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Да ли је бољи онај који је темељ своје грађевине поставио у страху од Аллаха и желећи Његово задовољство, или онај који је темељ своје зграде поставио на руб подлокане обале која се нагнула, да се сруши заједно са њим у ватри Пакла? А Аллах неће да упути на Прави пут неправедне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Грађевина коју су они саградили стално ће да уноси немир у њиховим срцима, све док им срца не попуцају - а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Аллах је откупио од верника њихове животе и њихове имовине у замену за Рај који ће им подарити. Они ће да се боре на Аллаховом путу, па да у борби убијају и буду убијени. Он је то, заиста, обећао у Тори, Јеванђељу и Кур''ану. А ко од Аллаха доследније испуњава своје обећање? Зато се радујте својој погодби коју сте са Њим постигли, а то је засигурно велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, 'Они се кају, и Њега обожавају, и Њега хвале, и ради Њега посте, и прегибају се и падају ничице, и траже да се раде добра дела, а одвраћају од неваљалих и придржавају се Аллахових прописа. А такве вернике обрадуј!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Веровеснику и верницима није допуштено да моле Бога да опрости незнанобошцима, макар им били и најближи род, кад им је јасно да ће они становници у Паклу да буду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'И једино због чега је Аврам тражио опрост за свога оца, јесте због обећања које му је дао. А чим му је било јасно да је он Аллахов непријатељ, одрекао га се. Аврам је, заиста, много Аллаху био посвећен и људима пуно праштао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Аллах неће дати да залута народ којег је на Прави пут упутио пре него што им објасни оно чега треба да се чувају; Аллах, заиста, све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Заиста је Аллахова власт на небесима и на Земљи, Он живот и смрт даје, и ви осим Аллаха немате ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Аллах је опростио Веровеснику, и исељеницима из Мекке, и становницима Медине, који су га следили у тешком часу, у време када су се срца неких од њих умало поколебала: Он је после и њима опростио. Он је према њима, заиста, милосрдан и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'А опростио је и оној тројици чије је покајање било одложено тако да им је Земља, колико год да је била пространа, постала тесна, и у душама њиховим им је било стиснуто, и схватили су да нема уточишта од Аллаха него само код Њега. Он им је после опростио, како би се и убудуће кајали, а Аллах, уистину, стално прима покајања, и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'О ви који верујете, бојте се Аллаха и будите са онима који су искрени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Није требало да становници Медине ни бедуини у његовој близини изостану за Аллаховим Послаником и да чувају свој живот запостављајући његов, јер њих неће да задеси ни жеђ, ни умор, ни глад на Аллаховом путу, нити ће да дођу на неко место које ће невернике да наљути, нити ће да остваре икакву добит над непријатељем, а да то све неће да им буде уписано као добро дело; Аллах, заиста, неће да допусти да пропадне награда онима који раде добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'И неће уделити иметак, било то мало или много, нити ће прећи неку долину, а да им то неће бити записано, да би их Аллах наградио бољим од онога што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'Не треба сви верници да иду у бој. Нека се по неколико њих из сваке заједнице потруде да се подуче верским наукама и нека упозоравају свој народ када им се врате, да би били на опрезу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'О ви који верујете, борите се против непријатељских неверника који су у вашој близини и нека они осете вашу чврстину, и знајте да је Аллах са богобојазнима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'А кад буде објављено неко поглавље, има оних који говоре: „Коме је од вас ово поглавље повећало веровање? Што се тиче верника, њима је повећало веровање и они се радују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'А што се тиче оних чија су срца болесна, оно им је додало сумњу на сумњу коју већ имају и они ће умрети као неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Зар они не виде да им сваке године једном или двапута долазе искушења, и опет се не кају, нити поуку примају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'А кад буде објављено које поглавље, само се загледају: „Да ли вас ко види?“ И онда се окрену и напусте. Аллах је скренуо њихова срца, зато што су они људи који не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'Дошао вам је Посланик, један од вас, тешко му је што ћете искушења да имате, једва чека да пођете правим путем, а према верницима је благ и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'А ако се они од тебе окрену, ти реци: „Мени је довољан Аллах, нема истинског божанства осим Њега; Само се на Њега ослањам, Он је Господар величанственог Престола!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Елиф-лам-ра. Ово су речи мудре Књиге.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'Зашто је чудно људима што Ми објављујемо једном између њих: „Опомињи људе! А оне који верују обрадуј да их искрена дела која су урадили чекају код њиховог Господара.“ Али, неверници говоре: „ Овај је, заиста, очити чаробњак!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Ваш Господар је Аллах, Који је створио небеса и Земљу за шест дана а онда се узвисио над Престолом, Он све одређује. Нико неће моћи да се заузима ни за кога без Његовог допуштења. То је Аллах, ваш Господар, па само Њега обожавајте! И зашто поуку не примите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, 'Њему ћете сви да се вратите - то је Аллахово истинско обећање; Он, заиста, из ничега ствара, и после ће поново да вас проживи, да би по правди наградио оне који буду веровали и добра дела чинили. А оне који не буду веровали чека пиће од кључале воде и болна патња, зато што су били неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'Он је Тај Који је Сунце учинио извором светлости а Месец сјајним, и одредио му је положаје да бисте знали број година и рачунање. Аллах је то са разлогом створио. Он потанко излаже доказе и знакове људима који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'У смени ноћи и дана и у оном што је Аллах створио на небесима и на Земљи заиста постоје докази за људе који се Бога боје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Заиста онима који не очекују да ће пред Нама да полажу рачун, и који су задовољни животом на овом пролазном свету, који су у њему смирени, и онима који су равнодушни према нашим речима и доказима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'њихово пребивалиште ће да буде Пакао, због онога што су заслужили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'Оне који верују и раде добра дела њихов Господар ће, заиста, да учврсти и упути због њиховог веровања. Испод њих ће у Рају реке тећи у вртовима уживања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Њихова молитва биће у Рају: „Узвишен нека си, Аллаху“, и поздрав њихов биће: „Мир Божји“, а њихова последња молба: „Хвала Аллаху, Господару светова.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Када би се Бог одазивао молбама људи када траже зло онако брзо као што им се одазива када траже добро, они би, уистину, страдали. А Ми, ипак, остављамо да лутају у својој осионости они који не верују да ће пред Нама стати да одговарају за своја дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'Када човека снађе невоља, он Нам се моли скрушено лежећи, или седећи, или стојећи. А чим му отклонимо невољу, он наставља да се понаша као да Нам се није ни обраћао молбом због невоље која га је задесила. Тако се неверницима чини лепим оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Ми смо народе пре вас уништавали зато што нису поверовали кад су им посланици њихови јасне доказе доносили. Нису хтели да верују. Тако Ми кажњавамо народ невернички.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Затим смо вас, после њих, учинили наследницима на Земљи, да бисмо видели како ћете да поступате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'А кад им се уче Наше јасне речи, онда они који не верују да ће да стану пред Нама говоре: „Донеси ти неки други Кур''ан, или га измени!“ Реци: „Није моје да га ја сам од себе мењам, ја следим само оно што ми се објављује, ја се бојим, ако будем непокоран своме Господару, патње на Великом дану.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, 'Реци: „Да Аллах није хтео, ја вам Кур''ан не бих учио нити би вас Он њиме подучио. Ја сам пре посланства дуго боравио међу вама - зар не разумете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Нико није неправеднији од онога који о Аллаху износи лажи или који Његове речи сматра неистинитим! Неверници заиста неће успети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'Они, поред Аллаха, обожавају оно што не може нити да им науди нити да им какву корист донесе, и говоре: „Ови се за нас заузимају код Аллаха.“ Реци: „Зар да Аллаха обавештавате да на небесима и на Земљи постоји нешто што Он не зна да постоји?!“ Узвишен је Он и врло високо у односу на оне које Му придружују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'Људи су били једна заједница, а онда су се разишли. А да није речи раније изречене од твога Господара, овима би већ било пресуђено о ономе у чему се разилазе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, 'Они говоре: „Зашто му његов Господар не пошаље какво чудо?“ Ти реци: „Само Аллах зна оно што је недокучиво чулима, па причекајте, и ја ћу, заиста, с вама заједно да чекам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'А када им подаримо да осете милост после невоље која их задеси, они опет у вези са Нашим речима и доказима смишљају сплетке. Реци: „Аллах најбрже узвраћа на сплетке; Наши анђели, оно што ви сплеткарите, заиста записују.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'Он је Тај Који вам омогућава да путујетe копном и морем, кад сте у лађама, и кад оне заплове са путницима уз благ поветарац, па се они обрадују томе, а када наиђе силан ветар и валови навале на њих са свих страна и они тада уверени да ће да настрадају, искрено се моле Аллаху: „Ако нас из овога избавиш, сигурно ћемо да будемо од захвалних.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'А кад их Он избави, одмах чине насиље на Земљи потпуно неосновано. О људи, ваше насиље које чините ради уживања у овосветском животу само вама штети; Нама ћете после да се вратите и Ми ћемо о оном што сте радили да вас обавестимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Живот на овом свету сличан је земаљском биљу на које Ми спустимо воду са неба са којим се она измеша, којим се онда хране људи и стока. Па кад се Земља окити својим накитом и украсима, и кад становници њени помисле да они тиме располажу, дође Наша одредба, ноћу или дању, и Ми то покосимо као да пре ничега није ни било. Ето, тако Ми појашњавамо речи и доказе људима који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Аллах позива у Рај, место мира и спаса, и упућује на Прави пут онога кога Он хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'Онима који чине добра дела припада лепа награда - Рај, а и више од тога! Њихова лица неће прекривати тама и потиштеност, они ће да буду становници Раја, у њему ће вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'А оне који чине лоша дела чека казна сразмерна оном што су чинили и њих ће прекривати потиштеност. Никога неће имати да их заштити од Аллаха, лица ће да им буду тамна као да су прекривена деловима мркле ноћи, они ће да буду становници Ватре, и у њој ће вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'А на Дан кад их све сакупимо, онима који су друге поред Аллаха обожавали рећи ћемо: „Останите на своме месту, и ви и ваша божанства!“ Па ћемо да их раздвојимо, а њихова божанства ће да кажу: „Нисте ви нас обожавали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Аллах је довољан сведок и нама и вама, ми, заиста, нисмо знали да сте нас обожавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Ту ће свако да се суочи са оним што је пре урадио, и биће враћени Аллаху, свом истинском Господару, а неће да им буде оних које су измишљали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'Упитај: „Ко вас опскрбљује са неба и из земље?“ Или: „Ко влада слухом и видом, ко изводи живо из неживог и из живог неживо, и ко управља свиме?“ „Аллах“, рећи ће они. А ти реци: „Па зар се Аллаха не бојите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'То вам је Аллах, ваш истински Господар! Зар после Истине има ишта осим заблуде?! Па куда се онда одмећете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Тако се обистинила реч твога Господара над онима који су грешили, да неће да верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'Реци: „Има ли међу вашим божанствима иједно које ствара из ничега, а затим то након смрти оживи?“ Реци: „Аллах ствара без претходног примера, а затим то оживи након смрти! Па куда се онда одмећете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'Реци: „Може ли иједно ваше божанство да упути ка Истини?“ И одговори: „Само Аллах упућује ка Истини! Па, да ли је онда достојнији слеђења Аллах Који ка Истини упућује или онај који ни сам није на правом путу, осим ако га Аллах на прави пут не упути? Шта вам је, како расуђујете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Већина њих следи само претпоставке, али претпоставке нимало нису од користи истини. Аллах уистину добро зна оно што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Овај Кур''ан није измишљен, од Аллаха је - он потврђује оно што је објављено пре њега и објашњава прописе, нема сумње да је он Објава од Господара светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'И зар они да говоре: „Мухаммед га измишља!“ Реци: „Па дајте ви једно поглавље као што је њему објављено, и кога год хоћете, од оних у које поред Аллаха верујете, у помоћ позовите, ако истину говорите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Заправо, они поричу пре него што темељно сазнају шта има у њему, а још им није дошло ни његово тумачење. Тако су и они пре њих порицали, па погледај како су завршили неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Има их који верују у истинитост Кур''ана, а има их који не верују. А твој Господар најбоље познаје смутљивце.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'И ако те они буду утеривали у лаж, ти реци: „Мени моја, а вама ваша дела; ви нећете да одговарате за оно што ја радим, а ја нећу да одговарам за оно што ви радите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'Има међу незнанобошцима оних који те слушају. А можеш ли ти да учиниш да те глуви чују, ако још и не разумеју?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'А међу незнанобошцима има и оних који те посматрају, а можеш ли ти да упутиш на Прави пут слепе, ако још и не увиђају?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Аллах, заиста, никакву неправду не чини људима, људи је чине сами себи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'А на судњем Дану када их Аллах сакупи, учиниће им се да су боравили само један кратак део дана на Земљи, и тада ће једни друге да препознају. Страдаће, засигурно, они који су порицали да ће пред Аллахом да стану и који нису Упуту следили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Било да ти покажемо део казне коју смо им припремили, било да те пре тога усмртимо, Нама ће сви да се врате, а Аллах је сведок ономе што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'Сваки је народ имао посланика, и кад њихов посланик дође међу њима на Судњем дану биће им праведно пресуђено, и неће им неправда бити учињена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Они говоре: „Када ће већ једном та претња да се оствари, ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'Реци: „Сам од себе не могу никакву штету да отклоним, а ни неку корист себи да прибавим; бива онако како Аллах хоће!“ Сваки народ има одређени рок, а кад рок његов дође, ни за трен неће моћи ни да га одложе ни да га убрзају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'Реци: „Кажите ви мени: Ако ће Његова казна да вас задеси ноћу или дању, зашто је онда пожурују злочинци?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, 'Зар ћете тек онда, кад се казна догоди, да поверујете?! Зар тек тада, а раније сте је пожуривали?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Затим ће онима који су били незнанобошци да буде речено: „Искусите вечну патњу; да ли сте кажњени осим према ономе што сте чинили?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, 'Они те запиткују: „Да ли је истина та патња?“ Реци: „Јесте, Господара ми мога, заиста је истина, и ви нећете моћи да је спречите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Кад би онај ко је био незнанобожац имао све оно што постоји на Земљи, све то дао само да се казне искупи. А кад доживе патњу, сакриће тугу, и биће им по правди пресуђено и неће да им буде учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Зар једино Аллаху не припада све што је на небесима и на Земљи? Аллахово обећање је, заиста, истина, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'Он живот и смрт даје и Њему ћете да се вратите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'О људи, већ вам је стигао Кур''ан као опомена од вашег Господара, он је лек за ваша срца, и упута и милост верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'Реци: „Нека се зато због Кур''ана - Аллахове благодати и милости радују; то је боље од онога што гомилају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'Реци: „Кажите ви мени зашто неку храну коју вам Аллах даје сматрате забрањеном, а другу допуштеном?“ Реци: „Да ли вам је то Аллах дозволио или о Аллаху износите лажи?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'И, шта мисле они који о Аллаху износе лажи, шта ће на Судњем дану да буде? Аллах је, заиста, неизмерно добар према људима, али већина њих не захваљује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, 'Шта год ти чинио, и шта год из Кур''ана учио и какав год ви посао радили, Ми над вама надзиремо док год се тиме бавите. Твоме Господару није ништа скривено ни на Земљи ни на небу, ни колико трун један, и не постоји ништа, ни мање ни веће од тога, што није у јасној Књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Заиста, Аллахови одабраници не треба да страхују и ни за чим не треба да тугују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'они који буду веровали и који се Аллаха буду бојали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'њима припадају радосне вести и на овом и на Будућем свету - а Аллахове речи не може нико да измени - то је, заиста, велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Нека те Посланиче не жалосте њихове увреде! Уистину, сва моћ припада Аллаху; Он све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'Заиста, у Аллаховој је власти све што је на небесима и на Земљи. А они који се, поред Аллаха, моле божанствима, поводе се само за претпоставкама и само измишљају лажи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'Он је Тај Који вам је дао ноћ да у њој нађете смирај, а дан да видите. У томе су, заиста, докази за људе који чују поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, 'Неки говоре: „Аллах је Себи узео дете!“ Узвишен је Он! Он ни од кога није зависан! Све што је на небесима и на Земљи Његово је! Ви за то никакав доказ немате. Зар о Аллаху да говорите оно што не знате?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, 'Реци: „Они који о Аллаху измишљају лажи неће успети.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, 'Уживаће кратко на овом свету, а затим ће Нама да се врате и Ми ћемо им дати да искусе жестоку патњу зато што нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Кажи им казивање о Ноји! Када он рече своме народу: „О народе мој, ако вам је тежак мој боравак међу вама, и ако вам је тешко моје опомињање Аллаховим речима и доказима, па ја се ослањам само на Аллаха, а ви се, заједно са својим лажним божанствима, одлучите, и нека вам одлука ваша не буде нејасна; затим је нада мном извршите и не одгађајте нимало!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, 'А ако се окренете од мог позива, па ја од вас никакву награду не тражим, мене ће Аллах да награди, мени је наређено да будем од оних који су Аллаху предани и покорни.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Али, прогласише га лажовом, па Ми у лађи њега и оне који су били уз њега спасисмо и учинисмо их наследницима а потописмо оне који су наше речи и доказе порицали, па погледај какав је био завршетак оних који су били упозорени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Затим смо, после њега, посланике народима њиховим слали који су им доносили јасне доказе, али они нису хтели да верују у оно што су пре порицали. Тако Ми печатимо срца онима који прелазе Аллахове границе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'Затим смо, после њих, Мојсија и Арона послали са Нашим доказима фараону и његовим главешинама, али су се они узохолили; били су народ злочиначки.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'А када им је од Нас дошла Истина, казали су: „Ово је, заиста, права враџбина!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, '„Зар за Истину која вам је дошла кажете да је враџбина?“ Казао је Мојсије, „а чаробњаци неће никад успети!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'А они рекоше: „Зар си дошао да нас одвратиш од онога на чему смо затекли наше претке, да би вас двојица добили власт у овој земљи? Ми нећемо да поверујемо вама двојици!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'И фараон рече: „Доведите ми сваког ученог чаробњака!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'И кад чаробњаци дођоше, Мојсије им рече: „Баците оно што имате да баците!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'И кад они бацише, Мојсије узвикну: „Оно што сте приредили чаролија је! Аллах ће заиста да је уништи, заиста, Аллах не дозвољава да дела покварењака буду исправна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Аллах ће Својим речима да утврди истину, макар то било криво неверницима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'И није поверовао Мојсију нико, осим мало њих из фараоновог народа, из страха да фараон и његове главешине не почну да их злостављају - а фараон је, заиста, на Земљи био насилник и заиста је био од оних који прелазе сваку границу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'И Мојсије рече: „О народе мој, ако верујете у Аллаха, поуздајте се у Њега ако сте Њему предани!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, '„Ослањамо се на Аллаха“, рекоше они. „Господару наш, не учини нас искушењем за људе који чине неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'И спаси нас Својом милошћу од неверничког народа!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'И ми објависмо Мојсију и његовом брату: „У Мисиру своме народу изградите куће и учините их богомољама и у њима обављајте молитву! А ти обрадуј вернике радосном вешћу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'И Мојсије рече: „Господару наш! Ти си дао фараону и његовим главешинама украсе и богатства на овом свету, да они, мој Господару, заводе са Твога пута! Господару наш, уништи њихова богатства и запечати њихова срца, па нека не верују све док не доживе болну патњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, '„Услишена је ваша молба!“ Рече Он, „а вас двојица устрајте на Правом путу и никако не следите пут незналица!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'И ми преведосмо преко мора Израиљеве синове, а за петама су им били фараон и његова војска, прогонећи их из злобе и непријатељства. Па када фараон поче да се дави, узвикну: „Ја верујем да нема бога осим Онога у Кога верују Израиљеви синови и ја сам Њему предан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, '„Зар сада верујеш, а пре си непокоран био и неред си ширио?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, '„Данас ћемо да избавимо само твоје тело, да би био поучан пример онима после тебе, али многи људи су равнодушни према Нашим речима и доказима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'И Ми смо Израиљеве синове населили у часни предео и опскрбили смо их лепом храном, и тек кад им је дошло право знање, они су се разишли у мишљењу. А твој Господар ће, сигурно, да им пресуди на Судњем дану о ономе у чему су се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'А ако сумњаш у оно што ти објављујемо, упитај оне који читају Књигу, објављену пре тебе. Теби истина од твога Господара долази, и никако не буди од оних који сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'И никако не буди од оних који поричу Аллахове речи и доказе, па да будеш од оних који ће страдати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'А они за које се испуни Реч твога Господара заиста неће никад поверовати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'Макар им дошли сви докази, све док не доживе болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'Није било ни једно насеље које је поверовало свом посланику, и да им је то веровање користило како би се сачували казне, осим Јониног народа; када су поверовали, отклонили смо им тешку патњу на овом свету, и дали смо им да још одређено време уживају у животу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Када би твој Господар то хтео, на Земљи би, заиста, сви људи били верници. Па зашто онда ти да нагониш људе да буду верници?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Ниједна особа не може да верује без Аллахове дозволе; а Он ће дати казну и пропаст онима који не размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, 'Реци: „Посматрајте оно што је на небесима и на Земљи!“ А ни од какве користи неће бити докази и упозорења народу који не жели да верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Зар они чекају да их снађе нешто слично ономе што је снашло оне који су били пре њих и нестали?! Реци: „Па чекајте, и ја ћу са вама да чекам!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Затим би спасили Наше посланике и оне који су веровали. Ето, тако је Наша обавеза да спасимо вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, 'Реци: „О људи, ако сумњате у моју веру - па, ја нећу да обожавам оне које ви, мимо Аллаха, обожавате, већ ћу да обожавам Аллаха, Који ће да вас усмрти и душе вам узме. Мени је наређено да будем од искрених верника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, 'И наређено ми је: „Потпуно и искрено се предај чистој вери монотеизма, и никако не буди од оних који друге поред Аллаха обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'И поред Аллаха, не моли се ономе ко не може ни да ти користи ни да ти науди, јер ако би то урадио, уистину, би био међу неправедницима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Ако ти Аллах да какву невољу, нико осим Њега не може да је отклони, а ако ти Аллах жели добро, па - нико не може Његову благодат да спречи; Он њоме награђује онога кога хоће од Својих створења; Он прашта грехе, и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, 'Реци: „О људи, Истина вам је дошла од вашег Господара, и онај ко се упути Правим путем - упутио се за своје добро, а онај ко крене странпутицом, кренуо је на своју штету, а ја нисам задужен да се бринем о вашим делима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Ти следи Објаву која ти се објављује и буди стрпљив док Аллах не пресуди, Он је судија најбољи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Елиф-лам-ра.[1] Ово је Књига чије су речи усавршене а потом разјашњене, од Мудрог и Оног Који све у потпуности зна,', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, '„да само Аллаха обожавате - ја сам вам од Њега онај који упозорава и доноси радосне вести,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, 'да од свога Господара тражите опрост и да се покајете, а Он ће да вам подари да на овом свету лепо живите до одређеног рока, и даће сваком вернику доброчинитељу потпуну награду из Своје дарежљивости. А ако напустите веровање - па, ја се, заиста, бојим за вас патње на великом Судњем дану.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'Аллаху ћете да се вратите, а Он Својом моћи све може да учини!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Ето, они своја прса окрећу да би се од Њега сакрили. А и кад се у одећу своју заогрћу, Он зна оно што скривају и оно што показују - Он, уистину, зна шта се у грудима крије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'На Земљи нема ниједног живог бића а да му Аллах није обезбедио опскрбу, и Он зна где се свако живо биће налази и где ће умрети. Све је то записано у јасној Књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'Он је Тај Који је створио небеса и Земљу у шест дана - а Његов је Престо био изнад воде - да би вас искушао - који ће од вас боље да поступа. Ако ти кажеш: „После смрти бићете заиста оживљени“, неверници ће сигурно да кажу: „Ово није ништа друго до очигледна враџбина!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Ако им Ми одложимо патњу до одређеног рока, они ће сигурно да кажу: „Шта је задржава?“ А онога дана кад им дође, неће да буде отклоњена од њих и са свих страна биће окружени оним чему су се ругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'Ако човеку дамо да осети Нашу милост, па му је после ускратимо, тада он, заиста, постаје прави очајник и незахвалник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'А ако му дамо да након невоље која га је задесила осети благостање, он ће сигурно да каже: „Невоље су ме напустиле!“ Он је, заиста, превише радостан и хвалисав.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Осим они који су били стрпљиви и радили добра дела - њима припада опрост и велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Нећеш, ваљда, да изоставиш нешто од онога што ти се објављује, што тишти твоје груди, само зато што они говоре: „Зашто му није послато какво благо или, зашто са њим није дошао анђео?“ Ти си само онај који упозорава, а Аллах је свему Заштитник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, 'Зар они да говоре: „Он га измишља!“ Реци: „Па сачините ви десет Кур''ану сличних, измишљених поглавља, и кога год хоћете, од оних у које верујете поред Аллаха, позовите у помоћ, ако истину говорите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'А ако вам се не одазову, онда знајте да се он објављује само са Аллаховим знањем и да нема истинског бога осим Њега - па јесте ли Му предани?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'Онима који желе само живот на овоме свету и овосветске украсе, Ми ћемо то наспрам њихових дела - у потпуности - да им дамо, и у томе неће да буду закинути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'То су они који ће на Будућем свету да добију само ватру; у њој ће да пропадне све оно што су чинили на Земљи и биће узалудно све што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Јесу ли они као они којима је јасно ко је њихов Господар - којима је дошао Кур''ан - Његов сведок, а још пре њега и Мојсијева Књига, водич и милост?! То су они који верују у њега. А ко год Кур''ан негира, међу разним групацијама, Ватра ће да му буде место где ће да сконча. Зато, ти никако не сумњај у њега, он је заиста истина од твога Господара, али већина људи не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'А има ли већих неправедника од оних који о Аллаху износе лаж?! Они ће пред својим Господаром да буду изведени, а сведоци ће да кажу: „Ови су измишљали лажи о своме Господару!“ Нека Аллахово проклетство стигне незнанобошце,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'оне који одвраћају од Аллаховог пута и који га желе искривљеним, такви ни у Будући свет не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Они на Земљи не могу да умакну Аллаховој казни, нити, осим Аллаха, имају другог заштитника. Њихова патња биће умногостручена. Они нису желели да чују истину, и нису желели да сагледају доказе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'То су они који су сами себе упропастили - а неће да буде ни трага од оних које су измишљали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'Без сумње, они ће на Будућем свету да буду највећи губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'Заиста, они који верују и раде добра дела и који су пред својим Господаром скрушени - то су становници Раја, у њему ће вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Пример неверника је попут оног ко је слеп и глув, а пример верника је попут оног који види и чује. Да ли су они у истом стању?! Па зашто поуку не узмете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'И Ноју смо послали његовом народу: „Ја сам вам, уистину, јасни упозоритељ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'да само Аллаха обожавате; ја се, заиста, плашим за вас патње на болном дану.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Главешине његовог народа, они који нису веровали, рекоше: „Сматрамо да си и ти човек као и ми, и видимо да те, без икаквог размишљања, следе само они који су наш најнижи сталеж; и сматрамо да ви никакве предности немате над нама. Штавише, мислимо да сте лажљивци.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, '„О мој народе“, рече он, „реците ми, ако ми је Господар мој дао јасан доказ и ако ми је дао веровесништво као милост Своју, а ви тога нисте свесни, да ли можемо да вас присилимо на веровање ако вам оно није по вољи?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'О мој народе! За ово од вас не тражим иметак; ја само од Аллаха желим награду. И ја нећу да отерам оне који верују, они ће сигурно свога Господара да сретну; али, ја видим да сте ви неук народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'О народе мој! Ко би ме од Аллаха одбранио кад бих их отерао? Зашто не размислите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Ја вам не кажем: ''Поседујем Аллахове ризнице'' - нити: ''Мени је познато оно што је недокучиво чулима'' - нити кажем: ''Ја сам анђео'' - а не говорим ни о онима које ваше очи са презиром гледају: ''Аллах никакво добро неће да им да'', Аллах најбоље зна шта је у њиховим душама - у супротном бих, сигурно, био међу неправеднима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, '„О Ноје“, рекоше они, „расправљао си са нама и претерао си у расправи. Дај, нека се оствари оно чиме нам претиш, ако си од искрених!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, '„Само Аллах даје казну, ако то буде хтео“, рече Ноје, „и ви тада нећете моћи да умакнете казни.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, '„Неће вам мој савет користити, ма колико ја желео да вас саветујем, ако Аллах одреди да вас остави у заблуду. Он је ваш Господар и Њему ћете да се вратите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Зар да говоре: „Он Кур''ан измишља!“ Реци им Мухаммеде: „Ако га измишљам, сам ћу сносити казну за мој грех, а ја се одричем вашег порицања истине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'И Ноји би објављено: „Нико више од твог народа неће веровати осим оних који су до сад веровали; зато не тугуј због онога што они чине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'и прави лађу пред Нашим очима и пажњом, и по Нашем упутству, и не обраћај Ми се молећи се за оне који су били неправедни - они ће сигурно да буду потопљени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'И он је градио лађу. И кад год би поред њега пролазили поглавари из његовог народа, исмејавали би му се. „Ако се ви нама исмејавате“, говорио је он, „исмејаваћемо се и ми вама, као што се и ви нама исмејавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'и сазнаћете, заиста, коме ће да дође казна која ће да га понизи и кога ће да снађе вечна патња."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, 'И кад је стигла Наша одредба и кад је покуљала вода са површине земље, рекли смо: „Укрцај у лађу од сваке животињске врсте по један пар, и своју породицу - осим оних којима је прописано да буду потопљени - и укрцај вернике“, а мало је било оних који су са њим веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'И он рече: „Укрцајте се у њу, у име Аллаха, нека плови и нека пристане! Мој Господар уистину је Опростилац греха, Милостиви.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'И лађа их је понела на валовима великим као брда; и Ноје дозва свога сина који је био издвојен: „О синко мој, укрцај се са нама, не буди са неверницима!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, 'А он рече: „Склонићу се на неко брдо које ће да ме заштити од воде.“ „Од Аллахове казне данас нема спаса, осим ономе коме се Он смиловао!“ Рече Ноје, и вал их раздвоји, и син би потопљен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'И би речено: „О Земљо, упиј своју воду, а ти, о небо, престани!“ И вода се повуче и испуни се одредба, а лађа пристаде на планини Ел-Џудијј, и би речено: „Далеко нека је неправедни народ!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'А Ноје се пре тога обрати своме Господару и рече: „Мој Господару, мој син је, уистину, из моје породице, а обећање Твоје је, заиста, истинито и Ти си Судија најправеднији!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, '„О Ноје“, рече Аллах: „он није од оних из твоје породице које сам обећао да спасим; он је, заиста, радио оно што не ваља, зато Ме не моли за оно што не знаш! Саветујем те да не будеш међу незналицама.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, '„Мој Господару“, рече, „Уточиште код Тебе тражим да Те више никада не замолим за оно што не знам! Ако ми не опростиш и не смилујеш ми се, сигурно ћу да будем међу губитницима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, '„О Ноје“, рече Аллах „искрцај се спашен и у миру, и благословима подареним теби и народима који ће да се изроде од ових који су са тобом! Биће народа којима ћемо дати да уживају у пролазном животу, а затим ће их од Нас задесити заслужена болна казна."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'То казивање спада у вести о нечему непознатом, које ти Ми објављујемо; ни ти Мухаммеде ни твој народ нисте пре овога ништа знали о томе. Зато буди стрпљив, победа ће, заиста, да припадне онима који су богобојазни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'И Аду - њиховог брата Худа посласмо. „О мој народе“, говорио је он, „Аллаха обожавајте, ви другог бога осим Њега немате, ви износите само неистине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'О мој народе, ја не тражим од вас награду за ово; награду желим само од Онога Који ме је створио! Зар не разумете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'О мој народе, молите свога Господара да вам опрости, и покајте Му се, а Он ће да вам шаље обилну кишу и даће вам још већу снагу, уз ону коју имате, и не одлазите као они који чине зло!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, '„О Худе“, говорили су они, „ниси нам донео никакав доказ и ми на саму твоју реч нећемо да напустимо своја божанства, јер ми теби не верујемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Ми тврдимо да те је неко наше божанство злом погодило.“ „Ја позивам Аллаха за сведока“, рече Худ, „а и ви посведочите да ја немам ништа са тим што ви друга божанства обожавате –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'поред Аллаха; и зато сви заједно против мене лукавство смислите и немојте ништа да одлажете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'ја се уздам у Аллаха, Он је мој и ваш Господар! Све живо је потчињено само Њему; заиста је мој Господар истинит и праведан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Па ако се окренете - а ја сам вам саопштио оно што вам је Аллах по мени послао - мој Господар ће уместо вас други народ да подари, и ви не можете ничим да Му наудите; мој Господар заиста надзире над свим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'И кад је дошла Наша одредба, Ми смо, Нашом милошћу, спасили Худа и вернике са њим и поштедили смо их жестоке казне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'Ето, то је био народ Ад, они су доказе свога Господара порицали и били су непослушни својим посланицима, и покоравали су се наредби сваког силника и пркосника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'И сустигло их је проклетство и понижење на овом свету, а биће проклети и понижени и на Судњем дану. Ад, заиста, није веровао у свога Господара; далеко нека је Ад, Худов народ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'И народу Семуду смо послали њиховог брата Салаха. „О мој народе“, говорио је он, „обожавајте само Аллаха, ви другог истинског бога осим Њега немате! Он вас је створио од земље и дао вам је да живите на њој! Зато Га молите да вам опрости и покајте Му се! Мој Господар је, заиста, близу и одазива се на молитве.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, '„О Салахе“, говорили су они, „ти си међу нама пре овог позива био цењен. Зашто браниш да обожавамо оно што су преци наши обожавали? Ми увелико сумњамо у оно чему нас ти позиваш.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, '„О мој народе“, говорио је он, „шта мислите: ако је мени јасно ко је мој Господар и ако ми је сам Он милост дао, па ко ће од Аллаха да ме одбрани ако Му не будем послушан? Ви бисте ми само повећали моју пропаст.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'О мој народе, ево, ова Аллахова камила је знак вама, па је пустите нека пасе по Аллаховој земљи и не чините јој никакво зло, да вас не би убрзо задесила казна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Али, они је заклаше, па он рече: „Уживајте у животу у земљи својој још само три дана, то није лажна претња!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'И кад је дошла Наша одредба, Ми смо, Нашом милошћу, спасили Салаха и вернике са њим од казне тога дана - твој Господар је, уистину, Моћни и Силни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'а оне који су били неверници погодио је страшан глас и они су у својим домовима осванули мртви, непомични,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'као да ту никад нису ни живели. Народ Семуд, заиста, у свога Господара није веровао; далеко нека је Семуд!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'И Авраму су дошли Наши анђели да му донесу радосну вест. „Мир Божји!“ Рекоше. „Мир Божји!“ Одговори он, и убрзо им донесе печено теле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'А кад виде да се њихове руке не дотичу хране, он схвати да су необични и осети страх од њих. "Не бој се!" рекоше они, "ми смо послати Лотовом народу."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'А жена његова стајаше ту, насмеја се, и Ми је обрадовасмо Исаком, а након Исака Јаковом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, '„Јадна ја!“ Рече, „зар да родим овако стара, а и овај мој муж је стар?! Ово је заиста нешто необично!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, '„Зар се чудиш Аллаховој одредби?“ Рекоше они, „Аллахова милост и Његови благослови нека су на вама, веровесничка породицо. Заиста је Он хваљен и слављен!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'И пошто Аврама прође страх и дође му радосна вест, он поче да расправља са Нама о Лотовом народу;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Аврам је, заиста, био благ, Аллаха је пуно молио и пуно се кајао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, '„О Авраме, прођи се тога, стигло је наређење од твога Господара; њих ће да стигне неизбежна патња!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'И када Наши анђели дођоше Лоту, он се због њих нађе у неприлици и то му тешко паде, па рече: „Ово је мучан дан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'И његов народ похрли њему - а пре су неваљаштине чинили. „О мој народе“, рече он, „ето вам за брак моје кћери, оне су вам чистије! Бојте се Аллаха и пред мојим гостима не срамотите ме! Зар међу вама нема разумног човека?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, '„Теби је свакако познато да нам твоје кћери нису потребне“, рекоше они, „ти, заиста, знаш шта ми желимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, '„Када бих само имао какву снагу да вас одбијем“, рече он, „или да могу код снажног заштитника да нађем помоћ!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, 'Анђели одговорише: „О Лоте, ми смо изасланици твога Господара, они теби не могу да науде. Ти крени са породицом својом у глуво доба ноћи без своје жене, њу ће да задеси исто што и њих, и нека се нико од вас не окреће! Рок им је јутро, а зар јутро није близу?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'И када је дошла Наша наредба, Ми њихова насеља наопако окренусмо, и на њих спустисмо кишу грумења од печеног блата, које је непрекидно падало,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, 'обележено од твога Господара, а оно од неправедника није далеко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'И Медену - посласмо њиховог брата Јофора. „О народе мој“, говорио је он, „Аллаха обожавајте, ви немате истинског бога осим Њега, и немојте из посуде за мерење и са ваге ништа да умањујете. Видим да заиста у обиљу живите и бојим се за вас казне на Дан који ће све да обухвати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'О мој народе! Посуду за мерење и вагу праведно испуните, и не закидајте људе ни у чему што је њихово, и не чините зло по Земљи неред правећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'Оно што вам претекне, а што вам је Аллах дозволио, боље вам је, ако хоћете да будете верници; а ја нисам ваш чувар.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, '„О Јофоре“, говорили су они, „да ли твоја молитва тражи од тебе да напустимо оно што су преци наши обожавали или да не поступамо са имањима нашим онако како нам је воља? Засигурно си обазрив и разуман!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, '„О мој народе“, говорио је он, „шта мислите, ако ја имам јасан доказ од мога Господара, а притом ми је Он дао и лепу опскрбу?! Ја не желим да чиним оно што вама забрањујем; једино желим да учиним добро колико могу, а мој успех зависи само од Аллаха; у Њега се уздам и Њему се обраћам.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'О мој народе! Нека вас неслагање са мном никако не доведе до тога да вас задеси оно што је задесило Нојев народ, или Худов народ, или Салахов народ. А и Лотов народ није од вас далеко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'И тражите опрост од свога Господара, и онда Му се покајте! Господар је мој, уистину, милостив и Онај Који воли.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, '„Јофоре“, рекоше они, „Ми не схватамо много тога што ти говориш, а видимо да си ти међу нама јадан; да није твоје родбине, ми бисмо те каменовали, ти над нама немаш моћ и не уживаш никакав углед.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, '„О мој народе“, рече он, „зар родбина моја код вас има већи углед од Аллаха, а Њега сте иза себе одбацили?! Уистину мој Господар оно што радите знањем обухвата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'О мој народе, чините све што можете, а чинићу и ја. Ви ћете сигурно да сазнате кога ће казна да стигне која ће да га осрамоти и ко је лажов. Па, чекајте пресуду, и ја ћу са вама да чекам!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'И када је наступила Наша наредба, Ми смо, из Наше милости, спасили Јофора и оне који су са њим веровали, а оне који су били неправедни погодио је ужасан глас и они су осванули у земљи својој мртви, непомични,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'као да на њој никад нису ни постојали. Далеко био Меден, као и Семуд!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'И Мојсија смо послали са Нашим знаковима и доказом јасним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, 'фараону и његовим главешинама, али су они следили фараонову веру, а фараонова вера била је заблуда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'На Судњем дану он ће свој народ да предводи и у Пакао да га уведе, а ужасно је место у које ће да буде доведен!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'На овом свету их је пратило проклетство а пратиће их и на Судњем дану; страшна је казна којом ће да буду кажњавани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'То су неке вести које ти казујемо о насељима; нека од њих још постоје, а нека су са земљом сравњена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Ми им нисмо учинили неправду. Они су сами себи учинили неправду. Ништа им нису помогла њихова божанства која су молили мимо Аллаха кад је наступила наредба твога Господара, само су им пропаст њихову повећала.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'Ето, тако твој Господар кажњава када кажњава она насеља која чине неправду. Његова казна заиста је болна и жестока.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'У томе је, заиста, поука за оне који се плаше патње на Будућем свету; то је Дан када ће сви људи да буду сабрани и то је Дан кад ће сви да буду присутни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'а Ми га одлажемо до тачно одређеног времена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'А онда кад дође, без Његовог допуштења нико ни реч неће да изусти, а међу њима биће несрећних и срећних.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'И несрећни ће у Ватру, у њој ће тешко да издишу и удишу;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'У њој ће да остану док је небеса и Земље, осим ако другачије твој Господар не одреди. Твој Господар, заиста, ради оно што жели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'А срећни ће у Рај; у њему ће вечно да бораве, док је небеса и Земље, осим ако другачије твој Господар не одреди; биће то дар који ће да траје непрекидно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, 'Зато не сумњај да је лажно оно што незнанобошци обожавају; они обожавају управо оно што су, још пре, обожавали њихови преци. Ми ћемо, заиста, казну коју су заслужили - без умањивања да им дамо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'И Мојсију смо дали Књигу, па су се о њој у мишљењу подвојили. И да није речи твога Господара раније изречене, било би са њима свршено, јер они у њу много сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'И свима њима ће твој Господар дати према делима, Он у потпуности зна оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Буди устрајан на Правом путу, као што ти је наређено, и нека тако поступе и верници који су уз тебе, и не будите охоли, Он добро види оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'И не нагињите незнанобошцима, па да вас Ватра пржи, јер ви осим Аллаха немате друге заштитнике, па да немате никог ко ће вам помоћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'И обављај молитву почетком и крајем дана, и у првим часовима ноћи! Добра дела заиста поништавају рђава. То је опомена за оне којима опомена користи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'И буди стрпљив! Аллах, заиста, неће да ускрати награду онима који добра дела чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'А да је барем међу народима пре вас било честитих који су бранили да се на Земљи чини неред, осим мало њих које смо Ми спасили! А они који су били незнанобошци одавали су се страстима у којима су уживали, и били су тешки грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Твој Господар не би никада уништавао насеља због неправде ако би њени становници поправљали стање и позивали на добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'А да је твој Господар хтео, све би људе учинио следбеницима једне вере. Међутим, они ће увек у веровању да се разилазе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'осим оних којима се твој Господар смилује. А зато их је и створио. И испуниће се реч твога Господара: „Напунићу, заиста, Пакао духовима и људима - заједно!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'А све ове вести које ти о појединим догађајима о посланицима казујемо је зато да тиме твоје срце учврстимо. И у овом поглављу дошла ти је права истина, и поука, и верницима опомена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'И реци онима који неће да верују: „Радите што год можете, и ми ћемо да радимо;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'и чекајте, и ми ћемо, сигурно, да чекамо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'Аллах зна тајне небеса и Земље и Њему се све враћа, зато само Њега обожавај и само се у Њега уздај! А Господар твој није немаран према ономе што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Елиф-лам-ра.[1] Ово су речи јасне Књиге!', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Објављујемо га као Кур''ан на арапском језику, да бисте разумели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Ми ти о најлепшим догађајима казујемо тиме што ти овај Кур''ан објављујемо, иако си пре њега, један од неуких био.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, 'Кад Јосиф рече своме оцу: „О мој оче, сањао сам једанаест звезда, и Сунце и Месец, и у сну сам их видео како ми се поклонише.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, 'Он рече: „О синко мој, не казуј свој сан својој браћи, да ти не учине какву сплетку; ђаво је, заиста, човеку отворени непријатељ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'И, ето тако, твој Господар ће тебе да одабере, и тумачењу снова научи, и Своју благодат теби и Јаковљевој породици да употпуни, као што је пре употпунио твојим прецима, Авраму и Исаку. Твој Господар, заиста, све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'У причи о Јосифу и његовој браћи налазе се поуке за све који се распитују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Када они рекоше: „Јосиф и његов брат су дражи нашем оцу од нас, а нас је читава скупина. Наш отац је, заиста, у очигледној заблуди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'Убијте Јосифа или га оставите у некој забити, ваш отац ће да се окрене вама, и после тога ћете да будете добри људи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'Један од њих рече: „Ако баш хоћете нешто да учините, онда Јосифа не убијте, већ га баците на дно неког бунара, узеће га нека каравана.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, '„О оче наш“, рекоше они, „зашто нам не повериш Јосифа? Ми му, заиста, желимо добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Пошаљи га сутра са нама да се забави и разоноди, ми ћемо, сигурно, да га чувамо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, 'Он одговори: „Биће ми, заиста, жао ако га одведете, а плашим се да га вук не поједе кад ви не будете пазили на њега.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, 'Они рекоше: „Ако би га вук појео, а нас оволико, били бисмо заиста губитници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'И када га одведоше и одлучише да га баце на дно бунара, Ми Јосифу објависмо: „Ти ћеш о овом њиховом поступку сигурно да их обавестиш, а они те неће ни препознати.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, 'И увече дођоше свом оцу плачући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, '„О оче наш“, рекоше, „отишли смо били да се такмичимо, а Јосифа смо оставили код наших ствари, па га је вук појео. А ти нећеш да нам верујеш иако истину говоримо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'И кошуљу његову окрвавише лажном крвљу. „У вашим душама је поникла зла мисао“, рече он, „а стрпљивост је лепа; од Аллаха тражим помоћ у ономе што ви говорите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'И дође једна каравана, па послаше свог водоношу и он спусти своје ведро. „Гле среће!“ Викну он, „ево једног дечака!“ И они су га као трговачку робу сакрили, а Аллах добро зна шта су чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'И продадоше га јефтино, за неколико сребрењака; били су према њему равнодушни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'И онда онај из Мисира, који га је купио, рече својој жени: „Учини му боравак пријатним! Може да нам буде користан, а можемо и да га посинимо!“ И ето тако смо Ми дали Јосифу лепо место на Земљи и научисмо га тумачењу снова - а Аллах чини шта хоће, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Кад он стаса, Ми му подарисмо мудрост и знање; тако Ми награђујемо оне који добра дела чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'И поче да га наводи на грех она у чијој је кући био, па закључа сва врата и рече: „Приђи!“ „Аллахову заштиту тражим!“ Узвикну он, „Власник мој ме лепо пази; а неправедници никад неће успети.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'И она га је била пожелела, а и он би њу пожелео да од свога Господара није угледао јасан знак - тако би, да одвратимо од њега зло и блуд. Уистину је он међу Нашим одабраним верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, 'И њих двоје према вратима потрчаше - а она поцепа његову кошуљу страга - и затекоше њеног мужа крај врата. „Какву казну заслужује онај који је хтео твојој жени зло да учини“, рече она, „ако не тамницу или болну казну?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, '„Она је покушала да ме заведе“, рече Јосиф. И посведочи један сведок из њене породице: „Ако је његова кошуља поцепана спреда, онда она истину говори, а он је међу лажљивцима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'а ако је његова кошуља поцепана страга, онда она лаже, а он говори истину.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'И кад он виде да је његова кошуља поцепана страга, рече: „То је једно од ваших женских лукавстава; ваша лукавства су, заиста, велика!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'Ти, Јосифе, заборави и не спомињи ово. А ти тражи опроштење за свој грех; ти си, уистину, била једна од грешница!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'И жене у граду почеше да причају: „Управникова жена заводи младића, свог слугу, у њега се лудо заљубила! Ми мислимо да је она у очигледној заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'И кад је она чула за њихова оговарања, посла по њих, па им припреми наслоне, дала је свакој од њих по нож и рече: „Изађи пред њих!“ А кад га оне угледаше, његова лепота их занесе и по рукама својим се порезаше: „Сачувај Аллаху!“ Ускликнуше, „ово није човек, ово је племенити анђео!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, '„Е, то вам је онај због кога сте ме критиковале“, рече она. „Истина је да сам га заводила, али се он сачувао. Ако не учини оно што од њега тражим, сигурно ће да заврши у затвору и биће међу пониженим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, '„Мој Господару“, рече он, „дража ми је тамница од овога на шта ме оне навраћају! И ако Ти не одвратиш од мене њихова лукавства, ја могу према њима да осетим наклоност и да постанем један од лакомислених.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'И Господар његов му услиша молбу и спаси га њиховог лукавства; Он, уистину, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'После им на памет паде, иако су се били уверили да је недужан, да га за неко време баце у тамницу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Са њим су у тамницу ушла још два момка. „Ја сам сањао да цедим вино“, рече један од њих. „А ја, опет“, рече други, „како на глави носим хлеб који птице кљују. Протумачи нам то, јер видимо да си, заиста, један од доброчинитеља.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, '"Ништа од онога што једете неће да вам буде донесено, а да вас ја не обавестим о томе детаљно пре него што вам буде донесено“, рече Јосиф. „То је само део онога чему ме је научио мој Господар, ја се клоним вере народа који у Аллаха не верује и који Будући свет негира,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'и следим веру својих предака, Аврама и Исака и Јакова; није на нама да поред Аллаха било шта обожавамо. То је из Аллахове дарежљивости према нама и осталим људима, али већина људи не захваљује.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, '„О моји другови у тамници, да ли су разноразна божанства боља или Аллах, Једини и Свемоћни?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Они које, мимо Њега, обожавате - само су имена којима сте их насловили ви и ваши преци - Аллах о њима није објавио никакав доказ. Суд припада једино Аллаху, а Он је наредио да само Њега обожавате. То је једино права вера, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'О моји другови у тамници, један ће од вас свога господара вином да поји, а други ће да буде разапет, па ће птице главу да му кљују. Оно што сте питали већ је одређено!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'А ономе од њих двојице за којег је знао да ће да буде спашен рече: „Спомени ме своме господару!“ Али ђаво учини па он заборави да га спомене своме господару, и Јосиф остаде у тамници неколико година.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'И владар рече: „Сањао сам како седам мршавих крава поједе седам дебелих, и сањао сам седам класова зелених и седам других, сасушених. О великани, протумачите ми мој сан, ако знате да тумачите снове?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, '„Збрканих ли снова!“ Рекоше они, „ми снове не знамо да тумачимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'И тада један од оне двојице који се спасио, који се после толико времена сетио, рече: „Ја ћу да вам протумачим сан, само ме пошаљите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, '“Јосифе, о ти који си увек искрен, протумачи нам шта значи: седам мршавих крава поједе седам дебелих; и седам класова зелених и седам других сасушених - па да се вратим људима, да би они сазнали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, '„Сејаћете седам година узастопно“, рече, „па оно што пожањете у класу оставите, осим оно мало што ћете да једете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Затим ће после да дође седам тешких које ће да поједу оно што сте за њих припремили, остаће једино оно мало што ћете за сетву да сачувате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Затим, после тога, ће да дође година у којој ће људима кише у обиљу да буде и у којој ће да цеде.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'И владар рече: „Доведите ми га!“ И кад Јосифу дође изасланик, он рече: „Врати се своме господару и упитај га: ''Шта је са оним женама које су своје руке порезале? Мој Господар добро зна њихове сплетке!''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, '„Шта је са вама било кад сте Јосифа заводиле?“ Упита владар. „Сачувај Аллаху!“ Рекоше оне, „ми о њему ништа ружно не знамо!“ „Сад ће истина да изађе на видело“, рече управникова жена, „ја сам га заводила, а он је, заиста, један од искрених.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, 'То је зато да зна да га ја нисам преварила и да Аллах неће дати да се остваре сплетке издајника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, 'Ја не правдам себе, душа је заиста склона злу, осим оне којој се мој Господар смилује. Мој Господар, заиста, опрашта грехе и милостив је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'И владар рече: „Доведите ми га, узећу га у своју свиту“, и пошто поразговара са њим, рече: „Ти ћеш од данас код нас да будеш утицајан и од поверења.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, '„Постави ме“, рече, „да водим бригу о залихама у земљи, ја заиста знам да чувам и имам знање.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'И тако смо Ми Јосифу дали власт у земљи; боравио је где је хтео; своју милост Ми дајемо ономе коме хоћемо и не дозвољавамо да пропадне награда онима који чине добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'А награда на Будућем свету је боља за оне који верују и који се боје Аллаха и греха клоне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'И дођоше браћа Јосифова и уђоше код њега, па их он познаде, а они њега не познадоше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'И кад их подмири намирницама и товаре им припреми, рече: „Доведите ми свога брата по оцу, зар не видите да пуну меру дајем и да најбоље угошћујем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Ако ми га не доведете, нећете више од мене да добијете меру са намирницама и не приближавајте ми се!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, '„Побринућемо се да га некако измамимо од његовог оца, заиста ћемо тако да поступимо“, рекоше они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'А Јосиф рече момцима својим: „Ставите њихове ствари за које су купили намирнице у њихове товаре, они ће, кад се својима врате, да их препознају и опет ће да се врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'И пошто се вратише своме оцу, рекоше: „О оче наш, бићемо ускраћени за меру са намирницама. Зато пошаљи са нама брата нашег да бисмо добили меру са намирницама, а ми ћемо, заиста, да га чувамо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, '„Зар да вам га поверим као што сам пре поверио његовог брата?“ Рече он. „Али, Аллах је Чувар најбољи и Он је Најмилостивији!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'А када отворише своје товаре, нађоше да су им враћене њихове ствари, и рекоше: „О оче наш, шта можемо више да пожелимо? Ево, враћене су нам наше ствари, и нашу породицу ћемо храном да намиримо, и нашег брата ћемо да чувамо, а добићемо и додатни товар који камила може да понесе; то је за њега незнатан износ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, '„Ја нећу са вама да га пошаљем“, рече, „док се чврсто Аллахом не закунете да ћете заиста да ми га вратите, осим ако онемогућени будете.“ И пошто му се они заклеше, он рече: „Аллах је јамац за оно што смо казали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'И рече: „О моји синови, не улазите на једну капију, већ на разне капије, а ја не могу да вас спасим од онога што вам Аллах одреди; власт припада једино Њему, ја се у Њега уздам, и нека се само у Њега уздају они који се уздају!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'И кад уђоше онако како им је наредио њихов отац, то им нимало није помогло да буду поштеђени онога што им је Аллах био одредио, једино се остварила жеља Јаковљева, коју је извршио, а он је, уистину, имао знање, зато што смо га Ми научили, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'И кад дођоше код Јосифа, он приви на груди свога брата и рече: „Ја сам, заиста, твој брат и не жалости се због оног што су они чинили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'И пошто их намири потребном храном, стави пехар у товар свога брата, а после један гласник поче да узвикује: „О каравано, ви сте, заиста, крадљивци!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Они им приђоше и упиташе: „Шта сте то изгубили?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, '„Изгубили смо владареву посуду“, одговорише. „Ко је донесе, добиће товар хране који камила може да понесе. Ја за то гарантујем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, '„Аллаха нам“, рекоше они, „ви знате да ми нисмо дошли да чинимо неред у земљи, и ми нисмо крадљивци.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, '„А каква је казна за таквог ако будете лагали?“ Упиташе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, '„Казна за оног у чијем се товару то нађе – јесте сам он“, одговорише браћа. „Ето тако ми кажњавамо насилнике.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, 'И он поче са њиховим врећама, пре вреће свога брата, а онда извади пехар из вреће свога брата. Тако смо, ето, у Јосифову корист варку направили. Он, по владаревом закону, није могао да узме као роба свога брата, осим ако то Аллах жели. Ми уздижемо на веће положаје онога кога хоћемо. Све знанији од знанијег има, а Свезнајући је изнад сваког.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, '„Ако је он украо“, рекоше они, „па и пре је брат његов крао!“ И Јосиф то у себи затаји и то им не откри. „Ви сте у горем положају“, помисли у себи, „Аллах најбоље зна оно што ви спомињете.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, '„О великану“, рекоше они, „он има врло старог оца, па узми једног од нас уместо њега! Ми уистину видимо да си доброчинитељ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, '„Сачувај Аллаху“, рече, „да узмемо неког другог до оног код кога смо нашли оно што је наше! Тада бисмо заиста били неправедници!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'И пошто у њему изгубише сваку наду да ће брата да спасу, одвојише се са стране да се посаветују. „Зар не знате“, рече најстарији међу њима, „да сте се заклели Аллахом своме оцу, а и да сте пре тога у вези са Јосифом учинили пропуст?! Нећу да напустим ову земљу док ми то мој отац не дозволи или док Аллах у моју корист не пресуди, а Он је Судија најбољи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, '„Вратите се свом оцу па реците: ''О оче наш, твој син је украо; ми тврдимо само оно што смо видели, а ми нисмо могли да знамо непознато.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, 'Питај насеље у којем смо боравили и каравану са којом смо дошли. Ми, заиста, говоримо истину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, '„Није тако“, рече Јаков, „у вашим душама је поникла зла мисао, а лепо је стрпити се. Надам се да ће Аллах све да ми их врати; уистину је Он Свезнајући и Мудри.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'И окрену се од њих и рече: „О Јосифе, туго моја!“ И очи му побелеше од јада, био је врло потиштен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, '„Аллаха нам“, рекоше они, „ти толико спомињеш Јосифа да ћеш тешко да оболиш или умреш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, '„Ја своју тугу и свој јад износим само Аллаху, а Аллах ми је дао да знам оно што ви не знате“, рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, '„О синови моји, идите и распитајте се за Јосифа и његовог брата, и не губите наду у Аллахову милост; заиста, наду у Аллахову милост губе само људи који су неверници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'И кад они уђоше код њега, рекоше: „О великану, и нас и нашу породицу притисла је невоља; донели смо мало вредне ствари, али ти нам дај пуну меру и удели нам милостињу, јер Аллах, заиста, награђује оне који удељују милостињу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, '„А знате ли“, упита он, „шта сте урадили са Јосифом и његовим братом када сте били лакомислени?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, '„А да ти ниси, уистину, Јосиф?“ Повикаше они. „Да, ја сам Јосиф, а ово је мој брат, Аллах нам је даровао милост; а ко год буде био богобојазан и стрпљив - па, Аллах, уистину, неће да допусти да пропадне награда онима који чине добра дела.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, '„Аллаха нам“, рекоше они, „Аллах ти је над нама дао предност, ми смо, заиста, грешили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, '"Данас вам неће бити укора", рече, "Аллах ће вам опростити, Он је најмилостивији!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, '„Понесите ову моју кошуљу и баците је на лице мога оца; он ће прогледати; и сву своју породицу ми доведите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'И кад каравана напусти Мисир, њихов отац рече: „Ја заиста осећам Јосифов мирис, иако ви то поричете.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, '„Аллаха нам“, рекоше они, „ти си заиста још увек у претходној обмањености.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'А кад гласник дође са радосном вешћу, он стави кошуљу на његово лице и он прогледа. „Зар вам не рекох“, рече, „да ја знам од Аллаха оно што ви не знате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, '„О оче наш“, рекоше они, „замоли за опрост наших греха, ми смо, заиста, грешили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, '„Замолићу Господара свога да вам опрости“, одговори он, „јер Он прашта грехе и милостив је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'И кад дођоше код Јосифа, он приви своје родитеље на груди и рече: „Настаните се у Мисиру, од свега, ако Аллах да, сигурни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'И он своје родитеље постави на престо и сви му се поклонише, па он рече: „О мој оче, ово је остварење мог некадашњег сна. Мој Господар га је учинио истинитим. Он је био добар према мени кад ме је избавио из тамнице и вас довео из пустиње, након што је ђаво између мене и моје браће посејао раздор. Господар мој је, заиста, благ према ономе коме Он хоће, и Он је, заиста, Свезнајући и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'Господару мој, Ти си ми дао део власти и научио си ме тумачењу снова! О Ти Који си створио небеса и Земљу без претходног примера, Ти си мој Заштитник и на овом свету и на другом; дај да умрем као муслиман и придружи ме честитима!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'Ето, то су неке вести непознате које објављујемо теби, а ти ниси био са њима када су се они одлучили, и када су сплетке смислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'А већина људи, ма колико ти настојао, нису верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Ти од њих не тражиш награду за то, то је само опомена свим световима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'А колико има доказа на небесима и на Земљи поред којих пролазе, и том приликом се од њих окрећу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Већина њих не верује у Аллаха, осим тако што Му друге у обожавању придружује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Зар могу да буду сигурни да невоља, као Аллахова казна, неће да их стигне или да суђени Час неће да их изненади, а да они то неће ни да примете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, 'Реци: „Ово је мој пут, ја позивам к Аллаху, имајући јасне доказе, ја, и сваки онај који ме следи, и нека је Узвишен Аллах, ја нисам од оних који друге поред Њега обожавају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'А Ми смо и пре тебе само људе као посланике слали, који су били из насељених места и којима смо објаве достављали. Зашто ови не путују по свету, па да виде како су скончали они пре њих – а Будући свет је заиста бољи за богобојазне - зар не разумете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'И кад би посланици готово наду губили и помишљали да ће за лажове да их прогласе, Наша помоћ би им дошла. Спасили бисмо оне које смо Ми хтели, а Наша казна не би мимоишла невернички народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'У казивању о њима је поука за оне који су разумом обдарени. Кур''ан није измишљен говор, он признаје књиге пре њега објављене, и објашњава све, и упута је и милост народу који верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Елиф-лам-мим-ра.[1] Ово су речи Књиге! А оно што ти се објављује од твога Господара је истина, али већина људи не верује.', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Аллах је небеса, видите их, подигао без стубова, и онда се узвисио над Престољем, и потчинио Сунце и Месец; свако се креће до одређеног рока. Он свиме управља и потанко излаже доказе како бисте у сусрет са својим Господаром били чврсто уверени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'И Он је Тај Који је распростро Земљу и на њој створио стабилне планине и реке и од сваког плода дао по пар, мушко и женско; Он дан застире ноћу. У томе, заиста, има доказа за људе који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'На Земљи има предела који се граниче једни са другима, и башта са грожђем, и њива, и палми; са више изданака и само са једним, и једном те истом водом се напајају; ипак плод неких чинимо укуснијим од других. У томе, заиста, има доказа за људе који разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'А ако се чудиш, па - чудо су њихове речи: „Зар ћемо кад будемо прах, заиста поново да будемо створени?“ То су они који не верују у свога Господара. То су они на чијим вратовима ће да буду окови. То су становници Ватре; у њој ће да остану вечно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Они те пожурују са Аллаховом казном, пре него са Аллаховим милосрђем, а било је казни и пре њих. Твој Господар људима прашта и упркос њиховом насиљу, али твој Господар, заиста, и жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'А они који не верују говоре: „Зашто му његов Господар не пошаље какво чудо?“ Ти си, међутим, само онај који упозорава, а сваки народ је имао онога који га је на Прави пут усмеравао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Аллах зна шта носи свако женско и шта материце краће носе, а шта дуже; код Њега све има меру.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, 'Он је Зналац и оног што је недокучиво чулима и оног што је појавно, Он је Величанствени и Узвишени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'За Њега је једнак онај од вас који тихо говори и онај који то гласно чини, онај који се ноћу скрива и онај који по дану хода.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'И уз сваког од вас су анђели, који се смењују испред њега и иза њега - по Аллаховом наређењу надзиру над њим. Сигурно је да Аллах неће да измени стање у којем се налази одређени народ све док се тај народ не промени. А кад Аллах одреди неком народу нешто што је лоше, нико то не може да спречи; без Њега им нема заштитника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'Он је Тај Који вам показује муњу, да се уплашите и понадате, и Он даје да изнова настају тешки облаци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'И грмљавина Њега велича и хвали, а и анђели, из страхопоштовања према Њему; Он шаље громове и њима погађа кога хоће, а они, и поред тога, расправљају о Аллаху, а Он жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, 'Само Њему може истински да се моли. А они којима се поред Њега моле - неће да им се одазову, као што ни вода неће да стигне у уста ономе који према њој само своје дланове пружи; молба неверника засигурно је бескорисна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'Аллаху се клања све што је на небесима и на Земљи, добровољно или зато што морају, а и њихове сенке - ујутро и на крају дана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, 'Реци: „Ко је Господар небеса и Земље?“ - И одговори: „Аллах!“ Реци: „Па зашто сте онда уместо Њега као заштитнике прихватили оне који сами себи не могу неку корист да прибаве нити од себе какву штету да отклоне?“ Реци: „Зар су једнаки слепац и онај који види, или, зар су исто тмине и светло? Зар су Аллаху придружили божанства која стварају као што Он ствара, па им се стварање чини сличним?!“ Реци: „Аллах је Створитељ свега и Он је, Једини, Потчинитељ свега.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'Он воду са неба спуста, па сваком долином тече онолико колико може да прихвати и бујица носи пену која нараста. И оно што људи топе на ватри у жељи да добију накит или оруђе има, такође, отпад сличан пени. Тако Аллах наводи пример за истину и неистину: пена се распршује, док оно што користи људима остаје на Земљи. Тако Аллах наводи примере.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Онима који се одазову своме Господару - припада најлепша награда; а они који Му се не одазову - кад би све што је на Земљи било њихово, и још толико, радо би се тиме откупили. Њих чека ужас полагања рачуна, пребивалиште њихово биће Пакао, а грозно ли је он боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Зар је онај који зна да је истина оно што ти се објављује од твога Господара као онај који је слеп?! А поуку примају само они који имају разум,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, 'Они који обавезу према Аллаху испуњавају и не крше обећање;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'И они који одржавају оно што је Аллах наредио да се одржава и свога Господара се боје и плаше се ужасног обрачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'И они који трпе у жељи за лицем свога Господара, и они који обављају молитву, и који од онога што им дајемо удељују и тајно и јавно, и који узвраћају добрим на зло - њима ће да припадне леп исход овога света, њих чека најлепше пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, 'Еденски вртови у којима ће да уђу и они и њихови родитељи и њихове жене и њихов пород - они који су били честити - а и анђели ће да им улазе на свака врата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, 'Мир Божји нека је над вама, зато што сте трпели, а дивно ли је ваше коначно боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'А они који крше обећање према Аллаху, након што су се на то чврсто обавезали, и кидају оно што је Аллах наредио да се одржава, и чине неред на Земљи - њих чека проклетство и ужасно боравиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Коме жели, Аллах даје опскрбу у изобиљу, и ускраћује. Они се радују животу на овом свету, а живот на овом свету према Будућем свету само је пролазно уживање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'Они који не верују говоре: „Зашто му од његовог Господара није спуштен какав знак?“ Реци: „Аллах одводи на странпутицу онога кога Он жели, а ка Себи упућује онога ко Му се покајнички обраћа.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, 'Оне који верују и чија се срца, кад се Аллах спомене, смирују - а срца се, заиста, смирују кад се Аллах спомене.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'Онима који верују и чине добра дела - благо њима, њих чека дивно пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'И тако смо те послали народу пре којег су били и нестали други народи, да им казујеш оно што ти објављујемо, а они у Свемилосног не верују. Реци: „Он је мој Господар, нема бога осим Њега, на Њега се ослањам и Њему се кајем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'Кад би се каквом књигом покренула брда или искомадала земља или дозвали мртви, био би то Кур''ан! Аллаху све припада! А зар не знају верници да кад би Аллах само хтео, све људе би упутио? А невернике ће несрећа непрестано да погађа или ће у близини њиховог места да се дешава, због онога што раде - све док се Аллахово обећање не оствари. Аллах, заиста, не крши обећање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'И пре тебе су посланици били исмејавани, па сам Ја онима који нису веровали остављао времена, и после сам их кажњавао, а каква је само била Моја казна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Па зар је Онај Који над сваким надзире, шта год да уради, као онај ко то није у стању да уради?! И узели су друга божанства поред Аллаха. Реци: ''Именујте их!'' Зар да Га ви обавештавате о нечему што се на Земљи налази - што он зна да постоји, или их ви тако називате по своме нахођењу?! Онима који не верују чини се лепим сплеткарење њихово, и они су са правог пута залутали. А онај кога Аллах на странпутицу окрене неће наћи никога да га на Прави пут упути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Они ће да пате у животу на овом свету, али ће патња на Будућем свету сигурно да буде тежа; нико неће да их одбрани од Аллаха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Пример Раја обећан онима који се буду бојали Аллаха је: вртови са рекама, кроз њега теку реке, његови плодови и хладовина су трајни; то ће, на крају, да припадне онима који се боје Аллаха и клоне греха, а одредиште неверника је Пакао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Они којима смо дали Књигу радују се свему што ти објављујемо, али неке групе међу њима поричу нешто од тога. Реци: „Мени је наређено да само Аллаха обожавам и да Њему никога у обожавању не придружујем; Њему ја позивам и Њему се враћам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'И Ми га тако објављујемо усавршеног на арапском језику. А ако би се ти повео за њиховим прохтевима, након што ти је дошло знање, ти не би имао никога ко би те заштитио нити одбранио од Аллаха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'И пре тебе смо слали посланике, и давали смо им да имају супруге и потомке. И ниједан посланик није могао да иступи са неким чудом, осим са Аллаховом дозволом. Свако доба имало је Књигу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Аллах уклања шта хоће, а оставља шта хоће; код Њега је главна Књига.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Било да ти покажемо део онога чиме им претимо, било да ти одузмемо живот, твоје је да обзнањујеш, а Наше да сводимо рачуне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Зар они не виде да Ми сужавамо Земљу умањујући њене крајеве?! А Аллах суди и нико не може побити Његову пресуду, и Он брзо своди рачун.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Сплетке су плели и они пре њих, само, Аллах је Господар свих сплетки, и Он зна шта свако заслужује. А неверници ће сигурно да сазнају коме ће леп исход да припадне на крају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Они који не верују говоре: „Ти ниси посланик.“ Реци: „Мени и вама Аллах ће да буде довољан као сведок, и они који знање из Књиге имају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Елиф-лам-ра.[1] Ово је књига коју ти објављујемо да људе дозволом њиховог Господара изведеш из тмина на светло, на пут Силнога и Хваљенога', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Аллаха, чије је оно што је на небесима и оно што је на Земљи. А тешко неверницима од жестоке патње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'онима који живот на овом свету више воле од Будућег света и који одвраћају од Аллаховог пута и настоје да га прикажу кривим! Они су далеко залутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Ми нисмо послали ниједног посланика а да није говорио језиком свога народа, како би им објаснио посланицу. Па Аллах у заблуди оставља онога кога жели а на Прави пут упути онога кога жели; Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'И Мојсија смо послали са Нашим доказима: „Изведи свој народ из тмина на светло и подсети га на Аллахове благодати.“ То су, уистину, докази за сваког ко је стрпљив и захвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'И кад је Мојсије свом народу казао: „Сетите се Аллахове благодати када вас је избавио од фараонових људи који су вас мучили најгорим мукама, који су вам клали мушку децу, а женску остављали у животу - то је било велико искушење од вашега Господара.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'И кад је ваш Господар објавио: „Ако будете захвални, Ја ћу сигурно још више да вам дам; будете ли незахвални, заиста ће жестока да буде Моја казна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'И Мојсије је још казао: „Ако будете незахвални и ви и сви други на Земљи, па, Аллах је, заиста, независан и хваљен.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Зар до вас није дошла вест о онима пре вас, о Нојевом народу, и о Аду, и о Семуду, и о онима после њих? Само их Аллах зна! Њихови Посланици су им доносили јасне доказе, али они су стављали на уста своје руке и говорили: „Ми не верујемо у оно што се по вама шаље и ми итекако сумњамо у оно у шта нас позивате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Њихови посланици су говорили: „Зар може да се сумња у Аллаха, Који је небеса и Земљу из ничега створио? Он вас позива да би вам опростио грехе и да би вас оставио до одређеног рока.“ Они су одговорили: „Ви сте људи као и ми; хоћете да нас одвратите од оних које су наши преци обожавали - па, донесите нам доказ јасни.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, '„Ми јесмо људи као и ви“, говорили су им њихови посланици, „али, Аллах уздиже само оне Своје слуге које Он хоће; ми не можемо да вам донесемо доказ осим са Аллаховом дозволом – а верници нека се само у Аллаха уздају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, '„Зашто да се не ослонимо на Аллаха кад нас је Он путевима којим идемо упутио? Ми ћемо, заиста, стрпљиво да подносимо оно чиме нас узнемиравате - а они који се ослањају, нека се само на Аллаха ослањају!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Они који нису веровали говорили су својим посланицима: „Или ћете у нашу веру да се вратите или ћемо, заиста, из наше земље да вас протерамо!“ А посланицима је њихов Господар објављивао: „Ми ћемо насилнике сигурно да уништимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, 'И после њих вас на Земљи да настанимо. Биће то за оне који ће полагања рачуна преда Мном да се боје и који ће од Моје претње да страхују.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, 'И посланици су тражили помоћ, па је сваки охоли пркосник настрадао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'Пред њим ће да буде Пакао - и он ће да буде напајан течношћу од сукрвице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Мучиће се да је прогута, али никако неће моћи да је прождере и смрт ће са свих страна да му прилази, али он неће да умре; а након тога га чека још тежа патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Дела оних који не верују у свога Господара налик су на пепео који разнесе вихор у олујном дану; неће моћи да очекују никакву награду за дела која су учинили, то је далека странпутица.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Зар не видиш да је Аллах небеса и Земљу створио са Истином? Ако жели вас ће уклонити и нова створења довести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'То Аллаху није тешко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'И изаћи ће сви пред Аллахом, па ће они који су били слабићи рећи својим главешинама, онима који су били охоли: „Ми смо били ваше присталице, па да ли сте у стању да нас бар мало заштитите од Аллахове казне?“ „Да је нас Аллах упутио“, одговориће они, „и ми бисмо вас упутили. Жалили се ми или трпели, свеједно нам је, нема нам више спаса.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'И када буде све решено, ђаво ће да каже: „Аллах вам је истинско обећање дао, а ја сам вам обећавао и своја обећања изневерио; али, ја нисам никаквог доказа над вама имао, само сам вас позивао и ви сте ми се одазивали; зато не корите мене, већ сами себе; нити ја могу вама да помогнем, нити ви можете да помогнете мени. Ја немам ништа са тим што сте ме, поред Њега, обожавали. Незнанобошце сигурно чека болна патња.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'А они који су веровали и чинили добра дела биће уведени, са дозволом њиховог Господара, у рајске баште кроз које теку реке и у њима ће да бораве вечно, њихов поздрав ће у њима да буде: ''Мир Божји''.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Зар не видиш како Аллах наводи пример - лепа је реч као лепо дрво: корен му је чврсто у земљи а гране према небу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'Оно свој плод даје у сваком моменту са дозволом свога Господара - а Аллах људима наводи примере да би узели поуку,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'а ружна реч је као ружно дрво које је ишчупано са површине земље. Њему нема опстанка.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Аллах учвршћује вернике постојаном речју у животу на овом свету, а и на Будућем свету, а незнанобошце одводи у заблуду; Аллах ради шта хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Зар не видиш оне који су уместо захвалности Аллаху на благодатима – узвратили незахвалношћу и народ свој довели у кућу пропасти,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, 'у Пакао, у коме ће да горе - а ужасно је он пребивалиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'И који су поред Аллаха друга божанства узели да би заводили са Његовог пута? Реци: „Уживајте, завршићете, сигурно, у Ватри!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, 'Реци Мојим слугама које верују да обављају молитву и да удељују и тајно и јавно из онога што им Ми дарујемо, пре него што наступи Дан у коме неће да буде ни трговања ни пријатељства.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Аллах је Тај Који је створио небеса и Земљу; Он спушта са неба воду и чини да помоћу ње рађају плодови којима се храните; и потчинио вам је лађе да морем плове по Његовој одредби, и потчинио вам је реке,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'и потчинио вам је Сунце и Месец, који се стално крећу, и потчинио вам је ноћ и дан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'И даје вам од свега онога што од Њега тражите, и ако бисте Аллахове благодати бројали, не бисте их набројали. Човек је, уистину, итекако неправедан и незахвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'А када Аврам рече: „Господару мој, учини овај град Мекку сигурним и сачувај и мене и моје синове од тога да обожавамо кипове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'Они су, мој Господару, многе људе на странпутицу навели. Онај ко буде мене следио - моје је вере, а онај ко буде против мене устајао, па - Ти си, уистину, Онај Који опрашта грехе и милостив си.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'Господару наш, ја сам неке своје потомке населио у котлини у којој се ништа не сеје, код Твоје часне Ка''бе, да би, Господару наш, обављали молитву; зато учини да срца неких људи за њима чезну и опскрби их разним плодовима да би били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'Господару наш, Ти сигурно знаш шта ми кријемо, а шта на јаву износимо. А Аллаху ништа није скривено; ни на Земљи, ни на небу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Хвала Аллаху, Који ми је у старости подарио Јишмаила и Исака; мој Господар молбе, уистину, услишава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'Господару мој, дај да ја и моји потомци у обављању молитве будемо устрајни; Господару наш, Ти услиши моју молбу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'Господару наш, опрости мени, и мојим родитељима и свим верницима – на Дан кад се буде полагао рачун!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'А ти никако не мисли да Аллах не мари за оним што раде неверници! Он им само одгађа до Дана када ће очи да им остану отворене!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, 'Журиће, уздигнутих глава, укоченог погледа; а срца ће да им буду празна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Ти опомињи људе Даном када ће казна да им дође, кад ће они који су неправедни били – да говоре: „Господару наш, остави нас још само кратко време, одазваћемо се Твоме позиву и следићемо посланике!“ А зар се пре нисте заклињали да са овог света нећете да одете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'И настанили сте се били у местима где су живели они који су се према себи огрешили, а било вам је познато како смо поступили са њима, и наводили смо вам примере.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, 'И они лукавства своја плету, а Аллах зна за њихова лукавства, само што њихова лукавства не могу брда да покрену.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, 'Немој ни да помислиш да Аллах неће да одржи Своје обећање Својим посланицима - Аллах је, уистину, силан и строг.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, 'На Дан кад Земља буде замењена другом земљом, а и небеса, и кад сви изађу пред Аллахом, Јединим, Свемоћним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'Тог дана ћеш да видиш грешнике у оковима заједно повезане.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Одећа ће од катрана да им буде, а ватра ће обавијати њихова лица.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, 'То је зато да Аллах свакоме да шта је заслужио - Аллах заиста брзо своди рачун.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, 'Овај Кур''ан је обзнана људима, и да њиме буду опоменути, и да знају да је само Он Један Бог, и да приме поуку они који имају разум!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Елиф-лам-ра.[1] Ово су речи Књиге, јасног Кур''ана!', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Неверници ће често да жале што нису били Аллаху предани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Пусти их нека једу и наслађују се, и нека их заварава нада - знаће они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, 'А ниједно насеље нисмо уништили а да му није прописан одређени рок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Ниједан народ не може ни да убрза ни да успори одређено му време.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Они говоре: „Хеј ти коме се Кур''ан објављује, ти си уистину луд!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'Зашто нам анђеле не доведеш, ако је истина то што говориш!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Ми анђеле шаљемо само са истином, а када би их послали, тада се њима не би дало времена да чекају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Ми, уистину, Кур''ан објављујемо и заиста ћемо Ми да га сачувамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'И пре тебе смо слали посланике претходним народима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'И ниједан им посланик није дошао а да му се нису изругивали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Ето, тако дајемо да то уђе у срца неверника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Они у Кур’ан неће да поверују, а зна се шта је било с народима давнашњим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Кад бисмо им отворили капију на небу и кад би се они кроз њу успињали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'опет би они, сигурно, казали: „Наше очи су опијене, штавише, ми смо људи опчињени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Ми смо на небу сазвежђа створили и за оне који их посматрају украсили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'И заштитили смо га од сваког проклетог ђавола.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'А онога који крадом прислушкује стиже видљиви пламен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'А Земљу смо прострли и по њој смо поставили непомичне планине и учинили смо да на њој све расте са мером.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'И ту смо вам дали све што је за живот потребно, а и онима које ви не храните.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'И не постоји ништа чије ризнице не поседујемо, а од тога Ми дајемо само по одређеној мери.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Ми шаљемо ветрове да оплођују, а из неба спуштамо воду па вас њоме напајамо - ви нисте у стању да је задржите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'И само Ми дајемо живот и смрт, и Ми ћемо све наследити', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'и само Ми знамо оне који су вам претходили, и само Ми знамо оне који ће после да дођу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'А Он, твој Господар, заиста ће да их сабере. Он је Мудри и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Ми смо створили Адама од суве глине; од глатког блата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'А још пре смо створили духове од ужарене ватре.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'И кад твој Господар рече анђелима: „Ја ћу да створим човека од суве глине, од глатког блата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'И кад му дам лик и у њега удахнем душу, ви му се поклоните.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Па су се сви анђели скупа поклонили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'осим Сотоне; он је одбио да се поклони.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, '„О Сотоно“, упита Он, „зашто се ниси поклонио са онима који су се поклонили?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, '“Не приличи ми”, рече, “да се поклоним човеку кога си створио од иловаче, од блата устајалог.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, '„Онда излази из Раја“, нареди Аллах, „заиста си проклет!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'И нека се проклетство задржи на теби до Дана судњег!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, '„Господару мој“, рече он, „дај ми времена до Дана кад ће они да буду оживљени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, '„Даје ти се време“, рече Он,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, '„до Дана већ одређеног.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, '„Господару мој“, рече, „зато што си ме довео у заблуду, ја ћу њима на Земљи пороке да прикажем лепим и све ћу да их заведем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'осим Твојих искрених верника међу њима.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, '„Ове ћу се истине Ја држати”, рече Аллах.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, '„Ти нећеш да имаш никакве власти над Мојим верницима, осим над онима који те буду следили, од оних залуталих;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'за све њих Пакао ће да буде одредиште,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'он седам капија има и кроз сваку ће да прође одређен број њих.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Они који су се Аллаха бојали и оног што им је забрањено клонили, они ће у Рајским баштама поред извора бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, '„Уђите у њих сигурни, страха ослобођени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Ми ћемо да истиснемо злобу из њихових груди; као браћа ће да буду, они ће на диванима да седе једни наспрам других.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Ту их умор неће дотицати, они одатле никада неће да буду изведени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, 'Кажи Мојим створењима да сам Ја, заиста, Онај Који опрашта грехе, Милостиви,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, 'али да је и Моја казна, заиста, болна казна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'И обавести их о Аврамовим гостима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'када су дошли код њега и казали: „Мир Божји!“ Он рече: „Ми смо се вас уплашили!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, '“Не плаши се!” Рекоше, “доносимо ти радосну вест, ученог ћеш сина имати.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, '„Зар ми доносите радосну вест сада кад ме је старост опхрвала?“ Рече он, „чиме ћете да ме обрадујете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, '„Доносимо ти радосну вест која ће заиста да се обистини“, казаше они, „зато не буди од оних који губе наду!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, '„А ко губи наду у милост свога Господара осим заблудели?!“ Рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, 'И упита: „А који је тачно разлог вашег доласка, о изасланици?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, '„Ми смо“, казаше, „заиста, послати народу који је огрезао у злу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, 'изузев Лотове породице, њих ћемо, заиста, све да спасимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, 'осим његове жене, она ће, одредили смо, да буде од оних који ће да остану и искусе казну.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'И кад изасланици дођоше до Лотове породице,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, 'он рече: „Ви сте, заиста, непознати људи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, '„Не“, казаше они. „Доносимо ти оно у шта ови стално сумњају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, 'доносимо ти оно што ће да се догоди сигурно, а ми, заиста, истину говоримо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Изведи породицу своју у глуво доба ноћи, а ти буди на њиховом зачељу, и нека се нико од вас не осврће, и идите тамо где вам се наређује!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'И Ми смо му објавили оно што ће да се догоди: да ће они, сви до последњег, у свитање да буду уништени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'И дођоше становници града, весели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, '„Заиста су ово моји гости“, рече, „па ме не срамотите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, 'и бојте се Аллаха, и не понижавајте ме!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, '„А зар ти нисмо забранили да било кога угостиш?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, 'Он рече: „Ево вам за брак моје кћери, ако то хоћете да учините!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, 'А живота ми твога, они су у пијанству свом лутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'И њих је задесио страшан глас кад је Сунце излазило,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'и Ми смо њихова насеља изврнули, и на њих смо сручили кишу грумења од скамењене глине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'У томе су, заиста, знаци за оне који о томе проницљиво размишљају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'а насеље Содома је поред постојећег пута.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'У томе су, заиста, знаци за оне који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'А и становници Ејке били су неверници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'па смо их казнили, и оба насеља су поред пута видљивог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'И становници Хиџра су посланике сматрали лажним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'а Ми смо им доказе Наше дали, али су се они од њих окретали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Они су клесали куће у брдима, верујући да су сигурни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'па и њих у свитање задеси страшан глас,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'и није им ни од какве користи било оно што су стицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Ми смо створили небеса и Земљу и оно између њих са истином. Час оживљења ће да дође засигурно, зато ти великодушно опрости,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'твој Господар је, заиста, Створитељ свега, Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Ми смо ти дали седам стиха, који се понављају, а и величанствени Кур''ан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Не пружај своје погледе на оно што Ми дајемо на уживање некима од њих и не буди тужан због њих, а према верницима буди благ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, 'и реци: „Ја само јавно опомињем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, 'Као што смо следбенике Књиге опоменули.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'Оне који Кур''ан поделише на делове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'И тако Ми твога Господара, њих ћемо све да позовемо на одговорност', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, 'за оно што су радили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Ти јавно исповедај оно што ти се наређује и незнанобожаца се клони.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'Ми те чувамо од оних који ти се ругају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, 'који поред Аллаха обожавају другог бога; а знаће они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Ми добро знамо да ти је тешко у прсима због онога што они говоре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'зато, величај свога Господара и хвали Га, и буди од оних који Му се клањају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'и Господара свога обожавај све док ти смрт не дође!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Оно што је Аллах одредио – догодиће се; зато то не пожурујте! Хваљен је Он и врло високо изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'Он шаље анђеле с Објавом, по вољи Својој, оним верницима Својим којима хоће: “Опомињите да нема бога осим Мене и бојте Ме се!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'Он је мудро небеса и Земљу створио; нека је Он врло високо изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'Он ствара човека од капи семена, а он одједном – отворени противник!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'И стоку Он за вас ствара; њоме се од хладноће штитите, а и других користи имате, њоме се највише и храните,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'она вам је украс кад је враћате са испаше и кад је на пашу изгоните.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'А носи вам и терете у места у која, осим уз велике муке, не бисте стигли. Ваш Господар је, уистину, благ и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'И коње, и мазге, и магарце - да их јашете, и као украс - а створиће и оно што не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, 'Аллахово је да укаже на Прави пут, а има их и кривих путева; а да Он хоће, све би вас упутио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'Он је Тај Који са неба спушта воду коју пијете и она помаже да изникне биље којим стоку напасате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Он вам даје да помоћу ње изникне жито, и маслине, и палме, и грожђе, и разноврсни плодови - у томе је, заиста, доказ за људе који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'Он вам је потчинио ноћ и дан, и Сунце и Месец, и звезде су потчињене по Његовој одредби. У томе су, уистину, докази људима који памети имају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'и све што вам је на Земљи разнобојно створио - у томе је, заиста, доказ људима који поуку примају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'И Он је Тај Који је потчинио море, да из њега једете свеже месо и да вадите накит који носите - ти видиш лађе како га секу да бисте нешто из обиља Његовог стекли и да бисте захвални били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'И по Земљи је стабилне планине поставио да вас она не потресе, и реке, а и путеве да се усмеравате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'а и путоказе, а и по звездама се они управљају:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Па је ли онда Онај Који ствара као онај који не ствара!? Уразумите се!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Ако бисте бројали Аллахове благодати, не бисте их набројали; Аллах, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Аллах зна шта кријете, а шта јавно износите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'А они којима се они моле уместо Аллаха – ништа не стварају; они су сами створени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, 'мртви су, нису живи и не знају када ће да буду оживљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Ваш Бог је – један Бог! Срца оних који у Будући свет не верују поричу, они се охолошћу размећу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'Нема сумње да Аллах зна и оно што они крију, а и оно што јавно износе; Он, заиста, не воли оне који се охоле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'А када их неко упита: „Шта је то што ваш Господар објављује?“ Они одговарају: „Измишљотине народа древних!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'То је зато да би на Судњем дану носили своје грехе у потпуности и део греха оних које су, а да они нису били свесни, у заблуду довели. Ужасан је терет који ће они да носе!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'И они пре њих су правили сплетке, па је Аллах порушио из темеља њихове грађевине, и кров се на њих срушио - стигла их је казна одакле нису ни очекивали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'А на Судњем дану Он ће да их осрамоти и упита: „Где су они које сте Мени у обожавању придруживали, они због којих сте се супротстављали?“ Они којима је дато знање ће да кажу: „Данас ће срамота и мука невернике, заиста, да снађе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, 'оне којима су анђели узели душе у тренутку када су незнанобошци били.“ И они ће тада да се покоре и да кажу: „Ми нисмо никакво зло радили!“ „Јесте, Аллах, заиста добро зна оно што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Зато, улазите на капије Пакла, у њему ћете да останете вечно! О како ће да буде грозно пребивалиште оних који су се охолили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'А онима који су се бојали Аллаха и клонили греха рећи ће се: „Шта је објављивао ваш Господар?“ „Велико добро!“ Одговориће. Они који чине добра дела имаће већ на овом свету лепу награду, а Будући свет је, сигурно, још бољи. О како ће да буде дивно боравиште оних који су се бојали Аллаха:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, 'Еденски вртови у које ће да уђу, где теку реке, и где ће да имају све што пожеле. Тако ће Аллах да награди оне који Га се буду бојали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, 'оне којима анђели узимају душу док су честити, и којима говоре: „Мир Божји вама! Уђите у Рај због онога што сте радили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Зар незнанобошци чекају да им дођу анђели, или да дође одредба твога Господара?! Тако су поступили и они пре њих; њима није неправду учинио Аллах, они су сами себи учинили неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, 'И стигла их је казна за оно што су чинили, и са свих страна их је обузело оно чему су се ругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'И говоре они који друге поред Њега обожавају: „Да је Аллах хтео, не бисмо ни ми ни наши преци, поред Аллаха, никога обожавали и не бисмо ништа, без Његове воље, забрањеним сматрали.“ Исто тако су и они пре њих поступали. А зар су посланици били дужни ишта друго него да јасно обзнане истину?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Ми смо сваком народу посланика послали који им је наређивао: „Аллаха обожавајте, а ђавола се клоните!“ И било је међу њима оних које је Аллах упутио, а и оних који су заслужили заблуду. Зато путујте Земљом да видите какав је био завршетак оних који су посланике утеривали у лаж.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, 'Ма колико ти желео да их упутиш, Аллах, заиста, неће указати на Прави пут оном кога је у заблуди оставио, и њима нико неће помоћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Они се заклињу Аллахом, најтежом заклетвом: „Аллах неће да оживи онога који умре!“ Напротив! То Његово обећање заиста ће да се испуни, али то већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, 'Да би им објаснио оно у чему су се разилазили, и да би сазнали они који нису веровали да су били лажови.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Ако нешто хоћемо, Ми само за то кажемо: „Буди!“ И оно буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Оне који су се иселили ради Аллаха, након што су били тлачени, Ми ћемо још на овом свету на лепо место да сместимо; а награда на Будућем свету биће још већа кад би само знали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, 'Онима који су били стрпљиви и на Господара свога се ослањали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Ми смо и пре тебе само људе као посланике са објавом слали; ако за то не знате, питајте следбенике Књиге!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, 'Слали смо их са јасним доказима и књигама, а теби објављујемо Кур''ан, да би објаснио људима оно што им се објављује, и да би они размислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'А зар су сигурни они који подмукло праве зло - да Аллах неће у земљу да их утера, или да неће, одакле не могу ни да помисле, казна да им дође,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'или да их неће на путовањима њиховим казнити – а они Му неће моћи умаћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Или да их неће казнити док у страху стрепе? Али, Господар ваш је заиста благ и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Зар они не виде да све оно што је Аллах створио сад десно, сад лево, пружа своје сенке клањајући се Аллаху и да је све то покорно?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'Аллаху се клања све живо на небесима и на Земљи, и анђели, а они се не охоле,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'боје се свога Господара који је изнад њих и чине оно што им се нареди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Аллах каже: „Двојицу богова за обожавање не узимајте! Само је један Бог, и само од Мене страхујте!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'Све што је на небесима и на Земљи Аллахово је, и Њему треба увек послушан бити. Зар некога другог осим Аллаха да се бојите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'Сваку благодат коју имате вам је од Аллаха, а чим вас задеси каква невоља, опет од Њега гласно помоћ тражите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'А потом, кад вам Он невољу отклони, неки од вас поред Господара свога друга божанства обожавају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'да би занегирали оно што смо им Ми дали. Па уживајте, али заиста, знаћете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'Незнанобошци својим божанствима која ништа не знају остављају део хране коју им Ми дајемо. Кунем се Аллахом, бићете сигурно питани за све што сте измишљали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, 'Они Аллаху приписују кћери - Узвишен је Он! - а себи оно што прижељкују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'И кад се неком од њих јави да му се родила ћерка, лице му потамни и постаје потиштен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Крије се од људи због лоше вести која му је дојављена: да ли да је задржи уз понижење, или да је зарови у прашину? Како ружно они просуђују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'Они који у Будући свет не верују имају лоша својства, а Аллах има најузвишенија својства: Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Кад би Аллах људе због грехова њихових кажњавао, ништа живо на Земљи не би оставио, али Он их до рока одређеног оставља, и кад рок њихов дође, ни за трен га један не могу ни одложити ни убрзати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Они Аллаху приписују оно према чему сами осећају одвратност и њихови језици говоре лаж да њих чека најлепша награда; а њих, нема сумње, чека Ватра: они ће у њу први да буду потерани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'Кунем се Собом, Ми смо и пре тебе народима слали посланике, али им је ђаво улепшао њихове поступке, па им је он сада заштитник, и њих све чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Ми ти објављујемо Књигу само да би им објаснио оно у чему се разилазе, и да буде упута и милост верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Аллах воду с неба спушта и њоме живот мртвој земљи враћа! То је, заиста, доказ за људе који хоће да чују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Ви имате поуку и у стоци: „Ми вам дајемо да пијете оно што долази из њене утробе, што настаје између гризина и крви; то је млеко, укусно онима који га пију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'А од плодова палми и лозе припремате опојно пиће и пријатну храну. Ту је, заиста, доказ за људе који схватају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Твој Господар је надахнуо пчелу: „Прави себи куће у брдима, на дрвећу и у ономе што направе људи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, 'затим, храни се разноврсним плодовима, па онда иди стазама свога Господара, послушно!“ Из њихових утроба излази пиће различитих боја, у њему је лек људима. Ту је, уистину, доказ за људе који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Аллах вас ствара и после вам душе узима. Има вас који дубоку старост доживите, па брзо заборавите оно што сазнате. Аллах је, заиста, Свезнајући и Свемоћни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Аллах опскрбљујући вас даје једнима више него другима. Али они којима је дато више не дају онима који су у њиховој власти, а потребе су им једнаке. Зашто нису на Аллаховим благодатима захвални?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Аллах вам од вашег рода ствара жене, а од жена ваших даје вам синове и унуке, и укусна јела вам даје. Па зашто у лаж они верују, а Аллахове благодати поричу?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'И обожавају, поред Аллаха, оне који нису у стању да им дају било какву опскрбу, ни из небеса ни из земље, и који ништа не могу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Зато ништа не поредите са Аллахом! Аллах, заиста, зна, а ви не знате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Аллах наводи пример роба у туђем власништву, који ништа нема, и онога коме смо Ми дали лепу опскрбу и који удељује из тога, и тајно и јавно – зар су они једнаки?! Нека је хваљен Аллах! Али, већина њих не зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Аллах вам наводи као пример двојицу људи од којих је један глувонем, који ништа нема и који је на терету господару свом – куд год га пошаље, никаквог добра не донесе. Да ли је он једнак оном који тражи да се праведно поступа, а и сам је на Правом путу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'Аллах зна тајне небеса и Земље! А Смак света ће у трен ока доћи, или још брже, јер је Аллах, уистину, Свемоћни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Аллах вас из утроба ваших мајки изводи док још ништа не знате, и даје вам слух и вид и разум - да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Зар они не виде птице како без муке лете у пространству небеском?! Њих само Аллах држи. Ту су, заиста, докази људима који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Аллах вам даје да у кућама својим станујете и даје вам од коже стоке шаторе које лако носите кад на пут идете и кад коначите, а од вуне њихове и длаке њихове и кострети њихове простирку и корисне ствари – све док се не истроше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Аллах вам у ономе што је створио даје хлад, и даје вам склоништа у брдима, и даје вам одећу која вас чува од врућине, даје вам и оклопе који вас у борби штите - тако вам употпуњава Своју благодат да бисте били Њему предани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'А ако се они окрену од веровања, па твоја дужност је само да јасно доставиш поруку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Они признају да је благодат од Аллаха, па је после поричу – већина њих су неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'А на Дан када из сваког народа доведемо сведока, неверницима неће да буде допуштено да се правдају, нити ће им се пружити прилика да се врате на Земљу, како би постали верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Кад они који нису веровали угледају казну, она им неће бити ни умањена ни одгођена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'А кад они који су, поред Аллаха, обожавали друга божанства виде своја божанства, рећи ће: „Господару наш, ово су наша божанства којима смо се, мимо Тебе, молили. “Божанства ће им одговорити: „Ви сте, уистину, лажљивци!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'И они ће тога дана Аллаху да се покоре, и нестаће лажи које су измишљали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Онима који нису веровали и који су од Аллаховог пута одвраћали, Ми ћемо двоструком казном казнити зато што су правили смутњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'А на Дан када из сваког народа доведемо по једног сведока који ће да сведочи против свог народа, а тебе доведемо као сведока против ових! Ми теби објављујемо Књигу као објашњење за све и као упуту и милост и радосну вест за оне који једино у Њега верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Аллах, заиста, наређује правду, доброчинство и помагање ближњих, а разврат, све што је одвратно и насиље забрањује; Он вас саветује како бисте узели поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'И испуњавајте обавезе на које сте се обавезали Аллаху и не кршите заклетве кад сте их чврсто дали, а Аллаха као јамца узели, јер Аллах зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'И не будите као она која би своју плетеницу распрела кад би је већ била чврсто уплела, и не служите се заклетвама својим да бисте једни друге преварили само зато што је једно племе многобројније од другог. Аллах вас тиме само искушава, а на Судњем дану ће вам, заиста, објаснити оно око чега сте се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Да Аллах хоће, учинио би вас следбеницима једне вере, али Он у заблуду одводи оног кога хоће, а на Прави пут указује оном коме Он хоће; и ви ћете заиста одговарати за оно што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'И не служите се заклетвама својим зато да бисте једни друге варали, да се не би поклизнула нога која чврсто стоји и да не бисте несрећу искусили зато што сте од Аллаховог пута одвраћали; а патња велика вас још чека.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'И не замењујте обавезу дату Аллаху за нешто што мало вреди - оно што је код Аллаха за вас је боље, ако знате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Оно што је код вас - пролазно је, а оно што је код Аллаха - вечно је. Ми ћемо, сигурно, оне који су били стрпљиви наградити многоструком наградом за оно што су чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Оном ко чини добро, био мушкарац или жена, а верник је, Ми ћемо дати да проживи леп живот и заиста ћемо их наградити бољом наградом него што су заслужили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Када будеш хтео да учиш Кур''ан, затражи Аллахову заштиту од проклетог ђавола,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'он заиста нема никакве моћи над онима који верују и који се уздају у свога Господара,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'његова је моћ једино над онима који њега за заштитника узимају и који друге поред Аллаха обожавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Када Ми пропис заменимо другим - а Аллах најбоље зна шта објављује - они говоре: „Ти само измишљаш!“ А није тако, него већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'Реци: „Од твог Господара спушта га анђео Гаврило као истину, да још више учврсти вернике, и да буде упута и радосна вест онима који су Аллаху предани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Ми добро знамо да они говоре: “Поучава га један човек!” Језик оног због кога они криво говоре је језик неарапина, а овај Кур’ан је на јасном арапском језику.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Онима који неће да верују у Аллахове доказе Аллах, сигурно, неће указати на Прави пут, и њих чека патња несносна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Усуђују се да лажи измишљају само они који у Аллахове речи не верују, и они су прави лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Оног који занегира Аллаха, након што је у Њега веровао – осим ако буде на то приморан, а срце му остане чврсто у вери – чека Аллахова казна. Оне којима се неверство буде милило стићи ће срџба Аллахова и њих чека патња велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Зато што су више волели живот на овом свету од Будућег света, а Аллах неће да упути на Прави пут народ који не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'То су они чија је срца и слух и вид Аллах запечатио, и они су заиста немарни;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'они ће, нема сумње, на Будућем свету бити изгубљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Господар твој ће онима који се иселе, након што су злостављани били, па се онда буду борили и све стрпљиво подносили – Господар твој ће им, после тога, заиста опростити и самилостан бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, 'На Дан у којем ће сваки човек само о себи да брине и у коме ће се сваком човеку за дела његова пуна награда или казна дати, неправда им се неће учинити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Аллах наводи као пример град, сигуран и спокојан, коме је у обиљу долазила храна са свих страна, а који је незахвалан на Аллаховим благодатима био, па му је Аллах дао да искуси и глад и страх због онога што су радили његови становници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'И њима је дошао посланик, један од њих, али су га они лажљивцем назвали, и њих је стигла казна зато што су неправедни били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Храните се допуштеним и лепим јелима којима вас Аллах опскрбљује и будите захвални Аллаху на Његовим благодатима, ако само Њега обожавате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'Он вам забрањује једино стрв, и крв, и свињско месо, и ону стоку која је заклана у нечије друго, а не у Аллахове име. А оном ко буде приморан, али не из жеље, него само толико да утоли глад – па Господар твој ће, заиста, да опрости и самилостан да буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'И не говорите неистине језицима својим: “Ово је допуштено, а ово је забрањено” – да бисте тако о Аллаху неистине износили. Они који о Аллаху говоре неистине неће успети,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, 'кратко ће уживати, и њих чека страшна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'Јеврејима смо забранили оно о чему смо ти пре казивали; Ми према њима нисмо неправедни били, они су сами себи неправду нанели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'Онима који ураде зло из незнања, па се касније покају и поправе, твој Господар ће, после тога, сигурно да опрости и да буде милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Аврам је био пример честитости, покоран Аллаху, прави верник, и није био од оних који су друге поред Аллаха обожавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'И био је захвалан на Његовим благодатима; њега је Аллах изабрао и на Прави пут упутио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'и Ми смо му сачували леп спомен на овом свету, а на Будућем свету ће заиста бити међу онима добрима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'После смо теби објавили: „Следи Аврамову веру, праву веру, он није био од оних који су друге поред Аллаха обожавали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Светковање суботе прописано је онима који су имали о њој различита мишљења, и твој Господар ће на Судњем дану да пресуди у вези са оним у чему су се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'На пут свога Господара мудро позивај и лепим саветом, и са њима на најлепши начин расправљај! Твој Господар зна оне који су залутали са Његовог пута, и Он зна оне који следе Упуту.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Ако хоћете да на неправду узвратите, онда учините то само у оноликој мери колико вам је учињено; а ако се стрпите - то је, заиста, боље за стрпљиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Стрпљив буди! Али, стрпљив ћеш да будеш само уз Аллахову помоћ. И не тугуј за њима, и нека ти није тешко због њиховог сплеткарења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Аллах је заиста на страни оних који се Њега боје и греха клоне и који добра дела чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Узвишен нека је Онај Који је у једном часу ноћи превео Свог слугу Мухаммеда од Часне џамије до Далеке џамије, чију смо околину благословили како бисмо му нека знамења Наша показали. Он, уистину, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'А Мојсију смо дали Књигу и упутом је Израиљевим синовима учинили и казали: “Поред Мене – Господара другог не узимајте,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, 'о потомци оних које смо са Нојем у лађи превезли!“ Он је, заиста, био слуга захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'И Ми смо у Књизи објавили Израиљевим синовима: „Ви ћете заиста два пута неред на Земљи да учините и увелико да се охолите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'Када дође време прве претње, послаћемо против вас Наше слуге жестоке снаге, они ће уздуж и попреко земљу вашу да прегазе, и обећање о казни ће да се испуни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Затим ћемо да вам дамо победу против њих и повећаћемо вам имовину и синове и учинићемо вас бројнијим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, 'Све што чините – чините себи, добро и зло. А кад дође време друге претње, послаћемо их да на лицима вашим тугу и јад оставе и да у Храм као и први пут, поново провале и да све што освоје до темеља поруше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, 'И Господар ће вам се ваш опет смиловати; али ако се вратите нереду, вратићемо се и Ми казни. А Пакао смо за невернике учинили тамницом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Овај Кур’ан води једином исправном путу, и верницима који чине добра дела доноси радосну вест да их чека награда велика,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'а да смо за оне који у Будући свет не верују - припремили болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'Човек и проклиње и благосиља; човек је склон журби и брзим одлукама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'И Ми смо ноћ и дан као два знамења учинили: знак ноћи смо уклонили, а знак дана смо учинили видним како бисте могли да тражите благодати свога Господара и да бисте број година знали и да бисте време рачунали - и све смо потанко објаснили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'И сваком човеку је сачувано и забележено све што је урадио, а на Судњем дану показаћемо му књигу отворену:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, '“Читај своју књигу, доста ти је данас то што ћеш свој рачун да полажеш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Онај који иде Правим путем, од тога ће само он користи имати; а онај ко лута – на своју штету лута, и ниједна душа неће да носи туђе грехе. А Ми ниједан народ нисмо казнили док посланика нисмо послали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Кад хоћемо да уништимо неко насеље, онима који су у њему на раскош навикли наредимо покорност, а они у њему буду непокорни и тако се над њима обистини Реч казне, па га до темеља разрушимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'И колико смо само народа после Ноја уништили! А довољно је то што твој Господар у потпуности зна и види грехе Својих створења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Ономе који жели овај краткотрајни свет, Ми му на њему брзо дајемо - шта хоћемо и коме хоћемо, али ћемо после да му припремимо Пакао, у коме ће да гори презрен и одбачен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'А онај ко жели Будући свет и труди се да га заслужи, а верник је, труд ће му хвале вредан бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'Свим људима, и једнима и другима, Господар твој пружа Своје дарове; а дарови твога Господара нису никоме забрањени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Гледај како некима дајемо предност над другима; а на Будућем свету ће да буде разлика у степенима и предностима, заиста, већа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Не узимај уз Аллаха неког другог бога, па да будеш понижен и без помоћи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Твој Господар заповеда да само Њега обожавате и да родитељима чините доброчинство. Кад једно од њих двоје, или обоје, код тебе доживе старост, не реци им ни: „Уф!“, и не одбиј их од себе, и обраћај им се речима пуним поштовања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'Буди према њима пажљив и понизан и реци: “Господару мој, смилуј им се, они су мене, кад сам био дете, неговали!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'Господар ваш најбоље зна шта је у вашим душама: ако будете доброчинитељи, па Аллах ће, заиста, да опрости онима који се кају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, 'Дај своме ближњем његово право, и сиромаху, и путнику, али нипошто не расипај.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Заиста су расипници ђавољева браћа, а ђаво је своме Господару итекако незахвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'А ако немаш ништа да уделиш, јер и сам од Господара свог милост тражиш и њој се надаш, онда им барем коју лепу реч реци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Не држи руку своју стиснуту, а ни посве отворену, па да будеш укорен и да без ичега останеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'Твој Господар, заиста, пружа обилну опскрбу ономе коме хоће, а и ограничава је. Он, уистину, у потпуности зна и види Своје слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Не убијајте своју децу из страха од сиромаштва, и њих и вас Ми хранимо, њихово убијање је заиста велики грех!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'И никако се не приближавајте блуду. Заиста је блуд разврат, и ружан пут!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'И не убијајте никога кога је Аллах забранио, осим када је то законом оправдано! А ако је неко, ни крив ни дужан, убијен, онда његовом наследнику или старатељу дајемо власт, али нека ни он не прекорачује границу у убијању. Он је, заиста, од Аллаха потпомогнут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'И не приближавајте се имовини сирочета, осим ако желите да је унапредите, све док не постане пунолетно. И испуњавајте оно на шта сте се обавезали, јер ће за уговоре заиста да се одговара!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Употпуните меру када мерите и вагајте исправном вагом! То је боље и последице су лепше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'И не поводи се за оним што не знаш! И слух и вид и разум - за све то ће, заиста, да се одговара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Не ходај по Земљи охоло! Земљу сигурно не можеш да пробијеш ни брда висином да достигнеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Све су то ружна дела, Господару твоме мрска.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'То је мудрост коју ти твој Господар објављује. И не сматрај да поред Аллаха постоји друго божанство, да не би био бачен у Пакао, понижен и од милости одбачен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Зар је вас ваш Господар обдарио синовима, а Себи, као кћери, узео анђеле?! Ви, заиста, изговарате крупне речи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'У Кур''ану смо мноштво опомена навели да би они поуку извукли, али њима Кур''ан само одбојност повећава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'Реци: „Да поред Њега постоји друго божанство, као што они говоре, они би онда потражили пут до Власника Престола.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Слављен нека је Он и врло високо изнад оног што они говоре!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Њега величају седам небеса, и Земља, и они на њима; и не постоји ништа што Га не велича, хвалећи Га; али ви не разумете њихово величање. Он, заиста, не жури са казном и опрашта грехе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'А када учиш Кур''ан, између тебе и оних који у Будући свет не верују Ми ставимо невидљиви застор који раздваја,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'а на њихова срца покриваче да га не би разумели, и учинимо их глувим. И када ти у Кур''ану споменеш свога Господара да је Једини, они из одбојности окрену леђа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Ми добро знамо шта они желе да чују када долазе да те прислушкују, и о чему се сашаптавају кад неправедници говоре: „Ви следите само опчињеног човека!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Погледај шта о теби они говоре, па онда лутају и не могу да нађу Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Они говоре: „Зар кад се у кости и прашину претворимо, зар ћемо новим стварањем, заиста, да будемо оживљени?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, 'Реци: “Хоћете, и да сте камење или гвожђе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'или било какво створење за које мислите да не може да буде оживљено!“ „А ко ће у живот да нас врати?“ Упитаће они. Ти реци: „Онај Који вас је и први пут створио“, а они ће према теби да одмахну главама својим и да упитају: „Када то?“ Ти реци: „Можда убрзо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'На Дан када вас Он позове, ви ћете са захвалом да Му се одазовете, и помислићете да сте само мало времена на Земљи боравили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'И реци Мојим слугама да говоре само лепе речи: јер би Сотона могао посејати непријатељство међу њима, Сотона је, заиста, човеков отворени непријатељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Господар ваш вас најбоље познаје: ако хоће, Он ће вам се смиловати или ће вас, ако хоће, казнити. И Ми ти нисмо дали власт над њима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Твој Господар најбоље зна оне на небесима и оне на Земљи; Ми смо једне веровеснике над другима одликовали, а Давиду смо Псаламе дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'Реци: “Молите се онима које, поред Њега, сматрате боговима – али вас они неће моћи невоље ослободити нити је изменити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Они којима се они моле и сами траже начин како ће што више своме Господару да се приближе, и надају се Његовој милости и плаше се Његове казне. А казне Господара твог свако треба да се чува.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'И не постоји ниједно насеље које Ми пре Судњег дана нећемо да уништимо или да га тешкој муци изложимо; то је у Књизи одређено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'А не шаљемо чуда само зато што древни народи у њих нису поверовали. Семуду смо као видљиво чудо камилу дали, али они у њу нису поверовали. А чуда шаљемо само да застрашимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'И казали смо ти: “Сви су људи у власти твога Господара!” А сан који смо ти дали да усниш и дрво уклето, у Кур’ану споменуто, искушење су за људе. Ми их застрашујемо, али њима то само повећава ионако велику охолост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'И када смо казали анђелима: „Поклоните се Адаму!“ - Они се сви, осим Сотоне, поклонише. „Зар да се поклоним ономе кога си од глине створио?“ Рече.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, '“Реци ми”, рече онда, “ево овог кога си изнад мене уздигао: ако ме оставиш до Судњег дана сигурно ћу, осим малобројних, над потомством његовим загосподарити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, '“Одлази!” Рече Он. “Теби и онима који се за тобом буду повели следи потпуна казна у Паклу."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'И заводи гласом својим кога можеш и сакупи против њих своју коњицу и своју пешадију, и имај удела у њиховој имовини и деци, и дај им обећања – а само је обмана то што им Сотона обећава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, 'Ти, заиста, нећеш да имаш никакве власти над Мојим слугама!“ А твој Господар је довољан као заштитник!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Господар ваш је Тај Који због вас покреће лађе по мору да бисте трагали за Његовим обиљем. Он је, заиста, према вама милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Кад вас на мору невоља задеси, тад нема оних којима се иначе молите, постоји само Он. А кад вас Он на копно спаси, ви окрећете главе – човек је увек незахвалан!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Зар сте сигурни да Он неће Земљу да потресе па да вас у њу утера или да неће да пошаље на вас кишу камења, па да онда себи никаквог заштитника не нађете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Или сте можда сигурни да Он неће на море поново да вас изведе, и буру на вас да пошаље и потопи вас због ваше непослушности?! Тада не бисте никога нашли ко би Нас због вас на одговорност позвао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Ми смо Адамовом потомству почаст указали: дали смо им да копном и морем путују, и опскрбили смо их укусним јелима, и дали Смо им посебну предност над многим створењима које смо створили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, 'А на Дан кад позовемо све људе с вођом својим, они којима се књига њихова да у десну руку њихову читаће књигу своју и неће им бити ни колико трун један учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'онај ко је на овом свету био слеп за истину биће слеп и на Будућем свету и далеко од Правог пута.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'И замало да те они одврате од онога што ти Ми објављујемо, да би против Нас нешто друго изнео, и тада би те они као пријатеља прихватили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'А да те нисмо учинили чврстим, готово да би им се мало приклонио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'и тада бисмо ти, заиста, дали да искусиш двоструку патњу у животу и двоструку патњу после смрти; тада не би никога нашао да те од Нас спаси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'А они су те толико на Земљи узнемиравали како би те из ње истерали, али тад ни они у њој не би дуго, после тебе, остали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, 'јер тако је било са свима онима који су посланике протерали, које смо пре тебе послали, и ни ти нећеш наићи на одступање од закона Нашег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Обављај молитву кад сунце с половине неба крене, па до ноћне тмине, и молитву у зору, јер молитви у зору многи присуствују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'И пробди део ноћи у молитви – то је само твоја дужност; Господар твој ће ти на Будућем свету хвале достојно место даровати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'И реци: “Господару мој, подстакни ме на оно што је исправно и добро за мене, и поштеди ме свега оног у чему је зло за мене, и даруј ми од Себе доказе и снагу која ће ми помоћи!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'И реци: “Дошла је истина, а нестало је лажи – лаж, заиста, нестаје!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Ми објављујемо у Кур''ану оно што је лек и милост верницима, а неверницима он само повећава пропаст.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'Кад човеку какву благодат дарујемо, он се окреће и охоло удаљава, а кад га задеси зло, онда очајава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'Реци: „Свако на свој начин поступа, а ваш Господар најбоље зна ко је на Правом путу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Питају те о души. Реци: “Шта је душа само Господар мој зна, а вама је дато само мало знања.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'А да хоћемо, Ми бисмо учинили да ишчезне оно што смо ти објавили, и ти, после, не би никога нашао ко би ти против Нас помогао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'али, твој Господар је према теби милостив и Његова доброта према теби заиста је велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'Реци: „Кад би се сви људи и духови удружили да саставе један овакав Кур''ан, они, као што је он, не би саставили, па макар једни другима помагали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Ми у овом Кур''ану објашњавамо људима свакакве примере, али већина људи никако неће да верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'И говоре: „Нећемо да ти поверујемо све док не учиниш да из земље извор потече;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'или док не будеш имао врт од палми и лозе, па да кроз њега реке проведеш;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'или док на нас небо у парчадима не обориш, као што тврдиш; или док нам Аллаха и анђеле не доведеш да их својим очима видимо;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'или док не будеш имао кућу од злата, или док се на небо не успењеш; а нећемо да верујемо ни да си се успео све док нам не донесеш Књигу да је читамо.“ Реци: „Узвишен нека је мој Господар! Зар ја нисам само човек, посланик?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'А људе је, кад им је долазила објава, одвраћало од веровања само то што су говорили: „Зар је Аллах као посланика послао човека?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, 'Реци: „Кад би на Земљи анђели ходали смирено, Ми бисмо им са неба анђела као посланика послали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, 'Реци: “Аллах је довољан сведок мени и вама, јер Он зна и види Своја створења.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Онај кога Аллах упути - он је упућен, а онога кога на странпутицу одведе, томе, мимо Њега, нећеш да нађеш заштитника. Ми ћемо, на Судњем дану, да их сакупимо, лицем земљи окренуте, слепе, неме и глуве; боравиште њихово биће Пакао; кад год му пламен јења, појачаћемо им огањ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'То ће да им буде казна зато што у речи и доказе Наше нису веровали и што су говорили: „Зар кад постанемо кости и прах, зар ћемо као нова створења заиста да будемо оживљени?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Зар они не знају да је Аллах, Створитељ небеса и Земље, способан да створи њима сличне и да им је већ одредио час оживљења, у који нема сумње? Али неверници само поричу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'Реци: „Да ви поседујете ризнице милости мога Господара, и тада бисте шкртарили из страха да не потрошите; човек је заиста тврдица.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'Ми смо Мојсију девет очигледних знамења дали, па упитај Израиљеве синове кад је њиховим прецима дошао и када му је фараон рекао: „Ја мислим, о Мојсије, да си ти заиста опчињен“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, 'а Мојсије одговори: „Ти знаш да ово није дао нико други него Господар небеса и Земље, као очигледна знамења, и ја мислим да ћеш ти, о фараоне, сигурно да настрадаш.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Фараон одлучи да их из земље истера, па ми потописмо и њега и све оне који су били са њим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'и после тога казасмо Израиљевим синовима: „Населите се по Земљи, па кад време Смака света наступи, све ћемо заједно да вас окупимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Ми Кур’ан пун истинске мудрости објављујемо, и на истинит начин се он објављује. А тебе смо послали само зато да радосне вести доносиш и да опомињеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, 'И као Кур''ан, све део по део га објављујемо да би га ти људима постепено казивао, и према потреби га објављујемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'Реци: “Веровали у њега или не веровали, они којима је још пре објављивања његовог дато знање падају лицем на тло кад им се он чита.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'И говоре: „Узвишен нека је наш Господар, обећање нашег Господара се испунило!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'И падају лицем на тло плачући, и он им увећава страхопоштовање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'Реци: „Зовите Га: ''Аллах'', или зовите: ''Свемилосни'', а како год Га будете звали, Његова су имена најлепша. Не изговарај на сав глас Кур''ан кад молитву обављаш, а и не пригушуј га; нађи средину између тога.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, 'И реци: „Сва хвала Аллаху Који Себи није узео детета и Који у власти нема сличног, и Коме не треба заштитник због немоћи“ – и истински Га величај!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, 'Сва хвала припада Аллаху Који Свом слуги објављује Књигу, у којој нема искривљености,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, 'тачна и потпуна, да тешком казном, коју ће Он дати, упозори, а да вернике који раде добра дела дивном наградом обрадује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'У којима ће вечно да бораве,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'и да упозори оне који говоре: „Аллах има сина.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'О томе они ништа не знају, а ни њихови преци. Како крупна реч излази из њихових уста! Они не говоре осим неистину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Па зар ћеш да уништиш себе од туге за њима, ако они у Кур''ан неће да поверују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Све што је на Земљи Ми смо створили као украс да би искушали људе чија ће дела да буду боља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'и заиста ћемо Ми све што је на њој у опустошено тло да претворимо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Мислиш ли ти да су само становници пећине, чија су имена на плочи написана, били чудо међу чудима Нашим?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, 'Кад се неколико момака у пећини склонило па казало: “Господару наш, дај нам Своју милост и пружи нам у овом нашем поступку присебност.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'И Ми смо их у пећини дубоким сном успавали за дуго година.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'После смо их пробудили како би се видело која ће од две скупине боље оценити колико су времена ту провели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Испричаћемо ти повест њихову – онако како је било. То су били момци, веровали су у Господара свог, а Ми смо им уверење још више учврстили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Оснажили смо били њихова срца кад су се дигли и рекли: „Наш Господар - Господар је небеса и Земље, ми нећемо поред Њега другом богу да се молимо, јер бисмо тада лаж казали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, 'Овај наш народ обожава друга божанства мимо Аллаха, па зашто о њима јасан доказ не донесу? А има ли већег неправедника од онога који о Аллаху износи лаж?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, 'Кад напустите њих и оне које мимо Аллаха обожавају, склоните се у пећину, ваш Господар ће Својом милошћу да вас обаспе и припремиће вам све оно што ће да вам буде корисно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'И ти си могао видети како Сунце, кад се рађа, обилази пећину с десне стране, а кад залази – заобилази је с леве стране, а они су били у средини њеној. То је доказ Аллахове моћи! Коме Аллах укаже на Прави пут, он ће Правим путем ићи, а кога у заблуду одведе, ти му нећеш наћи заштитника који ће га на Прави пут упутити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'И помислио би да су будни, али они су спавали; и Ми смо их превртали сад на десну, сад на леву страну, а пас њихов, опружених предњих шапа, на улазу је лежао; да си их видео, од њих би побегао и страх би те ухватио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'И Ми смо их, исто тако, пробудили да би једни друге питали. „Колико сте овде остали?“ Упита један од њих. „Остали смо дан или део дана“, одговорише. „Ваш Господар најбоље зна колико сте остали“, рекоше. „Пошаљите једног од вас са овим вашим сребрењацима у град, па нека види код кога је најчистије јело и нека вам од њега донесе храну и нека буде пажљив, и нека никоме не говори ништа о вама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'јер, ако они сазнају за вас, каменоваће вас или ће на силу у своју веру да вас обрате, и тада никад нећете да успете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'И Ми смо, исто тако, учинили да они за њих сазнају, да би се уверили да је истинито Аллахово обећање и да у час оживљења нема никакве сумње, кад су се између себе о њима расправљали, и рекли: “Саградите на улазу у њу ограду, Господар њихов најбоље зна ко су они.” А онда они до чијих се речи највише држало рекоше: “Направићемо на улазу у њу богомољу!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'Неки ће да кажу: „Била су тројица, пас њихов је био четврти“, а неки ће да говоре: „Била су петорица, пас њихов је био шести“, нагађајући о ономе што не знају, док ће неки да кажу: „Била су седморица, а пас њихов био је осми.“ Реци: „Мој Господар најбоље зна њихов број, само мало њих то зна. Зато не расправљај о њима осим површно и лепо, и не питај о њима никога од њих!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'И ни у ком случају не реци: „Урадићу то сигурно сутра!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, 'Не додавши: „Ако Аллах да!“ А када заборавиш, сети се свога Господара и реци: “Господар мој ће ме упутити на оно што је боље и корисније од овог.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'А они су остали у пећини својој три стотине година, а томе додајте још девет.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'Реци: “Аллах најбоље зна колико су остали; тајне небеса и Земље једино Он зна. Како Он све види, како Он све чује! Они немају другог заштитника осим Њега, а Он не узима никог у одлукама Својим као судруга.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'А ти казуј из Књиге свога Господара оно што ти се објављује, нико не може да измени Његове речи, и ти осим код Њега, нећеш наћи никакво уточиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Буди стрпљив уз оне који се своме Господару моле ујутру и навече у жељи за Његовим Лицем, и не окрећи се од њих из жеље за украсима живота на овоме свету, и не слушај онога чије смо срце учинили немарним да Нас слави, који страст своју следи и чији су поступци далеко од разборитости.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'И реци: „Истина долази од вашег Господара, па ко хоће – нека верује, а ко хоће - нека не верује!'' Ми смо неверницима припремили Ватру чији ће пламен да их обухвати са свих страна; ако замоле помоћ, помоћи ће им се течношћу попут растопљене руде која ће лица да испече. Ужасног ли пића и грозног ли боравишта!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'Оне који буду веровали и добра дела чинили – Ми заиста нећемо допустити да пропадне награда оном који је добра дела чинио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'њих сигурно чекају еденски вртови, кроз које теку реке, у њима ће наруквицама од злата да се ките и у зелена одела од свиле и броката облаче, на софама ће у њима да буду наслоњени. Дивне ли награде и величанственог ли боравишта!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'И наведи им као пример два човека: једном од њих смо дали два врта засађена лозом и опасали смо их палмама, а између њих смо поставили њиве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Оба врта давала су свој плод, ничега није мањкало, а кроз њихову средину смо провели реку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'Он је и другог иметка имао. И рече другу свом, док је с њиме разговарао: “Од тебе сам богатији и јачег сам рода!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'И уђе у врт свој незахвалан Господару свом на благодатима, говорећи: “Не мислим да ће овај врт икад пропасти,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'и не мислим да ће Смак света икада да дође; а ако будем враћен своме Господару, сигурно ћу да нађем нешто боље од овог мог врта.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'И рече му његов друг, док је са њим разговарао: „Зар не верујеш у Онога Који те је створио од земље, затим од капи семена, и најзад те учинио потпуним човеком?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'Што се мене тиче, Он је Аллах мој Господар, и ја поред свог Господара не обожавам никога.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'А зашто ниси, кад си у врт ушао, рекао: ''Машаллах! Сва снага припада само Аллаху!'' Кад већ видиш да је код мене мање богатства и потомства него код тебе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'па мој Господар ми може дати бољи врт од твога, а на твој да пошаље казну са неба, па да остане само клизава ледина без ичега,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'или да му вода у понор оде па да не можеш да је пронађеш никада.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'И пропадоше плодови његови и он поче кршити руке своје жалећи за оним што је на њега утрошио – а лоза се беше поваљала по подупирачима својим - и говораше: „Камо среће да своме Господару нисам никога у обожавању придруживао!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'И није имао никога ко би могао да му помогне, осим Аллаха; а сам себи није могао да помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'Тада може да помогне само Аллах Истинити, Он даје најбољу награду и чини да се све на најбољи начин оконча.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Наведи им као пример да је живот на овом свету као биље, које и после натапања водом, коју Ми спуштамо са неба, ипак постане суво и ветрови га разнесу. А Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Богатство и синови су украс у животу на овом свету, а добра дела, која вечно остају, биће од Господара твог боље награђена и оно у шта се човек може поуздати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'А на Дан кад планине уклонимо и кад видиш Земљу опустошену – а њих смо већ сакупили, ниједног нисмо изоставили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'Пред твојим Господаром биће они у редове поређани: „Дошли сте нам онако како смо вас први пут створили, а тврдили сте да нећемо да вам одредимо време за оживљавање.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'И Књига ће бити постављена и видећеш грешнике престрављене због оног што је у њој. “Тешко нама!” Говориће, “каква је ово Књига: ни мали ни велики грех није пропустила, све је набројала!” – И наћи ће уписано оно што су радили. Господар твој неће ником неправду учинити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'И када смо рекли анђелима: „Поклоните се Адаму!“ Сви су се поклонули осим Сотоне, он је био један од духова, па је одбио послушност на заповест свог Господара. Па зар ћете њега и његов пород, поред Мене, као заштитнике да прихватите, кад су вам они непријатељи? Како је Сотона лоша замена неверницима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Ја их нисам узимао за сведоке приликом стварања небеса и Земље, нити неке од њих приликом стварања других, и за помагаче нисам узимао оне који на пут заблуде одводе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'А на Судњем дану када каже: “Позовите оне за које сте тврдили да су божанства поред Мене!” – И кад их позову, они им се неће одазвати, и Ми ћемо их све увести у ватру Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'И неверници ће угледати ватру и увериће се да ће у њу пасти, и да им из ње неће никад повратка бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'У овом Кур''ану Ми на разне начине објашњавамо људима многобројне примере, али је човек, више него ико, спреман да расправља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'А људе, кад им долази упута, одвраћа од веровања и од тражења опроста од свог Господара, само то што очекују судбину древних народа, или то што очекују очиту казну!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Ми шаљемо посланике само зато да доносе радосне вести и да упозоре. А неверници се расправљају, служећи се неистинама, да би тиме оповргли истину, и исмејавају се доказима Мојим и Мојим опоменама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'И има ли неправеднијег од оног који, кад се доказима Господара свог опомиње, за њих не мари, и заборавља на последице оног што је учинио? Ми на срца њихова покриваче стављамо да Кур’ан не схвате, и глувим их чинимо; и ако их ти на Прави пут позовеш они, као такви, никад неће Правим путем поћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Твој Господар прашта грехе и милостив је; да их Он кажњава за оно што заслужују, одмах би их на муке ставио. Али, њих чека одређени час од кога неће моћи да побегну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, 'А она села и градове смо разорили зато што становници њихови нису веровали и за пропаст њихову бисмо тачно време одредили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, 'И када Мојсије рече помоћнику свом: „Нећу стати све док не стигнем до места где се састају два мора, или ћу дуго, дуго да идем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'И кад њих двојица стигоше до места на коме се мора састају, заборавише на своју рибу, па она у море клизну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'А кад се удаљише, Мојсије рече своме помоћнику: „Дај нам нашу ужину, уморили смо се од овог нашег путовања.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, '„Види!“ Рече он, „кад смо код оне стене свратили, ја сам заборавио ону рибу - сам ђаво је учинио да је заборавим, да ти је не споменем - па мора да је она склизнула у море; баш чудновато!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, '„Е, то је оно што тражимо!“ Рече Мојсије, и њих двојица се вратише путем којим су били дошли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'и нађоше једног Нашег слугу којем смо Нашу милост даровали и ономе што само Ми знамо, научили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, '„Могу ли да те пратим?“ Упита Мојсије, „али да ме подучиш ономе чему си ти исправно подучен.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, '„Ти сигурно нећеш моћи са мном да се стрпиш“, рече онај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, '„а и како би се стрпео у ономе о чему ништа не знаш?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, '„Видећеш да ћу да будем стрпљив, ако Аллах да!“ Рече Мојсије, „и да нећу ни у чему да ти се супротстављам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, '„Ако ћеш већ да ме пратиш“, рече онај, „онда ме ни о чему не питај док ти ја о томе први не кажем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'И њих двојица кренуше. И кад се у лађу укрцаше, он је пробуши. Мојсије рече: „Зар је пробуши да потопиш оне који на њој плове? Учинио си нешто, заиста, крупно.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, '„Не рекох ли ја“, рече онај, „да ти, заиста, нећеш моћи да се стрпиш са мном?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, '„Не замерај ми што сам заборавио“, рече, „и не отежавај ми.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'И њих двојица кренуше. И кад сретоше једног дечака па га онај уби, Мојсије рече: „Зашто уби безгрешно дете, које није никога убило! Учинио си, заиста, нешто врло ружно.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, '„Не рекох ли ја теби“, рече он, „да ти, заиста, нећеш моћи да се стрпиш са мном.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, '“Ако те и после овог за било шта упитам”, рече, “онда се немој са мном дружити. То је моје обећање!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'И њих двојица кренуше; и кад дођоше до једног града, замолише његове становнике да их нахране, али они одбише да их угосте. У граду њих двојица наиђоше на један зид који само што се није срушио, па га онај презида и усправи. „Могао си“, рече Мојсије, „за њега да узмеш награду.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, '“Сад се растајемо ја и ти”, рече он, “па да ти објасним због чега ниси могао да се стрпиш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'Што се тиче оне лађе, она је припадала сиромасима који раде на мору, и ја сам хтео да је оштетим, јер је пред њима био један владар који је сваку исправну лађу отимао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Што се тиче оног дечака, његови родитељи су били верници; побојали смо се да их не наведе на непослушност и неверовање,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'па смо хтели да им њихов Господар, уместо њега, да бољег и честитијег, и милостивијег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'А што се тиче онога зида, то је био зид двојице дечака, сирочади из града, а под њим је закопано њихово благо. Њихов отац је био добар човек и твој Господар жели, из Своје милости, да они одрасту и изваде своје благо. Све то ја нисам урадио по своме нахођењу. Ето то је тумачење онога за шта ниси могао да се стрпиш.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'И питају те о Зулкарнејну. Реци: „Казаћу вам о њему неке вести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'Ми смо му дали власт на Земљи и омогућили смо му да изврши оно што жели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'И он је следио пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'Кад је стигао до места где Сунце залази, учини му се као да залази у један мутан извор и нађе у близини његовој један народ. “О Зулкарнејне,” рекосмо Ми, “или их казни или с њима лепо поступи!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, '“Оног ко остане незнанобожац”, рече, “казнићемо, а после ће се свом Господару вратити, па ће га и Он тешком муком мучити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'А оног ко буде веровао и добра дела чинио чека награда најлепша, и с њиме ћемо благо поступити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'И он настави даље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'И кад дође до места где Сунце излази, он нађе да оно излази изнад једног народа коме Ми нисмо дали да се од њега било чим заклони.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, 'Тако то би. А Ми обухватамо знањем све што је он поседовао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'И он опет настави.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'Кад стиже између две планине, нађе испред њих народ који је једва говор разумевао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, '„О Зулкарнејне“, рекоше они, „Гог и Магог чине неред по Земљи, па хоћеш ли да између нас и њих зид подигнеш, ми ћемо да те наградимо.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, '„Боље је оно што ми је мој Господар дао“, рече он. „Него, само помозите ви мени што више можете, и ја ћу између вас и њих преграду да подигнем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Донесите ми велике комаде гвожђа.“ И кад он изравна две стране брда, рече: „Распалите ватру!“ А кад га усија, рече: „Донесите ми растопљени бакар да га залијем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, 'И тако они нису могли ни да га пређу нити су могли да га прокопају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, '„Ово је благодат Господара мога!“ Рече он. „А кад се претња мога Господара испуни, Он ће са земљом да је сравни, а обећање мога Господара ће сигурно да се испуни.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'И Ми ћемо тада да оставимо да се једни од њих као таласи сударају са другима. И дувнуће се у рог, па ћемо све да их скупимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'Тог дана ћемо јасно да покажемо неверницима Пакао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, 'онима чије су очи биле копреном застрте, да о доказима Мојим размисле, онима који нису хтели ништа да чују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Зар неверници мисле да поред Мене за божанства могу да узимају Моја створења?! Ми смо, заиста, неверницима Пакао као место боравка припремили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, 'Реци: “Хоћете ли да вам кажем чија дела неће никако призната бити?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Чији ће труд у животу на овом свету да буде узалудан, а који ће да мисле да је добро оно што раде?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'То су они који у речи и доказе свога Господара не буду веровали и који буду порицали да ће пред Њим да изађу; због тога ће труд њихов да буде узалудан и они на Судњем дану неће имати никакву вредност.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Њима ће казна да буде Пакао, зато што су били неверници и што су се Мојим речима и Мојим посланицима исмејавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'Онима који буду веровали и добра дела чинили припадају најузвишенији степени у Рају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'вечно ће да бораве у њему и неће да пожеле да га нечим другим замене.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'Реци: „Када би море било мастило да се испишу речи мога Господара, море би пресушило, али не и речи мога Господара, па и кад бисмо га проширили морем попут њега.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'Реци: „Ја (Мухаммед) сам човек као и ви, мени се објављује да је ваш Бог - један Бог. Па ко се нада сусрету са својим Господаром, нека ради добра дела и нека поред свог Господара никога не обожава!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Каф-ха-ја-ајн-сад.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, 'Ово је спомен о милости твога Господара према Његовом слуги Захарији,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'кад је он свога Господара тихо замолио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'и рекао: „Господару мој, кости су ми оронуле и глава оседела, а никада нисам, кад сам Ти, мој Господару, молбу упутио, остао разочаран.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, 'Бојим се мојих рођака по крви после мене, а жена ми је нероткиња, зато ми поклони сина наследника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, 'да наследи мене и породицу Јаковљеву, и учини га таквим, Господару мој, да будеш задовољан њиме.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, '„О Захарија, јављамо ти радосну вест да ће ти се родити дечак, име ће да му буде Јахја (Јован), ником пре њега то име нисмо хтели да дамо.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, '„Господару мој“, рече он, „како ћу да имам сина кад ми је жена нероткиња, а већ сам доживео дубоку старост?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, '„Ето тако“, рече. Твој Господар је рекао: „То је мени лако, и тебе сам раније створио, а ниси ништа био.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, '„Господару мој“, рече, „дај ми неки знак.“ „Знак ће да ти буде то што три ноћи нећеш моћи са људима да разговараш, а здрав ћеш да будеш.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'И он изађе из храма у народ свој и знаком им је дао на знање: “Славите Га ујутру и навече!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, '„Јоване, прихвати Књигу одлучно!“ А дали смо му мудрост још док је био дечак,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'и нежност и чедност, и богобојазан је био,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'и родитељима својим је био послушан, и није био дрзак и непослушан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Нека су мир и спас над њим на дан кад се родио и на дан кад је умро и на дан кад буде из мртвих устао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'И спомени из Књиге Марију: када се од укућана својих повукла на источну страну,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'и од њих узела заклон, Ми смо ка њој послали Нашег анђела и он јој се показао у потпуном људском облику.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, '„Тражим заштиту Свемилосног од тебе, ако се Њега бојиш!“ Узвикну она.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, '„А ја сам управо изасланик твога Господара“, рече он, „да ти поклоним честитог дечака!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, '„Како ћу да имам дечака?“ Рече она, „кад ме ниједан мушкарац није додирнуо, а ја нисам блудница.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, 'А он рече: „Ето тако, Господар твој је казао: ''То је Мени лако, и зато да га учинимо да буде знак људима и знак наше милости.'' Тако је унапред одређено.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'И она занесе и бременита се склони негде далеко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'И порођајни болови присилише је да дође до стабла једне палме. „Камо среће да сам раније умрла и да сам потпуно у заборав пала!“ Узвикну она.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'И он је испод ње зовну: „Не жалости се, твој Господар је дао да ниже тебе потече поток.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, 'Затреси палмино стабло, посуће по теби свеже урме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'па једи и пиј и буди весела! А ако видиш неког човека, ти реци: ''Ја сам се заветовала Свемилосном да ћу да ћутим, и данас ни са ким нећу да говорим.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'И дође она са њим своме народу, носећи га. „О Марија!“ Рекоше они, „учинила си нешто нечувено!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'Хеј ти, која личиш на Арона, отац ти није био неваљао, а ни мајка твоја није била блудница!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, 'Она им показа на Исуса. „Како да говоримо са бебом у колевци?“ Рекоше они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, '„Ја сам Аллахов слуга“, рече он, „мени ће Он Књигу да подари и веровесником да ме учини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'и учиниће ме, где год будем, благословљеним, и наредиће ми да док год сам жив, обављам молитву и да удељујем милостињу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'и да мајци својој будем добар, а неће ми допустити да будем дрзак и непристојан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'И нека је мир нада мном на дан када сам се родио и на дан када будем умро и на дан кад будем проживљен из мртвих.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, 'То је Исус, Маријин син, то је права истина о њему, онај у кога они сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Незамисливо је да Аллах има дете, Узвишен је Он! Кад нешто одреди, Он за то само каже: „Буди!“- И оно буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, 'И рече: " И Аллах је, уистину, и мој и ваш Господар, зато обожавајте само Њега! То је Прави пут."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'И следбеници Књиге су се у погледу њега подвојили, па тешко онима који не верују када на Дану великом буду присутни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Како ће добро чути и како ће добро видети оног Дана кад пред Нас стану! А неверници су сад у очитој заблуди!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'И упозори их на Судњи дан кад ће бити с полагањем рачуна завршено, а они су немарни били и нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Ми ћемо Земљу и оне који живе на њој да наследимо и Нама ће они да се врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'И спомени из Књиге Аврама! Он је био истинољубив, веровесник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, 'Када је рекао своме оцу: „О оче мој, зашто обожаваш оно што нити чује нити види, нити може да ти буде од какве користи?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, 'О оче мој, објављује ми се знање које ти не знаш; зато ме следи, па ћу те ја упутити на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'Оче мој, не обожавај Сотону, Сотона је Свемилосном увек непокоран;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'оче мој, бојим се да те од Свемилосног не стигне казна, па да будеш Сотони друг.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, 'Његов отац рече: „Зар си ти против мојих божанстава, о Авраме? Ако се не оканиш, заиста ћу те каменовати, зато ме заувек напусти.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, '„Мир теби!“ Рече Аврам. „Молићу Господара свога да ти опрости, јер Он је врло добар према мени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, 'И напустићу и вас и све оне које мимо Аллаха обожавате, и само ћу своме Господару да се молим; Господар мој ме неће разочарати одбијањем моје молбе.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Пошто их је напустио и оне које су, мимо Аллаха, обожавали, Ми му даровасмо Исака и Јакова, и обојицу веровесницима учинисмо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'и даровасмо им Нашу милост и учинисмо да буду хваљени и по добру спомињани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'И спомени из Књиге Мојсија! Он је био одабран и био је посланик, веровесник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Ми смо га позвали са десне стране Синаја и приближили смо га Себи да чује Наше речи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'и даровали смо му, из Наше милости, као веровесника његовог брата Арона.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'И спомени из Књиге Јишмаила! Он је испуњавао дато обећање и био је посланик, веровесник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'Наређивао је својој породици да обављају молитву, и да удељују милостињу, и Господар је био њиме задовољан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'И спомени из Књиге Идриза (Хенока)! Он је био истинољубив, веровесник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'и Ми смо га уздигли на високо место.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'То су веровесници које је Аллах обасуо благодатима, од Адамових потомака и оних које смо са Нојем на лађи спасили, и Аврамових и Јаковљевих потомака, и оних које смо упутили и одабрали. Кад би им се училе речи Свемилосног, они би ничице падали и плакали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'А њих сменише зли потомци, који молитву напустише и за пожудама пођоше – они ће сигурно зло проћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Али они који су се покајали, и веровали, и радили добра дела, њима се неће никаква неправда учинити, и они ће у Рај ући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'У еденским вртовима које је Свемилосни Својим верницима обећао иако их нису видели – а обећање Његово ће заиста да се испуни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'У њима празне приче неће да слушају, већ само: „Мир Божји!“ - И у њима ће ујутру и навече да буду опскрбљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'Даћемо да такав Рај наследи сваки Наш богобојазни слуга.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, '„А ми анђели силазимо само по наредби твога Господара. Њему припада оно што је пред нама и оно што је за нама, и што је између тога. А твој Господар ништа не заборавља.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, 'Он је Господар небеса и Земље и онога што је између њих, зато само Њега обожавај и у томе буди устрајан! Знаш ли да има неко Њему сличан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'Човек говори: „Зар ћу, кад умрем, заиста да будем проживљен?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'А зар се човек не сећа да смо га још пре створили, а да није био ништа?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'Кунем се Собом, да ћемо да скупимо и невернике и ђаволе, затим ћемо да их доведемо да клече на коленима око Пакла,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'а онда ћемо из сваке групе да издвојимо оне који су према Свемилосном били најдрскији,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'јер Ми најбоље знамо оне који су највише заслужили да у њој горе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'И сваки од вас ће до Пакла да стигне! Твој Господар се сигурно тако обавезао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'Затим ћемо да спасимо оне који су се бојали Аллаха и клонили греха, а невернике ћемо да оставимо у њему на коленима да клече.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Када су им се Наше јасне речи казивале, онда су неверници говорили верницима: “Шта мислите, ко је у бољем положају и ко има више поборника?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'А колико смо Ми пре њих народа уништили који су благом и изгледом дивљење изазивали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'Реци: „Ономе ко је у заблуди, нека Свемилосни дуг живот да!“ Али кад такви доживе да се претње остваре, било казна, било Смак света, заиста ће да сазнају ко је у горем положају и ко има слабију војску и помагаче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'А Аллах ће помоћи онима који су на Правом путу! А добра дела која вечно остају – од Господара твог биће боље награђена и лепше узвраћена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'Зар ниси видео онога који у Наше речи и доказе не верује и говори: „Засигурно ће ми бити дато богаство и деца!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Или је он будућност прозрео или је од Милостивог обећање примио?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'Ниједно! Ми ћемо да запишемо оно што он говори и патњу ћемо знатно да му продужимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'а оно о чему он говори - наследићемо и сам лично ће да Нам се врати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Они, уместо Аллаха, узимају лажна божанства тражећи од њих помоћ и славу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Напротив! Божанства ће да порекну њихово обожавање, и биће им противници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Зар не видиш да Ми невернике ђаволима препуштамо да их што више на зло навраћају?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Зато не тражи да што пре буду кажњени, Ми им полако одбројавамо дане.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'На Дан када богобојазне, као делегацију, пред Свемилосним сакупимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'а кад у Пакао потерамо жедне невернике,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'нико се неће моћи ни за кога заузимати, осим онај коме Милостиви то допусти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, 'Они говоре: „Свемилосни је узео дете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Ви, заиста, говорите нешто страшно и гнусно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, 'Готово да се од тога небеса распадну, а Земља провали и планине здробе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'јер Свемилосном приписују дете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'Незамисливо је да Свемилосни има дете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Па, сви ће они, и они на небесима и они на Земљи, да дођу Свемилосном као слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'Он их је све знањем обухватио и зна колико их има,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'и сви ће Му на Судњем дану појединачно доћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'Оне који верују и раде добра дела Свемилосни ће вољеним учинити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Ми смо Кур''ан учинили лаким, на твоме језику, да би њиме обрадовао богобојазне, а упозорио пркосне грешнике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'А колико смо само народа пре њих уништили! Да ли иједног од њих видиш и да ли и најслабији глас њихов чујеш?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Та-ха.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, 'Не објављујемо ти Кур''ан да би туговао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'већ да буде опомена ономе који се Аллаха боји;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, 'објављује га Створитељ Земље и небеса високих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Свемилосни, Који се узвисио над Престољем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'Њему припада све што је на небесима и на Земљи и све што је између њих и све што је под земљом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'И кад гласно говориш – знај да Он зна и шта другом тајно говориш и шта само помислиш!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Аллах, истинског бога осим Њега нема, најлепша имена има.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'А да ли је до тебе дошла вест о Мојсију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'када је ватру угледао, па својој породици казао: „Сачекајте ме овде, видео сам ватру, отићи ћу до ње да вам можда донесем некакву потпалу или ћу поред ватре да нађем некога ко ће да ми покаже пут.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'А када до ње дође, неко га позва: „О Мојсије,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, 'Ја сам, уистину, твој Господар! Изуј своју обућу, јер ти си, заиста, у благословљеној долини Тува.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Тебе сам изабрао, зато слушај оно што ти се објављује!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Ја сам, уистину, Аллах, другог истинског бога осим Мене нема; зато само Мене обожавај и молитву обављај да би Ме у њој славио!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Час оживљења сигурно ће да дође, од сваког га кријем, како би сваки човек према труду своме био награђен или кажњен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, 'И нека те зато од веровања у Судњи дан никако не одврати онај који у њега не верује и који следи своју страст, па да настрадаш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'А шта ти је то у десној руци, о Мојсије?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, '„Ово је мој штап“, одговори он, „којим се поштапам и којим лишће својим овцама скидам, а служи ми и за друге потребе.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, '„Баци га, о Мојсије!“ Рече Он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'И он га баци, кад он, змија која гмиже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, '“Узми је и не бој се!“ Рече Он, „Ми ћемо да је вратимо у оно што је пре била.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'И увуци руку под свој пазух, рука ће да се укаже бела, без икакве мане; и то је знамење друго,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'како би ти показали неке Наше највеће знаке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Иди код фараона, јер је у злу сваку меру превршио!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, '„Мој Господару“, рече Мојсије, „учини пространим моја прса,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'и олакшај мој задатак:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'одреши чвор са мог језика', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'да би разумели мој говор', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'и подари ми помоћника из моје породице,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'Арона мог брата;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'учврсти ме њиме', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'и придружи ми га у мом задатку', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'да бисмо Те много величали и славили', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'и Твоје име много спомињали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Јер нас Ти, уистину, видиш.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, '„Удовољено је твојој молби, о Мојсије“, рече Он,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, '„а указали смо ти милост Своју још једном,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'када смо твоју мајку надахнули оним што се само надахнућем постиже:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, 'Стави га у сандук и спусти у реку, река ће на обалу да га избаци, па ће га Мој и његов непријатељ прихватити.'' И Ја сам учинио да те свако воли и да растеш под оком Мојим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, 'Када је твоја сестра отишла и казала: ''Хоћете ли да вам покажем жену која ће да се брине о њему? Ми смо те твојој мајци опет вратили да се радује и да више не тугује. И кад си убио човека, па смо те Ми ослободили бриге и из разних невоља смо те спасили. И ти си остао годинама међу становницима Медена, затим си, о Мојсије, у одређено време дошао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'и изабрао сам те за Свог посланика', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Идите ти и брат твој, с доказима Мојим, и нека сам вам Ја увек на памети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Идите код фараона, јер је он, заиста, претерао у неправди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'И обратите му се благим речима, како би размислио или се побојао.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, '„Господару наш“, рекоше они, „бојимо се да нас одмах не казни или да истину одбије."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, '“Не бојте се!”, рече Он, “Ја сам с вама, Ја све чујем и видим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Идите ка њему и реците: „Ми смо посланици твога Господара, пусти Израиљеве синове да иду са нама и немој да их мучиш! Донели смо ти знак од твога Господара, па нека је спас ономе ко следи Упуту!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, 'Нама се објављује да ће, сигурно, стићи казна оног који не поверује и од истине главу окрене.’”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, '„Па ко је ваш Господар, о Мојсије?“ Упита фараон.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, '“Господар наш је Онај Који је свему оном што је створио дао оно што му је потребно, затим га како да се тиме користи надахнуо.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, '„А шта је са претходним народима?“ Упитао је он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, '„Знање о њима је код мога Господара, у Књизи!“ Рече Мојсије, „Моме Господару није ништа скривено и Он не заборавља.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, 'Онај Који вам је Земљу прилагодио и по њој вам пролазе дао, и Он спушта кишу са неба, па Ми дајемо да уз њену помоћ у паровима ниче разноврсно биље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, 'Једите и напасајте своју стоку! Ту су докази за оне који имају памети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Од земље вас стварамо и у њу вас враћамо и из ње ћемо да вас проживимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'И Ми смо фараону све Наше доказе показали, али је он ипак порекао и одбио да поверује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, '„Зар си дошао да нас помоћу своје враџбине из земље наше истераш, о Мојсије?“ Упита фараон.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, '„И ми ћемо, заиста, теби да припремимо враџбину сличну овој! Закажи нам време састанка којег ћемо се и ми и ти придржавати, на месту које свима одговара!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, '„Нека време сусрета буде на дан вашег празника“, рече Мојсије, „и нека се народ ујутру сакупи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'И фараон оде, сакупи своје чаробњаке и после дође.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, '„Тешко вама!“ Рече им Мојсије. „Не износите лажи о Аллаху, па да вас Он казном уништи, а сигурно неће да успе онај који износи лажи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'И они су стали да се расправљају међу собом, тихо шапћући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, '„Мојсије и Арон су чаробњаци“, рекоше једни другима, „хоће да вас својим враџбинама истерају из ваше земље и да униште вашу најчаснију веру;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'зато паметно припремите своје лукавство, а онда у ред станите. Ко данас победи, сигурно ће да постигне оно што жели.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, '„О Мојсије“, рекоше они, „хоћеш ли ти први да бациш свој штап или ћемо ми бацити своје конопце?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, '„Баците ви!“, рече он, и одједном му се причини да се њихови канапи и њихови штапови крећу због њихове враџбине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'И Мојсије осети зебњу у себи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, '„Не бој се!“ Рекосмо Ми, „ти ћеш, заиста, да победиш!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, 'Баци штап, који је у твојој десној руци, прогутаће оно што су они направили, јер је оно што су они направили само варка чаробњака, а чаробњак, ма где био, неће успети."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, 'И чаробњаци се поклонише лицем на тло говорећи: „Ми верујемо у Ароновог и Мојсијевог Господара!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, '„Ви сте му поверовали“, викну фараон, „пре него што сам вам ја допустио! Он је ваш учитељ, он вас је научио враџбини и ја ћу, засигурно, унакрст ваше руке и ноге да вам одсечем и по стаблима палми да вас разапнем и сигурно ћете да знате ко је од нас у мучењу страшнији и устрајнији.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, '„Нећемо ти дати предност над јасним доказима који су нам дошли нити над нашим Створитељем“, одговорише они, „па ради шта хоћеш, то можеш само у овосветском животу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, 'Ми верујемо у нашег Господара да би нам наше грехе опростио и враџбине на које си нас ти приморао. А Аллах најбоље награђује и казна Његова је вечна.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Заиста, онога који пред својим Господарем дође као неверник - чека Пакао; у њему неће ни да умре ни да живи;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'а оне који пред Њим дођу као верници, а радили су добра дела, чекају високи степени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'еденски вртови кроз које теку реке, у њима ће они вечно да остану, и то ће да буде награда за оне који се буду греха очистили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'И Ми објависмо Мојсију: „Ноћу изведи Моје слуге и с њима сувим путем кроз море прођи, и не страхуј да ће те они стићи, нити се плаши утапања.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'И фараон је са својим војскама за њима кренуо, па су их огромни таласи мора прекрили;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'И фараон је одвео свој народ у заблуду, а није га упутио на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'О Израиљеви синови, Ми смо вас избавили од вашег непријатеља, и на десној страни Синаја вас довели, и дали вам пиће као мед слатко и препелице укусне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, 'Једите укусна јела којима вас опскрбљујемо и не будите у томе незахвални да вас не би снашла Моја срџба; а кога снађе Моја срџба - настрадао је!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'Ја ћу сигурно да опростим ономе ко се покаје и буде верник и ради добра дела, а затим устраје на Правом путу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, '„А зашто си пре народа свог пожурио, о Мојсије?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, '„Ево иду за мном“, одговори он, „а пожурио сам ка Теби, мој Господару, да будеш задовољан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, '„Ми смо твој народ, после твог одласка, ставили на искушење“, рече Он, „и њих је завео Самирија.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'И Мојсије се своме народу врати љут и жалостан. „О мој народе“, рече, „зар вам ваш Господар није дао лепо обећање? Зар вам се време одужило, или хоћете да вас стигне срџба вашега Господара, па се зато нисте држали обећања које сте ми дали?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, '„Нисмо својевољно прекршили обећање које смо ти дали“, одговорише. „Били смо натоварени теретима, накитом фараоновог народа, па смо то бацили.“ А то је урадио и Самирија,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'па им је излио теле које као да је мукало, и они су тада рекли: „Ово је ваш бог и Мојсијев бог, којег је заборавио.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Зар они нису видели да им оно ни речи не одговара и да од њих не може да отклони никакву невољу нити може икакву корист да им прибави?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'А њима је Арон још пре говорио: „О народе мој, ви сте тиме само стављени у искушење; ваш Господар је Свемилосни, зато следите мене и слушајте моја упуства.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, '„Ми ћемо да га обожавамо све док нам се не врати Мојсије,“ рекоше они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, '„О Ароне!“ Повика Мојсије. „Шта те је спречило, кад си их видео да су залутали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'па за мном ниси пошао? Зашто ниси послушао моје наређење?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, '„Брате мој“, рече Арон, „не хватај ме за браду и за косу! Ја сам се плашио да не кажеш: ''Раздор си међу Изриљевим синовима посејао и ниси поступио онако како сам ти рекао.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, '„А шта си ти то хтео, о Самирија?“ Упита Мојсије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, '„Ја сам видео оно што они нису видели“, одговори он, „а затим сам за анђелом узео шаку земље, па то после бацио, и ето, тако ме је моја зла душа навела на зло.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, '“Губи се одавде!” Рече Мојсије. “Читавог свог живота говорићеш: ‘Нека ме нико не дотиче!’ – А чека те још и одређени час који те неће мимоићи. Погледај само ово твоје божанство које си обожавао; ми ћемо га, сигурно, спалити и по мору му прах расути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Ваш Бог је Аллах, другог истинског бога осим Њега нема! Он све зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'Тако ти казујемо неке вести о онима који су били и нестали, и објављујемо ти од Себе Кур’ан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Ко се окрене од Кур''ана, на Судњем дану ће, заиста, огромни грех да понесе;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'вечно ће у казни да остану, а језив терет ће на Судњем дану да носе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'На Дан када ће анђео у рог да дувне - тога Дана ћемо да сакупимо невернике од страха модре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'и један другом ће тихо да говоре: „Нисте на Земљи боравили више од десет дана.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Ми добро знамо о чему ће они да говоре кад најразборитији међу њима каже: „Остали сте само један дан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'А питају те о планинама, па ти реци: “Господар мој ће их у прах претворити и разасути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, 'а места на којима су биле да остави равном ледином,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'ни удубине ни узвисине на Земљи нећеш да видиш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'Тог дана ће они да се одазову гласнику, мораће да га следе и пред Свемилосним ће да се стишају гласови и ти ћеш само да чујеш шапат.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'Тог дана ником неће да буде од користи заузимање осим ономе коме Свемилосни допусти да се за неког заузме.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'Он зна шта су радили и шта их чека, а они знањем не могу Њега да обухвате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Људи ће се Живом и Вечном покорити, а настрадаће онај који је друге поред Аллаха обожавао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'а онај ко је добра дела чинио, а верник био, неће се неправде ни закидања награде плашити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'И Ми тако Кур’ан на арапском језику објављујемо и у њему опомене понављамо да би се они греха клонили или да би их на послушност подстакао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'Нека је узвишен Аллах, Владар Истинити! И не жури са читањем Кур''ана пре него што ти се његово објављивање заврши, и реци: „Господару мој, Ти моје знање повећај!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'А Адаму смо одмах у почетку наредили, али он је заборавио и није одлучан био.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'А кад смо казали анђелима: „Поклоните се Адаму!“ Они сви ничице падоше, осим Сотоне који је то одбио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, '„О Адаме!“ Рекли смо, „овај је заиста непријатељ теби и твојој жени, зато никако не дозволи да због њега будете истерани из Раја, па да се онда мучиш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'У Рају нећеш никад огладнити нити го бити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'нити ћеш у њему ожеднити, нити врелину осетити.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'Али Сотона поче да га наговара и говори: „О Адаме, хоћеш ли да ти покажем дрво бесмртности и царство које неће да нестане?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'И њих двоје поједоше са дрвета и указаше им се њихова стидна места па почеше да стављају по њима рајско лишће. Адам није свога Господара послушао, па је скренуо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'После га је његов Господар изабраником учинио, и опростио му је, и на Прави пут упутио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, '„Напустите Рај сви“, рече Аллах, „једни другима ћете да будете непријатељи! Од Мене ће да вам долази Упута, и онај ко буде следио Моју Упуту неће да залута и неће да буде несрећан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'А онај ко се окрене од Моје Опомене, тај ће да живи тешким животом и на Судњем дану ћемо да га проживимо слепим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, '„Господару мој“, рећи ће, „зашто си ме слепог проживео кад сам имао вид?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, '„Ево зашто“, рећи ће Он. „Наше речи и докази су ти долазили, али си их занемаривао, па ћеш данас тако и ти да будеш занемарен.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'И тако ћемо Ми да казнимо све оне који су у греху претеривали, и у речи и доказе свога Господара нису веровали. А патња на Будућем свету биће, уистину, болнија и вечна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Зар њима није познато колико смо уништили народа пре њих, оних по чијим селима и градовима се они крећу! То су, заиста, поуке за разумне људе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'И да није реч твог Господара још пре одређена, стигла би их заслужена казна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Зато отрпи њихове увреде и обављај молитву, славећи Господара свог, пре изласка и пре заласка Сунца, и обављај је у ноћним сатима, и на крајевима дана – да би постигао задовољство.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'И никако не жуди за лепотама овог света које Ми као ужитак разним неверницима пружамо, да их тиме на кушњу ставимо, награда Господара твог је боља и вечна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Нареди породици својој да молитву обављају и буди у томе стрпљив и устрајан! Ми не тражимо од тебе да сам себе опскрбљујеш, Ми ћемо те опскрбити! А само богобојазнима припада леп завршетак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Незнанобошци говоре: “Зашто нам не донесе какво чудо од Господара свог?” А зар им не долази објашњење о оном што има у давнашњим објавама?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'А да смо их каквом казном уништили пре њега, сигурно би казали: „Господару наш, зашто нам ниси послао посланика, па да следимо Твоју Објаву пре него што смо понижени и осрамоћени у Паклу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, 'Реци: „Сви ишчекујемо, па ишчекујте и ви, а сигурно ћете сазнати ко су били следбеници праве вере и ко је био на Правом путу.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'Људима се ближи њихово полагања рачуна, а они, немарни, окрећу се од истине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'И не дође им ниједна нова опомена од Господара њиховог којој се, слушајући је, не подсмехују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'немарних срца. И тихо рекоше незнанобожци: „Да ли је овај нешто друго до човек као и ви?! Зар ћете да се предате враџбини, а видите да то јесте?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, '“Господар мој зна”, рече он, “шта се говори и на небу и на Земљи. Он све чује и све зна!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Они, чак, говоре: “То је само кошмар! Он га измишља! Он је песник! Нека нам донесе какво чудо као и претходни посланици!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Ниједно насеље које смо Ми уништили пре њих није у чудо поверовало, па зар ће они да поверују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'И пре тебе смо само људе као посланике слали и објављивали смо им, зато питајте следбенике Књиге, ако ви не знате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Ми их нисмо створили као бића која живе без хране, нити су били бесмртни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Затим би им обећање испуњавали, и њих, и оне које смо хтели спашавали, а невернике уништавали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Ми вам Књигу објављујемо у којој је слава ваша, па зашто се не опаметите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, 'А колико смо само уништили насеља која су била незнанобожачка и после којих би друге народе довели!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'И када би казну нашу предосетили, из домова својих би се разбежали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, '„Не бежите сад, и вратите се вашим уживањима и вашим домовима, можда ће вас неко шта упитати.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, '“Тешко нама”, они би говорили, “ми смо, заиста, неверници били!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, 'И кукали би тако све док их не бисмо учинили, као жито пожњевено, непомичним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Ми нисмо створили небо и Земљу и оно што је између њих да се забављамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Да смо хтели да се забављамо, забављали бисмо се онако како Нама доликује, али Ми то не чинимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Него истином сузбијамо лаж, истина је угуши и лажи нестане – а тешко вама због лажи које о Њему износите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'Његово је оно што је на небесима и на Земљи! А они који су код Њега не зазиру да Га обожавају, нити им то досади,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'славе Га ноћу и дању, не малаксавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Зар божанства која они од земље праве могу да оживе мртве?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Да на Земљи и небесима уистину постоје божанства поред Аллаха, пореметила би се. Па нека је слављен и узвишен Аллах, Господар Престола, од оног како Га описују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'Он неће бити питан за Своје поступке, а они ће бити питани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Зар да они уместо Њега узимају богове!? Реци: “Дајте ваш доказ! У овом Кур''ану и књигама пре мене објављеним немате доказ.” Али већина њих не зна истину, па је зато не прихватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, 'Пре тебе нисмо послали ниједног посланика, а да му нисмо објавили: „Нема истинског бога осим Мене, зато само Мене обожавај!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Они говоре: „Свемилосни има дете!“, Узвишен и слављен је Он! А анђели су само слуге поштоване!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Они не говоре док то Он не одобри и поступају онако како Он нареди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'Он зна шта су радили и шта ће да ураде, и они се заузимају само за оног са којим је Он задовољан, а и сами су, из страхопоштовања према Њему, богобојазни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'А ако би неки од њих казао: „Ја сам, поред Њега, такође бог!“ Казнили бисмо га Паклом, јер Ми тако кажњавамо незнанобошце.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Зар не знају неверници да су небеса и Земља били једна целина, па смо их Ми раздвојили, и да Ми од воде све живо стварамо?! И зар неће да верују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'Ми смо на Земљи створили стабилне планине да их она не потресе, и по њима смо учинили пролазе и стазе да би они стизали куда желе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'И створио је сигурни небески свод, а они се ипак окрећу од доказа која су на њему.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'И ноћ и дан Његово су дело, и Сунце и Месец, и сви они у свемиру плове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, 'И Ми нисмо ниједном човеку пре тебе дали вечност; ако ти умреш, зар ће они довека да живе?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Свако живо биће смрт ће да окуси! Ми вас стављамо на искушење и у добру и у злу, и Нама ћете да се вратите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Када те неверници угледају, само ти се исмејавају: „Је ли то онај који хули ваша божанства?“ А они сами, кад се спомене Свемилосни, не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'Човек је створен по природи нестрпљив. Показаћу Ја вама, заиста, доказе Своје, зато Ме не пожурујте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, 'Они говоре: „Када ће већ једном та претња да се оствари, ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'А кад би неверници само знали да тада неће моћи да отклоне ватру од својих лица и својих леђа, и да нико неће моћи да им пружи помоћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Напротив, казна ће изненада да им дође и они неће моћи да је отклоне, и неће им се дати прилика за покајање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Посланицима су се и пре тебе исмејавали, па је оне који су им се исмејавали стигла казна којој су се исмејавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'Реци: „Ко ће вас, ноћу и дању, заштитити од казне Свемилосног?!“ Па, ипак, се они од Објаве свога Господара окрећу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Зар ће их њихова божанства од наше казне одбранити? Па она сама себи не могу да помогну, и нико невернике од Наше казне не може да сачува!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Ми смо неверницима, а и њиховим прецима, дали да уживају тако да им се живот у томе одужио. А зар они не виде да Ми Земљу са њених крајева умањујемо, па како да они буду победници?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, 'Реци: „Ја вас упозоравам Објавом!“ Али, глуви не чују позив када се упозоравају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'А када би их дотакнуо само мали део казне твога Господара, сигурно би повикали: „Тешко нама, заиста смо били неправедни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'И на Судњем дану ћемо поставити тачне ваге за вагање дела, па никоме се неће учинити неправда. А ако дело буде тешко колико зрно горушице, нећемо га занемарити. А довољно је то што ћемо Ми рачуне испитивати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Ми смо Мојсију и Арону дали оно што раставља Истину од неистине, светло и опомену за богобојазне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, 'за оне који се Господара свог боје и кад их нико не види, и који се брину због Часа проживљења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Овај Кур’ан је благословљена поука коју објављујемо, па зар да га ви поричете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Ми смо још пре Авраму дали разборитост и добро смо га познавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Кад он своме оцу и своме народу рече: „Какви су ово кипови које тако предано обожавате?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, 'Они одговорише: „Затекли смо наше претке како их обожавају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, 'Аврам рече: "Заиста сте ви, а и преци ваши, у очигледној заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, '„Говориш ли ти то озбиљно или се само шалиш?“ Упиташе они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, '“Не!” Рече. “Господар ваш је Господар небеса и Земље, Он је њих створио, и ја ћу вам то доказати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, 'И нечујно рече: "Тако ми Аллаха, ја ћу, чим се удаљите, вашим идолима сплетку учинити!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'И поразбија их он у комаде, осим оног највећег, да би се њему обратили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, '„Ко уради ово са нашим боговима?“ Повикаше они, „заиста је насилник.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, '„Чули смо једног момка како их хули“, рекоше, „име му је Аврам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, '„Доведите га пред народ“, рекоше, „да људи посведоче.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, '„Јеси ли ти урадио ово са нашим боговима, о Авраме?“ Упиташе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, '„То је учинио овај највећи међу њима; питајте их ако могу да говоре“, рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'И они схватише, па сами себи рекоше: “Ви сте, заиста, неправедни!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Затим се на своје вратише: „Ти знаш да ови не говоре!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, '„Па зашто онда, уместо Аллаха, обожавате оне који не могу ни да вам користе нити могу од вас какву штету да отклоне?“ Упита он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, '„Тешко вама и онима које, уместо Аллаха, обожавате! Зашто се не опаметите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, '“Спалите га и богове ваше осветите, ако хоћете ишта да учините!” Повикаше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, '„О ватро!“ Рекосмо Ми, „буди хладна, и спас Авраму!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'И хтели су да му поставе сплетку, али их Ми учинисмо највећим губитницима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'И спасили смо њега и Лота и послали их у земљу коју смо за људе благословили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'и поклонили смо му Исака, и још Јакова као унука и све учинисмо честитим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'И учинили смо их веровесницима да упућују према Нашој заповеди, и објавили смо им да раде добра дела, и да обављају молитву, и да удељују милостињу, и само су Нас обожавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'И Лоту мудрост и знање смо дали и из града га, у ком су становници његови одвратне ствари чинили, избавили – то је, уистину, био народ развратан и зао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'и у Нашу милост смо га увели; он је, заиста, од оних добрих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'И спомени Ноја - кад је још давно завапио, па смо Му се одазвали, и њега и његову породицу од јада великог спасили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'и заштитили смо га од народа који је сматрао Наше речи и доказе неистинитим. То су били опаки људи, па смо их све потопили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'И спомени Давида и Соломона, када су судили о усеву којег су по ноћи нечије овце опасле, и Ми смо били сведоци њиховом суђењу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'и учинили смо да Соломон проникне у то, а обојици смо дали мудрост и знање. И потчинили смо планине и птице да са Давидом Аллаха славе и величају: све то Ми смо учинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'И научили смо га да израђује панцире за вас да вас штите у борби са непријатељем, па зашто нисте захвални?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'А Соломону смо јак ветар послушним учинили, по његовој заповеди је дувао према земљи коју смо благословили; и Ми све добро знамо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'и потчинио му је неке ђаволе да због њега роне, а радили су и друге послове, и над њима смо Ми бдели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'И спомени Јова, када је своме Господару завапио: „Мене је снашла невоља, а Ти си од милостивих најмилостивији.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'И Ми смо му се одазвали и отклонили невољу која га је мучила и вратили смо му, милошћу Нашом, његову породицу, и уз њих још толико, и да буде узор онима који су Нама покорни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'И спомени Јишмаела, и Еноха, и Језекиља, а сви су они били стрпљиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'И увели смо их у окриље Наше милости, они су заиста били добри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'Јону кад срдит оде и помисли да га нећемо казнити – па после у тминама завапи: “Нема бога, осим Тебе, хваљен нека си, а ја сам се заиста огрешио према себи!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Па смо му се одазвали и тегобе га спасили; ето тако Ми спашавамо вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'И спомени Захарија, када је позвао свога Господара: „Мој Господару, не остављај ме самог, Ти си једини вечан."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Одазвали смо му се и, излечивши му жену, Јована му поклонисмо. Они су се трудили да што више добра ураде и молили су Нам се у нади и страху, и били су према Нама понизни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'И спомени ону која је сачувала чедност - своје девичанство, па смо у њу удахнули живот, и њу и њеног сина смо учинили да буду свим световима знамење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Ова ваша вера – једина је права вера, а Ја сам ваш Господар, зато само Мене обожавајте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Људи су се, међутим, разишли и поделили у вери, а сви ће се Нама вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'Ко буде радио добра дела а притом је верник, труд му неће остати лишен награде, јер смо га Ми сигурно записали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'А немогуће је да се становници било којег насеља које смо Ми уништили поново врате на овај свет!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'И кад се ослободе Гог и Магог и кад се буду низ све стрмине журно спуштали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'и приближи се Истинита претња, тада ће погледи неверника да се укоче. „Тешко нама, ми смо према овоме били равнодушни, сами себи смо неправду учинили!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'И ви, и они које поред Аллаха обожавате, бићете гориво у Паклу, а у њему ћете сигурно да уђете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Да су они богови, не би у Пакао ушли, и сви ће у њему вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'У њему ће да уздишу пригушено, у њему ништа неће чути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'А они којима смо још пре обећали лепу награду, они ће да буду далеко од Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Његову буку неће да чују, и вечно ће да уживају у ономе што им буду душе желеле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, 'Неће осетити страх због највећег ужаса, него ће их анђели дочекивати: „Ево, ово је ваш Дан који вам је обећан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'На Дан кад смотамо небеса као што се смота лист папира за писање, онако како смо први пут из ништа створили, тако ћемо поново из ништа да створимо, то је Наше обећање, Ми ћемо, заиста, то да учинимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Ми смо у објавама, после Торе, написали да ће Земљу да наследе Моје честите слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'У овом је заиста поука за људе који буду само Аллаха обожавали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'а тебе смо послали само као милост световима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, 'Реци: „Мени се објављује да је ваш Бог један једини Бог, па хоћете ли му се предати?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'А ако они одбију, ти реци: „Ја сам вас све, без разлике, опоменуо, а не знам да ли је близу или далеко оно чиме вам се прети.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'Он зна шта гласно говорите и шта кријете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'а ја не знам, можда вам је то искушење, и препуштање световном уживању до одређеног времена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, '“Господару мој, пресуди онако како су заслужили!” Рече он. “А од Господара нашег, Милостивог, треба тражити помоћ против оног што ви износите.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'О људи, Господара свог се бојте! Заиста ће потрес, кад Смак света наступи, велики догађај бити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'Тада када угледате Судњи дан, заборавиће свака дојиља своје дете, а свака трудница ће свој плод да побаци и ти ћеш да видиш пијане људе, а они неће да буду пијани, него ће тако изгледати због страшне Аллахове казне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'А међу људима има ко расправља о Аллаху без знања, и следи сваког ђавола пркосног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'За кога је већ прописано да ће сваког оног ко га узме за заштитника да заведе на странпутицу и да га одведе у огњену патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'О људи! Ако сте у сумњи према проживљењу - па Ми смо вас, заиста, створили од земље, затим од капи семена, потом од заквачка, затим од груде меса, обликованих и необликованих удова, да бисмо вам показали нашу моћ! А у материцама задржавамо шта хоћемо, до одређеног рока, затим чинимо да се рађате као дојенчад и да после до мужевног доба израстете; једни од вас умиру, а други дубоку старост доживљавају, тако да зачас, забораве оно што су знали. И ти видиш земљу како је замрла, али кад на њу спустимо воду, она устрепће и узбуја, и из ње изникне разноразно прекрасно биље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Тако је јер Аллах постоји, и што Он може мртве да оживи, и што Он све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'и што ће Час оживљења да дође, у то нема сумње, и што ће Аллах да оживи оне у гробовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Има људи који расправљају о Аллаху без икаквог знања, и без Упуте и без Књиге светиљке,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'ходајући надмено, да би одвраћали од Аллаховог пута, њих на овом свету чека понижење, а на Судњем дану даћемо им да искусе патњу у огњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, '„Ето, то је због твојих дела, а Аллах, заиста, не чини насиље Својим слугама.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Има људи који Аллаха обожавају, али без правог уверења. Ако га прати срећа, он је смирен, а ако западне и у најмање искушење, враћа се неверству – па тако изгуби и овај и Будући свет. То је, уистину, очити губитак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'Он, се поред Аллаха, моли ономе који од њега не може никакву штету да отклони нити може било какву корист да му прибави; то је, заиста, далека странпутица;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'моли се ономе због чије ће молитве пре штету имати него корист; лош је то заштитник и зао пријатељ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Аллах ће оне који верују и раде добра дела, заиста, да уведе у баште Раја, кроз које теку реке. Аллах ради оно што хоће!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Онај ко мисли да Аллах неће помоћи Посланику ни на овом свету ни на Будућем, нека растегне уже до таванице и нека га пресече, па нек види да ли ће његов поступак да отклони оно што га срди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'И Ми га тако у виду јасних стихова објављујемо, а Аллах ће оном коме Он хоће на Прави пут да укаже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Аллах ће, заиста, на Судњем дану да одвоји вернике од Јевреја, Сабијаца, хришћана, поклоника ватре и незнанобожаца. Аллах је, заиста, свему сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Зар не знаш да се и они на небесима и они на Земљи Аллаху клањају, а и Сунце, и Месец, и звезде, и планине, и дрвеће, и животиње, и многи људи, а многи казну заслужују. А кога Аллах понизи, нико га не може поштованим учинити; Аллах, заиста, ради шта хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Ова два противничка табора споре се око Господара свог. Онима који не буду веровали биће одела од ватре скројена, а кључала вода биће сипана на главе њихове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'Од ње ће да се истопи оно што је у њиховим стомацима, и кожа,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'а биће ударани гвозденим маљевима;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'кад год покушају да због тешког јада из ње изађу, биће у њу враћени: “Ето вам патња у ужасној ватри!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'А оне који буду веровали и радили добра дела - Аллах ће сигурно да уведе у рајске баште кроз које теку реке; у њима ће се китити наруквицама од злата и бисером а одећа ће да им буде од свиле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, 'Они су били надахнути да изговарају најлепше речи и били су надахнути на пут Оног Који је хвале достојан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Заиста ћемо онима који не верују и одвраћају од Аллаховог пута и Часне Кабе, коју смо одредили за све људе - једнако за мештанина и за посетиоца, и ономе ко у њој било какво насиље учини, дати да искуси болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'И кад смо Авраму показали место за изградњу Храма: “Не обожавај осим Мене никог, и нека овај Храм Мој буде чист за оне који ће га обилазити, који ће ту у близини његовој становати, и који ће молитву обављати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, 'И огласи људима хаџ - и долазиће ти пешке и на изнуреним камилама које долазе са далеког пута,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'да би користи имали и да би у одређене дане, приликом клања жртвенице, којом их је Аллах опскрбио, Његово име спомињали. Једите то месо, а нахраните и тешког сиромаха!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Затим, нека са себе прљавштину уклоне, нека своје завете испуне и нека око Храма древнога обилазе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, 'Ето толико! А ко поштује Аллахове светиње, уживаће милост Господара свог. А дозвољена вам је стока, осим оне о којој вам је речено – па клоните се идола поганих и клоните се лажног говора!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, 'Будите искрено Аллаху одани, не придружујући Му никога у обожавању! А онај ко Аллаху придружује некога у обожавању - као да је са неба пао, па су га птице разграбиле, или га је ветар у далеки предео одувао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, 'Тако је то! Па ко поштује Аллахове прописе - то је знак богобојазног срца.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'Вама оне користе до одређеног рока, а после, њихово место је крај древног храма.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'Свакој заједници прописали смо клање жртвенице да би спомињали Аллахово име приликом клања стоке коју им Он даје. Ваш Бог је један Бог, зато се само Њему искрено предајте! А радосном вешћу обрадуј послушне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'чија срца, кад се Аллах спомене, обузме страх, и оне који стрпљиво подносе невоље које их задесе, и оне који обављају молитву и који, од онога што им Ми дајемо, удељују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'А камиле смо вам учинили једним од Аллахових знамења и ви у њима имате добро; зато спомињите Аллахово име над њима, када буду за клање припремљене, а када се то заврши, једите месо, а нахраните и онога који не проси, а и оног који проси; тако смо вам их потчинили да бисте захвални били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'До Аллаха неће допрети њихово месо и њихова крв, али ће допрети ваша искрено учињена дела. Тако вам их је потчинио да бисте величали Аллаха јер вас је на Прави пут упутио. И обрадуј оне који раде добра дела!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Аллах, заиста, штити вернике, Аллах сигурно не воли ниједног издајника, незахвалника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Допушта се одбрана онима које други нападну, зато што им се насиље чини – а Аллах је, заиста, способан да их помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, 'Онима који су бесправно прогнани из свога завичаја само зато што су говорили: „Господар наш је Аллах!“ А да Аллах не сузбије неке људе другима, до темеља би били порушени манастири и цркве, и синагоге, а и џамије, у којима се много спомиње Аллахово име. А Аллах ће сигурно да помогне оне који Њега помажу - Аллах је, заиста, моћан и силан;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'оне који ће, ако им дамо власт на Земљи, да обављају молитву и удељују милостињу и који ће да траже да се раде добра дела, а одвраћају од неваљалих - а Аллаху се, на крају, све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'А ако те они буду угонили у лаж, па и пре њих су народ Нојев, и Ад, и Семуд посланике угонили у лаж,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'и народ Аврамов, и народ Лотов,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'и становници Медена; а лажним је сматран и Мојсије, а Ја сам неверницима давао времена, затим сам их кажњавао, па каква је била Моја осуда?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'И колико смо насеља уништили, чији су житељи незнанобошци били, па су пуста у рушевинама остала! И колико бунарева има запуштених и колико високих палата празних!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Зашто они по свету не путују па да срца њихова схвате оно што требају да схвате и да уши њихове чују оно што требају да чују, али очи нису слепе, већ срца у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'Они од тебе траже да их казна што пре стигне, а Аллах ће испунити претњу Своју; само један дан код Господара твог траје колико хиљаду година, по вашем рачунању.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'И колико је било насеља чији су житељи били неправедни, којима сам Ја казну одлагао, да бих их најзад казнио! А Мени се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, 'Реци: „О људи, ја сам ту само да вас јасно упозорим!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'Они који буду веровали и радили добра дела имаће опрост и племениту опскрбу;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'а они који се буду трудили да доказе Наше порекну, уверени да ће Нам умаћи, биће становници Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'Пре тебе, Ми ниједног посланика и веровесника нисмо послали а да Сотона није, кад би он казивао, у његово казивање нешто убацио. Аллах би уклонио оно што би Сотона убацио, а затим би учврстио Своје речи, а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Да би оно што је Сотона убацио учинио искушењем за оне у чијим срцима је болест и за оне чија су срца окорела. А заиста су неверници у бескрајној неслози.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, 'И да би они који су знањем обдарени спознали да је Кур''ан истина од твог Господара, па у њега поверовали и да према Аллаху срца њихова буду понизна. Заиста оне који верују Аллах упућује на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'А неверници неће да престану да у Кур''ан сумњају, све док им Час изненада не дође или док им не дође патња у страховитом Дану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'Тог Дана власт ће само Аллах имати, Он ће им судити: верници и они који су добра дела чинили биће у рајским баштама уживања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'А они који нису веровали и порицали су Наше речи и доказе, они ће бити у понижавајућој патњи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Аллах ће, заиста, лепо да награди оне који су напустили свој родни крај да би се борили на Аллаховом путу, па затим погинули или умрли, а заиста је Аллах најбољи Опскрбитељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'Он ће их у место којим ће они бити задовољни заиста увести! – А Аллах све зна и благ је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, 'Ето тако! А оном ко истом мером узврати за учињено зло и коме опет неправда буде учињена, Аллах ће, сигурно, да му помогне - Аллах, заиста, стално брише грехе и опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Ето тако! А Аллах смењује ноћ даном, а дан ноћу, и Аллах све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'То је зато што је Аллах - истина, а они које они, поред Аллаха, моле - лаж, и зато што је Аллах Свевишњи и Велики.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Зар не видиш да Аллах с неба спушта кишу од које земља зазелени? – Аллах је заиста добар и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'Његово је оно што је на небесима и оно што је на Земљи! Аллах, заиста, није ни о коме овисан, и Он је једини хвале достојан!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Зар не видиш да вам је Аллах потчинио све што је на Земљи, па и лађе које, Његовом одредбом, морем плове?! Он чува оно што је на небесима да не падне на Земљу, осим са Његовом дозволом. Аллах је, уистину, према људима благ и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'Он вам даје живот и затим ће да вам га одузме и после ће да вас опет оживи; човек је, заиста, прави незахвалник!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'Свакој заједници прописали смо верозакон према којем је требало да се влада; и не дозволи, никако, да са тобом о томе расправљају. Ти позивај своме Господару, ти си, уистину, на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'А ако се они буду са тобом препирали, реци: „Аллах најбоље зна оно што ви радите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Аллах ће да вам пресуди на Судњем дану о ономе у чему се разилазите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Зар не знаш да Аллах зна све што је на небу и на Земљи?! То је све у Књизи, то је, уистину, Аллаху лако!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'Незнанобошци, поред Аллаха, обожавају оне за које им Он није дао никакав доказ, и о њима сами ништа не знају. А незнанобошце неће имати ко да спаси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'А кад им се Наше јасне речи казују, ти примећујеш велико негодовање на лицима оних који не верују, који умало да не насрну на оне који им речи Наше казују. Реци: “Хоћете ли да вам кажем шта ће вам бити мрзније од тога? Ватра којом Аллах неверницима прети, а грозно ће она пребивалиште бити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'О људи, ево једног примера, па га послушајте: „Они које ви, поред Аллаха обожавате, не могу никако да створе ни мушицу, макар се ради ње удружили. А ако би им мушица нешто уграбила, они то не би могли да избаве од ње. Слаб је онај који обожава и онај који се обожава!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Они не величају и не познају Аллаха како треба, а Аллах је, уистину, моћан и силан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Аллах одабира изасланике међу анђелима и људима - Аллах, заиста, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'Он зна шта су урадили и шта ће да ураде. А Аллаху се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'О верници, клањајте се и ничице падајте и свога Господара обожавајте, и радите добра дела да бисте постигли оно што желите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'И борите се, ради Аллаха, истински, онако како треба да се бори! Он вас је изабрао и у вери вам није ништа тешко прописао, у вери вашег претка Аврама. Аллах вас је одавно назвао муслиманима, и у овом Кур''ану, да би Посланик био сведок против вас, и да бисте ви били сведоци против осталих људи. Зато, обављајте молитву и дајте обавезну милостињу и Аллаха се чврсто држите. Он је Господар ваш, и то какав Господар и какав заштитник!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Верници ће успети,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'они који су скрушени у својој молитви,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'и који се окрећу од бесмислица,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'и који милостињу удељују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'и који чувају своја стидна места,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, 'осим од својих супруга или оних које су у њиховом поседу; они, заиста, неће да буду прекорени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'а они који и преко тога нешто траже, то су заиста они који прелазе границу;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'и који своја обећања и обавезе чувају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'и који своје молитве на време обављају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'они су заиста наследници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'који ће Рај да наследе, они ће у њему вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Ми смо, заиста, створили човека од бити земље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'затим чинимо да доспе у припремљено станиште као кап семена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'па онда кап семена угрушком створимо, затим од угрушка заквачак створимо, па од заквачка кости створимо, а онда кости месом заоденемо, и после га, као друго створење, формирамо, па нека је узвишен Аллах, Најбољи Створитељ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Ви ћете, после тога, заиста, да помрете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'затим ћете, на Судњем дану, да будете оживљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'Ми смо седам небеса изнад вас створили, и Ми нисмо немарни према оном што смо створили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Ми са неба спуштамо воду са мером, и у земљи је задржавамо - а можемо да учинимо и да нестане,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'и помоћу ње баште за вас подижемо од палми и винове лозе - у њима имате много воћа које једете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'и маслиново дрво које расте на Синајској гори, од њега добијате уље и зачин.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'И у стоци вам је поука: Ми вам дајемо да пијете оно што се налази у њеним утробама, и ви од ње имате многе користи и ви се њоме храните,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'и на њима, и на лађама се превозите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Ми смо послали Ноја његовом народу, па им он рече: „О мој народе, само Аллаха обожавајте, ви немате другог истинског бога осим Њега; зар се не бојите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Али су главешине његовог народа, које нису веровале, говориле: „Он је само човек као и ви, жели предност над вама. Да је Аллах хтео, послао би анђеле; овако нешто нисмо чули од наших давних предака.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Он је човек опседнут духовима, па пустите га неко време!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, '„Мој Господару“, рече он, „помози ми, зато што ме у лаж утерују!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'И Ми му објависмо: “Гради лађу под очима Нашим и према надахнућу Нашем, па кад заповед Наша дође и вода испод пећи на површину земље избије, ти у њу укрцај од сваке врсте животиње по пар, мужјака и женку, и чељад своју, али не оне о којима је већ суд донесен, и не обраћај Ми се за невернике, јер ће, заиста, бити потопљени.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Па кад се сместиш у лађу, ти и они који су уз тебе, реци: ''Хвала Аллаху, Који нас је спасио безбожничког народа!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'И реци: “Господару мој, искрцај ме на благословљено место, Ти то најбоље умеш!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'У томе су, заиста, поуке, а Ми смо заиста стављали на кушњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'После њих смо друга поколења стварали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'и послали смо им, као посланика, једног између њих: „Само Аллаха обожавајте, ви немате другог истинског бога осим Њега; зар се не бојите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Али су великани његовог народа, који нису веровали, који су порицали да ће да буду оживљени на Будућем свету, и којима смо дали да раскошно живе у животу на овом свету, говорили: „Он је човек као и ви; једе оно што и ви једете, и пије оно што и ви пијете;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'и ако се будете покоравали човеку попут вас, сигурно ћете да будете изгубљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Зар он вама да прети да ћете, након што умрете и земља и кости постанете, заиста, да будете оживљени?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Немогуће је оно чиме вам се прети!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'Постоји само наш живот на овом свету, ту живимо и умиремо, а оживљени нећемо бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'Он је човек који о Аллаху износи лажи, и ми му не верујемо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, '„Мој Господару,“ замолио је он, „помози ми, они ме у лаж утерују!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, '„Ускоро ће они да се кају!“ Одговори Он,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'и заслужено их је погодио страшан глас, и Ми смо их учинили као што је речни нанос, па далеко био насилнички народ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'А затим смо, после њих, друга поколења ствoрили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'ниједан народ не може убрзати ни успорити време своје пропасти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Затим смо посланике, једне за другим слали. Кад год би неком народу дошао његов посланик, утеривали би га у лаж, и Ми смо их зато редом уништавали, и само смо у причама о њима сачували спомен; па далеко били људи који нису веровали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'После смо послали Мојсија и брата му Арона са Нашим речима и знацима и очигледним доказом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, 'фараону и његовим главешинама, али су се они узохолили, били су то надмени људи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Говорили су: „Зар да поверујемо двојици људи који су као и ми, а њихов народ је у нашем ропству?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'И њих двојицу лажљивцима прогласише, па су зато били уништени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Мојсију смо онда дали Књигу не би ли Израиљеви синови ишли Правим путем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'И сина Маријиног и мајку његову знаком смо учинили. Ми смо њих на једној висоравни с текућом водом настанили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, '“О посланици, дозвољеним и лепим јелима се храните и добра дела чините, јер Ја добро знам шта ви радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Ова ваша вера - једна је вера, а Ја сам ваш Господар, па Ме се бојте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'А народи су се у питањима своје вере поделили на скупине, свака странка задовољна са оним што има.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Па, остави их у њиховој заблуди још неко време!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Мисле ли они - да тиме што их помажемо иметком и синовима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'да журимо да им благодати подаримо? Напротив, они не опажају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Они који из бојазни према Господару свом страхују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'и они који у доказе и речи свога Господара верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'и они који поред свог Господара ништа друго не обожавају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'и они који од онога што им је дато удељују, а срца су им пуна страха зато што ће да се врате своме Господару,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'они журе да раде добра дела, и у њима друге претичу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Ми никога не задужујемо преко његових могућности; код Нас је Књига која говори истину, и њима неће да буде учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Али, срца неверника су према овом сасвим равнодушна, а поред тога и ружна дела стално чине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'А кад будемо на муке ставили оне међу њима који су раскошним животом живели, одмах ће почети са запомагањем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, '„Сада не запомажите, Ми вам нећемо помоћ пружити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'вама су Моје речи биле казиване, али сте им леђа окретали;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'охолећи се Храмом, и у њему посеткујући, ружне речи сте говорили!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Зашто они о Кур''ану не размисле, или им је дошло нешто што није долазило њиховим давним прецима?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Зар они не познају свога Посланика, па га зато поричу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, 'Зар говоре: „Луд је!“ Међутим, он им доноси истину, али већина њих презире истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Када би Аллах ствари усклађивао према прохтевима њиховим, сигурно би нестало поретка на небесима и на Земљи и у оном што је на њима. Ми смо им дали Кур’ан, славу њихову, али се они од славе своје окрећу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Или од њих тражиш надокнаду? Па надокнада Господара твог боља је, Он је најбољи Опскрбитељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Ти их, заиста, позиваш на Прави пут,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'али они који у Будући свет неће да верују се од Правог пута, заиста, отуђују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'И кад бисмо им се смиловали и отклонили од њих невољу у којој се налазе, опет би они, сигурно, наставили да у својој заблуди лутају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'Ми смо их патњом ставили на искушење, али се они Господару своме нису покорили, нити су се понизно молили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'тек кад им отворимо капију тешке патње они ће наду да изгубе и у очајање ће да западну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Он је Тај Који вам је створио слух, и вид, и дао разум; а како мало ви захваљујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'Он вас на Земљи ствара, и пред Њим ћете се сакупити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'Он живот и смрт даје и само од Њега зависи измена ноћи и дана, па зашто не схватите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Али, они говоре као што су говорили они пре њих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Говорили су: „Зар кад помремо и кад постанемо прах и кости, зар ћемо, заиста, да будемо оживљени?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'И нама и, још давно, нашим прецима тим се претило, али, то су само измишљотине древних народа.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'Упитај: „Чија је Земља и све оно што је на њој, знате ли?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, '„Аллахова!“ Одговориће, а ти реци: „Па зашто онда не дођете себи?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, 'Упитај: „Ко је Господар седам небеса и ко је Господар величанственог Престола?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, '„Аллах!“, одговориће, а ти реци: „Па зашто Га се онда не бојите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, 'Упитај: “У чијој је руци власт над свим, и ко узима у заштиту, и од кога нико не може заштићен бити, знате ли?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, '“Аллах!” Одговориће, а ти реци: “Па зашто онда допуштате да будете заведени?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Да, Ми им истину доносимо, а они су заиста лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Аллах није за Себе узео сина, и поред Њега не постоји други бог! Иначе би сваки бог, с оним што је створио, радио шта би хтео, и један другог би побеђивао. Слављен нека је Аллах Који је далеко од онога како Га они описују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, 'Који зна невидљиви и видљиви свет и Он је врло високо изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'Реци: „Господару мој, ако ћеш да ми покажеш оно што им се претећи обећава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'онда ме, Господару мој, не остави с народом неверничким!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, 'А Ми, заиста, можемо да ти покажемо оно чиме им се прети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Ти лепим на зло узврати, Ми добро знамо шта они износе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'и реци: „Господару мој, тражим заштиту код Тебе од ђаволских наговарања,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'и Теби се, Господару мој, обраћам да ме од њиховог присуства заштитиш!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, 'И када неком од њих смрт дође, он узвикне: „Господару мој, поврати ме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'да урадим какво добро у ономе што сам пропустио!“ Никако! То су, заиста, речи које ће он узалудно да говори - пред њима ће препрека бити све до Дана када ће да буду проживљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Па кад у рог буде дувнуто, тада међу њима неће бити родбинских веза и једни друге неће ништа да питају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Они који ће имати довољно добрих дела, они ће успети и спасити се.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'а они који буду имали недовољно добрих дела, они ће у потпуности изгубљени бити, у Паклу ће вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'Ватра ће лица да им пржи и искежених зуба ће да буду у њој.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, 'Зар вам нису казиване Моје речи, а ви сте их порицали?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, '“Господару наш”, рећи ће, “наше страсти су биле јаче од нас, па смо постали народ залутали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'Господару наш, избави нас из ње. Ако бисмо поново зло радили, онда би, заиста, прави неправедници били.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, '„Останите у њој презрени и не обраћајте Ми се!“ Рећи ће Он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Кад су неке Моје слуге говориле: „Господару наш, ми верујемо, зато нам опрости и смилуј нам се, а Ти си Милосник најбољи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Ви сте им се толико ругали да сте због тога на Мене заборављали и увек сте их исмејавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Ја њих данас награђујем за оно што су трпели, и они су, заиста, прави победници.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, '“А колико сте година на Земљи провели?” Биће упитани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, '„Провели смо, дан или само део дана,“ одговориће, „питај оне који су бројали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, '“Да, кратко сте провели”, рећи ће им се, “да сте само знали!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, '„Зар сте мислили да смо вас узалуд створили и да Нам се нећете вратити?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'И нека је Узвишен Аллах, Истинити Владар, нема другог истинског бога осим Њега, Господара Престола дивног!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'А онај који се, поред Аллаха, моли другом богу, без икаквог доказа о томе, пред Господаром својим ће рачун полагати, а неверници се неће никад спасити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, 'И реци: „Господару мој, опрости и смилуј се, Ти си најмилостивији!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, 'Објављујемо поглавље и његове прописе чинимо обавезним! У њему објављујемо јасне доказе да бисте поуку примили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Блудницу и блудника избичујте са по стотину удараца бича, и нека вас при вршењу Аллахових прописа не обузима према њима никакво сажаљење, ако верујете у Аллаха и у Судњи дан, и нека њиховом кажњавању посведочи једна група верника!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Блудник се не жени осим са блудницом или незнанобошкињом, а са блудницом се жени само блудник или незнанобожац, а верницима је то забрањено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Они који потворе чедне жене, а потом не докажу то са четири сведока, избичујте их са осамдесет удараца и не примајте никада више њихово сведочење; они су нечасни људи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'осим оних који се после тога покају и поправе, јер Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'А они који окриве своје жене, а не буду имали других сведока, него су само они сведоци, потврдиће своје сведочење заклетвом Аллахом, и то четири пута да заиста говоре истину,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, 'а пети пут да их погоди Аллахово проклетство ако лажу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'А она ће казне бити поштеђена, ако се четири пута Аллахом закуне да он, уистину, лаже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, 'А пети пут да је стигне Аллахова срџба, ако он говори истину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'А да није Аллахове доброте према вама и Његове милости... А Аллах, заиста, прима покајање и мудар је!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'Међу вама је било оних који су износили потвору. Ви не сматрајте то неким злом по вас; не, то је добро по вас. Сваки од њих биће кажњен према греху који је заслужио, а онога од њих који је то највише радио чека велика патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'Зашто, чим сте то чули, верници и вернице нису једни о другима добро помислили и рекли: „Ово је очигледна потвора!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'Зашто нису довели четворицу сведока? А пошто сведоке нису довели, они су онда код Аллаха лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'А да није Аллахове доброте према вама и Његове милости и на овом свету и на Будућем свету, већ би вас снашла велика патња због онога у шта сте се упустили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'Када сте то препричавали својим језицима и када сте на сва уста говорили оно о чему нисте ништа знали, ви сте то ситницом сматрали, али је то код Аллаха крупно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Зашто нисте, чим сте то чули, рекли: „Не доликује нам да о томе говоримо, Узвишен нека си Ти! То је велика потвора!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Аллах вам наређује да више никад тако нешто не поновите, ако сте верници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'и Аллах вам прописе објашњава; а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'Заиста онима који воле да се о верницима шире бестидне гласине чека болна казна и на овом свету и на Будућем; Аллах зна, а ви не знате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'А да није Аллахове доброте према вама и Његове милости и да Аллах није благ и милостив...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'О верници, не следите Сотонине стопе! Онај ко буде следио Сотонине стопе он ће га на разврат и одвратна дела наводити. А да није Аллахове доброте према вама и Његове милости, ниједан од вас се не би никад очистио од греха; али Аллах чисти онога кога Он хоће. Аллах све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Нека се доброчинитељи и богати међу вама не заклињу да више неће да помажу рођаке и сиромахе, и оне који су на Аллаховом путу напустили свој родни крај; нека им опросте и не замере! Зар вам не би било драго да и вама Аллах опрости?! А Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Заиста они који потворе честите, безазлене вернице нека су проклети и на овом свету и на Будућем и њима припада болна патња', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'на Дан када против њих буду сведочили њихови језици, и њихове руке, и њихове ноге за оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'Тог Дана Аллах ће их казнити казном коју су заслужили и они ће сазнати да је Аллах, заиста, Истина очигледна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, 'Неваљале жене припадају неваљалим мушкарцима, а неваљали мушкарци припадају неваљалим женама; честите жене припадају честитим мушкарцима, а честити мушкарци припадају честитим женама. Они нису криви за оно што о њима говоре, њих чека опрост и велико обиље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'О верници, у туђе куће не улазите док допуштење не добијете и док укућане не поздравите – то вам је боље, поучите се!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'А ако у њима никога не нађете, не улазите у њих док вам се не допусти; а ако вам се каже: „Вратите се!“ Ви се вратите, то вам је чедније, а Аллах добро зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Није вам грех да улазите у ненастањене куће у којима се налазе ваше ствари, а Аллах зна оно што јавно показујете и оно што кријете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'Реци верницима нека оборе своје погледе и нека воде бригу о својим стидним местима; то им је чедније. Аллах у потпуности зна оно што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'А реци верницама нека оборе погледе своје и нека воде бригу о стидним местима својим; и нека не дозволе да се од украса њихових види ишта осим оног што је ионако спољашње, и нека вела своја спусте на груди своје; нека украсе своје не показују другима, то могу само мужевима својим, или очевима својим, или очевима мужева својих, или синовима својим, или синовима мужева својих, или браћи својој или синовима браће своје, или синовима сестара својих, или пријатељицама својим, или робињама својим, или мушкарцима којима нису потребне жене, или деци која још нису спознала стидна места жена; и нека не ударају ногама својим да би се чуо звекет накита њиховог који покривају. И сви се Аллаху покајте, о верници, да бисте постигли оно што желите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Удајте неудате и жените неожењене, и честите робове и своје робиње; ако су сиромашни, Аллах ће им из Свога обиља дати. Аллах је неизмерно дарежљив и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'И нека се суздрже они који немају могућности да се ожене, док им Аллах из Свога обиља не помогне! А са онима у вашем поседу који желе да се откупе, ако знате да су у стању да то учине, о откупу се договорите. И дајте им нешто од иметка који вам је Аллах дао. И не нагоните своје робиње да се баве блудом - ако оне желе да буду честите - да бисте стекли пролазна добра овога света; а ако их неко на то присили, Аллах ће, након што су биле приморане, да им опрости и према њима да буде милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Ми вам објављујемо јасне речи и примере из живота оних који су били пре вас и нестали, и поуку богобојазним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Аллах је светло небеса и Земље! Пример Његовог светла је као удубина у којој је фитиљ кандила; фитиљ је у стакленки, а стакленка је као блистава звезда; ужиже се благословљеним маслиновим дрветом, источним и западним, чије уље готово да сија кад га ватра и не дотакне; сама светлост изнад светлости! Аллах води ка Својој светлости онога кога Он хоће. Аллах наводи примере људима, Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'У џамијама, које се Његовом вољом подижу и у којима се спомиње Његово име – Њега славе и величају, ујутру и навече', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, 'људи које куповина и продаја не ометају да спомињу Аллаха и који обављају молитву и удељују обавезну милостињу, и који стрепе од Дана у коме ће срца и погледи да буду узнемирени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, 'да би их Аллах лепом наградом за дела њихова наградио и да би им од доброте Своје и више дао. А Аллах даје коме хоће, без рачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'А дела неверника су као варка у равници у којој жедан види воду, али кад до тог места дође, ништа не нађе – а затећи ће да га чека крај њега Аллахова казна и Он ће потпуно да му обрачуна његова дела; Аллах веома брзо обрачунава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'или су као тмине над дубоким морем које прекривају таласи све један за другим, изнад којих су облаци, све тмине једна изнад других, прст се пред оком не види – а онај коме Аллах не да светло неће светла ни имати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'Зар не знаш да Аллаха славе и величају сви који су на небесима и на Земљи, а и птице ширењем својих крила; сви знају како ће да Му се моле и како ће да Га славе и величају. А Аллах добро зна оно што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'Аллахова је власт и на небесима и на Земљи, а Аллаху се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Зар не видиш да Аллах полако покреће облаке, а онда их спаја и једне над другима гомила, па ти видиш кишу како из њих пада: Он с неба, из облака величине брда, спушта град, па њиме кога хоће погоди, а кога хоће поштеди – блесак муње Његове готово да одузме вид.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Он чини да ноћ и дан наступају наизменично и у томе је, заиста, поука за оне који памет имају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Аллах сва жива бића ствара од воде, нека од њих пузе на стомаку, нека иду на две ноге, а нека, опет ходају на четири; Аллах ствара што хоће, Аллах, заиста, све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Ми смо објавили јасне речи и доказе; а Аллах упућује на Прави пут онога кога Он хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, 'Лицемери говоре: „Ми верујемо у Аллаха и Посланика, и покоравамо се“, а затим се неки од њих одмећу. Нису они верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Кад буду позвани Аллаху и Његовом Посланику да им пресуди, неки од њих одједном леђа окрену.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'само ако знају да је правда на њиховој страни, долазе му послушно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Да ли су њихова срца болесна, или сумњају, или страхују да ће Аллах и Његов Посланик према њима неправедно да поступе? Ниједно, него желе другима неправду да учине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Кад се верници Аллаху и Посланику Његовом позову да им пресуди, само кажу: „Слушамо и покоравамо се!“ То су они који су успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Они који се Аллаху и Његовом Посланику буду покоравали, који се буду бојали Аллаха и Њега се чували - то су они који су успели и који су спашени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Лицемери се заклињу Аллахом, најтежом заклетвом, да ће сигурно да иду у бој ако им ти наредиш. Реци: „Не заклињите се! Ваша покорност је позната! Аллах, заиста, у потпуности зна оно што радите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'Реци: „Покоравајте се Аллаху и покоравајте се Посланику!“ А ако се окренете, он је дужан да ради оно што се њему наређује, а ви сте дужни оно што се вама наређује, па ако му будете послушни, бићете на Правом путу - а Посланикова дужност је само да јасно обзнани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Аллах обећава да ће оне међу вама који буду веровали и добра дела чинили сигурно намесницима на Земљи поставити, као што је поставио намесницима оне пре њих, и да ће им зацело веру њихову учврстити, ону коју им Он жели, и да ће им сигурно страх сигурношћу заменити; они ће само Мене обожавати, и неће друге Мени у обожавању да придружују. А они који и после тога буду неверници – они су прави грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'А ви обављајте молитву и дајте милостињу и Посланику будите послушни да би вам се милост указала.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, 'Никако не мисли да ће неверници умаћи Њему на Земљи; њихово боравиште биће ватра, а она је, заиста, грозно пребивалиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'О верници, нека од вас у три случаја затраже допуштење да вам уђу они који су у вашем поседу и они који још нису полно зрели: пре јутарње молитве, и када у подне одложите своју одећу, и после обављања ноћне молитве. То су три доба када нисте обучени, а у друго доба није ни вама ни њима грех, па они код вас често улазе, а и ви једни код других улазите. Тако вам Аллах објашњава прописе! А Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'А кад ваша деца достигну полну зрелост, нека онда увек траже допуштење за улазак, као што су тражили допуштење они старији пре њих; тако вам Аллах објашњава Своје прописе! А Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'А старим женама које више не жуде за удајом није грех да одложе огртаче своје, али не показујући она места на којима се украси носе; а боље им је да буду крепосне. Аллах све чује и зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, 'Није грех слепом, нити је грех хромом, нити је грех болесном, а нити вама самима да једете у вашим кућама, или у кућама ваших очева, или у кућама ваших мајки, или у кућама ваше браће, или у кућама ваших сестара, или у кућама ваших стричева, или у кућама ваших тетака по оцу, или у кућама ваших ујака, или у кућама ваших тетака по мајци, или оних чији су кључеви код вас или код вашег пријатеља; није вам грех да једете заједнички или појединачно. А кад улазите у куће, ви њене укућане поздравите поздравом прописаним од Аллаха, благословљеним и лепим. Тако вам Аллах објашњава прописе да бисте разумели!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'Прави верници су само они који верују у Аллаха и Његовог Посланика, а који се, кад су са њим на каквом важном састанку, не удаљују док од њега допуштење не добију. Они који од тебе траже допуштење, у Аллаха и Његовог Посланика, заиста, верују. И кад они затраже допуштење од тебе због каквог свог посла, допусти коме хоћеш од њих, и замоли Аллаха да им опрости - заиста Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Не сматрајте Послаников позив упућен вама као позив који ви једни другима упућујете; Бог сигурно зна оне међу вама који се крадом извлаче. Нека се припазе они који поступају супротно његовом наређењу да их не стигне какво искушење, или да их не снађе болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Аллахово је све што је на небесима и на Земљи, Он сигурно зна какви сте ви, и Он ће да их обавести о свему што су урадили на Дан кад се Њему буду вратили. А Аллах све добро зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Нека је узвишен Онај Који Своме слуги објављује Кур''ан да би световима био опомена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, 'Онај Коме припада власт на небесима и на Земљи, Који нема детета, Који у власти нема ортака и Који је све створио и како треба уредио!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'А они су узели божанства мимо Њега, која ништа не стварају, а која су сама створена, која нису у стању да од себе отклоне неку штету ни да себи прибаве какву корист, која немају моћ да живот одузму, да живот дају нити да оживе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Они који не верују говоре: “Ово није ништа друго до велика лаж коју он измишља, а у томе му и други људи помажу”, и тиме чине неправду и потвору.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, 'И говоре: „То су измишљотине древних народа које је он преписао, па му се казују јутром и вечери.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, 'Реци: „Објављује га Онај Који зна тајне небеса и Земље; Он опрашта грехе и милостив је."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'И још говоре: „Шта је овом посланику, он храну једе и по пијацама шета; зашто му није послат један анђео да заједно са њим опомиње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, 'или да му се спусти ризница са благом, или да има башту из које би се хранио?!“ И неверници још говоре: „Ви само опчињеног човека следите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Види шта о теби они говоре, па онда лутају и Прави пут не могу да нађу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Нека је узвишен Онај Који, ако хоће, може да ти подари боље од тога: баште кроз које теку реке и дворце.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Они, чак, поричу и Час оживљења, а Ми смо за оне који поричу Час оживљења припремили разбуктали Огањ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Кад их Огањ опази из даљине, они ће чути како гневан кључа и од жестине стење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'А кад буду бачени у Ватру, у теснац, везаних руку, пропаст ће призивати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, '“Не призивајте данас једну пропаст, него призивајте многе пропасти!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, 'Реци: „Да ли је боље то или вечни Рај, који је обећан богобојазнима?" Он ће да им буде награда и пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'У њему ће заувек све што зажеле да имају – то је обећање Господара твог – они ће да имају право то да траже од Њега.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'А на Дан када их Он сакупи, а и оне које су поред Аллаха обожавали, па упита: „Јесте ли ви ове Моје слуге завели у заблуду, или су они сами залутали са Правог пута?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, 'Они ће да кажу: „Узвишен нек си Ти, незамисливо је да смо ми поред Тебе узимали икакве заштитнике, него, Ти си овима и њиховим прецима дао да уживају, па су заборавили опомену; они су заслужили пропаст!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Они ће да порекну то што ви говорите, а ви нећете да будете у могућности да отклоните патњу нити да нађете помоћ. А ономе од вас који је незнанобожац био даћемо да искуси велику патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Ми пре тебе нисмо послали ниједног посланика који није јео и по трговима ходао. Ми чинимо да једни другима будете искушење, да видимо хоћете ли да будете стрпљиви. А твој Господар све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Они који не верују да ће пред Нас стати говоре: “Зашто нам се не пошаљу анђели или зашто Господара свог не видимо?” Они су, заиста, у душама својим охоли, а у неверству су све границе прешли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Оног Дана кад угледају анђеле, грешници се неће радовати,а анђели ће им говорити: „Милост вам је потпуно ускраћена.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'И Ми ћемо приступити делима њиховим која су учинили и у прах и пепео их претворити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Становници Раја ће тог дана да имају најбоље пребивалиште и најлепше одмаралиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'А на Дан кад се расцепи небо и из њега се појави облак и кад се анђели уистину спусте,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'тог дана ће да буде истинска власт само код Свемилосног, а биће то мучан дан за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'На Дан кад неверник прсте своје буде гризао говорећи: „Камо среће да сам се уз Посланика држао Правог пута!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, 'Камо среће, тешко мени, да тога и тога нисам узео за пријатеља!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'Он ме је од Кур''ана одвратио након што ми је дошао!“ - А ђаво човека увек оставља на цедилу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Посланик је рекао: „Господару мој, заиста мој народ овај Кур''ан избегава!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Исто тако смо Ми дали да сваком веровеснику зликовци непријатељи буду. А теби је Господар твој довољан као водич и као помагач!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Они који не верују говоре: “Требало је да му Кур’ан буде објављен читав, и то одједном!” А тако се објављује да бисмо њиме срце твоје учврстили, и Ми га постепено у етапама објављујемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Они неће ниједан приговор да ти упуте, а да Ми нећемо одговор и најлепше објашњење да ти наведемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, 'Они који буду наглавачке вучени ка Паклу биће у најгорем положају и у највећој невољи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Ми смо Мојсију дали Књигу и његовог брата Арона му учинили помоћником,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, 'Па смо казали: „Идите вас двоје народу који пориче Наше доказе“, и после смо тај народ потпуно уништили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'А и Нојев народ смо, кад су посланике у лаж утеривали, потопили и људима их поучним примером учинили, а неверницима смо патњу болну припремили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, 'И Аду и Семуду и становницима Реса и многим народима између њих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'свима смо објаснили примере за поуку, и све смо их затим у потпуности уништавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'И они пролазе поред насеља на које се сручила кобна киша - зар га не виде?! Напротив, они се не надају проживљењу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Кад те виде, ругају ти се: „Је ли ово онај којег је Аллах послао као посланика?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, 'Умало да нас није одвратио од наших божанстава, али ми смо им остали верни.“ А кад доживе патњу, сазнаће ко је био у највећој заблуди!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Кажи ти Мени, хоћеш ли ти сачувати оног који је страст своју за бога свог узео?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Мислиш ли ти да већина њих жели да чује или да схвати? Као стока су они, чак су још даље с Правог пута скренули.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Зар не видиш како твој Господар сенку распростире - а да хоће, оставио би је да мирује. А затим смо учинили да на њу Сунце утиче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'А после је мало-помало Себи привлачимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'Он је Тај Који вам је ноћ учинио покривачем, сан починком, а дан да се крећете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'И Он је Тај Који шаље ветрове као радосну вест, као претходницу Своје Милости; и Ми са неба чисту воду спуштамо', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'да њоме већ мртав предео оживимо и да многу стоку и многе људе које смо створили напојимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'И њима смо објаснили да би размислили, али већина људи осим неверништва одбија све.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Да хоћемо, у сваки град бисмо послали неког да опомиње.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Зато се не покоравај неверницима и Кур’аном се свим силама против њих бори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'Он је две водене површине једну поред друге оставио – једна је питка и слатка, друга слана и горка, а између њих је преграду и невидљиву брану поставио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'Он од воде ствара људе и чини да су род по крви и тазбини. Твој Господар је свемоћан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'Уместо Аллаха они обожавају оне који нису у стању неку корист да им прибаве нити од њих какву штету да отклоне. Неверник је ђаволу саучесник против његовог Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'А Ми смо те послали само зато да радосне вести доносиш и да опомињеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'Реци: „За ово од вас не тражим другу награду осим да онај који хоће пође путем који води његовом Господару.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Ти се поуздај у Живог, Који не може да умре, и величај Га, и хвали! А довољно је то што грехе Својих слуга у потпуности зна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'Онај Који је створио небеса и Земљу и оно што је међу њима у шест временских раздобља, а онда се узвисио над Престољем. Он је Свемилосни, и упитај о Њему онога који добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'А кад им се каже: „Ничице падните Свемилосном!“ Они питају: „А ко је Свемилосни? Зар да ничице падамо само зато што нам ти наређујеш?“ И то им повећа још већу одбојност.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Нека је Узвишен Онај Који је на небу створио сазвежђа и на њему дао Светиљку и Месец који сија.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'Он је учинио да се смењују ноћ и дан, и у њима је прилика за онога који жели да размисли и прими поуку или жели да буде захвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'А слуге Милостивог су они који се по Земљи у миру крећу, а кад им се бестидници обрате, одговарају: “Мир вама!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'и они који проводе ноћи пред Господаром својим на тло падајући и стојећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'И они који говоре: „Господару наш, поштеди нас патње у Паклу јер је патња у њему, заиста, пропаст неминовна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'Он је ружно пребивалиште и боравиште“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'и они који, кад удељују, не расипају и не шкртаре, већ се у томе држе средине;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'и они који мимо Аллаха другог бога не моле, и који, оне које је Аллах забранио, не убијају, осим када правда то захтева, и који не блудниче; а ко то ради, искусиће казну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Патња ће да му буде удвостручена на Будућем свету и вечно ће у њој да остане понижен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'Али они који се покају и поверују и раде добра дела; Аллах ће њихова лоша дела у добра да промени, а Аллах грехе опрашта и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'А онај који се буде покајао и радио добра дела, он се, уистину, Аллаху искрено вратио;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, 'И они који не сведоче лажно и који, пролазећи поред оног што их се не тиче, пролазе достојанствено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'и они који, када буду опоменути доказима свога Господара, ни глуви ни слепи на њих не остану;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'и они који говоре: “Господару наш, подари нам у женама нашим и деци нашој радост и учини да се честити на нас угледају!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Они ће да буду, за оно што су трпели, рајским одајама награђени и у њима ће поздравом добродошлице и благословом бити дочекивани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'У њима ће да остану вечно, а како су оне дивно пребивалиште и боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'Реци: “Господар мој вам поклања пажњу само због ваше молитве, а пошто сте ви порицали, неминовно вас чека патња."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Та-син-мим.[1]', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Ово су речи и докази јасне Књиге!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, 'Зар ћеш себе да упропастиш зато што они неће да поверују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Кад бисмо хтели, Ми бисмо им са неба послали знак пред којим би се они повиновали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'И њима не дође ниједна нова опомена од Свемилосног, а да се од ње не окрену.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Они поричу – па стићи ће их сигурно последице оног чему се изругују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Зар они не виде како чинимо да из земље ниче разноврсно племенито биље?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'То је заиста доказ, али већина њих не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'а твој Господар је, заиста, Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'А кад је твој Господар позвао Мојсија: „Иди насилничком народу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, 'фараоновом народу, не би ли постали богобојазни“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, 'Мојсије рече: „Господару мој, бојим се да ме они у лаж не утерају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, 'И да ми у души не постане тешко и да ми се језик не саплете; па дај посланство и Арону, да ми помогне;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'А према њима сам се огрешио, па се плашим да ме не убију.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, '„Неће!“ Рече Аллах. „Идите обојица са Нашим доказима, Ми ћемо са вама да будемо и слушамо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, 'Идите фараону и реците: ''Ми смо посланици Господара светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, 'Допусти да Израиљеви синови пођу са нама!''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, 'Фараон рече: „Зар те међу нама нисмо одгајали док си био дете и зар међу нама ниси провео толике године свога живота?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'И урадио си оно што си урадио и још си незахвалан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, '„Ја сам онда оно урадио а у заблуди сам био“, рече Мојсије,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, '„а од вас сам побегао зато што сам се вас бојао, па ми је Господар мој мудрост даровао и послаником ме учинио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'А доброчинство које ми пребацујеш - да није то што си Израиљеве синове поробио?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, '„А ко је Господар светова?“ Упита фараон.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, '„Господар небеса и Земље и онога што је између њих, ако чврсто верујете“, одговори он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, '„Чујете ли?“ Рече фараон онима око себе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, '„Ваш Господар и Господар ваших давних предака“, рекао је Мојсије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, '„Посланик који вам је послат, уистину је луд“, рече фараон.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, '„Господар истока и запада и онога што је између њих, ако разумете?“ Рече Мојсије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, 'А фараон рече: „Ако будеш признавао као бога некога другог осим мене, сигурно ћу у тамницу да те бацим!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, '„Зар и онда кад ти будем нешто што је очигледно донео?“ Упита он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, '„Па дај га, ако истину говориш!“ Рече фараон.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, 'И Мојсије баци свој штап, кад он - права змија.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'И руку своју извуче, кад она, онима који су гледали - бела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, '„Овај је, заиста, вешт чаробњак“, рече фараон главешинама око себе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, '„хоће да вас својом чаролијом из ваше земље изведе. Па шта саветујете?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, '„Остави њега и његовог брата!“ Рекоше, „а у градове пошаљи да сакупљају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'све веште чаробњаке ће ти довести.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'И сакупише чаробњаке у одређено време и означеног дана,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'а народу би речено: „Хоћете ли да се сакупите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'да будемо уз чаробњаке, ако они буду победници?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'А кад стигоше, чаробњаци упиташе фараона: „Да ли ће нама, заиста, да припадне награда ако ми будемо победници?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, '„Да“, одговори он, „и бићете тада, сигурно, од оних мени блиских.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Мојсије им рече: „Баците оно што желите да баците!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'И они побацаше своје конопце и своје штапове и рекоше: „Достојанства нам фараоновог, ми ћемо сигурно да победимо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Затим Мојсије баци свој штап, који одједном прогута оно што су они лажно извели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Чаробњаци онда ничице падоше', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'и рекоше: “Ми верујемо у Господара светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Мојсијевог и Ароновог Господара.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, '„Зар сте му поверовали пре мог допуштења?!“ Викну фараон, „он је ваш учитељ, он вас је научио чаробњаштву - а ви ћете да запамтите: поодсецаћу вам унакрст руке и ноге и све ћу да вас разапнем!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, '„Ништа страшно!“ Рекоше, „ми ћемо своме Господару да се вратимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'Ми се надамо да ће наш Господар да нам опрости грехе зато што смо први поверовали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'И Ми објависмо Мојсију: „Крени ноћу са Мојим слугама, али бићете гоњени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'И фараон посла сакупљаче по градовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, '„Заиста су ови мала скупина,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'и расрдили су нас,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'а сви смо спремни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'И Ми их изведосмо из вртова и река,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'из ризница и дивних двораца.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Тако је било, и Ми смо дали да то наследе Израиљеви синови,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'па их они, у зори, сустигоше,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'па кад једни друге угледаше, Мојсијеви следбеници повикаше: “Сустиће нас сигурно!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, '“Неће!” Рече он, “Господар мој је са мном, Он ће ми пут показати.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'И Ми објависмо Мојсију: „Удари штапом својим по мору!“ И оно се растави и свака његова страна је била као велико брдо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'и Ми онда тамо оне друге приближисмо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Мојсија и све оне који су били са њим спасисмо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'а оне друге потописмо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'У томе је, заиста, знак, али већина њих нису били верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'А, заиста, твој Господар је Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'И казуј им вест о Авраму,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'кад је свога оца и свој народ упитао: „Шта то ви обожавате?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, 'Они одговорише: „Обожавамо идоле и по цео дан им се молимо“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, 'он рече: „Да ли вас они чују када се молите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'или, да ли могу да вам користе или нашкоде?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, '„Не“, одговорише, „али ми смо упамтили наше претке како тако поступају.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, '„А да ли сте размишљали“, упита он, „да су они које обожавате', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'ви и ваши давни преци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'заиста, моји непријатељи? Али, то није Господар светова', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, 'Који ме је створио и Он ме на Прави пут упућује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'и Који ме храни и поји,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'и Који ме, кад се разболим, лечи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'и Који ће живот да ми одузме, и Који ће после да ме оживи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'и Који ће ми, надам се, грешке на Судњем дану опростити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, 'Господару мој, подари ми мудрост и придружи ме онима који су добри', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'и учини да ме спомињу по истини и добру они који ће доћи после мене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'и учини ме једним од оних којима ћеш рајске благодати даровати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'и мом оцу опрости, заиста је био међу залуталим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'и не понизи ме на Дан кад ће људи да буду оживљени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'на Дан кад неће никакво благо, а ни синови од користи бити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'само ће онај који дође Богу чистог срца да буде спашен.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, 'И Рај ће да се приближи богобојазнима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, 'а Пакао да се укаже заблуделима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, 'и рећи ће им се: „Где су они које сте обожавали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, 'а нисте Аллаха: могу ли они сада да вам помогну, или себи да помогну?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Па ће заједно са онима који су их у заблуду довели у Пакао бити бачени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'и Сотонине војске - сви заједно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'И они ће, свађајући се у њему, да говоре:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, '„Тако нам Аллаха, били смо, заиста, у очигледној заблуди', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'кад смо вас изједначавали са Господаром свих створења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'а само су нас зликовци на странпутицу завели,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'па немамо ни заговорника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'ни блиског пријатеља,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'да нам је само да се повратимо, па да постанемо верници!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'У томе је, заиста, знак, али већина њих ипак нису верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'А заиста је твој Господар – заиста је Он Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'И Нојев народ је сматрао посланике лажним', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Кад им брат њихов Ноје рече: “Како то да се Аллаха не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Ја сам вам, сигурно, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'За ово од вас не тражим никакву награду, мене ће да награди Господар свих светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, 'Они рекоше: „Како да те послушамо када те следе најнеугледнији људи?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, '“Не знам ја шта су они радили”, рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, '„Сви ће пред мојим Господаром, да знате, да полажу рачун,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'а ја вернике нећу да отерам,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'ја само јавно опомињем!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, '„Ако се не оканиш, о Ноја!“ Рекоше они, „бићеш сигурно каменован!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, '„Господару мој“, рече он, „народ мој ме у лаж утерује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'па Ти мени и њима пресуди и спаси мене и вернике који су са мном!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'И Ми смо спасили њега и оне који су били уз њега у крцатој лађи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'а остале смо потопили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'То је заиста доказ, али већина њих не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'А заиста је твој Господар – заиста је Он Силни и Милостиви!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, 'И народ Ад је сматрао лажним посланике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Кад им њихов брат Ебер рече: „Како то да се Аллаха не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Ја сам вам, сигурно, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'За ово од вас не тражим никакву награду, мене ће да награди Господар свих створења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Зашто на свакој узвишици палате зидате, друге исмејавајући,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'и подижете тврђаве као да ћете вечно да живите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'а кад кажњавате, кажњавате као силници?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Бојте се Оног Који вам дарује оно што знате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'дарује вам стоку и синове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'и баште и изворе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Ја се, заиста, за вас бојим патње на Великом дану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, 'Они рекоше: „Нама је свеједно саветовао ти или не саветовао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'овако су веровали и давни народи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'и ми нећемо да будемо подвргнути патњи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'И они су наставили да га утерују у лаж, па смо их Ми уништили. То је поука, али већина ових неће да верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'А Господар је твој заиста силан и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, 'И Семуд је сматрао лажним посланике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Кад им њихов брат Салах рече: „Како то да се Аллаха не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Ја сам вам, сигурно, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'За ово од вас не тражим никакву награду, мене ће да награди Господар светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Зар мислите да ћете овде да будете остављени сигурни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'у вртовима и међу изворима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'у усевима и међу палмама са зрелим плодовима?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'И ви у брдима врло спретно клешете куће,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'И не слушајте наредбе оних који у злу претерују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'који на Земљи неред чине и не поправљају се."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'Они рекоше: „Ти си само опчињен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'ти си човек, као и ми; зато нам донеси једно чудо ако је истина то што говориш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, '„Ево, то је камила“, рече он, „она ће да пије у одређени дан, а ви у одређени дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'и не чините јој никакво зло да вас не би стигла патња на Великом дану!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Али, они је заклаше и потом зажалише,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'и стиже их казна. У томе је, заиста, поука, али већина њих не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'А заиста је твој Господар - заиста је Он Силни и Милостиви!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'И Лотов народ је сматрао лажним посланике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Кад им њихов брат Лот рече: „Како то да се не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Ја сам вам, сигурно, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'За ово од вас не тражим никакву награду, мене ће да награди Господар светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Зашто ви, мимо свих светова, мушкарцима са страшћу прилазите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'а своје жене, које је за вас створио ваш Господар, остављате? Ви сте људи који прелазе сваку границу зла.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'Они рекоше: „Ако се не оканиш, о Лоте, бићеш сигурно прогнан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, '„Ја се грозим тога шта ви радите!“ Рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, '„Господару мој, сачувај мене и моју породицу од онога што они раде!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Ми смо сачували њега и његову породицу - све,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'осим старице која је остала са онима који су искусили казну,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'а затим смо остале уништили', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'спустивши на њих кишу - а страшне ли кише за оне који су били упозорени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'То је заиста доказ, али већина њих не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'А, заиста, твој Господар је Силни и Милостиви!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'И становници Ејке су угонили посланике у лаж.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Кад им Јофор рече: „Како то да се Аллаха не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Ја сам вам, сигурно, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'зато се бојте Аллаха и мени будите послушни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'За ово од вас не тражим никакву награду, мене ће да награди Господар светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Право мерите на литру и не закидајте,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'а на кантару мерите исправном мером,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'и људима њихова права не умањујте, и зло по Земљи, неред правећи, не чините,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'и бојте се Онога Који је створио и вас и давне народе.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, 'Они рекоше: „Ти си само опчињен;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'и ти си само човек као и ми; за нас си ти, заиста, прави лажов;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'зато спусти на нас казну са неба, ако си од оних који говоре истину!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, '„Господар мој добро зна шта ви радите“, рече он.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'И они су наставили да га утерују у лаж па их је стигла казна у Дану тамног облака; а то је била казна једног страшног дана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'То је заиста доказ, али већина њих не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'А, заиста, твој Господар је Силни и Милостиви!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'И Кур''ан је сигурно објава Господара светова;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'доноси га поверљиви анђео,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, 'на срце твоје, да опомињеш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'на јасном арапском језику.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'Он је споменут у књигама претходних посланика,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'зар њима није знак то што за њега знају учени људи Израиљевих синова?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'А да га објављујемо неком неарапу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'па да им га он чита, опет у њега не би поверовали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Ето, тако га Ми уводимо у срца грешника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'они у њега неће да верују док не виде болну патњу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'која ће изненада да им дође, а они неће ни да осете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'па ће рећи: „Хоће ли нам се дати мало времена?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Па зар они пожурују Нашу казну?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Шта ти мислиш, ако им Ми допуштамо да уживају годинама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'и на крају их снађе оно чиме им се прети,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'зар ће им користи сладак живот који су проводили?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Ми ниједно насеље нисмо разорили а да им нису послати они који су их упозоравали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'да би поуку примили, Ми нисмо неправедни били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Кур''ан не доносе ђаволи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'незамисливо је да то они раде; и они то не могу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Они су потпуно спречени и да га прислушкују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'Зато се, мимо Аллаха, не моли другом богу - да не би био од оних који ће да буду мучени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'И упозоравај своју најближу родбину,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'и буди понизан према верницима који те следе!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'А ако те не буду послушали, ти реци: „Ја немам ништа са тим што ви радите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'И поуздај се у Силног и Милостивог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'Који те види кад устанеш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'да са осталима молитву обавиш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'јер Он, заиста, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Хоћете ли да вас обавестим коме долазе ђаволи?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Они долазе сваком лажову, грешнику,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'и прислушкују, а већина њих су лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'А заведени следе песнике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Зар не знаш да они сваком долином блуде', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'и да говоре оно што не раде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'тако не говоре само они који верују и добра дела чине, и који често Бога спомињу, и који узвраћају кад их исмејавају. А многобошци ће, сигурно, сазнати у какву ће се муку увалити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Та-син. Ово су речи Кур''ана и јасне Књиге,[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'упуте и радосне вести онима који верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'који молитву обављају и милостињу удељују и који у Будући свет чврсто верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Заиста онима који у Онај свет не верују Ми приказујемо њихове поступке лепим - зато они лутају;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'то су они којима припада жестока патња, а на Будућем свету они ће, заиста, да буду највећи губитници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'а ти, заиста, примаш Кур''ан од Мудрог, Свезнајућег!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, 'Када Мојсије рече својој породици: „Видео сам ватру, донећу вам отуда какву вест, или ћу да вам донесем пламену бакљу да бисте се огрејали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Кад је дошао до ње, неки глас је дозивао: „Нека су благословљени они који се налазе на месту где је ватра и они око ње, и нека је слављен и узвишен Аллах, Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'О Мојсије, Ја сам - Аллах, Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'Баци свој штап!“ Па кад виде да се, као да је хитра змија, креће, он узмаче и не врати се. "О Мојсије, не бој се! Посланици код Мене не требају ничега да се боје;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'А оном који грех почини, а онда зло добрим делом замени – Ја ћу, уистину, опростити и самилостан бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Увуци своју руку у своја недра, појавиће се бела, али неће да буде болесна - биће један од девет знакова фараону и његовом народу; они су, заиста, народ невернички.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'И кад им јасно дођоше Наши знаци, рекоше: „Ово је права чаролија!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'И они их, неправедни и охоли, порекоше, али су у себи веровали да су истинита, па погледај како су скончали смутљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Давиду и Соломону смо дали знање и они су говорили: „Хвала Аллаху Који нас је одликовао над многим Својим слугама верницима!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'И Соломон наследи Давида и рече: „О људи, дато нам је да разумемо птичје гласове и свашта нам је дато: ово је, заиста, права благодат!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'И сакупише се Соломону војске његове – духови, људи и птице, све чета до чете, постројени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'и кад стигоше до мравље долине, један мрав рече: „О мрави, улазите у своја станишта да вас не погазе Соломон и његове војске, а да то и не примете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'И он се насмеши његовим речима и рече: „Мој Господару, надахни ме да будем захвалан на Твојој благодати, коју си указао мени и мојим родитељима, и да чиним добра дела на Твоје задовољство, и уведи ме, Својом милошћу, међу Своје добре слуге!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'И он изврши смотру птица, па рече: „Зашто не видим пупавца, да није одсутан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'Ако ми не донесе ваљано оправдање, тешком ћу га казном казнити или ћу га заклати!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'И не потраје дуго, а он дође, па рече: “Дознао сам оно што ти не знаш, из Сабе ти доносим поуздану вест.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Видео сам да једна жена њима влада и да јој је дато свега и свачега, а има и величанствени престо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Видео сам да се и она и њен народ клањају Сунцу, а не Аллаху, а Сотона им је приказао њихове поступке лепим и од правог пута их одвратио, па они не умеју да нађу Прави пут,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'па да се Аллаху клањају, Који изводи оно што је скривено на небесима и на Земљи и Који зна оно што кријете и оно што на јаву износите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Аллах је, нема истинског бога осим Њега, Господар Величанственог Престола!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, '„Видећемо“, рече Соломон, „да ли говориш истину или не.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Однеси ово моје писмо па им га баци, а онда се од њих мало измакни и погледај шта ће једни другима рећи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, '„О великани“, рече она, „мени је достављено једно писмо вредно поштовања!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'од Соломона и гласи: ‘У име Аллаха, Милостивог, Самилосног!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Не будите охоли преда мном и дођите ми Аллаху предани.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, '„О великани“, рече она, „саветујте ми шта треба у овом случају да радим; ја без вас ништа нећу да одлучим!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, '„Ми смо врло јаки и храбри“, рекоше они, „а ти одлучујеш. Па, гледај шта ћеш да наредиш!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, '„Кад цареви освоје неки град“, рече она, „они га разоре, а угледне његове становнике учине пониженим.“ Ето, тако они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, '„Послаћу им један дар и видећу са чиме ће изасланици да се врате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'И кад он пред Соломона изађе, овај му рече: “Зар да благом мене придобијете? Оно што ми је Аллах дао боље је од оног што је дао вама. Ви се оном што вам се дарује радујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'Врати се њима! Ми ћемо да доведемо војске којима неће моћи да се одупру и истераћемо их из Сабе понижене и покорене.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'О достојанственици, ко ће од вас да ми донесе њен престо пре него што ми дођу као Аллаху предани?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, '„Ја ћу да ти га донесем“, рече Ифрит, један од духова, „пре него што са свог места устанеш, ја сам за то, заиста, снажан и поуздан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'А ја ћу да га донесем“, рече онај који је имао знање из Књиге, “пре него што оком трепнеш.” И кад Соломон виде да је престо већ пред њим постављен, узвикну: „Ово је благодат мога Господара, Који ме искушава да ли ћу да будем захвалан или незахвалан. А ко је захвалан – у своју корист је захвалан, а ко је незахвалан - па, мој Господар је независан и племенит.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Промените изглед њеног престола да видимо хоће ли га или неће препознати!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'И кад она дође, би јој речено: „Је ли овакав твој престо?“ „Као да јесте!“ Она узвикну. „А нама је дато знање пре него њој, и ми смо Аллаху предани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'А од исправног веровања спречило је оно што је обожавала мимо Аллаха. Јер је она народу неверничком припадала.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'Би јој речено: „Уђи у дворану!“ Кад она погледа, помисли да је дубока вода, па задиже хаљину уз своје ноге. „Овај је дворац поплочан углачаним стаклом!“ Рече он. „Мој Господару!“ Узвикну она, „ја сам се према себи огрешила и у друштву са Соломоном предајем се Аллаху, Господару светова!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'А народу Семуд послали смо њиховог брата Салаха који им је говорио: „Обожавајте једино Аллаха“, али они се поделише у две групе које су се међусобно препирале.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, '“О народе мој”, говорио им је он, “зашто тражите да вас стигне казна пре него што се покајете? Зашто од Аллаха не тражите опроста да би вам се указала милост?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, '“Ми сматрамо лошим предзнаком тебе и оне који су с тобом!” Рекоше они. “Од Аллаха вам је и добро и зло”, рече он, “ви сте народ који је стављен у искушење.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'У граду је било девет особа које су по Земљи, уместо ред, неред чиниле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, '„Аллахом се закуните“, рекоше, „да ћемо ноћу и њега и његову породицу да убијемо, а онда његовом сроднику да кажемо: ''Ми нисмо присуствовали погибији његове породице, ми, заиста, истину говоримо.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'И ковали су сплетку, па смо и Ми припремили њима сплетку, а они то нису осећали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'па погледај каква је била последица њиховог сплеткарења: уништили смо све - и њих и њихов народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'Ено њихових кућа, пусте су због насиља који су чинили - у томе је, заиста, поука народу који зна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'а спасили смо оне који су веровали и који су се греха клонили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'И Лота смо послали када рече своме народу: „Зар чините разврат наочиглед једни других?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'Зар збиља са страшћу општите са мушкарцима уместо са женама? Ви сте, уистину, безумници.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'А одговор његовог народа само је гласио: „Истерајте Лотову породицу из вашег града, они су, заиста, људи чистунци!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'И Ми смо спасили њега и његову породицу, осим његове жене. Ми смо одредили да она остане с онима који ће казну искусити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'И сручили смо на њих камену кишу, а страшне ли кише за оне који су били упозорени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'Реци: „Хвала Аллаху и нека је мир Његовим слугама које је Он одабрао!“ Шта је боље: Аллах или они које поред Њега обожавају?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Онај Који је небеса и Земљу створио и Који вам спушта са неба кишу помоћу које Ми дајемо да озелене прекрасне баште, немогуће је да ви учините да израсте њихово дрвеће. Зар поред Аллаха постоји други бог?! Не постоји, али су они народ који друге са Њим изједначује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Онај Који је Земљу учинио пребивалиштем и кроз њу је провео реке и на њој је поставио непомична брда и између два мора учинио преграду. Зар поред Аллаха постоји други бог?! Не постоји, него већина њих у незнању живи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Онај Који се невољнику, кад Му се обрати, одазива, и Који зло отклања и Који вас на Земљи једне другима смењује. Зар поред Аллаха постоји други бог?! Како никако поуку ви да примите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Онај Који вам у тминама, на копну и на мору, показује пут и Који ветрове као радосну вест испред Своје милости шаље. Зар поред Аллаха постоји други бог?! Како је Аллах високо изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Онај Који све из ничега ствара, Који ће затим то поново да учини, и Који вам опскрбу са неба и из земље даје. Зар поред Аллаха постоји други бог?! Реци: „Докажите, ако истину говорите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'Реци: „Нико, осим Аллаха, ни на небу ни на Земљи, не зна оно што је недокучиво чулима; и они не знају када ће да буду оживљени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Они о Будућем свету ништа не знају! Они у њега још и сумњају, па чак су и слепи у вези са тим!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Неверници говоре: „Зар ћемо, кад постанемо земља, и ми и наши преци, заиста, да будемо оживљени?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Овим нам се већ одавно прети, и нама и прецима нашим, а ово су само измишљотине народа древних.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'Реци: “Путујте по свету и видите како су завршили грешници!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'И не тугуј због њих и нека ти није тешко у души због њихових сплетки.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, '“Кад ће се већ једном обистинити та претња, ако истину говорите?” Питају они.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'Реци: „Стићи ће вас сигурно нешто од онога што пожурујете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'А твој Господар је неизмерно добар према људима, али већина њих није захвална.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Твој Господар добро зна оно што њихове груди крију и оно што они јавно износе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Нема ничег скривеног ни на небу ни на Земљи, а да није у јасној Књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Овај Кур''ан казује Израиљевим синовима највише о ономе у чему се они разилазе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'и он је, уистину, путоказ и милост сваком оном који верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Твој Господар ће по Својој правди да им пресуди; Он је Силни и Свезнајући,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'зато се поуздај у Аллаха, јер ти, заиста, следиш праву истину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Ти не можеш мртве да дозовеш нити глуве да довичеш кад се леђима окрену.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Нити можеш слепе од заблуде њихове да одвратиш. Можеш једино да дозовеш оне који у речи Наше верују, они ће Аллаху да се предају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'И кад дође време да се оствари казна над њима, Ми ћемо учинити да из земље изађе једна животиња која ће им рећи да људи у доказе Наше нису уверени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'А на Дан када од сваког народа сакупимо гомилу оних који су порицали Наше речи и доказе - они ће бити вођени у строју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'А кад дођу, Он ће да упита: „Јесте ли ви порицали Моје речи и доказе не размишљајући о њима, или шта сте то радили?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'И њих ће стићи казна зато што су незнанобошци били, па неће моћи ни реч да изусте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Зар не виде да смо учинили ноћ да у њој имају спокоја, а дан видним за рад?! То су, заиста, докази за народ који верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'А на Дан кад се дувне у рог па се смртно престраве и они на небесима и они на Земљи, изузев оних које Аллах буде хтео да поштеди, сви ће понизно да Му дођу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'Ти видиш планине и мислиш да су непомичне, а оне се крећу као што се облаци крећу, то је Аллахово дело - Који је све савршено створио; Он, заиста, у потпуности зна оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Они који учине добро дело, имаће бољу награду за то, и биће поштеђени страха на Судњем дану,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'а они који буду чинили зло, у Ватру ће наглавачке да буду гурнути. „Па зар бивате кажњени осим за оно што сте радили?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'Ја сам примио заповест да обожавам једино Господара овог града који је Он учинио светим – а Њему све припада – и наређено ми је да будем Аллаху предан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'и да казујем Кур''ан; онај ко буде ишао Правим путем на Правом путу је за своје добро, а ономе који је у заблуди ти реци: "Ја само упозоравам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'И реци: “Хвала Аллаху, Он ће вам знамења Своја показати, па ћете их ви познати!” А Господар твој мотри на оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Та-син-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Ово су речи јасне Књиге!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Ми ћемо ти казати неке вести о Мојсију и фараону, онако како је било, и то за оне људе који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Заиста се фараон на Земљи охолио и становнике њене на странке је изделио; једне је тлачио, мушку им децу клао, а женску у животу остављао, заиста је смутљивац био.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'А Ми смо хтели да оне који су на Земљи тлачени милошћу обаспемо и да их вођама и наследницима учинимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'И да им на Земљи власт дарујемо, а да фараону и Хаману и војскама њиховим дамо да доживе баш оно због чега су од њих страховали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'И ми смо надахнули Мојсијеву мајку: „Доји га, а кад се уплашиш за његов живот, спусти га у реку, и не страхуј и не тугуј, Ми ћемо, заиста, да ти га вратимо и једним од посланика ћемо да га учинимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'И нађоше га фараонови људи, да им постане непријатељ и туга; заиста су фараон и Хаман и војске њихове увек грешили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'И фараонова жена рече: „Он ће да буде радост и мени и теби! Не убијте га, можда ће да нам буде од користи, а можемо и да га посинимо“; и они ништа не предосетише.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'И срце Мојсијеве мајке постаде празно, и готово би га открила да Ми њено срце нисмо учврстили и верницом је учинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'И она рече његовој сестри: „Иди за њим!“ И она га је гледала издалека, а они нису ништа приметили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'А Ми смо му већ били забранили дојиље, па она рече: „Хоћете ли да вам ја покажем породицу која ће о њему да се брине и која ће добро да му жели?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'И вратисмо га његовој мајци да се радује и да не тугује, и да се увери да је истинито Аллахово обећање; али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'И кад он достиже врхунац своје снаге и потпуно стаса, дали смо му мудрост и знање; тако Ми награђујемо оне који раде добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'И он уђе у град неопажен од становника његових и у њему затече двојицу људи како се туку, један је припадао његовом, а други непријатељском народу, па га је позвао у помоћ онај из његовог народа против оног из непријатељског народа, и Мојсије га удари и усмрти. ''Ово је Сотонино дело!'' – Узвикну -, ''он је, заиста, отворени непријатељ који у заблуду доводи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, '“Господару мој”, рече, “ја сам сам себи зло нанео, опрости ми!” И Он му опрости, Он, уистину, прашта и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, '“Господару мој”, рече, “због благодати коју си ми указао, више никад неправеднима нећу бити од помоћи!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'И Мојсије у граду освану престрашен, очекујући шта ће бити, кад га онај исти од јуче позва поново у помоћ. “Ти си, збиља, у правој заблуди!” Рече.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'И кад хтеде шчепати заједничког им непријатеља, рече му онај: “О Мојсије, зар ћеш убити и мене као што си јуче убио човека? Ти хоћеш на Земљи силу проводити, а не желиш мирити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'И један човек са краја града дотрча: „О Мојсије“, рече, „главешине се договарају да те убију, зато одлази, ја сам ти, заиста, искрен саветник!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'И Мојсије изађе из града, преплашен, ишчекујући шта ће да се деси. “Господару мој”, рече, “спаси ме народа који не верује!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'И кад се упути према Медену, он рече: “Господар мој ће ми показати прави пут!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'А кад стиже до меденске воде, затече око ње групу људи како напајају стоку а мало даље од њих угледа две жене које су је од воде одбијале. „Шта је са вама?“ Упита он. „Ми не напајамо док чобани не отерају стоку!“ Одговорише оне, „а отац нам је веома стар.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'И он им је напоји, а онда оде у хладовину и рече: “Господару мој, ма какву ми храну дао, заиста ми је потребна!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'А затим, једна од њих две му дође идући стидљиво и рече: „Мој отац те зове да те награди за то што си нам стоку напојио!“ И кад му он дође и каза шта је доживео, он рече: „Не страхуј, спасио си се народа који не верује!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, '„О мој оче, „рече једна од њих, „узми га у најам, најбоље је да унајмиш оног ко је снажан и поуздан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, '„Ја желим да те оженим једном од ове моје две кћери“, рече он, „али треба да ме служиш осам година; а ако напуниш десет биће твоја добра воља, а ја не желим да те на то силим; ти ћеш видети, ако Аллах да, да сам добар.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, '„У реду, то је договор између мене и тебе!“ Рече Мојсије, „који год од та два рока испуним нема шта да ми се приговори, а Аллах је гарант за оно што смо утаначили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'И када Мојсије испуни уговорени рок и крену са својом породицом, он угледа ватру на једној страни брда и рече својој породици: „Сачекајте, угледао сам ватру, можда ћу од ње какву вест да вам донесем, или запаљену бакљу, па да се огрејете.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'А кад дође до ватре, неко га зовну са десне стране долине, поред стабла, у благословљеном крају: „О Мојсије, Ја сам, збиља, Аллах, Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'Баци штап свој!” И кад виде да се попут хитре змије креће, он узмаче и не врати се. “О Мојсије, приђи и не бој се, сигурно ти се никакво зло догодити неће!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'Увуци своју руку у недра своја, појавиће се бела, а без мане, и прибери се тако од страха! То су два доказа од Господара твог фараону и главешинама његовим; они су, заиста, народ одметнички.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, '„Господару мој“, рече, „ја сам убио једног њиховог човека, па се бојим да и они мене не убију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'А мој брат Арон је речитији од мене, па пошаљи са мном и њега, као мог помоћника, да потврђује моје речи, јер се бојим да ме не назову лажовом.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, '„Помоћи ћемо те твојим братом“, рече Он, „и обојици ћемо власт дати, па вам се они неће усудити прићи због Наших доказа. Вас двојица ћете, и они који вас буду следили, да будете победници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'И кад им Мојсије донесе Наше јасне доказе, они повикаше: „Ово је само смишљена магија, нисмо чули да се овако нешто дешавало у доба наших предака!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, '“Господар мој добро зна оног који доноси упутство од Њега”, рече Мојсије, “оног који ће на крају да победи – а неверници заиста неће успети!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, '„О великани“, рече фараон, „ја не знам да ви имате другог бога осим мене а ти, о Хамане, пеци за мене опеке и сагради ми торањ да се попнем ка Мојсијевом Богу, јер ја мислим да је он, заиста, један од лажова!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'А он и његове војске су се, без икаквог права, охолили на Земљи и мислили су да нам се неће вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Па ми дохватисмо и њега и његове војске и у море их бацисмо; погледај како су скончали неверници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'А били смо их учинили вођама који су позивали у оно због чега се иде у ватру – а на Судњем дану нико им неће помоћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'И прогонило их је проклетство на овом свету, а на Судњем дану биће међу презренима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'И Ми смо Мојсију дали Књигу, након што смо уништили древне народе, да буде светло људима, и упута, и милост, да би се присетили и примили поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'Ти ниси био на страни западној кад смо Мојсију посланство поверили, а ниси био ни његов савременик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Ми смо многе народе подигли и они су дуго живели, а ти ниси боравио међу становницима Медена и речи им Наше казивао него ти Ми о њима казујемо вести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Ти ниси био поред брда кад смо Мојсија позвали, али Ми смо те послали као милост Господара твог да опомињеш људе којима пре тебе није дошао нико ко би их опоменуо, да би се опаметили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'И да не кажу, када их задеси несрећа због онога што су починили: „Господару наш, зашто нам ниси послао посланика, па да Твоје доказе следимо и да будемо верници?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'А кад им долази Истина од нас, они говоре: „Зашто му није дато исто као што је дато Мојсију?“ А зар они нису порекли оно што је дато Мојсију раније?! Они говоре: „Две чаролије, једна другу подржава“, и говоре: „Ми ни у једну не верујемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'Реци: „Па донесите ви од Аллаха књигу која боље, него ове две, на Прави пут упућује, њу бих следио, ако истину говорите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Па ако ти се не одазову, онда знај да се они поводе једино за страстима својим. А зар је ико горе залутао од оног који следи страст своју, а не Аллахову упуту? Аллах, заиста, неће указати на Прави пут народу који је неправедан према себи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'А Ми смо им Реч темељно доставили како би се опаметили и примили поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Они којима смо дали Књигу пре Кур''ана, верују у њега,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'а када им се он казује, говоре: „Ми верујемо у њега, он је Истина од нашег Господара, ми смо и пре били Аллаху предани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'Они ће да добију двоструку награду за то што трпе и што лепим на зло узвраћају и што од онога што им дајемо удељују;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'а кад чују какву бесмислицу, од ње се окрену и кажу: „Нама наша, а вама ваша дела, од нас сте мирни! Ми не желимо друштво неуких.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Ти, заиста, не можеш упутити на Прави пут оног кога ти желиш да упутиш. Аллах указује на Прави пут оном коме Он хоће, и Он добро зна оне који ће Правим путем поћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'Они говоре: “Ако с тобом будемо Прави пут следили, бићемо брзо из родног краја протерани.” Зар им Ми не пружамо прилику да бораве у светом и сигурном месту где се, као Наш дар, сливају плодови разноврсни; међутим, већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'А колико смо Ми насеља уништили, чији су становници према ономе што им је дато у животу били незахвални! Ето домова њихових, мало ко, после њих, наврати у њих, Нама су остали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'А Господар твој никада није насеља уништавао док у њихов главни град посланика не би послао, да им речи и доказе Наше казује. И Ми смо насеља уништавали само онда кад су становници њихови незнанобошци били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Све што вам је даровано само су насладе и украси у овосветском животу, а оно што је код Аллаха боље је и трајно. Зар не разумете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Како може да буде једнак онај коме смо обећали лепу награду коју ће да добије, и онај коме смо дали да се наслађује у овосветском животу, а који ће после, на Судњем дану, Ватри да буде приведен?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'А на Дан кад их Он позове и упита: “Где су они које сте поред Менe обожавали?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'Рећи ће они на којима ће реч да се обистини: „Господару наш, ове што смо навели на странпутицу, навели смо зато што смо и сами били на странпутици, ми их се пред Тобом одричемо, они нас нису обожавали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, '“Позовите божанства ваша!” Рећи ће им се, па ће их они позивати, али им се она неће одазвати, и патњу ће доживети. Да су само на Правом путу били!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'А на Дан кад их Он позове и упита: „Како сте се посланицима одазвали?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'Тог Дана они неће знати шта да одговоре, па ни један другог неће ништа питати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'А онај који се буде покајао, и који буде веровао, и који буде добра дела чинио – он ће бити од оних који ће успети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Твој Господар ствара шта хоће, и Он одабира. Они немају право да бирају. Узвишен нека је Аллах и врло високо изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Твој Господар зна оно што крију њихове груди и оно што они обзнањују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Он је Аллах, нема другог истинског бога осим Њега; Њему нека је сва хвала и на овом и на Будућем свету! Пресуда припада само Њему и Њему ћете да се вратите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'Реци: „Шта мислите, ако би Аллах дао да вам ноћ потраје вечно, до Судњег дана, који бог би вам, осим Аллаха, дао светлост?! Зар не чујете?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'Реци: „Кажите ви мени, ако би Аллах дао да вам дан потраје вечно, до Судњег дана, који би вам бог, осим Аллаха, ноћ дао да у њој нађете смирај?! Зар не видите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Из Своје милости Он вам је дао ноћ и дан - да се ноћу одмарате а да дању за Његовим добрима трагате и да будете захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'А на Дан кад их Он позове и упита: “Где су божанства које сте поред Мене обожавали?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'И из сваког народа довешћемо сведока и рећи: „Дајте свој доказ!“ И они ће да сазнају да истина припада једино Аллаху, а неће да им буде оних које су измишљали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Карун је био из Мојсијевог народа, па их је тлачио, а били смо му дали толико блага да је његове кључеве тешко могла да носи група снажних људи. Па му његов народ рече: „Не буди незахвалан, јер Аллах не воли оне који су незахвални!“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, '„И настој да тиме што ти је дао Аллах стекнеш Будући свет, а не заборави ни свој удео на овом свету, и чини добро као што је Аллах теби учинио добро, и не чини неред по Земљи, заиста Аллах не воли оне који чине неред.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, '“Ово ми је дато на основу мог знања!” Говорио је он. А зар није знао да је Аллах пре њега уништио неке народе који су били од њега јачи и који су били више накупили – а злочинци неће о гресима својим ни испитивани бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'И изађе он пред народ свој у свом сјају. “Ах, да је и нама оно што је дато Каруну”, говорили су они који су чезнули за животом на овом свету, “он је, уистину, пресрећан.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, '“Тешко вама”, говорили су учени, "онима који верују и раде добра дела боља је Аллахова награда, а она ће само стрпљивима да буде пружена.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'И Ми смо и њега и његов дворац у земљу утерали, и нико од Аллаха није могао да га одбрани, а ни сам себи није могао да помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'А они који су раније прижељкивали да су на његовом месту, стадоше да говоре: „Зар не видите да Аллах даје обиље оном од Својих слугу коме Он хоће, а и да ускраћује?! Да нам Аллах није Своју милост указао и нас би у земљу утерао! Зар не видите да неверници никад неће успети?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'Тај Будући свет даћемо онима који не желе на Земљи да се охоле и неред да чине, а богобојазне чека срећан крај.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Онај ко уради добро дело, добиће бољу награду за њега, а онај ко уради зло, па они који буду радили зло, биће кажњени само у сразмери са оним што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Онај Који ти објављује Кур’ан сигурно ће да те на Будући свет врати. Реци: “Господар мој добро зна ко је на Правом путу и ко је у очитој заблуди.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Ти ниси очекивао да ће Књига да ти буде објављена, али она ти је објављена као милост твога Господара, зато никако не буди помагач неверницима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'И нека те они никако не одврате од Аллахових речи, кад ти се објаве, и позивај Господару свом и никако не буди од оних који друге поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'И не моли, поред Аллаха, другог бога! Нема истинског бога осим Њега! Све ће, осим Њега, да пропадне! Њему припада суд и Њему ћете се вратити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Елиф-лам-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'Зар мисле људи да ће да буду препуштени сами себи ако кажу: “Ми верујемо!” И да неће да буду искушавани?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'А ми смо искушавали и оне пре њих, да би Аллах сигурно указао на оне који говоре истину и на оне који лажу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Зар мисле они који раде зла дела да ће Нама да умакну?! Лоше ли је оно што просуђују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Онај ко се нада сусрету с Аллахом – па доћи ће, сигурно, Дан обећани. А Он све чује и све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'А онај ко се бори - бори се само за себе, заиста, Аллах је независан од свих светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'Онима који верују и добра дела чине прећи ћемо сигурно преко лоших поступака њихових и за оно што су радили заиста ћемо их најлепшом наградом наградити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'Ми смо сваком човеку наредили да буде добар према родитељима својим. Али, ако те они буду наговарали да поред Мене неког другог обожаваш, о коме ти ништа не знаш, онда им се не покоравај. Мени ћете се вратити, па ћу Ја о ономе што сте радили да вас обавестим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'Оне који верују и раде добра дела сигурно ћемо да уврстимо међу оне који су добри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Има људи који говоре: „Верујемо у Аллаха!“ А кад неки од њих буде стављен на муке због Аллаха, он сматра да је искушење од људи исто као и Аллахова казна. А ако победа дође од твога Господара, сигурно ће они да кажу: „Били смо уз вас!“ А зар Аллах не зна најбоље оно што је у свачијим грудима?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'Аллах сигурно зна оне који верују и сигурно зна оне који су дволични.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Они који не верују говоре онима који верују: „Следите наш пут, а ми ћемо да носимо ваше грехе!“ А не би понели ниједан њихов грех. Они су, заиста, лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'А сигурно ће властите терете и терете оних које су одвели у заблуду да носе, и сигурно ће за оно што су измишљали на Судњем дану да одговарају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Ми смо Ноја послали његовом народу и он је међу њима остао хиљаду, мање педесет година, па их је потом задесио потоп, зато што су незнанобошци били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'И Ми смо њега и оне што су били у лађи спасили, и поучним примером световима је учинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'А и Аврама, кад је своме народу рекао: „Аллаха обожавајте и Њега се бојте, то вам је боље, кад бисте само знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'Ви, мимо Аллаха, обожавате идоле и смишљате лажи. Они које ви, мимо Аллаха, обожавате не могу никаквом опскрбом да вас опскрбе; ви тражите опскрбу од Аллаха и Њега обожавајте и Њему будите захвални! Њему ћете да се вратите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'А ако ви поричете, па већ су порицали народи пре вас; а Посланик је једино дужан да јасно обзнани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Зар ови не виде како Аллах све из ничег ствара? Он ће то опет да учини; Аллаху је то, заиста, лако.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'Реци: “Путујте по свету да видите шта је Он из ничег створио. И, Аллах ће то, после, по други пут да створи. Аллах, заиста, све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'Он кажњава онога кога Он хоће и милост указује ономе коме Он хоће, Њему ћете да будете враћени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Његовој казни нећете умаћи ни на Земљи ни на небу, а немате, мимо Аллаха, ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'А они који не верују у Аллахове речи и доказе и у сусрет са Њим, њима није стало до Моје милости – њих чека патња несносна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Одговор његовог народа беше само то што рекоше: „Убијте га или га спалите!“ Али, Аллах га је избавио из ватре. У томе су, заиста, докази народу који верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, '„Ви сте“, рече он, „мимо Аллаха прихватили кипове да бисте у овосветском животу одржавали међусобне пријатељске односе, а после, на Судњем дану, једни других ћете да се одричете и једни друге ћете да проклињете, Ватра ће да буде ваше боравиште и нико вам у помоћ неће моћи притећи.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'И Лот му је једини поверовао! А Аврам рече: „Ја се, уистину, селим тамо где ми је мој Господар наредио. Он је, заиста, Силни и Мудри.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'И Ми смо му подарили Исака и Јакова и међу његовим потомцима смо дали веровесништво и Књигу; а њему смо на овом свету леп спомен сачували, а на Оном ће, заиста, један од оних добрих бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'И спомени Лота. Када народу своме рече: „Ви чините такав разврат какав пре вас нико од свих светова није чинио:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'имате полне односе са мушкарцима, по друмовима пресрећете и на својим скуповима радите оно што је одвратно.“ А одговор његовог народа беше само то што рекоше: „Учини да нас стигне Аллахова казна ако си од оних који говоре истину!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, '“Господару мој”, рече он, “помози ми против искварених људи!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'И кад Наши изасланици Авраму донесоше радосну вест, рекоше: „Ми ћемо да уништимо становнике онога насеља! Његови становници су заиста неверници!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, '„У њему је Лот“, рече Аврам. „Ми добро знамо ко је у њему“, рекоше они, „ми ћемо да спасимо њега и његову породицу, осим његове жене. Она ће да остане са онима који ће да искусе казну.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'И кад Наши изасланици дођоше Лоту, он се због њих обневесели и узнемири. „Не бој се и не брини се“, рекоше они, „ми ћемо да спасимо тебе и породицу, осим твоје жене, она ће да остане са онима који ће да искусе казну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'А на становнике овог града спустићемо страшну казну са неба због тога што су развратници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'И од њега смо оставили јасан знак људима који буду памети имали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'А у Меден посласмо њиховог брата Шуајба: „О мој народе“, говорио је он, „Аллаха обожавајте, и очекујте Судњи дан, и не чините зло по Земљи правећи неред!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Али му они не повероваше, па их задеси страшан потрес и они освануше у земљи својој мртви, непомични.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'А и Ада и Семуда - остаци њихових домова су вам видљиви - а ђаво им је њихове поступке лепим приказао, па их, од Правог пута одвратио, а били су разумни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'И Каруна и фараона и Хамана; Мојсије им је донео јасне доказе, али су се они на Земљи охолили и нису могли да умакну казни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'и све смо казнили према њиховим гресима: на неке смо послали ветар пун песка, а неке смо уништили страшним гласом, неке смо утерали у земљу, а неке потопили; Аллах им није учинио неправду, сами су себи неправду нанели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Они који, мимо Аллаха, узимају заштитнике слични су пауку који себи исплете кућу, а најслабија кућа, засигурно, је паукова кућа, кад би само знали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Аллах добро зна да ови које они, поред Њега, обожавају ништа не представљају; Он је Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'То су примери које Ми наводимо људима, али их само учени схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Бог је небеса и Земљу с разлогом створио; то је, заиста, поука онима који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'Казуј Књигу која ти се објављује и обављај молитву - молитва, заиста, одвраћа од разврата и од свега што је ружно; а слављење Бога је сигурно веће! Бог зна шта радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'И са следбеницима Књиге расправљајте на најлепши начин, али не и с онима међу њима који су неправедни, и реците: „Ми верујемо у оно што се нама објављује и у оно што је вама објављено, а наш Бог и ваш Бог је један, и Њему смо ми предани!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Тако исто и теби објављујемо Књигу, а неки од оних којима смо већ дали Књигу - и у њу верују, а и међу овима има оних који у њу верују, а Наше речи и доказе негирају само неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Ти пре ње ниједну књигу ниси читао, а ниси је ни својом десном руком писао, иначе, посумњали би они који говоре лажи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Међутим, Кур''ан је сачињен од јасних речи; у грудима су оних којима је дато знање, а Наше речи негирају само неправедници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'и говоре: “Зашто му од Господара његовог нису нека чуда послата?” Реци: “Чуда су једино код Аллаха, а ја само јасно опомињем.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'А зар им није доста то што Ми теби објављујемо Књигу која им се казује: у њој је, заиста, милост и поука људима који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'Реци: „Аллах је довољан сведок мени и вама; Он зна све што је на небесима и на Земљи. А они који у лаж верују, а у Аллаха не верују, они су прави губитници.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Они траже од тебе Мухаммеде да их што пре стигне казна. А да није одређеног рока, казна би им дошла, а доћи ће им, сигурно, изненада, а они неће да је предосете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Они траже од тебе да их што пре стигне казна, а Пакао ће сигурно све невернике да обухвати', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'на Дан кад их патња и одозго и одоздо обузме, а Он каже: „Искусите оно што сте радили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'О слуге Моје које верујете, Моја је Земља пространа, зато само Мене обожавајте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Свака душа смрт ће да осети, а онда ћете Нама да будете враћени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'Оне који буду веровали и радили добра дела сместићемо у рајске одаје, испод којих реке теку, у њима ће вечно да бораве. Како ће дивна бити награда онима који су се трудили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'онима који су били стрпљиви и уздали се у Свога Господара!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'А колико има живих бића која не могу себи да скупљају опскрбу, Аллах их опскрбљује, а и вас! Он све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'А да их упиташ: „Ко је створио небеса и Земљу и ко је потчинио Сунце и Месец?“ Сигурно би рекли: „Аллах!“, па куда се онда одмећу!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Аллах у изобиљу даје опскрбу ономе коме хоће од Својих слуга, а и ускраћује коме хоће: Аллах, заиста, све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'А ако их упиташ: „Ко са неба спушта воду и њом оживљава мртву Земљу?“ Сигурно ће да кажу: „Аллах!“ А ти реци: „Хвала Аллаху!“ Али већина њих не разуме.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Живот на овом свету је људима само забава и игра, а само је Будући свет прави живот, кад би они само знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Кад се у лађе укрцају, Аллаха моле, предајући Му се искрено, а када их Он доведе до копна, одмах друге поред Њега обожавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'да би показали незахвалност према оном што им Ми дајемо и да би уживали. А сазнаће они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Зар не виде да смо Кабу учинили сигурном, док се свуда око њих отима и пљачка? Зар у лаж верују, а на Аллаховим благодатима су незахвални?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Има ли онда већег насилника од онога који о Аллаху измишља лажи или пориче истину која му долази?! Зар неверницима није боравиште у Паклу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Оне који се буду трудили због Нас, Ми ћемо, сигурно, да упутимо путевима који Нама воде, а Аллах је, заиста, на страни оних који добра дела чине!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, '1. Елиф-лам-мим.[1]', '[1]Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'Византинци су побеђени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'у најнижој земљи, али они ће, после пораза свог, сигурно победити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'за неколико година – и пре и после, Аллахова је одлука – и тад ће се верници радовати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'Аллаховој помоћи. Он помаже коме хоће и Он је Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'То је Аллахово обећање. Аллах ће своје обећање испунити, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Они знају само спољашњу страну овосветског живота, а према Будућем свету су немарни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'А зашто не размисле сами о себи?! Аллах је створио небеса и Земљу и оно што је између њих само са истином и са одређеним роком, а многи људи, заиста, не верују да ће пред Господара свог заиста стати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Зашто не путују по Земљи па да виде какав је био завршетак оних пре њих?! Они су били од њих јачи и земљу су обрађивали и на њој су градили више него што ови граде, и посланици су им доносили јасне доказе: Аллах им није учинио неправду, сами су себи неправду нанели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'А затим би завршетак оних који су чинили зло био је најужаснија казна, зато што су порицали Аллахове речи и доказе и што су их извргавали руглу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Аллах започиње стварање; ствара из ничега, затим ће то поново да учини, а онда ћете Њему да будете враћени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'На Дан кад наступи Час суда, незнанобошци ће очајавати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Божанства њихова неће се за њих заузимати, а због божанстава својих били су неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'На Дан кад наступи Час оживљења, људи ће се раздвојити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'они који су веровали и радили добра дела радоваће се у рајским баштама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'а они који нису веровали и који су порицали Наше речи и доказе и који су сусрет на Судњем дану порицали у вечној ће муци бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Па, слављен и узвишен нека је Аллах кад год омркнете и кад год осванете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'Њему нека је сва хвала и на небесима и на Земљи, и предвече и у подне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'Он из неживог ствара живо и живо претвара у неживо. Он оживљава Земљу након њеног мртвила; исто тако ћете и ви да будете оживљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'Један од доказа Његових је то што вас од земље ствара, и одједном вас, људи, свуда има разасутих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'И један од доказа Његових је то што за вас, од врсте ваше, ствара жене да се уз њих смирите, и што између вас успоставља љубав и самилост. У томе, заиста, има поуке за људе који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'И један од Његових доказа је стварање небеса и Земље, и разноврсност ваших језика и ваших боја; у томе, заиста, има поуке за оне који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'И један од Његових доказа је ваш сан ноћу и дању, и ваше настојање да стекнете нешто из Његовог обиља; у томе, заиста, има поуке за људе који чују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'И један од Његових доказа је то што вам показује муњу, да се побојите и понадате, и то што спушта са неба кишу и оживљава њоме земљу после њеног мртвила; у томе, заиста, има поуке за људе који разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'И један од Његових доказа је и то што небо и Земља постоје Његовом одредбом. Затим, ћете, чим вас Он само једном позове, брзо из земље да устанете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'Њему припада све што је на небесима и на Земљи, све је Њему послушно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'Он је Тај Који из ничег ствара и Он ће то поново учинити, то је Њему лако. Он је узвишен и на небесима и на Земљи. Он је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'Он вам као пример наводи вас саме: јесу ли они који су у поседу вашем изједначени с вама у оном што вам Ми дајемо, па сте у томе исти, и бојите ли их се као што се ви једни других бојите? Тако Ми, подробно, излажемо доказе Наше људима који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Али, неверници лакомислено следе страсти своје – а ко ће на Прави пут упутити оног кога је Аллах у заблуди оставио? – Њима неће моћи нико у помоћ притећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'Ти управи лице своје вери, као прави верник, вери Аллаховој, према којој је Он људе створио – не може се мењати Аллахова вера, али већина људи то не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'Покајнички Му се обраћајте! Бојте се Њега и обављајте молитву, и не будите незнанобошци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'од оних који су веру своју разбили и у странке се поделили; свака странка задовољна оним што исповеда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'А кад људе невоља снађе, они се Господару своме покајнички обраћају, а после, кад Он учини да осете Његову милост, одједном неки од њих своме Господару друге у обожавању придружују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'да би били незахвални на оном што им Ми дајемо. Па уживајте, а сазнаћете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Зар смо им Ми послали какав доказ који говори у прилог оних које поред Њега обожавају?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'Кад допустимо људима да се благодатима наслађују, они им се обрадују, а кад их погоди невоља, због оног што су руке њихове чиниле, одједном очајавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Зар они не виде да Аллах у обиљу даје опскрбу ономе коме Он хоће, и да је ускраћује?! То су, уистину, докази за људе који верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Зато подај ближњем право његово, и сиромаху и путнику! То је боље за оне који се настоје Аллаху умилити – они ће успети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'А новац који дајете да се увећа новцем других људи неће се код Аллаха увећати, а за милостињу коју уделите да бисте се Аллаху умилили – такви ће добра дела своја умногостручити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Аллах је Онај Који вас је створио, па вас опскрбио, затим ће да вас усмрти и потом оживи. Постоји ли иједно божанство које било шта од тога ради?! Чист је и Узвишен Он од онога што Њему сматрају равним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'Због оног што људи раде, појавио се неред и на копну и на мору, како би им Он дао да искусе казну због оног што раде, не би ли се поправили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'Реци: „Путујте по Земљи па погледајте какав је био завршетак оних који су били пре; већином су били незнанобошци.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'Зато ти усмери своје лице правој вери, пре него што вољом Аллаховом дође Дан који нико неће моћи да одбије. Тог дана ће они да се раздвоје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Они који нису веровали - на своју штету нису веровали, а они који су чинили добра дела - себи су припремили Рај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'да Он награди из Свога обиља оне који су веровали и радили добра дела; а Он, заиста, не воли невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Један од Његових доказа је то што Он шаље ветрове као носиоце радосних вести да би вам дао да осетите Његову милост и да лађе плове Његовом одредбом и да стичете из Његовог обиља, и да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'И пре тебе смо слали посланике њиховим народима и они су им доносили јасне доказе, па смо кажњавали оне који су грешили, а била нам је дужност да помогнемо вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Аллах је Тај Који шаље ветрове, па они облаке гоне и Он их по небу, како Он хоће, распростире и дели на комаде, па ти видиш кишу како из њих пада, и кад је Он на оне Своје слуге, на које жели, пролије, они се одједном радошћу испуне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'иако су били очајни пре него што се спустила на њих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Зато, погледај трагове Аллахове милости – како Он оживи земљу након њеног мртвила! Он ће, уистину, и мртве да оживи, Он све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'А да пошаљемо ветар и да они виде да је све пожутело, они би, и после тога, порицали благодати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'Ти не можеш да дозовеш мртве, ни глуве да довикнеш, кад се од тебе окрену, удаљавајући се,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'нити можеш заслепљене да одвратиш од њихове заблуде; можеш једино да дозовеш оне који верују у Наше речи и доказе, једино они ће да се одазову.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Аллах је Тај Који вас нејаким ствара, и онда вам, после нејакости, даје снагу, а после снаге изнемоглост и седе власи; Он ствара шта хоће, Он све зна и све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'А на Дан кад наступи Час оживљења, одметници ће да се заклињу да су само један час остали; а и пре су избегавали истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'А рећи ће они којима је дато знање и веровање: „Ви сте остали, према Аллаховој одредби, све до Дана оживљења, а ово је Дан оживљења, само што ви нисте знали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Тог Дана неће користити правдања онима који су се према себи огрешили и неће се од њих тражити да се Аллаху умиле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'У овом Кур''ану Ми наводимо људима разноврсне примере. А кад би им донео било какво чудо, опет би рекли они који не верују: „Ви само лажи износите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'Ето, тако Аллах печати срца онима који неће да знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'А ти буди стрпљив! Аллахово обећање је, заиста, истина и нека те никако не обману они који чврсто не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, '1. Елиф-лам-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Ово су стихови мудре Књиге,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'упуте и милости онима који раде добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'онима који обављају молитву и дају милостињу и који у Будући свет чврсто верују;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'њима је Господар њихов на Прави пут указао и они ће да успеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'Има људи који купују средства за забаву, да би, не знајући колики је то грех, с Аллаховог пута одводили и да би га предметом за исмејавање узимали. Њих чека срамна казна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Кад се неком од њих Наше речи казују, он охоло окреће главу, као да их није ни чуо, као да је глув - зато му наговести болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Онима који верују и раде добра дела, заиста, припадају баште уживања,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'у њима ће да бораве вечно - Аллахово обећање је истинито, а Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'Створио је небеса која ви видите без стубова, а по Земљи је стабилне планине поставио да вас не потреса, и по њој је разасуо животиње свих врста. Ми са неба спуштамо воду и чинимо да по њој ничу разноврсне племените биљке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'То је Аллахово дело, а покажите Ми шта су други, мимо Њега, створили? Ништа! Незнанобошци су у правој заблуди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'А Ми смо Локману даровали мудрост: „Буди захвалан Аллаху! Ко је захвалан, чини то у своју корист, а ко је незахвалан - па, Аллах је, заиста, независан и хваљен.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'Кад Локман рече своме сину, саветујући га: „О синко мој, немој Аллаху у обожавању никога да придружујеш; незнанобоштво је, збиља, велико насиље.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Ми смо наредили човеку да буде послушан родитељима својим. Мајка га носи, а њено здравље трпи, и одбија га у току две године. Буди захвалан Мени и родитељима својим, Мени ће се сви вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'А ако буду настојали да те наговоре да поред Мене обожаваш оно о чему ништа не знаш, ти их не слушај и према њима се, на овом свету, великодушно понашај. А следи Пут онога који се обраћа Мени искрено; Мени ћете после да се вратите и Ја ћу о ономе што сте радили да вас обавестим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, '"О мој синко, добро и зло, тешко колико зрно горушице, било у стени или на небесима или у земљи, Аллах ће на видело да изнесе. Заиста је Аллах благ и Он све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'О мој синко, обављај молитву и тражи да се раде добра дела, а одвраћај од лоших и стрпљиво подноси оно што те задеси - то, заиста, спада у истинске поступке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'И, из охолости, не окрећи своје лице од људи и не иди Земљом надмено. Заиста Аллах не воли ни гордог ни хвалисавог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'У ходу буди одмерен, а у говору не буди грлат; збиља, најнепријатнији глас је глас магарца!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Како не видите да вам је Аллах потчинио све што постоји на небесима и на Земљи и да вас дарежљиво обасипа Својим благодатима, и видљивим и невидљивим?! А има људи који расправљају о Аллаху без икаквог знања, без икакве упуте и без књиге светиљке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'А кад им се говори: „Следите оно што вам Аллах објављује!“ Одговарају: „Не, ми следимо оно што смо запамтили од наших предака.“ Зар и онда кад их Сотона позива на патњу у Огњу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Онај ко се сасвим преда Аллаху, а уз то још и добра дела ради, ухватио се за најчвршћу везу. Аллаху се на крају све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'А онај који не верује, па, нека те не забрињава његово неверовање. Нама ће сви да се врате и Ми ћемо о ономе шта су радили да их обавестимо; Аллах, уистину, добро зна све што је у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'Ми им дајемо да кратко уживају, а онда ћемо да их натерамо у жестоку патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'А да их упиташ: „Ко је створио небеса и Земљу?“ Сигурно би рекли: „Аллах!“ А ти реци: „Хваљен нека је Аллах!“ Само што већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'Аллахово је све на небесима и на Земљи! Аллах је, уистину, независан и хвале достојан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Да су сва стабла на Земљи писаљке, а море, уз помоћ још седам мора, тинта, не би се исписале Аллахове речи; Аллах је, уистину, силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Створити све вас и све вас оживети, исто је као створити и оживети једног човека; Аллах, заиста, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Зар не видиш да Аллах уводи ноћ у дан и дан у ноћ, и да је потчинио Сунце и Месец - свако се креће до одређеног рока - и да Аллах добро зна оно што радите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'То је зато што је Аллах - истина, а они којима они, поред Њега, упућују молбе - неистина, и што је Аллах Узвишени и Велики.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Зар не видиш да лађе морем плове Аллаховом благодати да би вам показао неке Своје знаке?! У томе су, заиста, знаци за сваког ко је стрпљив и захвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'А кад их талас, као облак, прекрије, моле се Аллаху, искрено Му исповедајући веру; а чим их Он доведе до копна, само Му неки захвални остају. А Наше речи и доказе само издајник, незахвалник пориче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'О људи, бојте се свога Господара и страхујте од Дана кад родитељ своме детету неће моћи нимало да помогне, нити ће дете моћи своме родитељу имало да помогне! Аллахова претња је истинита, па нека вас никако овосветски живот не завара и нека вас у Аллаха ђаво не поколеба.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Само Аллах зна кад ће да наступи Судњи дан, само Он спушта кишу и само Он зна шта је у материцама , а човек не зна шта ће сутра да заради и не зна нико у којој ће земљи да умре; Аллах, уистину, све зна и о свему је обавештен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Елиф-лам-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Књигу објављује, у то нема сумње, Господар светова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Међутим, они говоре: “Он је измишља!” Не, она је истина од Господара твог да опомињеш народ којем пре тебе није дошао нико да га опомиње, да би ишао Правим путем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Аллах је небеса и Земљу и оно што је између њих у шест временских раздобља створио, а онда се изнад Престоља узвисио. Ви, осим Њега, ни заштитника ни посредника немате, па зашто се не уразумите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'Он управља свима, од неба до Земље, а онда се све то Њему враћа у дану који, према вашем рачунању времена, хиљаду година траје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'То је Онај Који зна и оно што је чулима недокучиво, а и оно што је појавно, Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, 'Који све савршено ствара, Који је првог човека створио од иловаче,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'а онда је учинио да његово потомство настаје од узорка безначајне течности,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'затим му складно удове уобличи и у њега живот удахне, и Он вам је дао слух и вид и разум, а како ви мало захваљујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'Они говоре: „Зар ћемо, кад нестанемо под земљом, поново да будемо створени?!“ Напротив, они не верују да ће пред Господаром својим стати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'Реци им (Мухаммеде): „Анђео смрти, који је задужен за вас, душе ће да вам узме, а после ћете своме Господару да будете враћени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'А да ти је видети како ће (на Судњем дану) одметници, оборених глава, пред својим Господаром да кажу: „Господару наш, видели смо и чули смо, па нас врати да радимо добра дела; ми заиста, чврсто верујемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'А кад бисмо хтели, сваког човека бисмо на Прави пут упутили, али Ја сам већ истину рекао: „Напунићу, заиста, Пакао духовима и људима заједно!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, 'Па искусите патњу зато што сте занемаривали да ћете овај Дан да доживите – и Ми ћемо вас да занемаримо - и вечну патњу искусите због онога што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'У Наше речи верују само они који, кад њима буду опоменути, падају лицем на тло, и који свога Господара величају и хвале и који се не охоле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Њихови бокови се постеља лишавају и они моле свога Господара из страха и жеље, а део оног што им Ми дајемо удељују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'И нико не зна какве их, као награда за оно што су чинили, скривене радости чекају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'Зар да вернику буде исто као грешнику? Не, њима неће бити исто.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'Оне који су веровали и радили добра дела - чекају рајске баште у којима ће да бораве, као награда за оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'А оне који нису веровали - чека Ватра, у којој ће да пребивају; кад год покушају да из ње изађу, биће у њу враћени и биће им речено: „Трпите казну у Ватри коју сте порицали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'И Ми ћемо учинити да блажу казну искусе, пре оне највеће, не би ли се покајали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Има ли већег неправедника од онога који је опоменут речима и доказима свога Господара, а који се потом окрене од њих?! Ми ћемо, заиста, да се осветимо злочинцима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Мојсију смо Ми дали Књигу, зато не сумњај да је он није примио, и учинили смо је упутом Израиљевим синовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Између њих Ми смо одређивали вође и они су, одазивајући се Нашој заповеди, на Прави пут упућивали, јер су стрпљиви били и у Наше речи и доказе су чврсто веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Заиста ће твој Господар међу њима на Судњем дану да пресуди о ономе у чему су се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Зар им није јасно колико смо Ми уништили народа пре њих, по чијим они насељима ходају?! У томе су заиста докази, па зашто неће да чују?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Како они не виде да Ми гонимо кишу у оголелу земљу, и чинимо да, уз њену помоћ, ниче растиње којим се храни њихова стока, а и они сами - па зашто не виде?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'И они говоре: „Кад ће већ једном та пресуда, ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'Реци: “На Судњем дану, кад неверницима неће никако да користи то што ће тада да верују и неће да им се да нимало времена.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Зато се ти окрени од њих и чекај, и они, заиста, чекају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'О Веровесниче, бој се Аллаха, а невернике и лицемере не слушај - Аллах, уистину, све зна и мудар је!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'И следи оно што ти се од твога Господара објављује - Аллах, заиста, у потпуности зна оно шта радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'И на Аллаха се ослони, а Аллах је довољан као заштитиник!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Аллах ниједном човеку два срца у грудима није дао, а ни ваше супруге, од којих се растављате говорећи да су вам њихова леђа попут леђа ваших мајки, мајкама вашим није учинио, нити је ваше посинке учинио вашим синовима. То су само ваше речи, из ваших уста, а Аллах истину говори и на Прави пут упућује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Зовите их по њиховим очевима, то је код Аллаха праведније! А ако не знате њихове очеве, па они су ваша браћа по вери и ваши штићеници. Није вам грех ако у томе погрешите, грех је ако то намерно учините; а Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Веровесник је пречи верницима него они сами себи, а жене његове су као мајке њихове. А рођаци, по Божјој књизи, пречи су једни другима од осталих верника и исељеника из Мекке. Пријатељима својим можете опоруком нешто оставити. То је записано у Књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'Ми смо од веровесника узели њихов завет, и од тебе, и од Ноје, и од Аврама, и од Мојсија, и од Исуса, Маријиног сина. Од њих смо узели чврст завет,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'да би Он могао позвати на одговорност веровеснике за оно што су говорили. А неверницима је Он припремио болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'О верници, сетите се Аллахове благодати према вама када су до вас војске дошле, па смо Ми против њих послали ветар, и војске које ви нисте видели - а Аллах добро види шта ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'Кад су вам војске дошле и одозго и одоздо, кад су вам погледи скренули, а душа дошла до гркљана, и кад сте о Аллаху помишљали свашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'Тада су верници били стављени у искушење и жестоко су били узнемирени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'кад су лицемери и они болесних срца говорили: “Аллах и Посланик Његов су нас само обмањивали кад су нам обећавали!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Кад су неки међу њима казали: „О становници Медине, не можете издржати, зато се вратите“, а други међу њима тражили су допуштење од Веровесника и говорили: „Куће су наше незаштићене!“ А нису биле незаштићене, већ су они само желели да из борбе побегну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'А да су им с разних страна продрли и да су потом од њих затражили да опет постану незнанобошци, они би то, не двоумећи се око тога, брзо учинили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'а били су се још пре обавезали Аллаху да неће посустати - а за обавезу дату Аллаху одговараће се.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'Реци: “Ако бежите од смрти или погибије, бежање вам неће помоћи, јер и после тога, само ћете кратко да уживате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'Реци: „Ко ће да вас заштити од Аллаха ако Он жели да вас снађе зло, или, ко може да вам науди ако Он жели да вам укаже милост?!“ Осим Аллаха, они себи неће наћи ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Аллах добро зна оне међу вама који су друге задржали, и својим пријатељима говорили: „Прикључите нам се!“ А иначе они у борбу ретко иду,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, 'не желећи да вам помогну. А кад завлада страх, видиш их како гледају у тебе колутајући својим очима као пред смрт онесвешћени; чим страх мине, они вас псују својим оштрим језицима, шкрти да учине било какво добро. Они не верују, и зато је Аллах поништио њихова дела; а то је Аллаху лако.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, 'Они мисле да савезници још нису отишли. А кад би савезници опет дошли, најдраже би им било да су међу бедуинима у пустињи и да се распитују за вас; а када би са вама остали, мало би се борили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Ви у Аллаховом Посланику имате диван узор за оног који се нада Аллаховој милости и награди на Будућем свету и који често Аллаха спомиње.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'А кад су верници угледали непријатељске војске, казали су: „Ово је оно што су нам Аллах и Његов Посланик обећали, и Аллах и Његов Посланик су говорили истину!“ - И то им је само учврстило веровање и преданост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'Има верника који испуњавају завет дат Аллаху, има их који су погинули и има их који то очекују – нису ништа изменили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'То је зато да би Аллах наградио искрене за њихову искреност, а да ако жели подвргне лицемере патњи или да им опрости. Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Аллах је невернике пуне срџбе одбио, нису нимало успели, а вернике је Аллах поштедео борбе. Аллах је, уистину, моћан и силан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'А следбенике Књиге, који су их помагали, из њихових тврђава је извео, и страх је у њихова срца улио, па сте једне побили, а друге заробили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'И дао вам је да наследите њихове земље и њихове домове и њихова богатства, и земљу на коју пре нисте ступили; Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'О Веровесниче, реци женама својим: “Ако желите живот на овом свету и његов сјај, онда се одлучите, даћу вам пристојну отпрему и лепо ћу да вас разведем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'А ако желите Аллаха и Његовог Посланика и Будући живот, па, Аллах је, заиста, онима међу вама који раде добра дела припремио велику награду.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'О Веровесникове жене, ако би која од вас учинила очигледни грех, казна би јој била удвостручена, а то је Аллаху лако;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'а оној која се буде покоравала Аллаху и Његовом Посланику и радила добра дела - даћемо двоструку награду и припремили смо јој племениту опскрбу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'О Веровесникове жене, ви нисте као друге жене! Ако се Аллаха бојите, на себе пажњу говором не скрећите, па да тада осети жудњу онај у чијем је срцу болест, и пристојно говорите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'У својим кућама боравите и своју лепоту, као што је било у прво паганско доба, не показујте, и обављајте молитву и дајте милостињу, и покоравајте се Аллаху и Његовом Посланику! Аллах жели да од вас, о Посланикова породицо, отклони грехе, и да вас потпуно очисти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'И сећајте се Аллахових речи и мудрости која се казује у вашим домовима; Аллах је, уистину, добар и све у потпуности зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Муслиманима и муслиманкама, и верницима и верницама, и послушним мушкарцима и послушним женама, и искреним мушкарцима и искреним женама, и стрпљивим мушкарцима и стрпљивим женама, и понизним мушкарцима и понизним женама, и мушкарцима који деле милостињу и женама које деле милостињу, и мушкарцима који посте и женама које посте, и мушкарцима који о својим стидним местима воде бригу и женама које о својим стидним местима воде бригу, и мушкарцима који често спомињу Аллаха и женама које често спомињу Аллаха - Аллах је, заиста, за све њих опрост и велику награду припремио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Кад Аллах и Посланик Његов нешто одреде, онда ни верник ни верница немају право по свом нахођењу да поступе. А ко Аллаха и Његовог Посланика не послуша, тај је сигурно скренуо с Правог пута.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'А кад ти рече оном коме је Аллах милост даровао, а коме си и ти добро учинио: „Задржи своју супругу и бој се Аллаха!“ – У себи си скривао оно што ће Аллах да обелодани и бојао си се људи, а прече је да се бојиш Аллаха. И пошто је Зејдова потреба за њом престала и од ње се развео, Ми смо је за тебе удали како се верници више не би устручавали да се жене женама посинака својих кад се они од њих разведу. Како Аллах одреди, тако треба бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Веровеснику није грех да чини оно што му Аллах нареди јер такав је био Аллахов пропис и за оне који су били пре и нестали, а Аллахова одредба је неминовна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'За оне који су достављали Аллахове посланице и страховали од Њега, и који се никога, осим Аллаха, нису бојали. А довољно је то што ће се пред Аллахом рачун полагати!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Мухаммед није родитељ ниједном од ваших људи, него је Аллахов посланик и печат - последњи веровесник, а Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'О верници, Аллаха пуно спомињите', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'и ујутру и навече Га славите и величајте;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'Он вас благосиља, а и Његови анђели, да би вас извео из тмина на светло - Он је милостив према верницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'а на Дан кад они пред Њега стану, поздрав ће да им буде “Мир вама!” А Он им је припремио награду племениту.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'О Веровесниче, заиста смо те послали као сведока и као доносиоца радосних вести и као опомињача,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'да - по Његовом наређењу - позиваш к Аллаху, и као светиљку која сија.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'И обрадуј вернике да ће код Аллаха имати велику благодат.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'А не слушај невернике ни лицемере, не обраћај пажњу на њихове увреде и поуздај се у Аллаха, Аллах је довољан као заштитник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'О верници, кад се ожените верницама, а онда их, пре ступања у брачни однос, разведете, оне нису дужне да чекају одређено време које ћете ви да бројите, већ их дарујте и лепо их отпремите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'О Веровесниче, Ми смо ти дозволили да буду твоје жене оне којима си дао њихове венчане дарове, и оне у твојој власти које ти је Аллах дао, и кћери твојих стричева, и кћери твојих тетака по оцу, и кћери твојих ујака, и кћери твојих тетака по мајци које су се са тобом иселиле, и жену - верницу која себе поклони Веровеснику, ако Веровесник хоће да се њоме ожени, само теби, а не осталим верницима. Ми знамо шта смо верницима прописали у вези са њиховим супругама и онима које су у њиховом власништву, а и да ти не би било тешко. А Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'Можеш да занемариш оне међу њима које хоћеш и можеш да прихватиш ону коју хоћеш, а можеш да затражиш ону коју си удаљио, ниједно од тога није твој грех. Најлакше ће тако оне да буду радосне и неће да се жалосте и тако ће све оним што им ти дајеш да буду задовољне - а Аллах зна шта је у вашим срцима; Аллах зна све и благ је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'Од сада ти нису допуштене друге жене, ни да уместо њих неку другу узмеш, макар те и задивила њихова лепота, осим оних које поседујеш. А Аллах све надзире.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'О ви који верујете, не улазите у Веровесникове собе, осим ако вам се допусти ради јела, али не да чекате док се оно спреми; тек кад будете позвани, онда уђите, и пошто једете, разиђите се не упуштајући се у разговор. То смета Веровеснику, а он се стиди да вам то каже, а Аллах се не стиди истине. А ако од његових супруга, нешто тражите, тражите то иза застора. То је чистије за ваша и њихова срца. Вама није допуштено да Аллаховог Посланика узнемиравате нити да се његовим супругама после његове смрти икада ожените. То би, уистину, код Аллаха био велики грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Износили ви ваша дела у јавност или их у себи крили, па, Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Женама није грех да буду откривене пред својим очевима, и својим синовима, и својом браћом, и синовима своје браће, и синовима својих сестара, и женама верницама, и пред онима које су у њиховом власништву. И Аллаха се бојте! Аллах, је, заиста, свему сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Заиста Аллах и Његови анђели благосиљају Веровесника. О ви који верујете, благосиљајте га и ви и шаљите му поздрав срдачни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Оне који Аллаха и Његовог Посланика буду вређали, Аллах ће, заиста, и на овом свету и на Будућем свету проклети, и припремити им понижавајућу патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'А они који вређају вернике и вернице, а они то не заслужују, товаре на себе клевету и прави грех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'О Веровесниче, реци својим супругама, и својим кћерима, и женама верника нека спусте хаљине своје низа се. Тако ће најлакше да се препознају па неће да буду напаствоване. А Аллах прашта и самилостан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Ако се лицемери и они у чијим срцима је болест и они који по Медини шире лажи - не окане тога, Ми ћемо власт над њима да ти препустимо и они ће само кратко време као твоји суседи у њој да остану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Проклети да су. Где год да се нађу, нека буду ухваћени и убијени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'према Аллаховом закону који је вредео за оне који су били пре вас и нестали! А ти нећеш у Аллаховом закону наћи измене!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'Питају те људи о Часу смака света; реци: „То зна једино Аллах! А ти не знаш, можда је Час смака света близу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Аллах је проклео невернике и за њих је припремио разбуктали Огањ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'у њему ће вечно и заувек да бораве, и неће наћи ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'На Дан кад њихова лица буду превртана у Ватри, говориће: „Камо среће да смо се покоравали Аллаху и да смо слушали Посланика!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'И говориће: „Господару наш, ми смо слушали своје прваке и своје старешине, па су нас они одвели са Правог пута;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'Господару наш, подај им двоструку патњу и прокуни их великим проклетством!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'О ви који верујете, не будите као они који су узнемиравали Мојсија, па га је Аллах ослободио онога што су говорили, а он код Аллаха има велики углед!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'О ви који верујете, бојте се Аллаха и говорите само истину,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Он ће вас наградити за ваша добра дела и грехе ће да вам опрости! А онај ко се Аллаху и Његовом Посланику буде покоравао - постићи ће велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Ми смо небесима, Земљи и планинама понудили обавезу, па су се суздржали и уплашили да је прихвате, али је преузео човек - а он је према себи заиста неправедан и незналица,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'да би Аллах лицемере и лицемерке, и незнанобошце и незнанобошкиње казнио, а верницима и верницама опростио. Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'Нека је хваљен Аллах, Чије је све оно на небесима и све оно на Земљи! Хваљен нека буде и на Будућем свету! Он је Мудри и Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'Он зна шта у земљу улази, а шта из ње излази, и шта се с неба спушта, а шта се на њега успиње; Он је самилостан и Он прашта грехе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'А они који не верују говоре: „Час оживљења неће да нам дође!“ Реци: „Хоће, тако ми мога Господара, Који зна и оно што је недокучиво чулима, сигурно ће да вам дође!“ Њему ништа не може, ни колико једна трунчица, ни на небесима ни на Земљи, да измакне, и не постоји ништа, ни мање ни веће од тога, што није у јасној Књизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'Зато да би дао награду онима који верују и добра дела чине – њих чека опрост и опскрба племенита,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'а они који се боре против Наших доказа, одвраћајући од њих - то су они којима следи најболнија патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Они којима је дато знање добро знају да је оно што ти се објављује од Господара твога истина и да води на пут Силнога и Хваљенога.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'А они који не верују говоре: „Хоћете ли да вам покажемо човека који вам предсказује да ћете, када се сасвим распаднете, заиста, поновно да будете створени?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'Износи ли он лажи о Аллаху или је луд?“ Напротив, они који у онај свет неће да верују су у патњи и у дубокој заблуди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Зар не виде небо и Земљу, оно што је испред њих и оно што је иза њих?! Кад бисмо хтели, у земљу бисмо их утерали или бисмо комаде неба на њих сручили. То је, заиста, знак сваком вернику Аллаху оданом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Ми смо Давиду Нашу милост указали: „О брда, понављајте заједно са њим хвалу, и ви, птице!“ - И омекшали смо му гвожђе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, '„Прави широке панцире и честито их плети, и радите добро! Ја заиста добро видим шта ви радите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'А Соломону - ветар, ујутру је преваљивао растојање од месец дана, а увече растојање од месец дана; и учинили смо да му из извора тече растопљен бакар и да џинни, вољом његовог Господара, пред њим раде; а кад би неки од њих отказао послушност наређењу Нашем, учинили бисмо да огњену патњу осети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Они су му израђивали што год је хтео: богомоље и споменике, и зделе као чатрње, и котлове непокретне. „Трудите се и будите захвални, о Давидова породицо!“ А мало је захвалних међу Мојим слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'А кад смо одредили да умре, црв који је био расточио штап његов – упозорио их је да је умро, и кад се он срушио, џинни схватише да не би на муци срамној остали да су будућност могли прозрети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Становници Сабе имали су знак у месту у ком су живели: вртове, здесна и слева. Једите из опскрбе свога Господара и будите Му захвални; ово је леп предео, а Господар је Опростилац греха!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'Али они су незахвални постали, па смо на њих водену бујицу пустили, и заменили смо им њихове вртове другим вртовима са горким плодовима и тамариском и нешто мало дивљег лотоса.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'Казнили смо их тако зато што су били незахвални, а да ли Ми кажњавамо иког другог до неверника, незахвалника?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'А између њих и градова које смо благословили изградили смо били насеља повезана и одредили смо им потребну удаљеност. “Путујте кроз њих и по ноћи и по дану, сигурни!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Али они рекоше: „Господару наш, учини веће растојање приликом наших путовања!“ - И огрешише се према себи, и Ми учинисмо да се о њима само прича, а њих посвуда раселисмо. Заиста, су у томе знаци за сваког стрпљивог и захвалног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'А ђаво је остварио оно што је о њима мислио, и они су се повели за њим, осим групе верника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'над којима никакве власти није имао. Ми смо хтели указати на оног ко верује у онај свет, а ко у њега сумња. – А Господар твој бди над свим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'Реци: „Зовите оне које, поред Аллаха, сматрате боговима. Они ништа не поседују, ни колико један трун, ни на небесима ни на Земљи; они у њима немају никаквог удела и Он нема од њих никакве помоћи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Код Њега ће моћи да се заузима само онај коме Он допусти. И кад из њихових срца нестане страха, они ће да упитају: „Шта је то рекао ваш Господар?“ „Истину!“ Одговориће, Он је Узвишени и Велики.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'Упитај: „Ко вас опскрбљује и из неба и из земље?“ И одговори: „Аллах! Ко је онда, ми или ви, на правом путу, а ко је у очигледној заблуди!?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'Реци: „Ви нећете да одговарате за грехе које ми починимо, нити ћемо ми да одговарамо за оно што ви урадите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'Реци: „Господар наш ће да нас сабере и онда ће да нам праведно пресуди, Он је Праведни Судија и Свезнајући.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'Реци: „Покажите ми оне које придружујете Њему у обожавању!“ Нема их! Постоји само Аллах Силни и Мудри!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Ми смо те послали свим људима да радосне вести доносиш и да опомињеш, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'и говоре: „Када ће већ једном та претња, ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'Реци: „Дан вам је већ одређен, не можете ни за један час да га зауставите нити убрзате.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'А они који не верују говоре: „Ми нећемо да верујемо у овај Кур''ан нити у Књиге пре њега!“ А кад би само видео незнанобошце кад пред својим Господаром буду заустављени и кад стану међу собом да се препиру: „Да вас није било, сигурно бисмо били верници!“ Рећи ће охолници потлаченима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, '„А зар смо вас ми одвратили од Упуте након што вам је она дошла?! Не, сами сте ви били зли“, рећи ће охолници потлаченима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, '„Није било тако!“ Одговориће они који су били тлачени онима који су били охоли, „него сте и дању и ноћу сплеткарили кад сте од нас тражили да у Аллаха не верујемо и да Му друге једнаким сматрамо.“ И прикриће кајање кад виде да ће да буду кажњени, а ми ћемо на вратове неверника окове да ставимо; зар ће да буду кажњени другачије него према ономе како су радили?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Ми ни у једно насеље нисмо послали посланика а да нису рекли они који су били навикли на раскошан живот: „Не верујемо ми у оно што је послато по вама!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'И уз то су говорили: „Имамо више имовине и деце; ми нећемо да будемо подвргнути патњи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'Реци: „Мој Господар даје обилну опскрбу ономе коме хоће, а и ускраћује, али, већина људи не зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Ни богатства ваша ни деца ваша неће вас учинити Нама блиским. Само оне који буду веровали и добра дела чинили чека вишеструка награда за оно што су радили, и они ће да буду сигурни у високим одајама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'А они који се буду трудили да се доказима Нашим супротставе, да их онемогуће, они ће бити кажњени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'Реци: „Мој Господар даје обилну опскрбу ономе коме хоће међу Својим слугама, а коме хоће ускраћује. Шта год ви уделите, Он ће то да надокнади, Он најбоље опскрбљује.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'А на Дан кад их све сакупи, па упита анђеле: „Јесу ли вас обожавали?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'Они ће да одговоре: „Узвишен нека си, Ти си наш Господар, а не они! Они су обожавали духове и већина их је веровала у њих.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'Тог дана једни другима нећете моћи ни да користите ни да наудите, а Ми ћемо онима који су били незнанобошци да кажемо: „Трпите патњу у Ватри коју сте порицали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Кад им се Наше јасне речи казују, они говоре: „Овај човек само хоће да вас одврати од оног што су ваши преци обожавали“, и говоре: „Ово није ништа друго до измишљена лаж - измишљотина. А они који не верују говоре о Истини када им долази: „Ово није ништа друго него јасна магија!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'А Ми им нисмо дали никакве књиге да их изучавају и Ми им, пре тебе, нисмо били послали никога ко би их упозоравао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'А и они пре њих су посланике угонили у лаж, а ови нису постигли ни десети део од онога што смо прошлим народима дали, па су, ипак, Моје посланике сматрали лажним, па каква је само била казна Моја!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'Реци: „Саветујем вам само једно: устаните према Аллаху, двојица по двојица, или један по један, па затим размислите да друг ваш није луд. Он вас само пре тешке патње упозорава.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'Реци: „Какву год награду да затражим од вас, нек остане вама, мене ће да награди Аллах, Он је сведок свему."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'Реци: “Господар мој побеђује истином, Он добро зна и све оно што је веома скривено.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'Реци: “Дошла је истина, а лажи је неповратно нестало!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'Реци: „Ако залутам, залутао сам на своју штету, а ако сам на Правом путу, то је због онога што ми мој Господар објављује; Он, заиста, све чује и близу је.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'А да ти је видети их када се престраве па неће моћи да умакну; биће шчепани изблиза.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'И када буду казали: „Верујемо!“ А шта ће им то бити од користи кад је живот на Земљи био и прошао?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'У њу они нису пре веровали, говорили су оно што није познато, што је од истине далеко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'И између њих и онога што буду желели биће препрека, као што је пре било учињено са њима сличним, јер су сви они, заиста, много сумњали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Хваљен нека је Аллах, Створитељ небеса и Земље, Који анђеле са по два, три и четири крила чини изасланицима. Он оном што ствара додаје шта хоће. – Он, уистину, све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Милост коју Аллах подари људима - нико не може да ускрати, а оно што Он ускрати - нико не може, после Њега, да подари; Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'О људи, сетите се благодати којом вас Аллах обасипа! Постоји ли, осим Аллаха, икакав други створитељ који вас са неба и из земље опскрбљује?! Осим Њега нема другог истинског бога, па куда се онда одмећете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'Ако те они у лаж утерују - па и пре тебе су посланике у лаж утеривали, а Аллаху ће све да се врати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'О људи, Аллахова претња је заиста истина, па нека вас никако живот на овом свету не заслепи и нека вас Сотона у веровање у Аллаха не поколеба.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Сотона је, уистину, ваш непријатељ, па га таквим и сматрајте! Он позива своје присталице да буду становници у Ватри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'Онима који не верују припада жестока патња, а онима који верују и раде добра дела припада опроштај и велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'Како могу бити исти: онај коме су његова ружна дела приказана лепим, а и он их сматра лепим? Аллах у заблуди оставља оног кога хоће, а на Прави пут указује оном коме хоће, па не изгарај од жалости за њима. Аллах, заиста, добро зна све што они раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Аллах шаље ветрове који покрећу облаке, па их наводимо ка мртвим пределима и њима земљу, након што је била мртва, оживљавамо: такво ће да буде и проживљење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Ако неко жели величину - па, Аллаху припада сва величина! Ка Њему се дижу лепе речи, а добра дела их уздижу. А онима који имају зле намере, припада болна патња, а њихово сплеткарење ће пропасти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Аллах вас је створио од земље, затим од капи семена, и најзад вас чини мушкарцима и женама. И ниједна жена не затрудни, нити роди, а да Он то не зна. И ничији живот се не продужи, нити скрати, а да то није забележено у Књизи; то је Аллаху, уистину, лако!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Ни два мора нису једнака: једно је слатко и пријатно - вода му се лако пије, а друго је слано и горко; ви из сваког једете свеже месо и вадите накит којим се китите; и ти видиш лађе како по њему секу воду да би стекли из Његовог обиља, и да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'Он уводи ноћ у дан и уводи дан у ноћ, Он је потчинио Сунце и Месец - свако плови до одређеног рока; то вам је Аллах, ваш Господар; Њему припада сва власт! А они које, поред Њега, молите не поседују ништа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Ако их молите, не чују вашу молбу, а да и чују, не би вам се одазвали; на Судњем дану они ће да порекну да сте их Њему придруживали у обожавању! Нико неће да те обавести као Онај Који све у потпуности зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'О људи, ви сте сиромаси, ви требате Аллаха, а Аллах је независан и хвале достојан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Ако хоће, уклониће вас и довешће нова створења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'то Аллаху није тешко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'И ниједан грешник неће да носи туђе грехе; ако претоварени гресима позове да му они буду понесени, нико неће да му их понесе, па ни ближњи. А ти ћеш опоменути само оне који се Господара свог боје, иако их нико не види, и који обављају молитву – онај ко очисти своју душу, очистио је за своје добро. А Аллаху се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Нису никако исти слепац и онај који види,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'ни тмине и светло,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'ни хладовина и врућина,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'и нису никако исти живи и мртви. Аллах ће учинити да чује онај кога Он одабере, а ти не можеш да дозовеш оне у гробовима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'твоје је само да опомињеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Ми смо те послали с истином да радосне вести доносиш и да опомињеш. А није било народа коме није дошао онај који га је опомињао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Ако те они у лаж утерују - па, и они пре њих су посланике у лаж утеривали, а они су им доносили јасне доказе, и Листове и Књигу светиљку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'И Ја сам онда кажњавао оне који нису веровали, па каква је само била Моја осуда!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'Зар не знаш да Аллах спушта воду са неба и да Ми помоћу ње стварамо плодове различитих врста; а постоје брда белих и црвених стаза, различитих боја и сасвим црних;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'и има људи и животиња и стоке, исто тако, различитих врста. А Аллаха се, међу Његовим слугама, боје учени. Аллах је, заиста, силан и опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'Они који Аллахову Књигу читају и обављају молитву и удељују од онога чиме их Ми опскрбљујемо, и тајно и јавно, могу да се надају награди која неће да нестане,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'да их Он награди према ономе што су радили и још да им да из Свога обиља; јер Он много прашта и благодаран је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'А оно што ти из Књиге објављујемо сушта је истина, она потврђује да су истините и оне пре ње. Аллах, заиста, о својим створењима све у потпуности зна и све добро види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Ми ћемо учинити да Књигу после наследе оне Наше слуге које Ми изаберемо. Биће оних који ће се према себи огрешити, биће оних чија ће добра и лоша дела подједнако тешка бити, и биће и оних који ће, Аллаховом вољом, својим добрим делима друге надмашити. И то је благодат велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Рајски перивоји, у које ће да уђу, у којима ће златним наруквицама, бисером украшеним, да се ките, а хаљине ће, у њима, да им буду од свиле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, '„Хваљен нека је Аллах!“ Говориће, „који је од нас отклонио тугу. Наш Господар, заиста, много прашта и благодаран је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'Који нам је, од Своје доброте, даровао вечно боравиште, где умор неће да нас дотиче и у коме клонулост неће да нас сналази.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'А невернике чека ватра у Паклу, они неће да буду осуђени на смрт и неће да умру, и неће патња у њему да им се ублажи - ето, тако ћемо да казнимо сваког неверника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'они ће у њему да јаучу: "Господару наш, избави нас, радићемо добра дела, другачија од оних која смо радили!" А зар вас нисмо оставили да живите довољно дуго да би онај који је требало да размисли имао времена да размисли, а био вам је дошао онај који опомиње? Зато искусите патњу; неверницима нема помоћи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Аллах сигурно зна тајне небеса и Земље; Он добро зна све што крију груди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'Он чини да се смењујете на Земљи; ко не буде веровао, његово неверовање је на његову штету; неверницима ће њихово неверовање код њиховог Господара само да повећа презир, и неверницима ће њихово неверовање да повећа пропаст.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'Реци: „Кажите ви мени који су део Земље створила ваша божанства која, уместо Аллаха, молите, и реците ми имају ли они икаквог удела у стварању небеса, или смо Ми незнанобошцима дали Књигу, па имају у њој доказ за то!?“ Ниједно, већ неверници једни друге обмањују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'Заиста, Бог држи небеса и Земљу да не би нестали; а да нестану – нико то осим Њега не би могао спречити; Он је заиста благ и прашта грехе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'Они су се заклињали Аллахом, најтежом заклетвом, да ће, боље него било који народ, да се држе Правог пута - само ако им дође онај који ће да их опомиње. И кад им је дошао онај који опомиње, његов долазак само им је повећао одбојност;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'охолећи се на Земљи смишљали су зло - а сплетке ће да погоде управо оне који се њиме служе. Зар они могу да очекују нешто друго осим оно што је задесило древне народе?! У Аллаховим законима ти никад нећеш да нађеш промене; у Аллаховим законима ти нећеш да нађеш одступања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Зашто они не путују по Земљи да виде како су завршили они пре њих, који су били јачи од њих? Аллаху не може ништа да умакне ни на небесима ни на Земљи; Он, уистину, све зна и све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Да Аллах кажњава људе према оном што заслуже, ништа живо на Земљиној површини не би оставио; али, Он их оставља до одређеног рока и кад им дође рок - па, Аллах добро види Своје слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Ја-син.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, 'Тако Ми Кур''ана мудрог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'ти си, уистину, један од посланика,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, 'на Правом си путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'Кур''ан је објава Силног и Милостивог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'да упозораваш народ чији преци нису били упозоравани, па је немаран!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'О већини њих већ се обистинила Реч - зато они неће да верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Ми смо учинили да буду као они на чије смо вратове окове ставили све до подбрадака – зато су они глава уздигнутих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'и као они испред којих и иза којих смо преграду ставили и на очи им копрену ставили. Зато они не виде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'и њима је свеједно упозоравао их ти или их не упозоравао, они неће да верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Твоја опомена ће користити само оном који Кур’ан следи и Милостивог се боји и када га нико не види – њега обрадуј опростом и наградом лепом!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Ми ћемо, заиста, мртве оживети и Ми смо записали оно што су урадили и дела која су иза себе оставили – све смо Ми то у Књизи јасно побројали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Наведи им као пример становнике једног насеља, када су им дошли посланици;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'када им Ми посласмо двојицу, али их они сматраше лажним, и појачасмо трећим, па рекоше: „Ми смо, заиста, вама послати!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, '„Ви сте људи као и ми“, они одговорише, „Свемилосни није објавио ништа; ви говорите неистину!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, '„Наш Господар зна да смо, заиста, послати вама“, рекоше они,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, '„и дужни смо само да јасно обзнанимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'Они рекоше: „Ми слутимо да нам доносите несрећу; ако се не оканите, каменоваћемо вас и сигурно ће да вас задеси болна патња од нас.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, '“Узрок ваше несреће сте ви!” Рекоше они. “Зар зато што сте опоменути? Па ви сте народ који сваку границу зла прелази.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'И са краја града журно дође један човек и рече: „О мој народе, следите оне који су послати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'следите оне који од вас не траже никакву награду, а на Правом су путу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'Зашто да не обожавам Онога Који ме је створио, а Њему ћете да будете враћени?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Зар да прихватим друге богове поред Њега?! Ако Свемилосни хоће да ме снађе неко зло, њихово посредовање неће да ми буде ни од какве користи и они ме неће моћи спасити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'а ја бих тад био у правој заблуди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'ја верујем у Господара вашег, чујте ме!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'И би речено: „Уђи у Рај!“ - А он рече: “Камо среће да народ мој зна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'због чега ми је мој Господар опростио и учинио да будем међу почаствованим!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'И против његовог народа, после њега, Ми нисмо војску са неба послали, нити смо је иначе слали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'само би се чуо један ужасан крик, и они би одједном сви помрли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'О како су људи јадни! Ниједан посланик им није дошао, а да му се нису наругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Како они не увиде колико смо пре њих народа уништили од којих им се нико вратио није.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'А сви они биће заједно доведени пред Нас.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Доказ им је мртва земља: Ми јој живот дајемо и из ње ниче жито које они једу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Ми смо по њој створили баште, палмовике и винограде, и учинили смо да из ње извиру извори,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'да они једу њихове плодове - а нису то њихове руке привредиле - па зашто неће да буду захвални?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Нека је слављен и Узвишен Онај Који је у свему створио парове: у ономе што из земље ниче, у њима самима, и у ономе што они не знају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'И ноћ им је доказ: Ми уклањамо дневну светлост и они остају у мраку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'И Сунце се креће до свога станишта, то је одредба Силнога и Свезнајућег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'И Месецу смо одредили положаје; и он се увек поново враћа као стари савијени палмин прут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Нити Сунце може Месец да достигне, нити ноћ дан да претекне, сви они у свемиру плове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'Доказ им је и то што смо њихове претке превезли у крцатој лађи', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'и што смо за њих, сличне њој, створили, оно на чему се возе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'И ако желимо, Ми их потопимо, и нико у помоћ неће да им притекне, нити ће да буду избављени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'осим ако им се не смилујемо, да би до рока одређеног уживали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'А кад им се каже: „Бојте се онога што се пре вас догодило и онога што вас чека да бисте били помиловани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'И не дође им ниједан знак од знакова њиховог Господара којем они леђа не окренуше.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'А кад им се каже: „Удељујте од онога што вам Аллах даје“, онда неверници говоре онима који верују: „Зар да хранимо онога кога је Аллах, да је хтео, могао да нахрани? Ви сте, уистину, у правој заблуди!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'И говоре: „Кад ће већ једном то обећање, ако истину говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'А не чекају друго до један страшан звук који ће да их, док се буду једни са другима препирали, обузети,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'па неће моћи ништа опоручити, нити се својој породици вратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'И дувнуће се у рог, па ће они из гробова својих да похрле према своме Господару.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Рећи ће: „Тешко нама! Ко нас је оживео из наших гробова?“ „Ово је оно што је обећао Свемилосни, а посланици су говорили истину!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Биће то само један страшан звук, а они ће пред Нас сви да буду доведени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'Данас никоме неће да се учини насиље и ви ћете, само према ономе како сте радили, да будете награђени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Заиста ће становници Раја тог Дана уживати у благодатима весели и радосни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Они и њихове супруге биће у хладовини наслоњени на украшеним диванима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'у њему ће имати воћа, и оно што буду желели', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, '„Мир вама!“ - Биће речи Милостивог Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, '“а ви, о одметници, данас се одвојите!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'Зар вам нисам наредио о потомци Адамови: "Не обожавајте Сотону, јер вам је он, заиста, отворени непријатељ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'већ Мене обожавајте; то је Пут прави.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'Он је многе од вас одвео у заблуду, како нисте памети имали?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'Ово је Пакао којим вам се претило,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'пржите се сад у њему зато што нисте веровали!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'Данас ћемо да им запечатимо уста, њихове руке ће да Нам говоре, а њихове ноге ће о оном што су радили да сведоче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Да смо хтели, учинили бисмо их слепим, па кад би пошли на пут, како би видели?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'А да смо хтели, могли смо да их унаказимо на месту на коме су, па не би могли да се помере ни напред ни назад.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Ономе коме дамо дуг живот, Ми му изглед изменимо нагоре. Зар они не разумеју?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Ми Посланика нисмо учили песништву, то му не приличи. Ово је само поука - јасни Кур''ан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'да упозорава онога ко је жив, и да се обистини Реч о казни за невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Како они не виде да Ми само због њих стоку стварамо и да они њоме располажу као власници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'И подредили смо их њима - на некима јашу, а некима се хране,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'и других користи од ње имају, и напитке, па зашто нису захвални?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'И поред Аллаха друге узимају за богове како би им они помогли;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'они, међутим, не могу да им помогну, а људи су им послушна војска.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'И нека те не жалосте њихове речи; Ми, заиста, знамо и оно што они крију и оно што показују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'Како човек не види да га Ми стварамо од капи семена, и он опет отворени противник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'и Нама наводи пример, а заборавља како је створен, и говори: „Ко ће да оживи кости, кад буду труле?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'Реци: „Оживеће их Онај Који их је први пут створио; Он добро зна све што је створио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, 'Онај Који вам из зеленог дрвећа ватру ствара и ви њоме потпаљујете.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Зар Онај Који је створио небеса и Земљу није способан да створи њима сличне? Јесте, Он је Створитељ, Свезнајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'А Његова наредба, када нешто хоће, јесте да само за то каже: „Буди!“ - И оно буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Па нека је узвишен Онај у Чијој је руци власт над свим, и Њему ћете да будете враћени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'Тако ми оних поређаних у редове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'и оних који гоне облаке', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'и оних који читају Опомену,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'ваш Бог је, уистину, Један,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'Господар небеса и Земље и онога што је између њих, и Господар истока.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Ми смо најближе небо звездама украсили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'и чувамо га од сваког пркосног ђавола', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'да не прислушкује анђеле узвишене. Њих са свих страна гађају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'па бивају прогнани: њих чека непрекидна патња,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'а онога који шта уграби - стигне светлећа буктиња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Упитај их да ли је теже да створимо њих или све остало што смо створили? Њих смо, заиста, створили од лепљиве иловаче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Међутим, ти се чудиш и дивиш, а они се изругују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'а кад им се савети упућују, они их не прихватају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'и кад виде доказ, они се подсмејавају', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'и говоре: „Ово није ништа друго до права чаролија!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'Зар кад поумиремо и кад постанемо кости и земља, зар ћемо ми, заиста, да будемо оживљени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'и наши давни преци?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'Реци: „Да, а бићете и понижени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'То ће бити само глас један, и сви ће одједном прогледати', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'и рећи ће: „Тешко нама, ово је судњи Дан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, 'Да, ово је Дан раздвајања у који ви нисте веровали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, '„Сакупите оне који су били незнанобошци и њима сличне и оне које су обожавали', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'мимо Аллаха, и упутите их путем који у Пакао води.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'И зауставите их на тренутак, они ће, заиста, да буду питани:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, ',,Шта вам је, зашто једни другима не помогнете?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Али, тога Дана они ће сасвим да се предају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'И приступиће пребацивајући једни другима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Рећи ће: „Заиста сте нас ви у заблуду одвели.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, '„Нисмо“, одговориће, „него ви нисте хтели да верујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'И ми никакву власт нисмо имали над вама, него сте били незахвалан народ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'и реч нашег Господара да ћемо, заиста, да искусимо казну - на нама се остварила,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'а у заблуду смо вас позивали, јер и сами смо, заиста, били у заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'И они ће тог Дана да буду заједно у патњи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'а Ми ћемо, заиста, тако са незнанобошцима да поступимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Кад им је говорено: „Нема истинског божанства осим Аллаха!“ Они су се, заиста, охолили', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'и говорили су: „Зар да напустимо наша божанства због једног лудог песника?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'А није тако, он истину доноси и тврди да су сви посланици истину доносили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Ви ћете сигурно да искусите болну патњу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'и само ћете, сразмерно оном што сте радили, да будете кажњени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'Али не и Аллахове искрене слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'Њима ће заиста да припадне посебна опскрба;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'разно воће, и биће поштовани,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'у рајским баштама наслада,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'на диванима, једни према другим, седеће;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'биће служени пићем – из извора који стално тече –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'бистрим и пријатним онима који буду пили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'од њега им неће бити мука и због њега се неће памет губити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 'Поред њих биће оне које ће да гледају пред собом, прекрасних очију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'као да су оне јаја заштићена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'И они ће један с другим разговарати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'И један од њих ће да каже: „Имао сам једног друга,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'који је говорио: ''Зар и ти верујеш', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'да ћемо, кад поумиремо и постанемо земља и кости, заиста, да полажемо рачун?''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, '„Хоћете ли да погледате?“ Рећи ће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'И он ће да погледа, и њега усред Пакла да угледа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, '„Аллаха ми“, рећи ће му, „замало ме ниси упропастио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Да није било милости мога Господара, и ја бих сад био у Паклу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, 'Јел ми више нећемо никад да умиремо?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'Једном смо умрли, и нећемо више да патимо?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Ово је, заиста, велики успех!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'За овако нешто нека се вредни труде!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'А да ли је то боље као награда или дрво Зеккум?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Које смо неверницима као искушење одредили?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'То је дрво које расте усред Пакла,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'плод му је попут ђавољих глава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Они ће са њега да се хране и своје стомаке ће њиме да пуне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'затим ће то с кључалом водом измешати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'A потом ће, сигурно, опет да се врате у Огањ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Они су своје очеве затекли у заблуди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'па су и они њиховим стопама наставили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'А и пре њих су древни народи већином били у заблуди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'иако смо им Ми слали посланике који су их опомињали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'зато погледај какав је био крај оних који су били упозоравани,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'тако није било само са Аллаховим искреним слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'А када Нам се Ноје помолио, Ми смо се најбоље одазвали:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'и њега и његову породицу смо спасили тешке невоље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'и само смо његове потомке оставили у животу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'и у каснијим нараштајима му сачували спомен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, 'Мир и спас Ноју од свих светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Ми тако награђујемо оне који раде добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'он је био слуга Наш, верник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'а остале смо затим потопили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'Исте вере као и он био је и Аврам,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'кад је своме Господару дошао искреног срца,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'кад је своме оцу и своме народу рекао: „Шта то ви обожавате?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'Зар желите лажна божанства уместо Аллаха?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'И шта о Господару светова мислите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'И он баци поглед на звезде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'па рече: “Ја сам болестан!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'И они га оставише, окрећући се од њега.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'A он се њиховим киповима прикраде, па их упита: „Зашто не једете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'Шта вам је па не говорите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'И кришом им приђе ударајући их десном руком,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'па му народ журећи дође.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, '„Како можете да обожавате оне које сами клешете?“ Упита,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, '„кад Аллах ствара и вас и оно што направите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, '„Припремите за њега ломачу“, повикаше, „па га баците у ватру!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'И хтели су да му направе замку, али Ми њих учинисмо најпониженијим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, '„Идем тамо где ми је мој Господар наредио“, рече, „Он ће ме упутити где треба.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'Мој Господару, даруј ми честит пород!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'И Ми смо га обрадовали дечаком благе нарави.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'И кад је он одрастао толико да је почео у послу да му помаже, Аврам рече: „О мој синко, у сну сам видео да треба да те закољем, па шта ти мислиш?“ „О оче мој“, рече, „поступи онако како ти се наређује; видећеш, ако Аллах да, да ћу све издржати.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'И кад њих двојица послушаше, и он га положи челом према земљи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Ми га позвасмо: „О Авраме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'ти си одлучио да обистиниш свој сан - а Ми овако награђујемо оне који раде добра дела.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'То је, заиста, било очигледно искушење!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Великом жртвом га искуписмо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'и у каснијим нараштајима смо му сачували спомен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, 'Нека је у миру Аврам!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Ето, тако Ми награђујемо оне који раде добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'он је био слуга Наш, верник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'и обрадовали смо га Исаком, веровесником и добрим човеком,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'и благословили смо и њега и Исака; а међу њиховим потомцима има верника и неверника очигледних.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'И Мојсију и Арону смо дали благодати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'па и њих и њихов народ смо спасили велике невоље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'и помогли им, па су они били победници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'и дали им јасну Књигу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'и обојицу на Прави пут упутили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'и у каснијим нараштајима им сачували спомен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, 'Нека су у миру Мојсије и Арон!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Ето, тако Ми награђујемо оне који раде добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'а њих двојица су, уистину, били Наше слуге, верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'И Илија је био посланик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Кад он рече народу свом: “Зар се не бојите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Зар се молите Балу, а остављате најбољег Створитеља,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'Аллаха, свога Господара и Господара ваших древних предака?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Они га назваше лажовом и зато ће, сигурно, сви они у Ватру да буду приведени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'осим Аллахове искрене слуге,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'и у каснијим нараштајима му сачували спомен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, 'Нека је у миру Илија!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Ето, тако Ми награђујемо оне који раде добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'он је био слуга Наш, верник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'И Лот је био посланик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Ми смо њега и читаву његову породицу спасили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'осим старице, она је била са онима који су настрадали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'а остале смо уништили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'и ви поред њихових насеља пролазите и дању', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'и ноћу, па зашто се не уразумите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'И Јона је био посланик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'А кад побеже на једну лађу препуну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'И са њима баци коцку и коцка на њега паде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'па га риба прогута, а био је заслужио прекор,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'и да није био један од оних који Аллаха славе и величају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'сигурно би остао у њеној утроби до Дана кад ће сви да буду оживљени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'и Ми га избацисмо на једно пусто место, а био је болестан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'и учинисмо да изнад њега израсте врежа једне тикве,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'и посласмо га стотини хиљада људи, и више,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'и они повероваше, и њима смо дали да уживају до одређеног рока.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'А упитај их: „Зар су за твога Господара - кћери, а за њих синови?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Зар смо у њиховом присуству анђеле као жене створили?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Они, сигурно, измишљајући говоре:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, '„Аллах је родио!“ - А заиста су они лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'Зар је Он кћери синовима претпоставио?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Шта вам је, како расуђујете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Зашто не размислите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Или, ви, можда, имате очигледан доказ?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Донесите своју Књигу, ако говорите истину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Незнанобошци између Њега и анђела сродство успостављају, а анђели одавно знају да ће они који тако говоре у ватру бити бачени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Узвишен је Аллах и далеко од онога како Га они описују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'То не чине Аллахове искрене слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Али, ни ви незнанобошци, нити они које обожавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'не можете никога да одведете у заблуду,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'осим оног који ће ионако у Огњу да гори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'Свакоме од нас анђела је одређено место,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'ми смо поређани у редове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'и само Њега славимо и величамо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'А незнанобошци су говорили:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, '„Да смо ми имали Књигу као што су је имали претходни народи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'сигурно бисмо били Аллахове искрене слуге!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'Али у Кур''ан нису хтели да поверују, па сазнаће они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'А Наша реч већ је речена о Нашим слугама, посланицима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Они ће да буду, заиста, потпомогнути', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'и Наша војска засигурно ће да победи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'Зато се неко време окрени од њих', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'и посматрај их, и они ће да посматрају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Зар они Нашу казну да пожурују?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Кад их она стигне, зло јутро освануће онима који су били упозорени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'Зато се неко време окрени од њих', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'и посматрај, и они ће да посматрају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Величанствен је Господар твој, Достојанствени, и далеко од оног како Га представљају они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'И мир нека је над посланицима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'и хваљен нека је Аллах, Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Сад.[1] Тако Ми Кур’ана славног,', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'заиста су они који не верују инаџије и у расколу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Колико смо Ми уништили народа пре њих. И они су за помоћ вапили, али је било касно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'Они се чуде што им је дошао један од њих да их упозорава, и говоре неверници: „Ово је чаробњак, лажов!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Зар он да богове сведе на једног Бога?! То је, заиста, нешто веома чудно!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'И они угледни међу њима наставише: „Идите и устрајте уз своја божанства! Уистину, овим се нешто велико жели!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'За ово нисмо чули у вери предака наших, ово није ништа друго до измишљотина;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'зашто баш њему, између нас, да буде послата Опомена?!“ Али, они сумњају у Моју Опомену зато што нису искусили Моју казну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Зар су код њих ризнице милости Господара твог, Силног и Дарежљивог?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Или, они можда имају власт на небесима и на Земљи и над оним што је између њих?! - Нека се, онда, попну уз лестве ка небесима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'Они представљају незнатну уротничку војску која ће тамо бити поражена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'И пре њих су народ Нојев, и Ад, и фараон, који је имао моћну војску, порицали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'и Семуд, и Лотов народ, и становници Ејке – они су се против посланика уротили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Сви су они утеривали посланике у лаж и заслужили су казну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'А и ови не чекају до један звук рога који неће бити потребно поновити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'И говоре: „Господару наш, пожури и казни нас, пре Дана у којем ће рачун да се полаже!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Ти издржи оно што они говоре и сети се Наше слуге Давида, чврстог у вери, који се увек Аллаху покајнички обраћао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Ми смо потчинили брда да заједно са њим увече и у зору славе и величају Аллаха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'а и окупљене птице - сви су они са њим покорно понављали славу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'И учврстили смо његово царство и дали му мудрост и способност да расуђује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'А да ли је до тебе дошла вест о парничарима када су преко зида храма прешли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'кад су код Давида ушли, па се он од њих уплашио. „Не бој се“, рекли су, „ми смо двојица парничара, један другом смо учинили неправду, па нам пресуди по правди; не буди пристрасан, и на најбоље нас решење упути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'Овај мој пријатељ има деведесет и девет оваца, а ја само једну, и он ми рече: ''Дај ти њу мени!'' - И у говору ме победи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, '„Учинио ти је неправду!“ Рече Давид, „тиме што је тражио да твоју овцу дода својим овцама; многи ортаци чине неправду једни другима, такви нису једино они који верују и раде добра дела; а таквих је мало.“ И Давид се увери да смо Ми баш њега ставили на искушење, па опрост замоли од свога Господара, и паде лицем на тло и покаја се.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'И Ми смо му то опростили, и он је, заиста, Нама близак и чека га дивно пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'О Давиде, Ми смо те учинили намесником на Земљи, зато суди људима по правди и не поводи се за страшћу да те не одведе са Аллаховог пута; оне који скрећу са Аллаховог пута чека тешка патња зато што су заборављали Дан обрачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Ми нисмо узалуд створили небо и Земљу и оно што је између њих; тако мисле неверници, па тешко се неверницима због Ватре!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'Зар ћемо да поступимо са онима који верују и раде добра дела као са онима који праве неред на Земљи, и зар ћемо да поступимо са онима који се клоне греха исто као и са грешницима?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, 'Књига коју ти објављујемо је благословљена, да би они о њеним речима размислили и да би они који су обдарени разумом примили поуку.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'Ми смо Давиду поклонили Соломона; диван је он био слуга, стално се кајао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'Кад су једне вечери пред њим били изведени чистокрвни коњи који су на три ноге стајали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'он рече: „Уместо да величам свога Господара, ја исказујем љубав према иметку!“ И они се изгубише из вида.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, '“Вратите ми их!” И он их поче ударати сабљом по ногама и вратовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Ми смо Соломона искушали и на његов престо другу особу оставили, а затим се покајао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, '"Мој Господару" - рекао је - "опрости ми и даруј ми власт какву нико осим мене неће да има! Ти уистину богато дарујеш!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'И Ми смо му подредили ветар, који је према његовој заповеди благо дувао онамо куда је он хтео,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'и ђаволе, све градитељи и рониоци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'и други повезани у окове.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, 'Ово је Наш дар, па ти даруј или ускрати, нећеш због тога да одговараш!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Он је, заиста, Нама близак и чека га предивно пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'И сети се Наше слуге Јова, када је завапио своме Господару: „Сотона ме на зло навраћа и мисли лажне ми улива!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, 'Удари ногом о земљу ето хладна вода за купање и пиће!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'И Ми смо му, из Наше милости, даровали породицу и још толико уз њих, да буде поука за оне који имају памети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, '„И узми својом руком сноп и њиме удари, само заклетву не прекрши.“ Ми смо, заиста, увидели да је он стрпљив; диван је он слуга био и много се кајао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'И сети се наших слуга: Аврама и Исака и Јакова, сви у вери чврсти и постојани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Ми их посебно обдарисмо једном врлином: да им је увек био на уму Будући свет;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'и они су, заиста, код Нас од оних одабраних добрих људи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'И сети се Јишмаела и Јелисеја и Илије и Језекиља, сви су они били честити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Ово је леп спомен! А богобојазне чека дивно пребивалиште,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'вртови Една, чије ће капије да буду отворене за њих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'у којима ће се одмарати и разноврсно воће и пиће тражити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 'Поред њих биће рајске лепотице, истих година, које ће пред собом да гледају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'То је оно што вам се обећава за Дан у коме ће се рачун полагати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'то ће, заиста, да буде Наша благодат, која никада неће да престане!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Ето тако! А оне који буду зло чинили чека најгоре пребивалиште:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Пакао, у којем ће да горе; а грозног ли одмаралишта!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'Ето толико! Па ће кушати воду кључалу и капљевину смрдљиву,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'и друге муке сличне овима, многоструке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'Ова гомила заједно са вама, гурајући се, ће да уђе у Пакао! "Не било им пространо! У Ватри ће они, заиста, да горе!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, '„Вама не било пространо!“ Рећи ће они, „ви сте нам ово припремили, а грозног ли боравишта!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, '„Господару наш“, рећи ће, „удвостручи патњу у Ватри онима који су нам ово приредили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'И говориће: „Зашто не видимо људе које смо злим сматрали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'и које смо исмејавали? Да нам се нису изгубили из вида?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Истина је, сигурно, да ће становници Пакла међу собом да се расправљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'Реци: „Ја сам само опомињач; нема бога осим Аллаха, Јединога и Моћног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Господара небеса и Земље и онога што је између њих, Силнога и Опростиоца греха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'Реци: „Ово је велика вест,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'а ви од ње окрећете главе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'Ја нисам ништа знао о узвишеном скупу када су се препирали -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'мени се објављује да сам послат да јасно опомињем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'Када је анђелима твој Господар рекао: „Створићу човека од глине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'па кад му употпуним облик и у њега удахнем живот, ви му се поклоните!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Анђели су се, сви до последњег, заједно поклонили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'осим Сотоне - он се узохолио и постао неверник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, '„О Сотона!“ Рече Аллах, „шта те навело да се не поклониш ономе кога сам Ја Својим двема рукама створио? Јеси ли се узохолио или мислиш да си узвишен?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, '„Бољи сам од њега“, рече он, „мене си створио од ватре, а њега од глине.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, '„Излази онда из Раја!“ Рече Аллах, „проклет да си!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Моје ће проклетство да те прати до Судњег дана!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, '„Господару мој!“, рече он, „дај ми времена до дана када ће они да буду оживљени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, '„Даје ти се времена“, рече Аллах,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'до дана већ одређеног.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, '„Тако ми Твога достојанства“, рече Сотона, „сигурно ћу све да их наведем на странпутицу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'осим међу њима Твоје искрене слуге!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, '„Ово је истина а истину говорим“, рече Аллах,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, '„сигурно ћу свима, тобом и онима који се буду повели за тобом, да напуним Пакао!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'Реци: „Не тражим ја од вас за ово никакву награду и ја не додајем преко оног чиме ме је Аллах обавезао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'Кур''ан је, заиста, целом свету опомена!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'И ви ћете ускоро сазнати његову поруку!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Књигу објављује Аллах, Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Ми ти, заиста, објављујемо Књигу, праву истину, па обожавај само Аллаха, искрено верујући у Њега.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'А зар чисто веровање не припада само Аллаху? А они који поред Њега узимају заштитнике говоре: „Ми их обожавамо само зато да би нас што више приближили Аллаху.“ Аллах ће њима, заиста, да пресуди о ономе у чему су се они разилазили. Аллах никако неће да упути на Прави пут онога ко је лажљивац и неверник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'Да је Аллах хтео да има дете, изабрао би, између оних које је створио, онога кога би Он хтео. Слављен нека је, Он је Аллах, Једини и Свемоћни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'Небеса и Земљу је створио са истином; Он ноћу обавија дан, и даном обавија ноћ; Он је потчинио Сунце и Месец, свако се креће до одређеног рока. Он је Силни, Он много прашта!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'Он вас од једног човека ствара – а од њега је жену његову створио – и Он вам је дао осам врста стоке; Он вас ствара у утробама ваших мајки, дајући вам облике, један за другим, у три тмине. То вам је, ето, Аллах, ваш Господар, Његова је власт, нема истинског бога осим Њега, па куда се онда окрећете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Ако ви будете неверници – па Аллах од вас не зависи, али Он није задовољан ако су слуге Његове неверници, а задовољан је вама ако будете захвални. И ниједан грешник неће носити грехе другога! Затим ћете се Господару свом вратити, па ће вас Он о оном шта сте радили обавестити, јер Он добро зна свачије мисли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'Кад човека снађе невоља, моли се своме Господару, понизно Му се обраћајући, а онда, када му Аллах подари Своју благодат, заборави Онога Коме се пре молио, и поред Њега обожава друга божанства, како би са Његовог пута одводио на странпутицу. Реци: „Уживај неко време у своме неверовању, бићеш, сигурно, становник у Ватри!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Зар је такав као онај који у ноћним сатима проводи време у молитви, падајући лицем на тло и стојећи, страхујући од Судњег дана и надајући се милости свога Господара?! Реци: „Зар су исти они који знају и они који не знају?! Само они који памети имају поуку примају!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'Реци: „О слуге Моје који верујете, бојте се свога Господара! Они који на овом свету буду радили добра дела имаће добро, а Аллахова је Земља пространа; само ће они који буду стрпљиви бити награђени без обрачуна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'Реци: „Наређено ми је да обожавам Аллаха, искрено Му исповедајући веру.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'И наређено ми је да будем најпреданији верник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'Реци: „Ја се бојим патње на Великом дану, ако своме Господару будем непослушан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'Реци: „Само Аллаха обожавам, исповедајући Му искрено веру,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'а ви, поред Њега, обожавајте кога хоћете!“ Реци: „Губитници су, уистину, они који на Судњем дану изгубе и себе и своје породице. Заиста је то очигледан губитак!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'Над њима ће да буду наслаге од ватре, а и испод њих наслаге; тиме Аллах плаши Своје слуге. О слуге Моје, бојте се Мене!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'За оне који избегавају обожавање лажних божанстава и који се Аллаху обраћају - њима су намењене радосне вести, зато обрадуј Моје слуге', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'које Кур’ан слушају и следе оно најлепше у њему; њих је Аллах на Прави пут упутио и они су паметни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Зар ти да спасиш оног који је заслужио казну, оног који ће сигурно бити у Ватри?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'А оне који се боје свога Господара чекају одаје, саграђене све једне изнад других, испод којих теку реке - Аллахово је обећање, а Аллах неће обећање да прекрши.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Зар не видиш да Аллах спушта воду са неба, па је као изворе по Земљи разводи, а онда помоћу ње изводи разнобојно биље, затим се осуши и ти га видиш пожутелог, и најзад га скрши?! То је, заиста, опомена за оне који имају памети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Зар је исти онај чије је срце Аллах учинио склоним исламу, па он следи светло Господара свог? Тешко онима чија су срца неосетљива кад се спомене Аллах, они су у правој заблуди!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Аллах објављује најлепши говор, Књигу сличну по смислу, чије се поруке понављају, због којих подилази језа оне који се Господара свог боје, а кад се спомене Аллах, коже њихове и срца њихова се смирују. То је Аллахов Прави пут на који Он указује оном коме Он хоће. А оног кога Аллах остави у заблуди нико на Прави пут неће моћи да упути.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Зар је исти онај који ће се на Судњем дану лицем својим заклањати од страховите патње? Незнанобошцима ће бити речено: „Трпите оно што сте заслужили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Они пре њих су порицали, па их је стигла казна одакле нису очекивали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Аллах је дао да осете понижење у животу на овом свету, а патња на Оном свету биће, заиста, још већа - кад би они само знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Ми у овом Кур''ану наводимо људима свакакве примере, да би примили поуку;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'у Кур’ану на арапском језику, у коме нема никакве противречности, да би се Господара свог побојали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'Аллах наводи као пример човека који је у власти ортака и за којег се они отимају, и човека који је у власти само једног човека - да ли је положај њих двојице исти?! Сва хвала нека је Аллаху, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'Ти ћеш, сигурно, да умреш, а и они ће, такође, да помру.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'А затим ћете, на Судњем дану, пред својим Господаром међусобно да се спорите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Има ли већег неправедника од онога који о Аллаху говори лажи и сматра истину лажном када му долази?! Зар у Паклу неће да буде пребивалиште за невернике?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'А онај који доноси истину и они који у њу верују, они су богобојазни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'све што зажеле наћи ће код свога Господара, то ће да буде награда онима који су радили добра дела,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'да би Аллах преко ружних поступака њихових прешао, и да би их за лепа дела која су радили наградио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Зар Аллах није Свом слуги довољан?! А они те плаше онима које, поред Њега, обожавају. Онога коме да Аллах да је у заблуди - нико не може да га упути на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'А онога кога Он на Прави пут упути - нико не може да га доведе у заблуду. Зар Аллах није силан и Онај Који кажњава?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'Ако их упиташ ко је створио небеса и Земљу, сигурно ће да кажу: „Аллах!“ А ти реци: „Мислите ли ви, да ли би они које ви, поред Аллаха, обожавате могли да отклоне штету, ако Аллах хоће да ми је учини, или, да ли би могли да задрже Његову милост, ако Он хоће да ми је подари?“ Реци: „Мени је довољан Аллах, на Њега се ослањају верници.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'Реци: „О народе мој, ти поступај онако како поступаш, а и ја ћу да поступам, па ћете да сазнате', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'кога ће да стигне патња која ће да га понизи, и кога ће да снађе вечна патња!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Ми теби, заиста, објављујемо Књигу саму истину за све људе; онај ко буде ишао Правим путем - себи ће да користи, а онај ко буде ишао странпутицом - себи ће да науди, ти ниси задужен за њихову упуту.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Аллах узима душе у часу њихове смрти, а и оних који спавају, а који још умрли нису, па задржава оне којима је одредио да умру, а оставља оне друге до рока одређеног. То су, заиста, докази за оне који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Зар они мимо Аллаха заговорнике узимају?! Реци: „Зар и онда када су без икакве моћи и када ништа не разумеју?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'Реци: „Свакo заговарање припада Аллаху, Његова је власт на небесима и на Земљи, а затим ћете Њему да се вратите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Кад се спомене само Аллах, грче се срца оних који у Будући свет не верују, а када се спомену они које они поред Њега обожавају, одједном их обузме радост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'Реци: „Аллаху, Који си створио небеса и Земљу, Ти Који знаш невидљив и видљив свет, Ти ћеш Својим слугама да пресудиш у ономе у чему су се разилазили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Када би незнанобошци имали све што је на Земљи, и још толико, на Судњем дану они би све то дали како би се искупили од тешке патње; а Аллах ће их казнити казном какву нису могли ни наслутити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'и указаће им се њихова лоша дела која су радили и снаћи ће их баш оно чему су се изругивали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'Кад човека снађе каква невоља, Нама се моли; а кад му Ми после благодат пружимо, онда говори: „Ово ми је дато због мог знања!“ А није тако, то је само искушење, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Тако су говорили и они пре њих, па им није користило оно што су били стекли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'па их је стигла казна за зла дела која су радили. А и оне међу овима који се моле идолима - стићи ће казна за оно што чине, неће се спасити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Зар они не знају да Аллах даје опскрбу у изобиљу ономе коме хоће, и да ускраћује; то су, заиста, поуке народу који верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'Реци: “О слуге Моје које сте се према себи огрешили, не губите наду у Аллахову милост! Аллах ће, сигурно, све грехе да опрости. Он, заиста, много прашта и Он је Милостиви.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'И повратите се своме Господару и покорите Му се пре него што вам дође казна - после нико неће да вам прискочи у помоћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'И следите оно најбоље што вам објављује ваш Господар, пре него што вам изненада дође казна, чији долазак нећете да предосетите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'Да човек не би узвикнуо: „Тешко мени, колико сам само дужности према Аллаху пропустио, чак сам се и изругивао!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Или да не би рекао: “Да ме је Аллах Правим путем упутио, сигурно бих се Његове казне сачувао!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Или, да не би рекао кад доживи патњу: „Да ми је само да се повратим – добра дела бих радио!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, '“Никад! Долазиле су ти поуке Моје, па си их порицао и охолио се, и неверник си био.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'На Судњем дану видећеш поцрнела лица оних који су о Аллаху говорили лажи. А зар у Паклу неће да буде боравиште охолих?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Аллах ће да спаси оне који су извршавали Његове заповести а клонили се Његових забрана, па ће успети; зло их неће дотаћи и они неће туговати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Аллах је Створитељ свега и Он управља свим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'код Њега су кључеви небеса и Земље! А они који у Аллахове доказе и знакове не верују - они ће заиста да буду губитници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'Реци: „Зар од мене тражите да некога другог, поред Аллаха, обожавам, о незналице!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'А теби, и онима пре тебе, је објављено: „Ако би друга божанства поред Аллаха обожавао твоја дела би сигурно пропала, и сигурно би био међу страдалницима."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Него, једино Аллаха обожавај и буди захвалан!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Они нису величали Аллаха онако како треба да Га величају; а читава ће Земља на Судњем дану да буде у Његовој шаци, а небеса ће у Његовој десници да остану умотана. Чист је Он и Узвишен изнад оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'И у рог ће да буде дувнуто, и умреће они на небесима и они на Земљи, остаће само они које буде Аллах одабрао; после ће да се други пут дуне у рог и они ће, одједном, да устану и да чекају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'И Земља ће светлошћу свога Господара да засја, и Књига ће да буде постављена, веровесници и сведоци биће доведени, и по правди ће да буде пресуђено свима, никоме неправда неће да буде учињена;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'свако ће у потпуности да добије оно што је заслужио, а Он најбоље зна шта су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Они који нису веровали у поворкама ће у Пакао да буду натерани, и кад до њега дођу, његове капије ће да буду поотваране и чувари ће да их упитају: „Зар вам нису долазили ваши посланици, који су вам речи вашег Господара казивали, и упозоравали вас да ћете овај свој дан да доживите?!“ „Јесу“, рећи ће они, “али још је давно одређено да ће неверници кажњени бити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'И биће речено: „Улазите на капије Пакла, вечно ћете у њему да боравите! Грозног ли пребивалишта онима који су се охолили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'А они који су се свога Господара бојали у поворкама ће у Рај да буду поведени, и кад до њега дођу - његове капије већ широм отворене – његови чувари ће да им кажу: „Мир вама, од греха сте чисти, зато уђите у Рај, у њему ћете вечно да боравите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'И они ће да кажу: „Сва хвала нека је Аллаху Који нам је Своје обећање испунио, и у Рају нам место даровао, да се у њему населимо где хоћемо. Дивне ли награде онима који су се трудили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'И видећеш анђеле како окружују Престо, величајући и хвалећи свога Господара; и свима је пресуђено по правди, и биће речено: “Хваљен нека је Аллах, Господар светова!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Књигу објављује Аллах, Силни и Свезнајући,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Који опрашта грехе и прима покајање, Који страховито кажњава и обилно награђује. Другог истинског бога осим Њега нема, Њему се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'О Аллаховим речима и доказима расправљају само они који не верују, па нека те не обмањује то што они уживају путујући по Земљи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'И Нојев је народ пре њих порицао, а и после њега они који су се били против посланика уротили. Сваки народ настојао је домоћи се свог посланика и трудио се неистином угушити истину, па сам га Ја кажњавао – а каква је била казна Моја!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'И тако ће реч твога Господара да се испуни да ће они који нису веровали бити становници у Ватри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Анђели који носе Престо и они који су око њега, славе и хвале свога Господара и верују у Њега, и моле се да буду опроштени греси верницима: „Господару наш, Ти све обухваташ милошћу и знањем; зато опрости онима који се покају и који следе Твој пут и сачувај их патње у Ватри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'Господару наш, уведи их у вртове Едена које си им обећао, и оне који су били добри од њихових предака, и њихових жена, и њиховог потомства. Ти си, уистину, Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'И поштеди их казне због злих дела, јер, кога Ти тога дана поштедиш казне због злих дела - Ти си му се смиловао, а то ће, заиста, да буде велики успех!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Онима који нису веровали биће речено: „Аллахов презир према вама кад сте, позивани да верујете, остали неверници - је заиста већи од вашег презира сада према себи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, '„Господару наш“, рећи ће они, „два пута си нас усмртио и два пута си нас оживео; ми признајемо наше грехе, па има ли каквог начина за излазак из Ватре?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, '„То вам је зато што нисте веровали када се позивало Аллаху Једином, а веровали сте ако би се нешто друго поред Њега обожавало! Суд припада једино Аллаху, Узвишеном и Великом.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'Он вам показује Своје знакове и спушта вам опскрбу са неба, а поуку ће да прихвати само онај који се Њему обраћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Обожавајте зато једино Аллаха, искрено Му исповедајући веру - па макар то неверницима било мрско!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'Он је власник високих степена, Господар Престоља Који шаље Објаву, речи Своје – коме хоће међу Својим слугама, да упозори на Дан међусобног сусрета,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'на Дан када ће они да се појаве, када Аллаху неће да буде о њима ништа скривено. “Коме једино припада власт тог Дана? Аллаху Једином, Покоритељу!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'Сваки ће човек тог Дана да буде кажњен или награђен према заслузи; тог Дана неће да буде неправде! Аллах ће, заиста, брзо свести рачуне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'И упозори их на блиски дан, када ће срца до гркљана да допру и попрече се, када неверници неће имати ни блиског пријатеља ни посредника чији заговор би био услишан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, 'Он зна погледе који криомице у оно што је забрањено гледају, а и оно што груди крију;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Аллах ће по правди да пресуди, а они које поред Њега моле - неће ни по чему да суде. Аллах, заиста, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Зашто они не путују по Земљи, па да виде какав је био крај оних пре њих? Били су од њих моћнији и више су трагова на Земљи оставили, али их је Аллах, због њихових греха, казнио и није имао ко да их од Аллахове казне заштити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Аллах их је казнио зато што су порицали јасне доказе које су им доносили њихови посланици; Он је, заиста, Моћни, Он жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Ми смо послали Мојсија са Нашим речима и јасним доказом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'фараону и Хаману и Каруну, али су они рекли: „Чаробњак и лажов!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'А кад им је он донео истину од Нас, рекли су: “Убијајте мушку децу оних који верују у оно што он говори, а остављајте у животу њихову женску децу!” Али, лукавства неверника увек су узалудна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, '„Пустите ви мени“, рече фараон, „да убијем Мојсија, а он нека моли помоћ од свога Господара, јер бојим се да вам он веру вашу не измени или да у земљи неред не изазове.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Мојсије рече: „Молим свога Господара и вашег Господара да ме заштити од сваког охолог који не верује у Дан у коме ће да се полаже рачун!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'А један човек, верник, из фараонове породице, који је крио своје веровање, рече: „Зар да убијете човека зато што говори: ''Мој Господар је Аллах!'' А донео вам је јасне доказе од вашег Господара? Ако је лажов, његова лаж ће њему да науди, а ако говори истину, онда ће да вас стигне бар нешто од онога што вам се прети; заиста Аллах неће да упути на Прави пут онога који у злу претерује и који много лаже.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'О народе мој, данас вама припада власт и надмоћни сте у земљи, па ко ће да нас одбрани од Аллахове казне ако нас она стигне?“ А фараон рече: „Саветујем вам само оно што мислим, а само ћу ја да вас на исправни пут упутим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'А онда онај верник рече: “О народе мој, бојим се да и вас не стигне оно што је стигло народе који су се против посланика били уротили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'као што је то било са Нојевим народом, и Адом и Семудом, и онима после њих. А Аллах није неправедан према Својим слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'О мој народе, плашим се шта ће да буде са вама на Дан када једни друге будете дозивали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'на Дан кад будете узмичући бежали, кад вас од Аллаха неће моћи нико одбранити. А оног кога Аллах у заблуди остави, тога неће нико упутити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Јосиф вам је, још давно, донео јасне доказе, али ви сте стално сумњали у оно шта вам је донео. А кад је он умро, рекли сте: „Аллах више неће после њега да пошаље посланика!“ Ето, тако Аллах оставља у заблуди сваког ко у злу претерује и сумња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'Они који о Аллаховим речима и знаковима расправљају, иако им никакав доказ није дошао - заслужују велики презир код Аллаха и код оних који верују. Тако Аллах печати срце сваког охолог силника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, '„О Хамане“, рече фараон, „сагради ми торањ не бих ли стигао до стаза,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'небеских стаза, не бих ли се попео до Мојсијевог Бога, а ја сматрам да је Мојсије, заиста, лажов.“ И ето тако су фараону његова ружна дела улепшана, и он је био одвраћен од Правог пута, а лукавство се фараоново завршило на његову штету.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'А онај верник рече: „О мој народе, мене следите, ја ћу на Прави пут да вам укажем!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'О народе мој, живот на овом свету само је пролазно уживање, а Будући свет је, заиста, Кућа вечна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Ко год учини зло, само ће због њега да буде кажњен, а ко год учини добро - био мушкарац или жена, а верник је - тај ће да уђе у Рај; у њему ће имати у обиљу свега, без рачуна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'О народе мој! Шта је ово? Ја вас позивам у спас, а ви мене позивате у Ватру;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'Позивате ме да не верујем у Аллаха и да поред Њега обожавам оно о чему немам знања, а ја вас позивам Силноме, Оном који опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'Нема нимало сумње у то да се они којима ме позивате неће ником ни на овом ни на Будућем свету одазвати и да ћемо се Аллаху вратити и да ће незнанобошци становници у Огњу бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'И сетићете се овог што вам кажем! А ја Аллаху препуштам свој случај; Аллах, уистину, добро види Своје слуге.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'И Аллах га је сачувао од зала оног што су сплеткарили, а фараонове присталице зла патња задеси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'Они ће се ујутру и навече у ватри пржити. А кад наступи Час: “Уведите фараонове људе у патњу најтежу!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'И када се у Ватри буду препирали, па они који су били потлачени кажу својим главешинама: „Ми смо били ваши следбеници, можете ли да нас макар мало ослободите Ватре?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'Онда ће главешине да кажу: „Заиста смо сви у њој! Аллах је већ пресудио Својим слугама.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'И они који ће да буду у Ватри говориће чуварима Пакла: „Замолите свога Господара да нам бар један дан ублажи патњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, '„А зар вам ваши посланици нису доносили јасне доказе?“ Упитаће они. „Јесу!“ Одговориће. „Молите онда ви!“ Рећи ће они. Али ће молба неверника узалудна да буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'Ми ћемо, заиста, да помогнемо Наше посланике и оне који верују на овом свету, а и на Дан кад устану сведоци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'на Дан кад неверницима њихово правдање неће да буде од користи; њих чека проклетство и најгоре пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Ми смо Мојсију дали упуту и Израиљевим синовима смо оставили Књигу у наследство,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'да буде упутство и опомена онима који буду имали памети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Па ти буди стрпљив - Аллахово обећање је истина - и моли да ти буду опроштени греси, и свога Господара слави и хвали увече и ујутру!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Заиста они који о Аллаховим речима и знацима расправљају, иако никакав доказ немају - у њиховим срцима је само охолост са којом неће ништа постићи, па ти тражи од Аллаха заштиту. Он, уистину, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Стварање небеса и Земље сигурно је веће него стварање људског рода, али већина људи не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Нису једнаки слепац и онај који види, нису једнаки верници који добра дела чине и злочинитељи. Како мало вас поуку прима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Доћи ће Судњи час, у то нема сумње, али већина људи не верује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Ваш Господар каже: „Помолите Ми се, и ја ћу вам се одазвати! Заиста, они који из охолости неће да Ме обожавају - ући ће, сигурно, понижени у Пакао.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Аллах вам је дао ноћ да се у њој одмарате, а дан да видите. Аллах је неизмерно дарежљив према људима, али већина људи не захваљује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'То вам је, ето, Аллах, ваш Господар, Створитељ свега, другог истинског бога осим Њега нема, па куда се онда одмећете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'Тако су се одметали и они који су Аллахове речи и доказе порицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Аллах вам је учинио Земљу пребивалиштем, а небо здањем, и Он вам обличје даје и ликове ваше чини лепим, и јелима вас опскрбљује укусним. То је Аллах, ваш Господар, и нека је Узвишен Аллах, Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'Он је Живи, нема истинског бога осим Њега, па, молите Га, исповедајући Му искрено веру. Свака хвала припада Аллаху, Господару светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'Реци: „Мени је забрањено да обожавам оне које ви мимо Аллаха молите, након што су ми дошли јасни докази од мога Господара, и наређено ми је да се предам Господару светова.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'Он вас ствара од земље, затим од капи семена, затим од угрушка, затим чини да се као дојенчад рађате, и да до мужевног доба стигнете, и да старци постанете – а неки од вас умиру пре – и да до одређеног рока поживите како бисте могли схватити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'И Он даје живот и смрт! А кад нешто одлучи, само каже: „Буди“, и оно буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Зар не видиш оне који расправљају о Аллаховим речима и знацима; куда се они окрећу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'То су они који поричу Књигу и оно што смо слали по посланицима?! А сазнаће они!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Кад са оковима о врату и ланцима буду вучени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'по кључалој води, а затим пржени у Ватри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'Затим ће да буду упитани: „Где су они које сте обожавали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'мимо Аллаха?“ „Изгубили су се од нас“, одговориће, „ми се пре, у ствари, нисмо никоме ни молили.“ Ето, тако Аллах оставља у заблуди невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, '„То вам је зато што сте се са заблудом дичили на Земљи и зато што сте охоли били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'Улазите кроз капије Пакла, у њему ћете вечно да останете - а ружно је пребивалиште охолих!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Зато се стрпи! Заиста је Аллахова претња истина! Било да ти покажемо део онога што им Ми претимо, било да ти пре тога живот одузмемо - Нама ће они да се врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'И пре тебе смо посланике слали, о некима од њих смо ти казивали, а о некима ти нисмо казивали. И ниједан посланик није могао учинити никакво чудо без Аллахове воље. А када се Аллахова одредба испуни, биће пресуђено по истини и страдаће тада губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Аллах је за вас створио животиње, да на некима јашете а неке једете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Ви од њих користи имате и ви на њима за вас важне потребе остварујете – и на њима и на лађама ви се превозите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'Он вам показује доказе моћи Своје, па које Аллахове доказе не признајете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Зашто они не путују по свету, па да виде како су завршили они пре њих? Они су били од њих бројнији и јачи и више су трагова на Земљи оставили, и ништа им није користило оно што су стекли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Када су им њихови посланици доносили јасне доказе, они су се дичили знањем које су имали, и снашло их је оно чему су се стално ругали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'А кад би доживели Нашу казну, онда би говорили: „Ми верујемо у Аллаха, у Њега јединог, а одричемо се оних које смо Му у обожавању придруживали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Али им веровање њихово, кад би казну Нашу доживели, не би нимало било од користи, према Аллаховом закону који је вредео за све слуге Његове које су биле и нестале – и тад би неверници страдали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, 'Објава је од Свемилосног Милостивог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'Књига чији су докази јасно изложени, Кур''ан на арапском језику за људе који знају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'Доносилац радосних вести и опомена - али се већина њих опет окреће, неће да чују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'И говоре: „Наша срца су затворена за оно у шта нас ти позиваш. Ми смо глуви према томе, а између нас и тебе је преграда, па ти ради, и ми ћемо да радимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'Реци: „Ја сам само човек као и ви, мени се објављује да је ваш Бог само један Бог, зато устрајно верујте у Њега, и опрост од Њега тражите. А тешко незнанобошцима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'који милостињу не дају и који у Будући свет не верују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'Онима који верују и раде добра дела, заиста припада непрекидна награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'Реци: „Зар ви заиста нећете да верујете у Онога Који је Земљу створио у два дана - и још Му друга божанства приписујете?! То је Господар светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Он је по њој непомична брда створио и учинио је благословљеном и храну за њене становнике на њој je одредио, све то у четири дана равномерна – то је објашњење за оне који питају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Затим се усмерио на небо док је оно још било магла, па њему и Земљи рекао: „Појавите се милом или силом!“ „Појављујемо се драге воље!“ Одговорили су.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Тада их је створио у два дана, као седам небеса, и одредио је шта ће на сваком небу да се налази. А најближе небо смо украсили светиљкама и њих смо учинили као заштиту. То је одредба Силнога и Свезнајућег.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Па ако се окрену, ти реци: „Упозоравам вас на онакав удар какав је погодио Ад и Семуд“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'Кад су им, са свих страна, њихови посланици долазили говорећи: „Не обожавајте никога осим Аллаха!“ А они су одговарали: „Да је наш Господар хтео, Он би послао анђеле! Заиста ми не верујемо у оно што је послато по вама!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'Што се тиче народа Ад, они су се на Земљи без икаквог основа охолили и говорили: „Ко је од нас јачи?“ А зар нису знали да је Аллах, Који их је створио, јачи од њих - а и Наше речи и доказе су порицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'И Ми смо послали против њих, у узастопним данима, ледени ветар, да бисмо им још у овосветском животу дали да осете срамну патњу. А патња на оном свету биће, заиста, још више понижавајућа и нико неће у помоћ да им притекне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'А што се тиче народа Семуд, њих смо били упутили истини, али њима је била дража слепоћа од упуте, па их је стигао понижавајући удар, онако како су заслужили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'а спасили смо оне који су веровали и Аллаха се бојали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'А на Дан кад Аллахови непријатељи у ватру буду потерани – они први биће задржани, да би их сустигли остали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'И кад дођу до ватре, њихове уши, и њихове очи, и њихове коже сведочиће против њих о оном што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, '„Зашто сведочите против нас?“ Упитаће они своје коже. „Аллах, Који је дао способност говора сваком бићу, обдарио је и нас даром говора“, одговориће. „Он вас је први пут створио и Њему сте се вратили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Ви нисте скривали грехе како не би ваше уши и ваше очи и ваше коже против вас сведочиле, већ зато што сте мислили да Аллах неће да сазна много штошта што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'И то уверење које сте имали о своме Господару вас је упропастило, и сад сте настрадали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Па ако буду трпели, њихово боравиште ће да буде Ватра; а ако буду тражили наклоност да се врате, њиховој молби се неће удовољити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'И Ми смо им били одредили пратиоце па су им лепим приказивали оно што су урадили и оно што ће урадити, и на њима се обистинило оно што је речено за народе, духове и људе који су пре њих били и нестали - заиста су настрадали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Они који не верују говоре: „Не слушајте овај Кур'' ан, него правите буку да бисте га надвикали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'Зато ћемо Ми, сигурно, дати да неверници искусе несносну патњу, и казнићемо их најгором казном за дела која су починили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'То је казна за Аллахове непријатеље - ватра у којој ће да им буде вечно боравиште, као казна што су Наше речи и доказе стално порицали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'А они који нису веровали рећи ће: „Господару наш, покажи нам духове и људе, оне који су нас завели, да их ставимо под своје ноге, нека буду најдоњи.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Заиста онима који говоре: „Наш Господар је Аллах“, па после буду устрајни, долазе анђели: „Не бојте се и не жалостите се, и радујте се Рају који вам је обећан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Ми смо ваши заштитници у животу на овом свету, а и на Будућем свету; у њему ћете да имате све оно што ваше душе зажеле, и што год затражите - имаћете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'бићете почашћени од Оног Који прашта и Који је милостив.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'А ко говори лепше од онога који позива Аллаху, који ради добра дела и који говори: „Ја сам, заиста, муслиман!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'Добро и зло нису исто! На зло добрим узврати, па ће ти непријатељ твој одједном као присни пријатељ постати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'То могу постићи само стрпљиви, то могу постићи само врло срећни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'А кад Сотона покуша да те наведе на зле мисли, ти затражи уточиште код Аллаха. Он, уистину, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Међу Његовим знацима су ноћ и дан, и Сунце и Месец. Не клањајте се ни Сунцу ни Месецу, већ се једино клањајте Аллаху, Који их је створио, ако желите да само Њега обожавате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'А ако те они не послушају – па, они који су код твога Господара, славе и величају Га и ноћу и дању и то им не досађује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'А од Његових знакова је и то што ти видиш суву земљу, а кад на њу спустимо кишу, она се покрене и узбуја. Онај Ко њој даје живот оживеће сигурно и умрле. Он све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Збиља, они који Наше речи изврћу неће се сакрити од Нас. Па да ли је бољи онај који у Ватру буде бачен или онај који на Судњем дану дође сигуран? Радите шта хоћете, Он, заиста, добро види шта ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Заиста они који не верују у Кур''ан, након што им је дошао, биће кажњени! То је, заиста, моћна књига,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'лаж јој не може прићи са било које стране, она је Објава од Мудрог и Хваљеног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Теби се не говори ништа што већ није речено посланицима пре тебе. Твој Господар заиста прашта, а и болно кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'А да смо Кур''ан објавили на туђем језику, они би сигурно казали: „Требало је да су му речи разумљиве! Зар туђ језик, а онај коме се објављује Арап?“ Реци: „Он је онима који верују упута и лек. А они који не верују – они су глуви и слепи за њега! Они као да се издалека дозивају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'И Мојсију смо дали Књигу, па су се због ње подвојили. А да није речи твога Господара пре изречене, са овима би било већ свршено. И они у Кур''ан много сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Ко чини добро, чини у своју корист, а ко ради зло, ради на своју штету. А твој Господар није неправедан према Својим слугама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'Само Он зна кад ће да наступи Смак света. А ни плодови не излазе из својих цветних чашица, и ниједно женско не занесе и не роди, а да Он то не зна. А на Дан кад их Он упита: “Где су они које сте поред Мене обожавали?” Они ће одговорити: “Обавештавамо Те да нико од нас то не тврди.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'И изгубиће им се они којима су се пре молили и увериће се да никуд не могу да умакну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'Човеку не досади да тражи добро, а када га задеси зло, онда очајава и губи наду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'Кад га обаспемо Нашом милошћу, после несреће која га задеси, он говори: „Ово сам и заслужио, и ја не мислим да ће Судњи час да дође. А ако будем враћен своме Господару, код Њега ме чека само добро и Рај.“ А Ми ћемо оне који нису веровали, сигурно, о ономе што су радили да обавестимо и даћемо им да искусе тешку патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Када човеку дарујемо Своју милост, постаје незахвалан и узохоли се, а кад га дотакне невоља, онда се дуго моли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'Реци: „Шта мислите, ако је Кур''ан од Аллаха, а ви у њега нећете да верујете - ко је онда у већој заблуди од онога који је у далекој противречности од истине?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Ми ћемо да им покажемо Наше знакове у даљини - на обзорима, а и у њима самим, док им не буде сасвим јасно да је Кур''ан истина. А зар није довољно то што је твој Господар свему сведок?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'Они сумњају да ће да стану пред својим Господаром, а Он, заиста, све обухвата.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Ајн-син-каф.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'Тако Аллах, Силни и Мудри објављује теби, као и онима пре тебе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'Његово је све што је на небесима и на Земљи, и Он је Свевишњи, Величанствени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Готово да се небеса одозго распадну! А анђели величају и хвале свога Господара и моле опрост за оне који су на Земљи. Зар Аллах, заиста, не опрашта грехе, Милостиви?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Аллах мотри на оне који, поред Њега, узимају заштитнике, а ти ниси задужен за њихову упуту.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Ето, тако Ми теби објављујемо Кур''ан, на арапском језику, да би упозоравао Мекку и оне око ње и упозорио на Дан сакупљања у који нема никакве сумње. Једни ће у Рај, а други у Пакао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'А да Аллах хоће, учинио би их следбеницима једне вере, али, Он у Своју милост уводи кога Он хоће, а неверници немају ни заштитника, ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Зар они да друге, а не Њега, узимају за заштитнике?! Па Аллах је једини Заштитник, Он оживљава мртве и Он над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'А у чему год се ви разишли, пресуда за то је код Аллаха! То вам је, Аллах, мој Господар - у Њега се ја уздам и Њему се обраћам;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, 'Створитељ небеса и Земље без претходног примера! Учинио вам је од ваше врсте парове, и од стоке парове. Тако вас распростире. Ништа није као Он! Он све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'Код Њега су кључеви небеса и Земље, Он даје опскрбу у изобиљу коме хоће, а и ускраћује; Он, уистину, зна све.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'Он вам прописује у вери исто оно што је наредио Ноји и оно што објављујемо теби, и оно што смо наредили Авраму и Мојсију и Исусу: „Праву веру исповедајте и у томе се не раздвајате!“ Тешко је незнанобошцима оно у шта их позиваш. Аллах бира за Своју веру онога кога Он хоће и упућује у њу онога ко Му се искрено обрати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'А они су се, баш онда кад им је дошло знање, из међусобне злобе разишли. И да није Речи твога Господара пре изречене о одгађању казне до одређеног рока, њима би било већ пресуђено. А они којима се после њих оставља Књига у наследство, према њој су у великој сумњи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'Зато ти томе позивај и буди устрајан, онако како ти се наређује, и не следи њихове хирове, и реци: „Ја верујем у књиге које је Аллах објавио, и наређено ми је да будем праведан међу вама; Аллах је и наш и ваш Господар, нама наша, а вама ваша дела; нема препирања између нас и вас; Аллах ће све да нас сакупи, а код Њега је коначно одредиште."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'А они који се расправљају о Аллаху након што је Његов позив прихваћен - њихови докази су ништавни код њиховог Господара; на њима је гнев и њима припада жестока патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Аллах је Онај Који је Књигу са истином и правдом објавио! А шта ти знаш - можда је Судњи час близу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Пожурују га они који у њега не верују, а они који верују, због њега страхују и да је истина заиста знају. Заиста су они који расправљају о Судњем часу у великој заблуди!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Аллах је благ према слугама Својим; Он даје опскрбу коме хоће, и Он је Моћан и Силан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Ко буде желео награду Будућег света, његову награду ћемо да повећамо! А ко буде желео награду овог света, даћемо му је, али на Будућем свету нема никаквог удела!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Зар они да имају ортаке који им прописују да верују оно што Аллах није наредио? Да није Речи одлуке, њима би већ било пресуђено. А неверницима, заиста, припада болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'Видећеш невернике како стрепе због онога што су радили, а то ће сигурно да их стигне; а они који су веровали и радили добра дела биће у дивним рајским баштама, имаће све што пожеле код свога Господара; биће то велика благодат.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'То је оно чиме Аллах радује Своје слуге који верују и раде добра дела. Реци: „Не тражим ја за ово никакву награду од вас, осим родбинске пажње.“ А ко учини добро, Ми ћемо њему за то да повећамо добро. Заиста Аллах опрашта грехе и захвалан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Зар они да говоре: „Он измишља лажи о Аллаху!“ А ако хоће, Аллах ће да запечати твоје срце! Аллах поништава неистину и утврђује Истину Својим речима; Он добро зна шта се крије у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'Он прима покајање од Својих слугу и прашта лоше поступке и Он зна шта радите;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'И одазива се онима који верују и чине добра дела и из Своје доброте им и више пружа, а невернике чека жестока патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'А кад би Аллах Својим слугама давао преобилну опскрбу, они би се осилили на Земљи, али Он је даје са мером, онолико колико хоће! Заиста Он у потпуности зна и види Своје слуге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'Он спушта кишу кад они изгубе сваку наду и распростире Своју милост; Он је, уистину, Заштитник, Хваљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Међу Његовим знацима је стварање небеса и Земље и живих бића која је расејао по њима; Он је способан све да их сабере кад буде хтео.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Несрећа која вас задеси је због онога што су стекле ваше руке, а много тога Он и опрости.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'А ви на Земљи нећете моћи да Му умакнете, и ви осим Аллаха немате ни заштитника ни помагача!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'И међу Његовим знацима су лађе налик на брда које плове морем.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Ако жели, Он умири ветар и оне на његовој површини остају непокретне - заиста у томе има знакова за сваког стрпљивог, захвалног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Или их потопи, због греха које су зарадили – а много тога Он и опрости,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'да би они који поричу Наше речи и знакове знали да Нашој казни не могу да умакну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Оно што вам је дато, само је уживање у овосветском животу, а оно што је код Аллаха - боље је и трајније за оне који верују и на свога Господара се ослањају;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'И за оне који се клоне великих греха и разврата и који, кад се расрде, опраштају;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'И за оне који се своме Господару одазивају, и обављају молитву, и о пословима својим се договарају, и удељују део од онога чиме смо их опскрбили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'и за оне који се одупру онима који их угњетавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Неправда се може узвратити истом мером, а онога који опрости и измири се Аллах ће да награди; Он, уистину, не воли насилнике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'А онај ко узврати након што му је учињено насиље, па такви не могу да буду кажњени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Биће кажњени они који тлаче људе и без икаквог основа нарушавају ред на Земљи; њих чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'А ко се стрпи и опрости, заиста то спада у истинске поступке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'А коме да Аллах да је у заблуди, томе после Њега неће да буде помагача! И ти ћеш да видиш како ће незнанобошци, кад угледају патњу, повикнути: „Постоји ли икакав начин да будемо опет враћени?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'И видећеш како се понижени и клонули излажу Ватри, а они је кријући гледају. Они који су веровали, казаће: „Заиста су настрадали они који на Судњем дану и себе и породице своје упропасте!“ А зар неверници неће да буду у непрестаној патњи?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Њима неће да буде заштитника да им помогну, осим Аллаха; а коме да Аллах да је у заблуди, такав пут спаса неће ни да има!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Одазовите се своме Господару пре него што дође Дан који Аллах неће да заустави. Тог Дана уточишта нећете да имате и нећете моћи да поричете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'А ако се окрену - па, Ми тебе нисмо ни послали да над њима надзиреш, ти си дужан само да доставиш посланицу. А када човеку дамо да осети Нашу милост, он јој се обрадује, а кад их задеси каква несрећа због онога што су урадиле њихове руке, онда човек не признаје благодати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'Аллахова је власт на небесима и на Земљи. Он ствара шта хоће! Дарује женску децу коме хоће, а коме хоће - мушку,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'или им даје и мушку и женску, а кога хоће, учини да је без порода; Он је, уистину, Онај Који све зна и свемоћан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Ниједном човеку није дато да му се Аллах обраћа, осим објавом, или иза застора, или да пошаље изасланика, па са Његовом дозволом објави оно што Он хоће. Он је, заиста, Узвишен и Мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Тако Ми и теби објављујемо Кур''ан одредбом Нашом. Ти ниси знао шта је Књига, нити си познавао верске прописе, али смо је Ми учинили светлом помоћу којег упућујемо оне Наше слуге које желимо. А Ти, заиста, указујеш на Прави пут,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'на Аллахов пут, Коме припада све што је на небесима и све што је на Земљи. А зар се Аллаху неће све вратити?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'Тако Ми јасне Књиге,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Ми је објављујемо као Кур''ан на арапском језику, да бисте разумели,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'а он је у Главној књизи, код Нас, цењен и савршен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Зар да одустанемо да вам објављујемо Кур''ан зато што сте људи који прелазе сваку меру зла?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'А колико смо Ми претходим народима послали веровесника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'и ниједан им веровесник није дошао, а да му се нису изругивали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Зато смо уништавали оне који су од ових били моћнији, а наведен вам је пример претходних народа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Па ако их упиташ ко је створио небеса и Земљу, они ће сигурно да кажу: „Створио их је Силни и Свезнајући!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, 'Онај Који вам је Земљу учинио колевком и по њој вам створио пролазе, да бисте се усмеравали;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'Онај Који са неба спушта воду са мером, помоћу које враћамо у живот мртве пределе – тако ћете и ви да будете проживљени из гробова.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'Онај Који ствара створења сваке врсте и даје вам лађе и стоку да на њима путујете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'да се сместите на њиховим палубама и леђима и да се, потом, када се сместите на њих, сетите благодати свога Господара и да кажете: „Слављен и Узвишен нека је Онај Који нам је ово потчинио, ми то сами не би могли да постигнемо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'и ми ћемо сигурно своме Господару да се вратимо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'И они сматрају да су неке Његове слуге део Њега. Човек је, заиста, очигледни незахвалник.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Зар да између оних које Он ствара узима Себи кћери, а вама дарује синове?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'А кад неко од њих буде обавештен о ономе што Свемилосном приписује, лице му се ојађеном помрачи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'Зар да оно које у украсима расте и које у расправи нејасно збори приписују Аллаху?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Они анђеле који су слуге Свемилосног сматрају женским. Да нису присуствовали њиховом стварању?! Њихова тврдња биће записана и они ће да одговарају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'И они говоре: „Да је хтео Свемилосни, не бисмо их обожавали!“ Они о томе ништа не знају, они само лажу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Или смо им дали Књигу пре тога па се ње придржавају?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Они чак говоре: „Ми смо затекли наше претке како исповедају веру и, пратећи њихове трагове, ми смо на Правом путу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Исто тако, пре тебе, Ми нисмо послали посланика ни у један град, а да они који су раскошно живели нису говорили: „Затекли смо наше претке како тако верују и ми их у стопу пратимо.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, '„Зар и онда“, говорио би он, „кад вам ја доносим бољу веру од оне коју сте упамтили од ваших предака?“ А они би одговарали: „Не верујемо ми у оно што је по вама послато!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'И Ми смо их кажњавали, па види какав је био крај оних који су посланике сматрали лажним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'А кад Аврам рече своме оцу и своме народу: „Немам ја ништа са онима које ви обожавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'осим са Оним Који ме је створио јер ће Он, заиста, на Прави пут да ме упути.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Он то учини трајном речју за своје потомство, да би се вратили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'А Ја сам чак овима допустио, а и њиховим прецима да уживају све док им није дошла Истина и јасни Посланик.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'А кад им је дошла Истина, рекоше: „Ово је враџбина, и ми у њу никако не верујемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'И рекоше: „Зашто овај Кур''ан није објављен неком великану из ова два града?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Зар они да распоређују милост твога Господара? Ми распоређујемо међу њима оно што им је потребно за живот на овом свету и Ми уздижемо једне над другима по степенима, да би једни друге узимали да им служе. А милост твога Господара боља је од онога што они гомилају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'А да неће сви људи да постану једна заједница (у неверству), Ми бисмо кровове кућа, оних који не верују у Свемилосног, од сребра учинили, а и степеништа уз која се пењу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'и врата њихових кућа и диване на којима се одмарају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'дали бисмо им и украсе од злата, јер све је то само уживање у овосветском животу, а Будући свет, код твога Господара, биће за богобојазне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Ономе ко се буде слепим правио пред Кур''аном Свемилосног, додаћемо му ђавола, па ће му он бити друг;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'и ђаволи ће их од Правог пута одвраћати, а они ће мислити да су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'И када дође пред Нас, рећи ће: „Камо среће да је између мене и тебе била толика раздаљина колика је између истока и запада! Како си ти био зао друг!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Тог дана неће вам користити то што ћете заједно бити у патњи, кад сте незнанобошци били.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Зар ти да дозовеш глуве и упутиш слепе и оне који су у очигледној заблуди?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'Ако бисмо ти узели душу, њих бисмо, сигурно, казнили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'или, кад бисмо хтели да ти покажемо оно што смо им обећали, па Ми над њима, заиста, имамо потпуну моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Зато се држи онога што ти се објављује, а ти си, уистину, на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Кур''ан је, заиста, част и теби и твоме народу; па бићете питани!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'А питај оне које смо послали пре тебе од Наших посланика - да ли смо Ми наређивали да се, осим Свемилосног, обожавају божанства?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Још давно смо Ми послали Мојсија са Нашим знамењима фараону и његовим главешинама, и он је рекао: „Ја сам, заиста, посланик Господара светова!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'И пошто им је донео Наше доказе, они су, одједном, почели да их исмејавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'А нисмо им показивали ниједан знак а да није био већи од претходног! И подвргли смо их патњи, како би се повратили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'И говорили су: „О ти, чаробњаче! Замоли за нас свога Господара, јер ти је обећао, а ми ћемо сигурно да пођемо Правим путем!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'А чим бисмо их ослободили невоље, зачас би прекршили обавезу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'И фараон обзнани своме народу: „О мој народе“, рече он, „зар мени не припада власт у Мисиру и ове реке које теку испред мене - зар не видите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'Зар ја нисам бољи од овог бедника који једва разговетно говори?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'Зашто му нису стављене наруквице од злата, или зашто заједно са њим нису дошли анђели?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'И он заведе свој народ па му се покорише; они су, заиста, били народ грешни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'А кад изазваше Наш гнев, Ми их казнисмо и све их потописмо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'и учинисмо их примером и поуком каснијим народима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'А кад је твоме народу као пример наведен Маријин син, одједном су они, због тога, почели да се расправљају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'и рекли: „Да ли су наша божанства боља или он?“ А навели су ти га као пример само зато да би се препирали. Они су свађалачки народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'Он је био само слуга којег смо Ми обасули благодатима и учинили га примером Израиљевим синовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'А да хоћемо, Ми бисмо учинили да вас на Земљи наследе анђели;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'и заиста је он предзнак Смака света, зато никако не сумњајте у њега и следите мене! Ово је Прави пут,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'и нека вас ђаво никако не одврати; он вам је, заиста, отворени непријатељ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'А кад је Исус донео очигледне доказе, казао је: „Доносим вам мудрост и долазим да вам објасним оно у чему се разилазите. Зато се бојте Аллаха и мени се покоравајте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Аллах је и мој и ваш Господар, па Њега само обожавајте! Ово је Прави пут!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Али су се групе из њихових редова подвојиле. Па тешко онима који о њему криво говоре од казне на болноме Дану!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Чекају ли они друго осим да им Смак света изненада дође, и да они и не осете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Тог дана пријатељи ће једни другима постати непријатељи, осим оних који су били богобојазни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, '„О слуге Моје, за вас данас неће да буде страха, нити ћете да тугујете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, 'А онима који су у Наше речи и доказе веровали и који су били муслимани - биће речено:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, '„Уђите у Рај, ви и ваше супруге, радосни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Они ће да буду служени из посуда и чаша од злата. У њему ће да буде све што зажеле душе и чиме се наслађују очи, и у њему ћете вечно да боравите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'Ето, то је Рај који сте у наследство добили за оно што сте радили;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'у њему ћете да имате разноврсног воћа којег ћете јести.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Заиста ће неверници у Паклу вечно да остану,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'она неће да им буде ублажена и никакве наде у спас неће да имају. Они ће у њој да буду очајни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Нисмо им Ми учинили неправду, него су они сами себи неправду нанели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'Они ће да дозивају: „О Малик! Нека нас твој Господар докрајчи!“ А он ће да каже: „Заиста ви ту остајете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Ми смо вам слали Истину, али већина вас презире истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Ако они спремају замке, и Ми ћемо замке њима да поставимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Зар они мисле да Ми не чујемо шта они насамо разговарају и како се међу собом договарају? Чујемо Ми, а Наши анђели, који су уз њих, записују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'Реци: „Да Свемилосни има дете, па ја бих га први обожавао!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Нека је Слављен и Узвишен Господар небеса и Земље, и Господар Престола, од онога како Га они описују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Па, ти их остави нека се упуштају у заблуду и забављају док не доживе Дан којим им се прети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'Он је Бог на небесима и Бог на Земљи. Он је Мудри и Свезнајући!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'И нека је узвишен Онај Чија је власт на небесима и на Земљи, и између њих, Он једини зна када ће Смак света да буде, и Њему ћете се сви вратити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Они које они, поред Њега, моле - неће моћи да се заузимају за друге; моћи ће само они који признају истину, они који знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'А ако их упиташ ко их је створио, сигурно ће да кажу: „Аллах!“ Па куда се онда одмећу?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'И рече Посланик: „Мој Господару, ово су, заиста, људи који не верују!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'Па ти се окрени од њих и реци: „Мир!“ А сазнаће они сигурно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'Тако ми јасне Књиге,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Ми смо је објавили у благословљеној ноћи и Ми, заиста, упозоравамо;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'у њој се одређује свака савршена одредба!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'по Нашој заповеди! Ми смо, заиста, слали посланике', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'као милост твога Господара - а Он, уистину, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'Господар небеса и Земље, и онога што је између њих - ако чврсто верујете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'другог истинског бога осим Њега нема; Он даје живот и смрт - ваш Господар и Господар ваших давних предака!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'али, они сумњају и забављају се.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Па ти зато сачекај Дан кад ће на небу да се појави видљиви дим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'Који ће људе да прекрије: „Ово је болна патња!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, 'Господару наш, отклони патњу од нас, ми ћемо, сигурно, да верујемо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'А како да сада приме поуку, а већ им је био дошао истинити Посланик?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'од кога се они потом окренуше и рекоше: „Подучени лудак!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'А кад бисмо мало отклонили патњу, ви бисте се сигурно вратили у неверовање;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'али на Дан када их најжешће зграбимо, заиста ћемо да их казнимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'А Ми смо и пре њих фараонов народ ставили у искушење, и дошао им је племенити посланик Мојсије:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, '„Препустите ми Аллахове слуге! Ја сам вам, заиста, поуздани посланик,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'и не уздижите се изнад Аллаха, ја вам доносим очигледни доказ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'и ја се обраћам и своме и вашем Господару, да ме не каменујете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'а ако ми не верујете, онда ме оставите на миру!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'И он позва у помоћ свога Господара: „Ово је, заиста, невернички народ!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, '„Изведи ноћу Моје слуге, а сигурно ће вас гонити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'и остави море нек мирује, они су војска која ће заиста да буде потопљена.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'И колико оставише за собом башта и извора,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'и засејаних њива и дивних боравишта,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'и благодати у којима су уживали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Тако то би, и Ми смо то другима оставили да наследе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'ни небо их ни Земља нису оплакивали, и нису били поштеђени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'А Израиљеве смо синове спасили понижавајуће патње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'од фараона - он је био збиља надмен, један од оних који су превршили сваку меру у злу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'и знајући какви су, одабрали смо их међу савременицима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'и нека смо им знамења очигледних благодати и искушења дали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'А неверници, заиста, говоре:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, '„Постоји само наша прва смрт, ми нећемо да будемо оживљени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'наше претке нам доведите, ако је истина то што говорите!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Да ли су бољи они или народ Туббе''ов и они пре њега? Њих смо уништили, јер су били преступници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Ми нисмо створили небеса и Земљу и оно што је између њих из забаве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Ми смо их створили са Истином, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'Заиста је Судњи дан одређени рок за све њих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'Дан, када ближњи неће нимало да буду од користи ближњем, нити ће бити помогнути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'осим оних којима се Аллах смилује. Он је, уистину, Силни и Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'А заиста је дрво Зеккум', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'храна грешника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'као уљани талог у стомаку ће да ври,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'као што кључала вода ври.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, '„Зграбите га и усред Огња одвуците,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'а затим му, за казну, на главу изливајте кључалу воду!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, '"Кушај, ево ти си, заиста, моћан и поштован!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Ово је, заиста, оно у што сте сумњали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'А богобојазни ће, заиста, да буду на сигурном месту,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'у сред вртова и извора,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'обучени у свилу и брокате и окренути једни према другима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Ето, тако ће да буде и Ми ћемо да их женимо рајским лепотицама, крупних очију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'Тамо ће моћи, сигурни, да траже коју хоће врсту воћа;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'ту, после оне прве смрти, смрт више неће да окусе и Он ће патње у Огњу да их сачува,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'благодат ће то да буде од твога Господара; то ће, заиста, да буде велики успех!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'А Кур''ан смо учинили лаким, на твоме језику, да би се они присетили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'Ти зато чекај, а и они чекају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Књигу објављује Аллах, Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'На небесима и на Земљи, заиста, постоје знаци за вернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'И у стварању вас и живих бића која је разасуо, знаци су за људе који су чврсто уверени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'и у смени ноћи и дана, и киши коју Аллах спушта са неба да помоћу ње оживи земљу, након њеног мртвила, и усмеравању ветрова - знаци су за људе који разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'То су Аллахове речи и докази које ти као истину наводимо, па у које ће, ако не у Аллахове речи и Његове доказе да верују?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'Тешко сваком лажљивцу, великом грешнику,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'који чује Аллахове речи кад му се читају, затим устраје у неверовању, охолећи се као да их није ни чуо - њему наговести болну патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'А кад сазна за неке Наше речи и доказе, он им се руга. Такве чека понижавајућа патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'Пред њима је Пакао, и ни од какве користи неће да им буде оно што су стекли, ни они које су, поред Аллаха, узели за заштитнике, и њих чека огромна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'Ово је Упута, а оне који не верују у доказе и речи свога Господара чека болна, највећа казна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Аллах вам је потчинио море да би лађе, Његовом одредбом, по њему пловиле, да бисте могли да тражите Његове благодати и да бисте били захвални.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'И потчинио вам је оно што је на небесима и на Земљи, све је од Њега! То су, заиста, знаци за људе који размишљају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'Реци верницима да опросте онима који не очекују Аллахове дане, када ће Он људима дати оно што су заслужили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Онај који ради добро - ради га себи, а онај који ради зло - против себе ради; а на крају ћете се сви вратити своме Господару.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Израиљевим синовима смо дали Књигу и власт, и веровесништво, и опскрбили смо их лепом храном, и одликовали их над осталим народима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'И дали смо им јасне доказе о вери, а они су се подвојили баш онда кад им је дошло знање, и то због непријатељства и међусобне зависти. Твој Господар ће, сигурно, да им пресуди на Судњем дану у вези са оним у чему су се разилазили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'А теби смо после одредили да у вери идеш одређеним правцем, зато га следи и не поводи се за хировима оних који не знају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'они, заиста, од Аллаха не могу нимало да те заштите! Насилници су једни другима заштитници, а Аллах је заштитник богобојазних.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'Овај Кур''ан путоказ је људима, и упута и милост онима који чврсто верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Мисле ли они који раде зла дела да ћемо са њима да поступимо једнако као са онима који верују и раде добра дела, да ће у овом животу и након смрти да буду исти?! Како лоше расуђују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'А Аллах је небеса и Земљу створио са истином и зато да би свака особа била награђена или кажњена према оном што је урадила, и неће им бити учињено насиље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Шта мислиш о ономе који је узео своју страст за свога бога, онога кога је Аллах, знајући га, оставио у заблуди, и његов слух, и његово срце запечатио, а пред његове очи ставио копрену? Ко ће, ако не Аллах, да га упути на Прави пут? Зашто се не уразумите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'И они кажу: „Постоји само наш земаљски живот, живимо и умиремо, једино нас време уништи.“ А они о томе баш ништа не знају, они само нагађају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'А кад им се Наше јасне речи казују, другог доказа немају осим што кажу: „Наше претке у живот повратите, ако је истина то што говорите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'Реци: „Аллах вам даје живот, затим ће вас усмртити, а после ће да вас сабере на Судњем дану, у то нема никакве сумње, али већина људи не зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'Аллахова је власт на небесима и на Земљи! А на дан кад наступи Час оживљења, тог дана биће изгубљени они који су следили лажи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'И видећеш све народе како клече; сваки народ биће позван према својој Књизи: „Данас ћете да будете награђени или кажњени према томе како сте поступали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Ова Наша Књига о вама ће само истину да говори, јер смо наредили да се запише све што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'Оне који су веровали и радили добра дела Господар њихов ће да уведе у Своју милост. То ће да буде очигледни успех!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'А онима који нису веровали: „Зар вам Моје речи нису казиване, али сте се охолили и народ одметнички били?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Кад се говорило: „Аллахово је обећање, заиста, истина! И у Час оживљења нема нимало сумње“, ви сте говорили: „Ми не знамо шта је Час оживљења, ми само замишљамо, ми нисмо уверени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'И указаће им се њихова лоша дела, и са свих страна сколиће их оно чему су се ругали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'и биће речено: „Данас ћемо ми вас да заборавимо као што сте и ви заборавили сусрет на овај ваш Дан; Ватра ће да вам буде пребивалиште и нико неће моћи да вам помогне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'зато што сте се ругали Аллаховим речима и што вас је обмануо живот на Земљи.“ Зато данас из Ватре неће да буду изведени, нити ће да им буде удовољено да траже благонаклоност за повратак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'Па, сва захвала припада Аллаху, Господару небеса и Господару Земље, Господару свих светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'Њему припада величанственост на небесима и на Земљи, Он је Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Ха-мим.[1]', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Књигу објављује Аллах, Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Ми смо небеса и Земљу и оно што је између њих мудро створили и до рока одређеног, али неверници окрећу главе од оног чиме им се прети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'Реци: „Шта мислите о онима које молите мимо Аллаха? Покажите ми који део Земље су створили, или они можда имају каквог удела у небесима?! Донесите ми Књигу објављену пре ове, или само какав остатак знања, ако говорите истину.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Ко је у већој заблуди од оних који, уместо Аллаха, моле оне који неће да им се одазову до Судњег дана и који су равнодушни према њиховим молбама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Када људи буду сабрани, та божанства ће да им буду непријатељи и њихово обожавање ће да порекну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'А кад се овима казују Наше јасне речи, онда они који не верују говоре о истини чим им дође: „Ово је права чаролија!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Зар они да говоре: “Он га измишља!” Реци: “Ако га измишљам, па ви ме од Аллаха нећете моћи заштити. Он добро зна шта о Кур’ану говорите. Он је довољан сведок и мени и вама. Он прашта и самилостан је.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'Реци: „Ја нисам први посланик и не знам шта ће да буде са мном или са вама; ја следим само оно што ми се објављује, и ја сам само јасни опомињач.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'Реци: “Кажите ви мени шта ће с вама бити ако је Кур’ан од Аллаха, а ви у њега нећете да верујете, и ако је један од синова Израиљевих посведочио да је и он од Аллаха, па он поверовао, а ви се узохолили.” Аллах, заиста, неће указати на Прави пут народу неправедном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'И говоре неверници о верницима: „Да је у томе добро, они нас не би претекли у томе.“ А како помоћу њега нису нашли Прави пут, сигурно ће да кажу: „Ово је још давна измишљотина.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Мојсијева Књига била је предводник и милост пре њега. А ово је Књига на арапском језику која њу потврђује, да би упозорила оне који чине неправду, и да би обрадовала оне који чине добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Они који говоре: „Наш Господар је Аллах!“ И устрају на Правом путу, за њих нема страха и ни за чим нек не тугују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Они ће да буду становници Раја, у њему ће вечно да бораве, и то ће да им буде награда за оно што су радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'А човека смо задужили да родитељима својим чини добро. Мајка га његова с муком носи и у мукама га рађа, носи га и доји тридесет месеци. Па кад своју зрелост достигне и кад достигне четрдесет година, он каже: „Господару мој, упути ме да Ти захвалим на Твојој благодати, коју си даровао мени и мојим родитељима, и да радим добро којим си Ти задовољан, и моје потомство Ти учини добрим! Ја се Теби, заиста, кајем и Теби сам предан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'Од таквих ћемо Ми добра дела која су радили примити, а преко ружних поступака њихових прећи; они ће да буду међу становницима Раја, истинито обећање које им је дато Ми ћемо да испунимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'А онај који родитељима својим каже: “Их, што ми претите да ћу бити оживљен кад су пре мене толики народи били и нестали!” – А они, молећи Аллаха у помоћ, говоре: “Тешко теби, веруј, Аллахова ће се претња, заиста, обистинити!” Он одговара: “То су измишљотине народа древних!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'На таквима се треба испунити реч речена о народима: духовима и људима који су пре њих били и нестали, јер они су, заиста, настрадали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'За све ће да буду посебни степени, према томе како су радили; да их награди, или казни за њихова дела, неће да им буде учињена неправда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'А на Дан кад они који нису веровали пред ватром буду заустављени: “Ви сте у свом животу на Земљи све своје насладе искористили и у њима уживали, а данас срамном патњом бићете кажњени зато што сте се на Земљи, без икаквог основа, охоло понашали и што сте непокорни били.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'И спомени Адовог брата, кад је народ свој у Ахкафу опомињао – а било је и пре њега и после њега посланика: “Аллаха само обожавајте, ја, заиста, страхујем да ћете бити у мукама на Великом дану!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'Они су одговарали: „Зар си нам дошао да нас одвратиш од наших божанстава? Нека се, ето, остваре претње твоје, ако истину говориш!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, '“Само Аллах зна кад ће то бити”, он би говорио, “ја вам казујем оно што ми се објављује, а ви сте, видим, народ у незнању огрезао.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'И кад угледаше на обзорју облак, који се према долинама њиховим кретао, повикаше: “Овај нам облак кишу доноси!” “Не, то је оно што сте пожуривали: ветар који вам болну патњу носи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'који, одредбом свога Господара, све руши.“ И ујутру су се видела само њихова насеља; тако Ми кажњавамо преступнички народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'Њима смо дали могућности које вама нисмо дали: и дали смо им слух и вид и разум, али им ни њихов слух ни њихов вид ни њихов разум нису били ни од какве користи, јер су порицали Аллахове доказе, и са свих страна окружило их је оно чему су се исмејавали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Неке градове око вас још давно смо уништили, а објаснили смо им били на разне начине доказе, не би ли се покајали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'А зашто им нису помогли они које су, поред Аллаха, прихватили да им буду посредници и божанства? Али, њих није било. То су биле само клевете њихове и лажи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'И када ти посласмо неколико духова да слушају Кур''ан, па када дођоше да га чују, рекоше: „Ћутите и слушајте!“ А кад се заврши, вратише се своме народу да упозоравају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, '„О народе наш“, говорили су, „ми смо слушали Књигу која се објављује после Мојсија, која потврђује да су истините и оне пре ње, и која упућује ка Истини и на Прави пут.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'О народе наш, одазовите се Аллаховом гласнику и верујте у Аллаха, Он ће да вам опрости неке ваше грехе и да вас заштити од болне патње!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'А они који се не одазову Аллаховом гласнику, такви на Земљи неће да Му умакну и мимо Њега неће да нађу заштитника. Они су у великој заблуди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Зар не знају да је Аллах - Који је створио небеса и Земљу и Који се није, стварајући их, уморио – способан да оживи мртве?! Јесте, уистину Он све може.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'А на Дан кад они, који нису веровали, буду изложени Ватри: „Зар ово није истина?“ Одговориће: „Јесте, Господара нам нашег!“ „Е па искусите патњу“, рећи ће Он, „због тога што сте стално порицали.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'Ти издржи као што су издржали одлучни посланици и не тражи да им казна дође што пре! А онога Дана када доживе оно чиме им се прети, учиниће им се да су остали само један часак дана. Ово је обзнана! А зар ће ко други да буде уништен до народ одметнички?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Аллах ће поништити дела оних који не верују и од пута Његовог одвраћају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'А онима који верују и раде добра дела и верују у оно што се објављује Мухаммеду, а то је истина од њиховог Господара, Он ће им њихова лоша дела опростити и њихово стање поправити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'То је зато што неверници следе неистину, а верници следе истину од свога Господара. Ето, тако Аллах наводи људима њихове примере.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Кад се у борби с неверницима сретнете по вратовима их ударајте све док их не ослабите, а онда их вежите када их заробите, и после, или их великодушно ослободите или откупнину захтевајте, све док борба не престане. Тако учините! Да Аллах хоће, Он би им се осветио, али Он вас жели искушати једне помоћу других. Он неће поништити дела оних који на Аллаховом путу погину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'Он ће, сигурно, да их упути и њихове прилике да побољша,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'и да их уведе у Рај, о коме их је већ упознао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'О верници, ако Аллаха помогнете, и Он ће вас да помогне и ваше кораке да учврсти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'А онима који не верују – пропаст њима! Он неће дела њихова прихватити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'То је зато што они мрзе оно што Аллах објављује, и Он ће да поништи њихова дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Зашто они не иду по Земљи да виде какав је био крај оних пре њих? Њих је Аллах уништио, а то очекује и остале невернике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'То је зато што је Аллах заштитник оних који верују и што неверници немају заштитника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Аллах ће оне који верују и раде добра дела да уведе у рајске баште, кроз које теку реке, а они који не верују - који се наслађују и једу као што једе стока - њихово пребивалиште ће да буде Ватра!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'А колико смо уништили градова, много моћнијих од твога града из којег си протеран, и није било никог да им помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Зар је онај који има јасну представу о своме Господару као они којима су улепшана њихова ружна дела и који се поводе за својим страстима?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Изглед Раја који је обећан богобојазнима: у њему су реке од неустајале воде и реке од млека непромењеног укуса, и реке од вина, пријатног онима који пију, и реке од процеђеног меда, и у њему за њих има разноврсног воћа, а уз то и опрост од њиховог Господара. Зар су такви исти као они који ће у Ватри да вечно бораве, који ће узаврелом водом да буду појени, која ће црева да им кида?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Има оних који долазе да те слушају, али чим се од тебе удаље, питају оне којима је дато знање: „Шта оно он малопре рече?“ То су они чија је срца Аллах запечатио и који се поводе за својим страстима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'А онима који су на Правом путу Он ће повећати упуту и подариће им богобојазност.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Зар они чекају да им само Час смака света изненада дође, а већ су дошли његови предзнаци? А шта ће им користити опомена кад им он дође?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Знај да нема бога осим Аллаха! Тражи опрост за своје грехе и за вернике и вернице! Аллах зна куда се крећете и где боравите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'А они који верују говоре: “Зашто се не објави једно поглавље?” А кад би објављено једно поглавље и у њему би споменута борба, ти си могао видети оне чија су срца болесна како те гледају погледом пред смрт онесвешћеног! Тешко њима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'Боље би им било да су послушни и да добро говоре! А кад је борба већ прописана, боље би им било да су према Аллаху искрени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Зар и ви не бисте, кад бисте се власти дочепали, неред на Земљи чинили и родбинске везе кидали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'То су они које је Аллах проклео и учинио их глувим и слепим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Како они не размисле о Кур''ану, или су им на срцима катанци!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Оне који су од вере своје отпали, пошто им је био јасан Прави пут, ђаво је на грех наводио и лажну им наду уливао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'То је зато што су говорили онима који не воле оно што Аллах објављује: “Ми ћемо вам се у неким стварима покоравати.” А Аллах добро зна њихове тајне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'А како ће тек да буде кад им анђели буду узимали душе ударајући их по њиховим образима и леђима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Тако ће да буде зато што су следили оно што изазива Аллахов гнев, а презирали су оно чиме је Он задовољан; па ће поништити њихова дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Зар они болесних срца мисле да Аллах њихове злобе неће да изнесе на видело?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'А да хоћемо, Ми бисмо ти их, уистину, показали и ти би их, сигурно, препознао по њиховим обележјима. Али, ти ћеш да их препознаш и по начину њиховог говора, а Аллах зна ваше поступке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'Ми ћемо да вас искушавамо све док не укажемо на борце и постојане међу вама, а и вести о вама ћемо проверавати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Заиста, они који не верују и одвраћају од Аллаховог пута, и који се супротстављају Посланику, након што им је постала јасна Упута, неће нимало да науде Аллаху, и Он ће да поништи њихова дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'О ви који верујете, покоравајте се Аллаху и покоравајте се Посланику, и не поништавајте своја дела!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Онима који не верују и одвраћају од Аллаховог пута, па после умиру као неверници, Аллах, заиста, неће да опрости.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'И не будите кукавице и не нудите примирје јер сте јачи, а Аллах је са вама и Он неће да вас лиши награде за ваша дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'Овосветски живот је људима само игра и забава! А ако будете веровали и били богобојазни, Он ће вас наградити и неће од вас тражити ваш иметак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Ако би их од вас тражио и упоран у томе био, ви бисте постали шкрти и тиме би се показала ваша малодушност.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'Ви се позивате да трошите на Аллаховом путу, али неки су од вас шкрти, а ко шкртари, шкртари на своју штету, јер Аллах је богат, а ви сте сиромашни. А ако се одметнете, Он ће да вас замени другим народом, који онда, неће да буде као што сте ви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'Ми смо ти, заиста, дали да победиш јасном победом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'да би ти Аллах раније и касније грешке опростио, да би Своју благодат теби потпуном учинио, да би те на Прави пут упутио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'и да би те Аллах победоносном помоћи помогао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'Он улива смирај у срца верника да би још више повећали своје веровање, а војске небеса и Земље су Аллахове; Аллах све зна и мудар је,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'да би вернике и вернице увео у рајске баште, кроз које теку реке, у којима ће вечно да бораве, и да би прекрио њихова лоша дела - а то је код Аллаха велики успех,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'и да би казнио лицемере и лицемерке и незнанобошце и незнанобошкиње, који о Аллаху зло мисле. У злу се они налазе! Аллах се на њих разљутио и проклео их и припремио им Пакао, а грозно је то боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'Аллахове су војске небеса и Земље; Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'Ми смо те послали као сведока, и доносиоца радосних вести, и опомињача,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'да верујете у Аллаха и у Његовог Посланика, и да веру Његову помогнете, и да Га величате и да Га јутром и вечери славите и хвалите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Они који су ти се заклели на верност - заклели су се, заиста, на верност самом Аллаху - Аллахова рука је изнад њихових руку! Онај ко прекрши заклетву крши је на своју штету, а ко испуни оно на шта се обавезао Аллаху, Он ће да му подари велику награду!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Говориће ти бедуини који су изостали: „Задржали су нас имања и наше породице, па замоли за нас опрост?“ Они говоре својим језицима оно што није у њиховим срцима. Реци: “Па ко може променити Аллахову одлуку, ако вам Он хоће наудити, или ако вам хоће какво добро учинити?” Аллах у потпуности зна оно шта радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Ви сте мислили да се Посланик и верници никад неће вратити породицама својим; ваша су срца била задовољна због тога и ви сте на најгоре помишљали, ви сте народ у души покварен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'А ко год не верује у Аллаха и Његовог Посланика - па, Ми смо за невернике припремили разбуктали Огањ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'Аллахова власт је на небесима и на Земљи, Он прашта коме хоће, а кажњава кога хоће – Аллах много опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'Они који су изостали сигурно ће рећи кад пођете да плен узмете: “Пустите и нас да вас пратимо!” – да би изменили Аллахове речи. Реци: “Ви нас нећете пратити, то је још пре Аллах казао!” – А они ће рећи: “Није тако, него, ви нама завидите.” А није ни то, већ они мало шта разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Реци бедуинима који су изостали: “Бићете позвани да се борите против народа веома храброг и моћног, све док се не покори. Па ако послушате, Аллах ће вам лепу награду дати. А ако избегнете, као што сте и досад избегавали, казниће вас болном патњом.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'Није грех изостати слепом, хромом ни болесном! Ко год се покорава Аллаху и Његовом Посланику Он ће да га уведе у рајске баште, кроз које теку реке, а онога ко се одметне, болном патњом ће да казни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'Аллах је задовољан оним верницима који су ти се под дрветом на верност заклели. Он је знао шта је у њиховим срцима, па је спустио смирај на њих, и наградиће их скором победом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'и богатим пленом који ће узети – јер Аллах је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Аллах вам обећава обилни плен који ћете узети, а са овим је пожурио и руке људи од вас је задржао - да би то био поучан пример за вернике и да би вам на Прави пут указао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'и други, који нисте били у стању узети – Аллах вам га је дао, јер Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'А да су неверници са вама започели борбу, сигурно би се дали у бег и после не би нашли ни заштитника ни помагача.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'То је према Аллаховом закону који одувек важи, а ти нећеш наћи да се Аллахов закон мења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'Он је задржао њихове руке од вас и ваше од њих усред Мекке, и то након што вам је пружио могућност да их победите - а Аллах добро види оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'Они не верују и бране вам да приступите Часном храму, и да жртвенице које водите са собом до места својих стигну. И да није било бојазни да ћете побити вернике, мушкарце и жене, које не познајете, па тако, и не знајући, због њих срамоту доживите – Ми бисмо вам их препустили. А нисмо их препустили зато да би Аллах у Своју милост увео онога кога хоће. А да су они били одвојени, заиста бисмо болном патњом казнили оне међу њима који нису веровали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'Кад су неверници пунили своја срца жаром, жаром паганским, Аллах је спустио смиреност Своју на Посланика Свог и на вернике и обавезао их је да испуњавају оно због чега ће постати прави верници – а они и јесу најпречи и најдостојнији за то. А Аллах све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Аллах ће да обистини сан Свога Посланика да ћете заиста да уђете у Часни храм сигурни - кад Аллах буде хтео - неки обријаних глава, а неки подрезаних коса, без страха. Он је оно што ви нисте знали знао и зато вам је, пре тога, дао недавно победу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'Он је послао Свога Посланика са упутом и истинитом вером да би је уздигао изнад свих вера. А Аллах је довољан Сведок!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Мухаммед је Аллахов Посланик, а његови следбеници су строги према неверницима, а самилосни међу собом; видиш их како се клањају и лицем на тле падају желећи Аллахову награду и задовољство – на лицима су им знаци, трагови од падања лицем на тло. Тако су описани у Тори. А у Јеванђељу: они су као биљка кад свој изданак избаци па га онда учврсти, и он ојача, и усправи се на својој стабљици изазивајући дивљење сејача - да би Он са верницима ојадио невернике. Онима који верују и раде добра дела Аллах обећава опрост и велику награду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'О верници, не одлучујте се ни за шта док за то не упитате Аллаха и Његовог Посланика, и бојте се Аллаха! Аллах, заиста, све чује и све зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'О ви који верујете, не дижите своје гласове изнад Веровесниковог гласа и не разговарајте са њим гласно, као што гласно један са другим разговарате, да не би била поништена ваша дела, а да ви то и не приметите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Оне који утишају гласове своје пред Аллаховим Послаником – а то су они чија је срца Аллах прекалио у честитости – чека опрост и награда велика.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Већина оних који те гласно дозивају испред соба нису довољно уљудни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'А да су се они стрпели док им ти сам изађеш, било би им боље. А Аллах прашта и самилостан је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'О ви који верујете, ако вам какав грешник донесе какву вест, добро је проверите, да у незнању некоме зло не учините, па да се због оног што сте учинили покајете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'И знајте да је међу вама Аллахов Посланик; кад би вас он у много чему послушао, заиста бисте настрадали, али Аллах је некима од вас право веровање омилио и у срцима га вашим лепим приказао, а незахвалност и непослушност вам омрзио. Такви су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'Због Аллахове доброте и благодати; Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'Ако се две скупине верника сукобе, измирите их. А ако једна од њих ипак учини насиље другој, онда се борите против оне која је учинила насиље све док се Аллаховим прописима не приклони. Па ако се приклони, онда их непристрасно измирите и будите праведни. Аллах заиста воли праведне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Верници су само браћа, зато помирите своја два брата и бојте се Аллаха да би вам се указала милост.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'О ви који верујете, нека се мушкарци једни другима не ругају, можда су они бољи од њих, а ни жене другим женама, можда су оне боље од њих. И не кудите једни друге и не зовите једни друге ружним надимцима! Како је ружно да се верници спомињу подругљивим надимцима! А они који се не покају – сами себи чине неправду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'О верници, клоните се многих сумњичења, нека су сумњичења, заиста, грех. И не уходите једни друге и не оговарајте једни друге! Зар би неком од вас било драго да једе месо свога умрлог брата - а вама је то одвратно - зато се бојте Аллаха; Аллах, заиста, стално прима покајања и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'О људи, Ми вас од једног човека и једне жене стварамо и на народе и племена вас делимо да бисте се упознали. Најугледнији је код Аллаха онај који Га се највише боји. Аллах, уистину, све зна и није Му скривено ништа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Неки бедуини говоре: “Ми верујемо!” Реци: “Ви не верујете, али реците: ‘Ми се покоравамо!’ – Јер у срца ваша права вера још није ушла. А ако Аллаху и Његовом Посланику будете покорни, Он нимало неће да вам умањи награду за ваша дела. Аллах, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'Прави верници су само они који верују у Аллаха и Његовог Посланика и после више не сумњају и боре се на Аллаховом путу својим богатствима и својим животима. Они су заиста искрени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'Реци: „Зар ви да обавештавате Аллаха о своме веровању, кад Аллах зна све што је на небесима и на Земљи! Аллах све зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Они ти пребацују што су примили ислам. Реци: „Не пребацујте ми што сте примили ислам; напротив, Аллах је вама милост подарио тиме што вас је упутио у праву веру, ако искрено говорите.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Аллах сигурно зна тајне небеса и Земље и Аллах добро види оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Каф,[1] тако Ми величанственог Кур''ана!', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Они се чуде што им је дошао један од њих да их опомиње, па неверници говоре: “То је чудна ствар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'Зар кад помремо и постанемо земља?! Незамислив је то повратак.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Ми знамо шта ће од њих земља одузети, код Нас је Књига у којој се све чува.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Они, међутим, поричу истину која им долази и они су у збуњеном стању.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'А зашто не погледају небо изнад себе? Како смо га саздали и украсили и како у њему нема нереда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'А Земљу смо распрострли и по њој смо побацали непомична брда и дали смо да из ње ниче разноврсно, прекрасно биље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'да би размислио и опоменуо се сваки слуга који се Господару свом покајнички обраћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Ми са неба спуштамо благословљену воду и чинимо да уз њену помоћ ничу вртови и жито које се жање,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'и високе палме у којима су нагомилани замеци једни изнад других,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'као опскрбу слугама, а Ми њоме оживљавамо и мртви предео; тако ће да буде и проживљење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Пре њих порицао је Нојев народ и становници Ресса и Семуд.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'И Ад и фараонов народ и Лотов народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'И становници Ејке и народ Туббеа; сви су они сматрали посланике лажним и казну су Моју заслужили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'Па зар смо након првог стварања постали немоћни?! Не, али они у поновно стварање сумњају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Ми смо створили човека и знамо што му шапуће његова душа, и Ми смо му ближи од вратне жиле куцавице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Кад се двојица састану и седну један с десне, а други с леве стране.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'Он не изусти ниједну реч, а да поред њега није онај који надзире.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Смртне муке ће заиста доћи – то је нешто од чега не можеш побећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'и у рог ће да буде дувнуто - то је Дан којим се прети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'И свако ће да дође, а са њим водич и сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, 'Ти ниси марио за ово па смо скинули твоју копрену, данас ти је оштар вид.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'А његов пратилац ће да каже: “Ово што је код мене спремно је.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'Баците у Пакао сваког незахвалника, пркосника', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'који је бранио да се раде добра дела и који је прелазио Аллахове границе и био сумњичав,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'који је поред Аллаха у другог бога веровао – зато га баците у патњу најтежу!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'А други његов пратилац ће рећи: „Господару наш, ја га нисам завео силом, био је сам у великој заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, '„Не препирите се преда Мном“, рећи ће Он, „још давно Сам вам запретио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'Моја реч се не мења и Ја нисам према Својим слугама неправедан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'На Дан када упитамо Пакао: „Јеси ли се напунио?“ Он ће одговорити: „Има ли још?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'А Рај ће да буде примакнут богобојазнима, неће да буде ни од једног далеко.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, '„Ово је оно што вам је обећано, свакоме ономе ко се Аллаху покајнички обраћао и чувао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'Који се бојао Свемилосног у самоћи, и који је дошао покајничког и покорног срца.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'Уђите у Рај, у миру, ово је Дан вечни!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'У њему ће да имају шта год зажеле, а добиће од Нас и више од тога.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'А колико смо народа пре ових уништили, који су били моћнији од њих, па су по свету трагали - има ли места за спас?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'У томе је, заиста, опомена за онога ко има разум, или ко слуша, а прибран је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Ми смо створили небеса и Земљу и оно што је између њих за шест временских раздобља, и није Нас опхрвао никакав умор.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Зато стрпљиво подноси оно што они говоре и слави и величај свога Господара и захваљуј Му пре изласка Сунца и пре заласка.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'И слави Га и величај ноћу и после обављања молитве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'И очекуј Дан када ће гласник да позове из места које ће свима бити близу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'Дан кад ће они чути истинит глас – то ће бити Дан оживљења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Ми, заиста, дајемо живот и дајемо смрт и код Нас је коначно одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'А на Дан када ће над њима земља да попуца они ће журно да изађу; биће то проживљење, за Нас једноставно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Ми најбоље знамо шта они говоре; ти не можеш да их присилиш, него подсети Кур''аном онога који се боји Моје претње.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'Тако ми оних који уздижу прашину,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'и оних који носе терет,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'и оних којих лако плове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'и оних који спроводе наредбе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'истина је, заиста, оно чиме вам се прети.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Полагање рачуна сигурно ће да се деси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'Тако Ми неба пуног звезданих путева.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Ви говорите противречно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Oд Кур''ана се одвраћа онај за ког се знало да ће се одвратити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Нека проклети буду лажови,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'који су, утонули у неверовање, равнодушни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'Они питају: „Када ће Судњи дан!?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'Биће оног дана када у Ватри буду пржени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, '“Искусите казну своју – то је оно што сте пожуривали!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'А богобојазни ће, заиста, да бораве у рајским баштама, међу изворима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Примаће оно што им њихов Господар буде даровао; они су пре тога добра дела чинили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'ноћу само мало спавали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'и у праскозорје молили опрост од греха,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'а у њиховим иметцима био је удео и за онога који проси и за онога који је ускраћен, а не проси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'На Земљи су докази за оне који чврсто верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'а и у вама самима - зар не видите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'А на небу је ваша опскрба и оно што вам се обећава', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'и, тако Ми Господара неба и Земље, то је истина, као што је истина да говорите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'Да ли је дошла до тебе вест о уваженим Аврамовим гостима?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Кад му они дођоше и рекоше: „Мир вама!“ И он рече: „Мир вама, људи незнани.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'И он неприметно оде својим укућанима и донесе дебело теле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'И примаче им га: „Зар нећете да једете?“ Упита', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'и осети од њих у себи страх. „Не бој се!“ Рекоше и обрадоваше га дечаком који ће учен да буде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'И појави се жена његова узвикујући и по лицу се удари од чуда, рекавши: “Зар ја, стара, нероткиња!?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, '“Тако је одредио твој Господар“, рекоше они, „Он је Мудри и Свезнајући.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, '„А шта ви хоћете, о изасланици?“ Упита Аврам.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, '„Послати смо грешном народу“, рекоше,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, '„да сручимо на њих грумење од глине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'обележено код твога Господара за оне који су прешли сваку меру у разврату.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Ми из њега изведосмо вернике,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'а у њему нађосмо само једну муслиманску кућу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'и у њему, за све оне који се боје болне патње, остависмо знак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, 'И у Мојсију, такође - када га посласмо фараону са очигледним доказом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'а он, охолећи се, окрену се на страну и рече: „Чаробњак је или луд.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'И Ми смо ухватили и њега и његове војске, и бацили их у море, јер је био заслужио казну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, 'И у Аду - кад на њих ветар посласмо у коме није било никаквог добра;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Поред чега год је прошао, ништа није поштедео, све је претворио у трулеж.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'И у Семуду - кад им би речено: „Уживајте још неко време!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Они су се оглушили о наређење свога Господара, па их уништи страшан глас на њихове очи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'и не могаше ни да се дигну ни одбране од казне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'И уништили смо пре Нојев народ: то је, заиста, био грешни народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Ми смо небо снагом изградили, и Ми га, уистину, проширујемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'И Земљу смо прострли - и дивно смо је прострли!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'И од свега стварамо по пар да бисте ви размислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, '„Зато пожурите Аллаху, ја сам вам Његов јасни опомињач!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'И поред Аллаха не узимајте другога бога! Ја сам вам Његов јасни опомињач!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'И тако је било: ни онима пре ових није дошао ниједан посланик, а да нису рекли: „Чаробњак!“ Или: „Лудак!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Јесу ли то они једни другима опоручили? Нису, него су они људи који су били превршили сваку меру у злу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Па, ти се окрени од њих, нећеш да будеш прекорен!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'И опомињи! Заиста, опомена верницима користи!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Духове и људе сам створио само зато да Ме обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Ја не тражим од њих опскрбу нити желим да ме хране,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Опскрбитељ је једино Аллах, Снажни и Силни!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'А оне који су чинили неправду стићи ће казна као што је стигла и оне који су били као они, па нека Ме не пожурују;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'а, тешко неверницима на Дан којим им се прети!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'Тако Ми брда Тур,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'и Књиге у редовима написане', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'на кожи развијеној,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'и небеским Храмом', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'и уздигнутог свода,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'и морем пуним воде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'казна твога Господара сигурно ће да се догоди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Нико неће моћи да је отклони', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'на Дан кад се небо силно узбурка,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'а планине помере са места!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'Тешко тога дана онима који су порицали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'који су се упуштали у лаж, забављајући се!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'На Дан када ће грубо да буду гурнути у Пакао:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, '„Ово је Ватра коју сте порицали', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'па, је ли ово враџбина, или ви не видите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Пржите се у њој, исто вам је трпели или не трпели - то вам је казна за оно што сте радили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'А богобојазни ће, заиста, да буду у рајским баштама и благодатима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Уживаће у оном што ће им њихов Господар дати - и сачуваће их Господар њихов патње у Огњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, 'Једите и пијте и нека вам је пријатно, то је за оно што сте радили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'Биће наслоњени на поређаним диванима, а венчаћемо их са рајским лепотицама крупних очију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Онима који су веровали и за којима су се њихова деца повела у веровању прикључићемо њихову децу, а њихова дела нећемо нимало да умањимо - сваки човек је залог за оно што је урадио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Још ћемо да их дарујемо воћем и месом какво буду желели,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'једни другима ће, у њему, пуне чаше додавати - због њих неће да буде празних беседа и побуда на грех,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'а служиће их њихова послуга налик на скривени бисер,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'и примакнуће се једни другима и једни друге ће да питају:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, '„Некада смо међу својим људима страховали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'па нам је Аллах даровао милост и сачувао нас од патње у Огњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Ми смо Му се молили, а Он је, заиста, Доброчинитељ, Милостиви."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Зато ти опомињи, јер ти, милошћу свога Господара, ниси врачар нити си луд.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Зар они да говоре: „Песник је, сачекаћемо док не умре потресен невољама.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, '„Па чекајте“, ти реци, „и ја ћу заједно са вама да чекам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Да ли им ово њихови умови наређују?! Не, него су они охол народ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Зар они да говоре: „Измишља га!“ Напротив, они не верују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'Зато, нека они саставе говор сличан Кур''ану, ако говоре истину.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Да ли су они створени без Створитеља или су они сами себе створили?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Да ли су они створили небеса и Земљу?! Не, него, они нису убеђени!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Да ли су код њих ризнице твога Господара, или они владају?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Да ли они имају степенице, па на њима прислушкују?! Нека онај међу њима који тврди да је нешто чуо донесе очигледан доказ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Зар да су за Њега - кћери, а да су за вас - синови?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Да ли ти тражиш од њих накнаду, па су наметом оптерећени?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Или, да није у њих знање о ономе што је недокучиво чулима, па они преписују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Зар они желе да праве сплетке?! Па, они који не верују, они су у сплетки!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Зар они другог бога осим Аллаха да имају? Узвишен је Аллах од оних које поред Њега обожавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'И кад би видели да пада комад неба, рекли би: „Нагомилани облаци.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Зато их пусти док се не суоче са Даном у коме ће пропасти,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Даном када њихове сплетке нимало неће да им користе и када нико неће да им помогне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'А за све који су били незнанобошци и друга ће казна пре оне да буде, али већина њих не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'А ти стрпљиво чекај пресуду свога Господара, јер ти си пред Нашим очима; и величај и хвали свога Господара кад устајеш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'и величај Га ноћу кад се звезде губе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'Тако Ми звезде кад залази,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'ваш друг није скренуо са Правог пута и није залутао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Он не говори по својим прохтевима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'То је само Објава која му се обзнањује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, 'Подучава га један великих моћи;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'снажни, који се исправио и показао у своме лику,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'на највишем обзорју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Затим се приближио, па наднео', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'близу колико два лука или ближе', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'и слуги Његовом објавио оно што је објавио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'И срце није порекло оно што је видео.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Па зашто се препирете са њим о оном што је видео?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'Он га је и други пут видео.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'Код Сидретул-Мунтеха,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'где је рајско уточиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Кад је Сидру прекрило оно што ју је прекрило,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'поглед му није скренуо и није прекорачио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'Видео је највеличанственије доказе свога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Шта мислите о Лату и Узау?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'И оном трећем, Менату?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Зар за вас да су синови, а за Њега кћери?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'То је онда неправедна подела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'То су само имена која сте киповима наденули ви и ваши преци; Аллах о њима није послао никакав доказ; они се поводе само за претпоставкама и оним за чим њихове душе жуде, а већ им је дошла Упута од њиховог Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'И зар да човек добије све што пожели?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Па, Аллаху припада и овај и Будући свет.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'А колико на небесима има анђела чије заузимање никоме неће да буде од користи, све док Аллах то не дозволи ономе коме Он хоће и у корист онога којим је задовољан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Они који не верују у Будући свет називају анђеле женским именима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'А о томе ништа не знају, следе само претпоставке, а претпоставка баш нимало не користи Истини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Па, ти се остави онога ко се окренуо од Наше Опомене и који жели само овосветски живот.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'То је врхунац њиховог знања - твој Господар најбоље зна оне који су скренули са Његовог пута и Он најбоље зна оне који су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'Аллахово је све што је на небесима и што је на Земљи, да би, према ономе како су радили, казнио оне који раде зло, а наградио најлепшом наградом оне који чине добро,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'оне који се клоне великих греха и разврата, а оне мале грехе Он ће да опрости, јер твој Господар, заиста, неизмерно прашта, Он најбоље зна све о вама, откад вас је створио од земље и од кад сте били замеци у утробама ваших мајки; зато се не хвалишите - Он најбоље зна оног који се клони греха и чини добра дела.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Зар не видиш онога ко се окренуо од ислама', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'и мало удељивао, а онда у потпуности престао да удељује?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Зар он има знање о ономе што је недокучиво чулима, па види?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Зар он није обавештен о оном што се налази у Мојсијевим листовима', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'и Аврамовим - који је обавезе потпуно испуњавао', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'и да ниједан грешник неће да носи туђе грехе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'и да је човеково само оно што сам уради,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'и да ће његов труд сигурно да буде примећен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'и да ће према њему да буде у потпуности награђен или кажњен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'И да ће поново да се врати твоме Господару,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'и да Он наводи на смех и на плач,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'и да Он усмрћује и оживљава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'и да Он ствара пар, мушко и женско,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'од капи семена кад се избаци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'и да ће Он поновно да их оживи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'и да Он даје да стичу богатство и моћ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'и да је Он Господар Сиријуса,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'и да је Он уништио древни народ Ад,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'и Семуд, и да није поштедео никог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'и још пре Нојев народ, који је био најокрутнији и најохолији,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'и преврнута насеља Он је сручио на земљу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'и снашло их је оно што их је снашло.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Па, у коју благодат свога Господара ти још сумњаш?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'Ово је опомињач из реда претходних опомињача:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'Блиски час се приближава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'осим Аллаха нико не може да га открије, нити отклони!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Па зар се чудите овом говору,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'и смејете се, а не плачете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'гордо дигнутих глава?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Зато, Аллаху ничице падајте и Њега обожавајте.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Ближи се Час и Месец се располовио!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'А они, увек када виде знак, окрећу се и говоре: „Пролазна магија!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'Они поричу истину и следе своје страси, а све ће се остварити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'И дошле су им вести у којима је оно што треба да их одврати од неверства', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, '- савршена мудрост - па како таквима опомињачи могу користити?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Зато се окрени од њих! На Дан кад их гласник позове на нешто ужасно,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 'они ће да излазе из гробова оборених погледа, као скакавци расути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'журећи ка гласнику. А неверници ће да говоре: „Ово је тежак дан.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Порицао је Нојев народ пре њих па су Нашу слугу утеривали у лаж, говорећи: „Лудак!“ - и би одбачен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'И он је свога Господара замолио: „Ја сам побеђен, па Ти помози!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'И Ми смо небеске капије поотварали води која је непрестано лила,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'и учинили да из земље провру извори, и воде су се састале по ономе што је већ било одређено,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'а њега смо носили на лађи саграђеној од дасака и клинова,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'која је пловила пред Нашим очима, а то је била казна за онога који је порицао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'И Ми то остависмо као знак - па има ли икога ко би поуку узео?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'О, каква је била Моја казна и упозорење Моје!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'А Ми смо Кур''ан олакшали за опомену, па има ли икога ко би поуку узео?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'Порицао је Ад, па каква је била Моја казна и упозорење Моје!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Једног кобног дана послали смо на њих леден ветар који је непрестано дувао', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'и људе дизао, као да су ишчупана палмина стабла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'Каква је била казна Моја и упозорење Моје?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'А Ми смо Кур''ан учинили лаким за опомену, па има ли кога ко би се присетио?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'И Семуд је порицао упозорења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, '"Зар да следимо једног од нас!" - Говорили су. "Тада бисмо, уистину, били у заблуди и били бисмо луди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Зар баш њему, између нас, да буде послата Објава?! Не, он је охоли лажљивац!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Сазнаће они сутра ко је охоли лажљивац!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'Ми ћемо послати камилу да бисмо их искушали, па причекај их и буди стрпљив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'И упозори их да ће вода између њих и ње да се дели, сваком оброку приступиће онај чији је ред!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Али они позваше једног од својих, па се он спреми и закла је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'Па каква је само била Моја казна и упозорење Моје!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Ми посласмо на њих један једини крик, и они постадоше попут здробљеног сувог лишћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'А Ми смо Кур''ан олакшали за опомену, па има ли икога ко би се присетио?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'Народ Лотов је порицао упозорења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'На њих посласмо ветар, пун песка, само не на Лотову породицу, њу смо у свитање спасили', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'из Наше милости. Ето, тако Ми награђујемо оне који захваљују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'И он их је упозоравао на Нашу казну, али су они сумњали у упозорење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Они су од њега тражили његове госте, па смо их Ми ослепили: „Искусите Моју казну и Моју претњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'А рано ујутру стиже их непрекидна казна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, '„Искусите Моју казну и Моју претњу!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'А Ми смо Кур''ан олакшали за опомену, па има ли икога ко би поуку примио?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'И фараоновој породици су долазила упозорења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'али они порекоше све Наше знакове, па их Ми казнисмо онако како кажњава Силни и Апсулутно Моћни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, 'Да ли су ваши неверници бољи од њих, или ви у небеским књигама имате какво оправдање?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Зар ови да говоре: „Ми смо скуп непобедиви!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'Скуп ће сигурно да буде поражен, а они ће се у бег дати!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Међутим, Час оживљења им је рок, а Час оживљења је ужаснији и горчи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Грешници су, заиста, у заблуди и патњи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'на Дан када буду одвучени у Ватру, са лицима окренутим доле: „Искусите кажњавање Огњем!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Ми заиста све стварамо са одређењем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'и Наше наређење само је једна реч - све буде у трен ока.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'А Ми смо већ уништили вама сличне, па има ли икога ко би поуку примио?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'И све што су урадили у листовима је,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'и све, и мало и велико, у редовима записано.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Они који су се бојали Аллаха биће у рајским баштама и поред река,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'на месту истине, код Краља Свемоћног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Свемилосни', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'подучава Кур''ану,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'ствара човека,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'учи га изговору.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Сунце и Месец плове по тачно одређеном прорачуну,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'и звезде и дрвеће се Њему клањају', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'а небо је уздигао. И мерила поставио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'да не прелазите границе правде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'и право мерите и на ваги не закидајте!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'А Земљу је учинио погодном за створења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'и на њој има воћа и палми са плодом у чашицама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'и жито са лишћем и мирисног цвећа,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, 'Он је човека створио од сасушене иловаче, као што је грнчарија,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'а духове од пламена ватре –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, 'Господар два истока и два запада –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'Пустио је два мора да се сусрећу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'између њих је преграда и она се не мешају –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Из њих се ваде бисери и украси корала –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'Његове су и лађе које се као брда уздижу високо по мору –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Све што је на Земљи пролазно је,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'а остаје Лице твога Господара, Величанствено и Племенито,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Њему се моле они који су на небесима и на Земљи; сваког трена Он се занима нечим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'Обрачунаћемо се са вама, о људи и духови!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'О дружине духова и људи, ако можете да продрете кроз слојеве небеса и Земље, продрите! Нећете продрети осим једино уз велику моћ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Па, коју благодат Господара свога поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'На вас ће се слати огњени пламен и дим и ви се нећете моћи одбранити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'па, коју благодат Господара свога поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'А кад се небо раздвоји и постане ружичасте боје као растопљено уље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, 'па, коју благодат Господара свога поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'Тог дана људи и духови за своје грехе неће да буду питани', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'па, коју благодат Господара свога поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'А грешници ће по знацима својим да буду препознати, па ће за косе и за ноге шчепани бити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'па, коју благодат Господара свога поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, 'Ово је Пакао, којег су грешници порицали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Између ватре и узавреле воде они ће да круже,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'А ономе ко се буде бојао стајања пред својим Господаром припашће две рајаске баште,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'пуна стабала гранатих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'у којима су два извора која теку,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'у њима ће од сваког воћа по две врсте да буду,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, 'Биће наслоњени на постеље чије ће поставе од свилене тканине да буду, а плодови у обе баште надохват руке ће стајати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'У њима ће да буду оне које испред себе гледају, оне које, пре њих, ни човек ни дух није додирнуо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'као да су оне драгуљ и мерџан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'Зар за добро учињено дело награда може да буде нешто друго осим добро?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Осим те две биће још две незнатније баште,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'тамнозелене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'У њима су два извора из којих вода прска;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'У њима ће да буде воћа и палми и шипака,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'У њима ће да буду лепотице нарави дивних,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Хурије у шаторима скривених,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Које никада ни човек ни дух није додирнуо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, 'Они ће да буду наслоњени, на прекривачима зеленим и ћилимима чудесно украшеним и лепим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'па, коју благодат свога Господара поричете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Благословљено је име твога Господара, Величанственог и Племенитог!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Када се Неизбежни догађај догоди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, 'догађање његово нико неће порицати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Неке ће да понизи, а неке да узвиси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Кад се Земља јако потресе', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, 'и брда се у комадиће здробе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'и постану разасута прашина,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, 'вас ће да буде три врсте:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, 'они са десне стране - шта ће да буде са оним са десне стране?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, 'и они са леве стране - шта ће да буде са онима са леве стране?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, 'И они који су предњачили – они ће предњачити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'То су они блиски,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'у рајским баштама уживања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'Биће их много из првих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'а мало из задњих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, 'на диванима извезеним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'једни према другима на њима ће да буду наслоњени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'служиће их вечно млади дечаци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'са чашама и ибрицима, и пехаром пуним пића из текућег извора', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'од кога глава неће да их боли и због кога неће памет да изгубе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'и воћем које ће сами да бирају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'и месом птичијим какво буду желели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'У њима ће да буду и рајске лепотице крупних очију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'сличне скривеном бисеру у шкољкама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'као награда за оно што су чинили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'У њима неће да слушају празне беседе, ни грешни говор,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'него само речи: "Мир Божји, мир Божји!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'А они са десне стране - шта ће да буде са оним са десне стране?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, 'Биће међу лотосовим дрвећем без бодљи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'и међу дрвећем акације нанизаним плодовима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'и у пространој хладовини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'поред текуће воде', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'и међу разноврсним воћем', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'које ће увек да имају и које неће да буде забрањено', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'и на уздигнутим постељама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'Њихово стварање, заиста, ћемо да обновимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'и девицама да их учинимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, 'и оним које се умиљавају својим мужевима и истих година', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'за оне са десне стране.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'Биће их много из првих,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'а много из каснијих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'А они са леве стране - шта је са онима са леве стране?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'Они ће да буду у ватри ужареној и кључалој води,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'и у сенци црног дима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'у којој неће да буде свежине ни било какве угодности.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Они су пре тога живели раскошним животом', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'и упорно су чинили тешке грехе', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'и говорили су: „Зар кад умремо и земља и кости постанемо - зар ћемо збиља да будемо оживљени;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'зар и наши древни преци?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'Реци: „И древни и каснији,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'у одређено време, и у Дан одређени биће сакупљени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'и тада ћете ви, о заблудели, који поричете оживљење,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'сигурно са дрвета Зеккум да једете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'и њиме ћете да пуните стомаке,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'па затим на то кључалу воду да пијете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'попут камила које не могу да угасе жеђ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'то ће да им буде угошћење на Дан полагања рачуна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'Ми смо вас створили - па зашто не поверујете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Шта мислите да ли семену које убацујете', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'ви облик дајете или Ми то чинимо?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Ми одређујемо кад ће ко од вас да умре, и нико не може да Нас спречи', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'да ликове ваше изменимо и да вас изнова у ликовима које ви не познајете створимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Познато вам је како сте први пут створени, па зашто се не уразумите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Шта мислите о оном што посејете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'Да ли му ви дајете снагу да ниче, или то Ми чинимо?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Када би хтели могли би да га претворимо у суво растиње, па бисте се снебивали:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, '„Ми смо, заиста, оштећени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'чак смо свега лишени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Шта мислите о води коју пијете –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'да ли је ви или Ми из облака спуштамо?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Ако желимо, можемо да је сланом учинимо - па зашто нисте захвални?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Шта мислите о ватри коју палите -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'да ли дрво за њу Ми стварамо или ви?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'Ми смо је учинили као упозорење, и као корист путницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Зато слави и величај име Господара свога Величанственог!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'И кунем се положајима звезда', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'а то је, да знате, велика заклетва!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Он је, заиста, Кур''ан племенити', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'у Књизи брижљиво чуваној.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Додирнути је смеју само они који су чисти!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'Он је објава од Господара светова,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'па како овај говор омаловажавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'и уместо захвалности што вам је дарована опскрба, ви у њега не верујете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'А зашто ви, кад душа допре до грла,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'и кад ви будете тада гледали –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'а Ми смо му ближи од вас, али ви не видите –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'зашто је онда, ако рачун нећете да полажете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'не повратите, ако истину говорите?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'И ако буде један од оних који су Аллаху блиски –', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'удобност и лепа опскрба и рајске благодати припашће њему!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'А ако буде један од оних који су са десне стране,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'па, мир Божји теби од оних са десне стране!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'А ако буде један од оних који су порицали и у заблуди остали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'па, кључалом водом биће угошћен', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'и у Огњу пржен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Сама је истина, заиста, све ово!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Па, слави и величај име свога Господара Величанственог!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Аллаха слави и велича све што је на небесима и на Земљи, и Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'Његова је власт на небесима и на Земљи; Он даје живот и смрт, и Он над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'Он је Први и Последњи, и над свиме Доминантни и у бити свега Проницљиви; и Он све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'Он је створио и небеса и Земљу за шест дана, а затим се узвисио над својим Престолом; Он зна шта улази у земљу и шта излази из ње и шта силази са неба и шта се диже према њему, Он је са вама где год били, и све што радите Аллах види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'Његова је власт на небесима и на Земљи, и Аллаху ће се све вратити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'Он уводи ноћ у дан и дан у ноћ, и Он зна шта се скрива у грудима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'Верујте у Аллаха и Његовог Посланика и удељујте из онога што вам је дао да наследите, јер оне од вас који буду веровали и удељивали чека велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Како да не верујете у Аллаха, а Посланик вас позива да верујете у свога Господара - а већ је узео ваш завет - ако сте верници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'Он слуги Свом објављује јасне речи и доказе, да би вас из тмина на светло извео - а Аллах је, уистину, према вама благ и милостив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'И како да не трошите на Аллаховом путу, а Аллаху припада наслеђе небеса и Земље?! Нису једнаки они међу вама који су удељивали пре победе и лично се борили - они су на вишем степену од оних који су после удељивали и лично се борили, а Аллах свима обећава награду најлепшу; Аллах у потпуности зна оно шта радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Ко је тај ко ће Аллаху леп зајам дати да би му га Он многоструко вратио, а уз то ће и дивну награду имати?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'На Дан кад будеш видео како се пред верницима и верницама, и са њихове десне стране, њихово светло буде кретало: “Благо вама од данас! Рајске баште, кроз које теку реке, у којима ћете вечно да боравите – то је велики успех!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'На Дан када ће лицемери и лицемерке да говоре верницима: “Сачекајте нас да се светлом вашим послужимо!” “Вратите се назад, па друго светло потражите?” Биће речено. И између њих ће преграда да буде постављена која ће да има врата; унутар ње биће милост, а изван ње патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, '“Зар нисмо са вама били?” Дозиваће их. “Јесте”, одговориће, “али сте сами себе завели и ишчекивали сте и сумњали сте, и пусте жеље су вас заваравале, све док није дошла Аллахова одредба, и док вас није ђаво о Аллаху обмануо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Никаква откупнина данас од вас неће да буде примљена, а ни од оних који нису веровали; Ватра ће да буде ваше пребивалиште, њу сте заслужили, а ужасно је она одредиште!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'Зар није време да се онима који верују смекшају срца због спомена Аллаха и истине која се објављује и да они не буду као они којима је још давно дата Књига, па су њихова срца, зато што је протекло много времена, постала немилосрдна и многи су од њих непокорни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Знајте да Аллах даје живот већ мртвој земљи! Ми вам појашњавамо доказе да бисте разумели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Онима који милостињу буду удељивали и онима које је буду удељивале, и који драге воље Аллаху зајам буду давали - многоструко ће да им се врати и њих чека дивна награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'А они који верују у Аллаха и Његове посланике - то су они истинољубиви! А мученицима на Божјем путу припада код њиховог Господара награда, и њихово светло! А они који не верују и поричу Наше речи и доказе, то су становници Ватре!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'Знајте да је овосветски живот код људи само игра и слеђење страсти, и украшавање, и међусобно хвалисање, и надметање имовином и децом! Он је налик киши од које биље задиви земљораднике, које потом, након кише, узбуја, а затим га видиш пожутелог и на крају сасушено. На Будућем свету биће жестока казна, а и Аллахов опрост и задовољство. А шта је живот на Земљи ако не само варљиво уживање!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'Надмећите се да код свога Гоподара заслужите опрост и Рај, простран колико су пространи небо и Земља, и припремљен за оне који у Аллаха и Његове посланике верују. То је Аллахова награда коју ће дати ономе коме Он хоће; а Аллах поседује огромну награду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Нема несреће која задеси Земљу и вас, а која није, пре него што је дамо, записана у Књизи - то је Аллаху, заиста, лако -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'да не бисте туговали за оним што вам је промакло, а и да се не бисте превише радовали ономе што вам Он подари. Аллах не воли никакве разметљивце, хвалисавце,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'који шкртаре и траже да и људи буду шкрти. А онај ко одбије и окрене се - па, Аллах је, заиста, Независни и Хваљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Ми смо Наше изасланике слали са јасним доказима и по њима смо слали Књиге и мерило правде, да би људи праведно поступали, а гвожђе смо спустили, у коме је велика снага и које људима користи, а да би Аллах знао оне који помажу Њега и Његове посланике иако их и не виде. Аллах је, уистину, моћан и силан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Ми смо послали Ноја и Аврама, и некима од њихових потомака смо објаву и веровесништво дали; неки су од њихових потомака на Правом путу, а многи од њих су неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Затим смо, њиховим траговима, једног за другим слали Наше посланике, док нисмо Исуса, Маријиног сина, послали. Њему смо дали Јеванђеље, и учинили смо да у срцима његових следбеника буду благост и самилост. А монаштво су они сами као новотарију увели у жељи за Аллаховим задовољством - Ми им га нисмо прописали; већ смо им прописали трагање за Аллаховим задовољством, али они о њему нису водили бригу онако како би требало, па ћемо оне међу њима који буду исправно веровали да наградимо, а многи од њих су неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'О ви који верујете, бојте се Аллаха и у Његовог Посланика верујте. Он ће вам даровати Своју двоструку милост, и даће вам светло помоћу ког ћете да идете, и опростиће вам, а Аллах опрошта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'И нека следбеници Књиге знају да они никакву Аллахову благодат неће да добију, јер је благодат само у Аллаховој руци - даје је ономе коме Он хоће; а Аллах поседује огромне благодати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Аллах је чуо речи оне која се са тобом о своме мужу расправљала и Аллаху се јадала, а Аллах чује ваш међусобни разговор. Аллах, уистину, све чује и све види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Они од вас који својим женама кажу да су им забрањене попут њихових мајки, а оне нису њихове мајке - њихове мајке су само оне које су их родиле, они, заиста, говоре страшне речи и неистину - а Аллах, заиста, грехе поништава и опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Они који својим женама кажу да су им забрањене попут њихових мајки, а онда се поврате у ономе што су казали, дужни су, пре него што једно друго додирну, једног роба ропства да ослободе. То је оно што вам се наређује - а Аллах у потпуности зна шта ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Онај који не нађе, дужан је да пости два месеца узастопно пре него једно друго додирну. А онај ко не може, дужан је да нахрани шездесет сиромаха, зато да бисте потврдили да у Аллаха и Његовог Посланика верујете – то су Аллахови прописи. А невернике чека болна казна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'Заиста, они који се супротстављају Аллаху и Његовом Посланику биће одбачени и понижени, као што су били одбачени и понижени и они пре њих. Ми смо објавили јасне речи и доказе, а невернике чека понижавајућа патња', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'на Дан кад их Аллах све оживи, па их обавести о оном шта су радили; Аллах је о томе свео рачун, а они су то заборавили - Аллах је свему сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Зар не знаш да Аллах зна све што је на небесима и што је на Земљи?! Нема тајних разговора међу тројицом, а да Он није четврти, ни кад их је мање, ни кад их је више, а да Он није са њима где год они били; Он ће да их обавести на Судњем дану о оном што су радили. Аллах заиста све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Зар не видиш оне којима је забрањено да се сашаптавају како се затим враћају ономе што им је забрањено и сашаптавају се о греху, непријатељству и непослушности према Посланику?! А кад ти долазе, поздрављају те онако како те Аллах никад није поздравио, и међу собом говоре: “Требало би да нас Аллах већ једном казни за оно што говоримо!” Довољан ће да им буде Пакао! У њему ће да горе, а ужасно је то одредиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'О ви који верујете, када се међу собом дошаптавате, не дошаптавајте се о греху, непријатељству и непослушности према Посланику, већ се дошаптавајте о доброчинству и богобојазности, и бојте се Аллаха, пред Којим ћете да будете окупљени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'Такво сашаптавање је од ђавола, да би растужио оне који верују, а то не може њима нимало да науди, осим ако то Аллах допусти. И верници нека се поуздају само у Аллаха!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'О ви који верујете, кад вам се каже: “Направите места другима тамо где се седи”, ви направите, па и вама ће Аллах место да направи; а кад вам се каже: “Дигните се”, ви се дигните, и Аллах ће на високе степене да уздигне оне међу вама који верују и којима је дато знање. А Аллах у потпуности зна оно шта радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'О ви који верујете, кад хоћете да се са Послаником сашаптавате, пре тога милостињу уделите. То је за вас боље и чистије. А ако не нађете ништа - па, Аллах је, заиста, Опростилац греха, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Зар вас је страх да пре разговора свога уделите милостињу?! А ако не уделите и Аллах вам опрости, онда обављајте молитву и дајте обавезну милостињу и будите покорни Аллаху и Његовом Посланику! Аллах у потпуности зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Зар не видиш оне који за пријатеље и заштитнике узимају људе на које се Аллах разљутио?! Они нису ни ваши ни њихови, заклињу се лажно, а знају то.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Аллах је њима припремио жестоку патњу, а заиста је ружно оно што раде.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'Штите се својим заклетвама, и тако одвраћају од Аллаховог пута, па им зато припада понижавајућа патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Ни њихова имовина, ни њихова деца нимало неће да им помогну код Аллаха, они ће да буду становници у Ватри, у њој ће вечно да бораве.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'На Дан када их Аллах све оживи они ће да Му се заклињу, као што се вама заклињу, мислећи да ће то нешто да им користи. Они су, заиста, прави лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Њима је овладао ђаво и учинио да забораве да спомињу Аллаха, они су ђавољева странка, а збиља, они из ђавољеве странке су прави губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Они који се супротстављају Аллаху и Његовом Посланику биће, сигурно, међу оним најпониженијим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Аллах је записао: “Ја и посланици Моји сигурно ћемо да победимо!” Аллах је, заиста, моћан и силан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Нећеш наћи да људи који у Аллаха и Судњи дан верују буду у љубави са онима који се Аллаху и Његовом Посланику супротстављају, па били то њихови очеви, или њихови синови, или њихова браћа, или њихови рођаци. Њима је Он у срца усадио веровање и оснажио их Својим светлом, и Он ће да их уведе у рајске баште, кроз које теку реке, да у њима вечно остану. Аллах је њима задовољан, а и они су задовољни Њиме. Они су Аллахови следбеници а, заиста, Аллахови следбеници ће сигурно да успеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Аллаха слави и велича све што је на небесима и што је на Земљи, Он је силан и мудар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'Он је приликом првог прогонства протерао из њихових домова оне следбенике Књиге који нису веровали. Ви нисте мислили да ће изаћи, а они су мислили да ће њихове тврђаве да их одбране од Аллаха, али их је Аллах казнио одакле се нису надали и Он је у њихова срца улио страх; властитим рукама и рукама верника своје домове су рушили. Зато узмите из тога поуку, о ви разборити!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'А да им Аллах није већ био прописао изгнанство, Он би их другој патњи још на овом свету подвргао! А њима на Будућем свету припада патња у Ватри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'То је зато што су се супротстављали Аллаху и Његовом Посланику; а онај ко се Аллаху супротставља – па Аллах, заиста, жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'То што сте неке палме посекли или их, да усправно стоје, оставили - са Аллаховим допуштењем сте учинили, и зато да Он невернике понизи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'А ви нисте гонили коње ни камиле због онога што је Аллах од њих, као плен, даровао Своме Посланику, него, Аллах препушта власт Својим посланицима над онима над којима Он хоће; Аллах над свиме има моћ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Плен становника села и градова који Аллах Своме Посланику дарује припада: Аллаху и Његовом Посланику, и његовим ближњима, и сирочадима, и сиромашним, и путницима намерницима - да не би прелазио само из руку у руке ваших богаташа; оно што вам Посланик да, то прихватите, а оно што вам забрани - оставите, и бојте се Аллаха. Аллах, заиста, жестоко кажњава.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'И сиромашним исељеницима на Аллаховом путу који су протерани из својих домова и из својих поседа, трагајући за Аллаховим обиљем и задовољством, и који Аллаху и Његовом Посланику помажу, то су, заиста, искрени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'А они који су пре њих Медину населили и веру прихватили, они воле оне који им се досељавају, и у својим грудима никакву завист, зато што им се даје, не осећају, и више воле њима него себи, мада им је и самима потребно. А они који се причувају похлепе и тврдичлука, они ће сигурно да успеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Они који после њих долазе - говоре: “Господару наш, опрости нама и нашој браћи која су нас претекла у вери и не допусти да у нашим срцима буде имало злобе према верницима; Господару наш, Ти си, заиста, милосрдан и милостив.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Зар ниси видео лицемере како говоре својим пријатељима, следбеницима Књиге који не верују: “Ако будете протерани, ми ћемо сигурно са вама да пођемо и кад се вас буде тицало, никада никоме нећемо да се покоримо; а ако будете нападнути, сигурно ћемо да вам у помоћ притекнемо”, а Аллах је сведок да су они, заиста, лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'Ако би били протерани, они не би са њима пошли; ако би били нападнути, они им не би у помоћ притекли; а ако би им у помоћ притекли, сигурно би побегли и они би без помоћи остали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'Они се више боје вас него Аллаха, зато што су они људи који не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Само у утврђеним градовима или иза зидина они против вас смеју заједно да се боре. Њихово међусобно непријатељство је жестоко. Ти мислиш да су они сложни, међутим, срца су њихова разједињена, зато што су то људи који не разумеју.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, 'Слични су онима који су, ту недавно, искусили сву погубност својих поступака - њих чека болна патња.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'Слични су ђаволу кад каже човеку: “Буди неверник!” Па кад постане неверник, он онда каже: “Ја више немам ништа са тобом; ја се, заиста, бојим Аллаха, Гоподара светова.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'Обојицу их, на крају, чека Ватра у којој ће вечно да бораве, а то ће да буде казна за све насилнике.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'О ви који верујете, бојте се Аллаха, и нека сваки човек гледа шта је припремио за сутра, и бојте се Аллаха. Аллах, заиста; у потпуности зна оно шта радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'И не будите као они који су заборавили Аллаха, па је Он учинио да забораве сами себе; то су прави грешници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Нису једнаки становници Пакла и становници Раја; становници Раја су успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Када би овај Кур''ан објавили некој планини, ти би видео како је пуна страхопоштовања и како би се распала од страха пред Аллахом. Такве примере наводимо људима да би размислили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'Он је Аллах, осим Којег нема другог истинског бога, познавалац оног што је недокучиво чулима, а и оног што је појавно, Свемилосни, Милостиви.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'Он је Аллах, осим Којег нема другог истинског бога, Владар, Благословљени и Свети, Савршени - Онај Који је без недостатака, Онај Који пружа сигурност, Онај Који над свим бди, Силни, Узвишени, Горди. Слављен и Узвишен је Аллах од оних које поред Њега обожавају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'Он је Аллах, Креатор, Творац, Обликовалац, Он има најлепша имена. Њега слави и велича све што је на небесима и на Земљи, Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'О ви који верујете! Не узимајте Моје непријатеље и своје непријатеље за присне пријатеље, волећи их, а они поричу Истину која је вама дошла, и изгоне Посланика и вас само зато што верујете у Аллаха, вашега Господара, ако сте већ изашли ради борбе на Моме Путу и тражећи Моје задовољство. Ви њима љубав тајно исказујете, а Ја најбоље знам шта ви скривате и шта обзнањујете. А ко то од вас буде радио, па - тај је залутао са Правог пута.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Ако вас се они домогну, биће ваши непријатељи и пружиће према вама, у злој намери, своје руке и своје језике, и желеће да будете неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Ни ваша родбина ни ваша деца неће да вам буду од користи, на Судњем дану Он ће да вас раздвоји. Аллах добро види оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Имате добар узор у Авраму и у онима који су са њим били кад су своме народу казали: „Ми са вама немамо ништа, а ни са онима које ви, уместо Аллаха, обожавате, ми вас се одричемо, и непријатељство и мржња између нас стално ће да се јавља све док не будете у Аллаха, Њега Јединог, веровали!“ Али не и у Аврамовим речима своме оцу: „Ја ћу за тебе да молим опрост, али не могу од Аллаха да те одбраним." Господару наш, на Тебе се ослањамо, Теби се обраћамо и код Тебе је крајње одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'Господару наш, не учини да будемо искушење онима који не верују и опрости нам, Господару наш! Ти си, заиста, Силни и Мудри.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Они су добар узор сваком оном ко се нада Аллаху и очекује Судњи дан. А свако ко одбије и окрене се - па, Аллах је, заиста, Независтан и Хваљен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Аллах ће сигурно да успостави љубав између вас и оних са којима сте у непријатељству; Аллах је свемоћан, и Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Аллах вам не забрањује да чините добро и да будете праведни према онима који нису ратовали против вас због вере и који вас из ваших домова нису изгнали - Аллах, заиста, воли оне који су праведни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'али вам забрањује да будете блиски са онима који су ратовали против вас због вере ваше и који су вас из домова ваших изгнали и који су помогли да будете прогнани. Они који су са њима блиски су неправедни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'О ви који верујете, кад вам вернице као исељенице из Мекке дођу, испитајте их; Аллах најбоље зна какво је њихово веровање, па ако се уверите да су вернице, онда их не враћајте неверницима; оне њима нису допуштене, нити су они њима допуштени; а њима дајте оно што су потрошили. Није вам грех да се њима жените кад им венчане дарове њихове дате. У браку невернице не задржавајте! Тражите оно што сте потрошили, а нека и они траже оно што су потрошили! То је Аллахов суд, Он суди међу вама, а Аллах све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'А ако нека од жена ваших неверницима умакне, и ако ви после у борби плен заробите, онда онима чије су жене умакле венчане дарове које су им дали намирите. И бојте се Аллаха, у Кога верујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'О Веровесниче, када ти дођу вернице да ти дају обећање на верност: да неће Аллаху никога у обожавању да придружују, и да неће да краду, и да неће мужевима туђу децу да подмећу, и да неће ни у чему, што је добро, послушност да ти одбијају, ти обећање њихово прихвати и моли Аллаха да им опрости; Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'О ви који верујете, не узимајте за присне пријатеље и заштитнике људе на које се Аллах расрдио; они су изгубили наду да ће било какву награду на Будућем свету да имају, исто као што су неверници изгубили наду у вези са онима који су у гробовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Аллаха слави и велича оно што је на небесима и оно што је на Земљи; Он је Силни и Мудри!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'О ви који верујете, зашто говорите оно што не радите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'Како само Аллах презире да говорите оно што не радите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Аллах, заиста, воли оне који се боре на Његовом путу у редовима као да су утврђено здање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Када Мојсије рече своме народу: „О народе мој, зашто ме узнемиравате, а добро знате да сам вам ја Аллахов посланик!” И кад они скренуше у страну, Аллах скрену њихова срца, а Аллах неће да упути народ који је огрезао у греху.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'А када Исус, Маријин син, рече: “О синови Израиљеви, ја сам вам Аллахов посланик, да вам потврдим пре мене објављену Тору и да вам донесем радосну вест о посланику чије је име Ахмед, који ће после мене доћи”, и кад им је донео јасне доказе, они рекоше: “Ово је очигледна враџбина!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'А има ли већег насилника од онога који о Аллаху износи лажи док се у ислам позива?! А Аллах неће да упути народ који неправду чини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'Они желе да утру Аллахово светло својим устима, а Аллах ће да употпуни Своје светло, макар то мрзели неверници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'Он је послао Свог Посланика са упутом и истинитом вером да би је уздигао изнад свих вера, макар то мрзели незнанобошци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'О ви који верујете, хоћете ли да вам укажем на трговину, која ће да вас сачува болне патње?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'Верујте у Аллаха и Његовог Посланика и својим богатствима и својим животима борите се на Аллаховом путу - то вам је, да знате, боље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, 'Он ће ваше грехе да вам опрости и да вас уведе у рајске баште, кроз које теку реке, и у дивне дворове у вртовима Едена; то је велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'А даће вам и другу благодат коју волите: Аллахову помоћ и скору победу! Зато обрадуј вернике!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'О ви који верујете, будите Аллахови помагачи, као што је рекао Исус, Маријин син, блиским следбеницима: “Ко су моји помагачи у позивању Аллаху?” Они одговорише: “Ми смо Аллахови помагачи!” Па је једна група од Израиљевих потомака поверовала, а друга група узневеровала! Па смо оне који су веровали против њихових непријатеља оснажили и били су надмоћни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Аллаха слави и велича све што је на небесима и оно што је на Земљи, Владара, Благословљеног и Светог, Силног и Мудрог.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'Он је неписменима послао Посланика, једног између њих, да им речи Његове казује и да их очисти и да их Књизи и мудрости научи, иако су пре били у очигледној заблуди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'и другима који им се још нису прикључили, Он је Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'То је Аллахова милост коју Он даје ономе коме хоће – а Аллах је поседник великог обиља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Они којима је Тора дата да је следе, а затим је не следе, слични су магарцу који носи књиге. О како су лоши они који Аллахове речи и доказе поричу! А Аллах неће да упути на Прави пут народ неправедни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'Реци: “О Јевреји, ако тврдите да сте ви од свих људи једини Аллахови миљеници, онда пожелите смрт, ако истину говорите.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'А због онога што њихове руке раде неће никад да је пожеле; А Аллах добро зна неправедне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'Реци: “Смрт од које бежите заиста ће да вас стигне. Затим ћете Оном који зна невидљиви и видљиви свет да будете враћени и Он ће вас, о оном што сте радили, обавестити.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'О ви који верујете, кад у петак на молитву будете позвани, пожурите на слављење Аллаха, и оставите се трговине, то вам је боље, ако знате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'А кад се молитва заврши, онда се по Земљи разиђите и трагајте за Аллаховим благодатима и Аллаха много славите, да бисте успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Али, кад они какву трговачку робу или забаву угледају, похрле јој и тебе оставе самог да стојиш. Реци: “Оно што је код Аллаха боље је и од забаве и од трговине. А Аллах је најбољи Опскрбитељ.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Кад ти лицемери долазе, они говоре: „Ми сведочимо да си ти, заиста, Аллахов посланик!” И Аллах зна да си ти, заиста, Његов посланик, а Аллах сведочи и да су лицемери прави лажљивци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Они су своје заклетве узели као штит, па одвраћају од Аллаховог пута. Ружно је, заиста, како поступају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'То је зато што су били верници, а затим неверници, па су им срца запечаћена, па не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Кад их погледаш, њихов те изглед задивљује; а кад проговоре, ти слушаш њихове речи - међутим, они су као шупљи наслоњени балвани, и мисле да је сваки повик против њих. Они су прави непријатељи, па их се причувај! Аллах их уништио, куда се одмећу?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'А кад им буде речено: “Дођите, Аллахов Посланик ће да моли да вам се опрости!” Они својим главама тресу и видиш их како охоло одбијају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'Исто им је – молио ти за њих опрост или не молио, Аллах неће да им опрости. Аллах, заиста, неће на Прави пут да упути народ одметнички.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Они говоре: “Не удељујте ништа онима који су уз Аллаховог Посланика, не би ли га напустили!” А ризнице небеса и Земље су Аллахове, али лицемери не схватају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Они говоре: “Ако се вратимо у Медину, сигурно ће јачи да истерају из ње слабијег!” А снага је код Аллаха и код Његовог Посланика и код верника, али лицемери не знају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'О ви који верујете, нека вас ваша имања и ваша деца не забаве од спомињања Аллаха. А они који то учине, прави су губитници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'И удељујте од онога чиме вас Ми опскрбљујемо пре него што неком од вас дође смрт, па да онда каже: “Господару мој, да ме још само кратко време задржиш у животу, па да милостињу удељујем и да будем добар!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Аллах сигурно неће да остави у животу никога коме дође његова смрт. Аллах у потпуности зна оно што ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'Аллаха слави и велича све што је на небесима и све што је на Земљи. Њему припада сва власт и Њему припада сва похвала; Он над свиме има моћ!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'Он вас је створио, па има међу вама и неверника, а има међу вама и верника. Све што ви радите Аллах добро види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'Он је небеса и Земљу створио са Истином и уобличио вас и ваше ликове чини најлепшим, и код Њега је коначно одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'Он зна шта постоји на небесима и на Земљи и зна шта кријете и шта показујете! Аллах добро зна шта груди крију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Није ли до вас дошла вест о онима који још давно нису веровали, па су кобност свога поступка искусили - а још их и болна казна чека?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'То је зато што су говорили, кад су им њихови посланици јасне доказе доносили: “Зар да нас људи упућују?” Па нису веровали и одметали су се; а Аллаху није нико потребан, Аллах је независан и хваљен!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Неверници мисле да неће да буду оживљени. Реци: “Хоћете, Господара ми мога, сигурно ћете да будете оживљени, па ћете о оном што сте радили, заиста, да будете обавештени!” А то је Аллаху лако.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Зато, верујте у Аллаха и Његовог Посланика и у Светло које објављујемо, Аллах у потпуности зна оно шта ви радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'Онда када вас Он сакупи на Судњем дану, тог дана схватићете да сте били обмањени. Ко буде веровао и радио добра дела, Аллах ће да му прекрије лоша дела и увешће га у рајске баште кроз које теку реке, у њима ће вечно да бораве. То ће да буде велики успех!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'А они који нису веровали и који су Наше речи и доказе порицали, биће становници у Ватри; у њој ће вечно да остану, а ужасно је то место!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Никаква невоља не погађа осим са Аллаховом дозволом! А ко у Аллаха верује, Он ће да упутити његово срце, а Аллах све добро зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'И покоравајте се Аллаху и Његовом Посланику; а ако се окренете, па обавеза Нашег Посланика је само јасна обзнана!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Аллах - нема другог бога осим Њега. А верници нека се само у Аллаха поуздају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'О ви који верујете, међу вашим супругама и вашом децом, заиста, имате непријатеља, па их се причувајте! А ако преко тога пређете и не корите и опростите, па Аллах, заиста, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Ваша имања и ваша деца само су искушење, а код Аллаха је велика награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Па Аллаха се бојте колико год можете, и слушајте и покоравајте се и удељујте за своје добро. А они који буду сачувани похлепе и тврдичлука, такви су успели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'А ако Аллаху леп зајам дате, Он ће да вам га увећа и опростиће вам. Аллах је Захвалан и Благ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, 'Познавалац онога што је недокучиво чулима и онога што је појавно, Силни и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'О Веровесниче, кад хоћете жене да разведете, ви их разведите у време кад су чисте, и рачунајте то време, и Аллаха, свога Господара, се бојте. Не изгоните их из њихових кућа, а ни оне нека не излазе, осим ако учине очигледно срамно дело. То су Аллахове границе. А онај који прелази Аллахове границе, сам себи је учинио неправду. Ти не знаш, можда Аллах, после тога нешто ново одреди!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Па када оне испуне време свог чекања, ви их или на леп начин задржите, или се лепо од њих коначно раставите, и као сведоке узмите двојицу својих праведних људи, и обавите сведочење ради Аллаха! То је савет за оног који верује у Аллаха и у Судњи дан - а ономе који се Аллаха боји, Он ће излаз дати', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'и опскрбиће га одакле се и не нада; ономе ко се на Аллаха ослони, Он му је довољан. Аллах ће, заиста, да испуни оно што је одлучио; Аллах је свему већ рок одредио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'А оне ваше жене, које су изгубиле наду у месечно прање - ако сумњате - оне треба да чекају три месеца, а и оне које га још нису добиле! Време чекања за трудне жене јесте порођај. А ономе ко се Аллаха боји, Он ће му у свему олакшати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'То је Аллахов пропис који вам Он објављује. А ономе ко се буде Аллаха бојао, Он ће да покрије лоше поступке и још ће да му увећа награду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Њих оставите да станују тамо где и ви станујете, према својим могућностима, и не чините им тешкоће, зато да бисте на њих извршили притисак. Ако су трудне, сносите трошкове њиховог издржавања све док се не породе; а ако вам доје децу, онда им дајте накнаду и споразумите се међусобно на леп начин. А ако настану размирице, нека му онда друга доји дете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Нека имућан према своме богатству сноси трошак дојења, а онај који је у оскудици, нека издваја према томе колико му је дао Аллах. Аллах никог не задужује више него што му је дао; Аллах ће, сигурно, после тегобе, олакшање да подари.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'А колико ли је само било насеља која су се о заповеди свога Господара и Његових посланика оглушила?! Па смо са њима жестоко рачун свели и казнили их - а и казнићемо их - патњом ужасном!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Они су погубност својих поступака искусили, а пропаст је била - и биће - њихов крај.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Аллах је за њих припремио болну патњу; зато се бојте Аллаха, о ви који сте разумом обдарени, ви који верујете! Аллах вам је већ спустио Опомену,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'и послао Посланика, који вам Аллахове јасне речи казује, да би извео из тмина на светло оне који верују и добра дела чине. А онога који буде у Аллаха веровао и добро радио, увешће у рајске баште кроз које теку реке. У њима ће вечно, заувек да остану; најлепшу опскрбу Аллах му је припремио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Аллах је седам небеса створио, а исто толико је и земаља створио; Његова одредба до свих њих доспева да бисте ви знали да Аллах над свиме има моћ и да Аллах знањем Својим све обухвата!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'О Веровесниче, зашто себи забрањујеш оно што ти је Аллах дозволио - желећи задовољство својих супруга? А Аллах опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Аллах вам је прописао како да искупите своје заклетве; Аллах је ваш Господар; Он је Свезнајући и Мудри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'А кад Посланик једној својој супрузи тајно говор повери, па га она разгласи, а Аллах му то обзнани, он је упозна са нечим што је казала, а нешто прећути. Па кад је он о томе обавести, она упита: „Ко те је о томе обавестио?“ Он одговори: „Обавестио ме је Свезнајући, Онај Који у потпуности све зна.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'Ако се вас две покајете Аллаху, па, ви сте биле учиниле оно због чега је требало да се покајете. А ако се против њега удружите, па, Аллах је заштитник његов, и анђео Гаврило, и честити верници; на крају, и сви анђели ће му подршка бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Ако вас он разведе, његов Господар ће да му подари, уместо вас, боље супруге; муслиманке, вернице, покорне Аллаху, покајнице, побожне, које посте, и удаване и девице.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'О ви који верујете, себе и своје породице чувајте од Ватре којој су гориво људи и камење, о којој се брину анђели строги и снажни, који се ономе што им Аллах заповеди не опиру, и који оно што им се нареди извршавају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, '„О ви који нисте веровали, данас се не правдајте, бићете кажњени само за оно што сте радили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'О ви који верујете, покајте се чинећи Аллаху искрено покајање, како би вам ваш Господар ваше лоше поступке избрисао и да би вас у рајске баште, кроз које теку реке, увео, на Дан у којем Аллах неће да понизи Веровесника и оне који су заједно са њим веровали; њихово светло ће да иде испред њих, са њихове десне стране. „Господару наш“, говориће они, „учини потпуним наше светло и опрости нам. Ти, заиста, над свиме имаш моћ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'О Веровесниче, бори се против неверника и лицемера и буди строг према њима! Њихово пребивалиште биће Пакао, а ужасно је то крајње одредиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Аллах наводи као пример, оних који не верују, Нојеву жену и Лотову жену: биле су удате за Наше две честите слуге, па су их изневериле, и њих двојица им неће моћи ништа код Аллаха помоћи, и биће речено: „Улазите вас две у Ватру, са онима који у њу улазе!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'А Аллах наводи као пример, оних који верују, фараонову жену, кад је рекла: „Господару мој, сагради ми код Себе кућу у Рају и спаси ме од фараона и његових поступака, и избави ме од насилних људи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'И Марију, кћер Јоакимову, која је своју невиност сачувала, па смо у њу живот удахнули, и она је у речи свога Господара и Његове књиге поверовала и била је од оних који су покорни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'Узвишен и благословљен је Онај у Чијој је руци власт и Он над свиме има моћ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'Онај Који је створио смрт и живот да би искушао који ће од вас боља дела да има; Он је Силни, Опростилац греха,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'Онај који је седам небеса као слојеве, једне изнад других, створио - ти у ономе што Свемилосни ствара не видиш никаквог несклада, па поново погледај, видиш ли икакве пукотине!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Затим, поново више пута погледај, поглед ће да ти се врати клонуо и уморан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Ми смо најближе небо украсили сјајним светиљкама и учинили смо их за гађање ђавола, и припремили смо им патњу у Огњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'А онима који не верују у свога Господара, припада патња у Паклу. Ужасно је то боравиште!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Кад буду у њега бачени, чуће његовo грозно хукање, док кључа,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'готово да се од беса распадне. Кад год се која гомила баци у њега, стражари у њему ће да их упитају: „Зар није нико долазио да вас упозорава?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, '„Јесте, долазио нам је онај који нас је упозоравао,“ одговориће, „а ми смо порицали и говорили: ''Аллах није објавио ништа, ви сте у великој заблуди!''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'И рећи ће: „Да смо слушали или размишљали, не бисмо међу становницима Огња били!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'И они ће да признају своје грехе, па далеко били становници Огња!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Онима који се свога Господара боје и кад их нико не види - припада опрост и награда велика!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Говорили ви тихо или гласно - па, Он сигурно зна шта груди крију!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'А како и не би знао Онај Који ствара, Који зна и оно што је најситније, Онај Који у потпуности све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'Он вам је Земљу учинио погодном, па ходајте њеним пределима и храните се оним што Он даје, и Њему се све враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Јесте ли сигурни да Онај Који је на небесима неће у земљу да вас утера, кад она почне изненада да се тресе?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'Или сте сигурни да Онај Који је на небесима неће да пошаље на вас ветар са камењем?! Па, сазнаћете какво је Моје упозорење!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'А порицали су и они пре њих, па каква је била Моја осуда!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Зар они не виде птице изнад себе како лете раширених крила, а и скупљају их? Само их Свемилосни држи; Он, заиста, све добро види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'И, ко је тај који ће да буде ваша војска и да вам помогне, осим Свемилосног?! Неверници су само обманути!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'А, и ко је тај који ће да вас нахрани, ако Он храну Своју ускрати?! Али, они су устрајни у охолости и одбојности.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Да ли је боље упућен онај који иде погнут са лицем према земљи или онај који правим путем усправно иде?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'Реци: „Он вас је први пут створио и дао вам слух, вид и разум, па како само мало захваљујете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'Реци: „Он вас је по Земљи разасуо и пред Њим ћете да будете сакупљени.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'А они говоре: „Кад ће већ једном та претња, ако истину говорите?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'Реци: „Само Аллах зна! А ја сам само јасни упозоритељ.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Кад је изблиза угледају биће ојађена лица оних који нису веровали и биће речено: „Ево, ово је оно што сте пожуривали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'Реци: „Кажите ви мени: ако Аллах пошаље смрт мени и онима који су са мном, или ако нам се смилује, ко ће невернике од болне патње да заштити?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'Реци: „Он је Свемилосни, у Њега верујемо и на Њега се ослањамо, а ви ћете сигурно да сазнате ко је у очигледној заблуди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'Реци: „Шта мислите, ако ваше воде које пијете нестану, ко ће дати обилну текућу воду?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'Нун.[1] Тако Ми пера и онога што они пишу,', '[1] Види фусноту првог стиха у поглављу "Крава".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'ти због благодати свога Господара, ниси луд,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'ти ћеш, сигурно, да имаш непрестану награду.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'И, заиста, твој морал је величанствен', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'и ти ћеш да видиш, а и они ће да виде,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'ко је од вас заведен!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'Твој Господар најбоље зна ко је са пута Његовог скренуо и Он најбоље зна оне који су на Правом путу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Па, не покоравај се онима који поричу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'они би једва дочекали да ти попустиш, па би и они попустили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'и не слушај ниједног кривоклетника, презреног,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'онога који преноси туђе речи ради смутње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'који спречава добро, онога који скрнави прописану границу, грешника', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'суровог и, поред тога, по злу познатог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'само зато што има много имовине и синова,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'који говори, кад му се речи Наше казују: „То су само приче древних народа!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'На нос ћемо Ми њему да утиснемо белег!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Ми смо их ставили на искушење, као што смо власнике једне баште ставили на искушење кад су се заклели да ће сигурно рано ујутру да је оберу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'а нису рекли: „Ако Аллах да!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'И док су они спавали, њу од твога Господара задеси несрећа', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'и она освану опустошена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'А у зору они су једни друге дозивали:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, '„Пораните до своје њиве ако мислите да ја оберете!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'И они кренуше тихо разговарајући:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, '„Нека вам данас у њу никако ниједан сиромах не улази!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'И они поранише одлучни да ће моћи да је оберу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'а кад је угледаше, повикаше: „Ми смо залутали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'напротив - свега смо лишени!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'Најбољи између њих рече: „Нисам ли вам ја говорио да треба Аллаха да славите?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, '„Слављен и Узвишен је наш Господар!“, рекоше, „ми смо, уистину, били неправедни!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'И онда почеше да критикују једни друге.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, '„Тешко нама“, говорили су, „ми смо, заиста, били охоли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Наш Господар може да нам подари бољу од ње, само од Господара нашег ми се надамо накнади!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'Ето, таква је била казна, а на Будућем свету је казна још већа, кад би само они знали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'За оне који се буду бојали Аллаха биће, заиста, баште уживања код њиховог Господара,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'зар ћемо муслимане са неверницима да изједначимо?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Шта вам је, како расуђујете?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Или, можда имате Књигу, па у њој читате', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'да ћете да имате оно што ви изаберете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Или, можда имате Наше заклетве које ће до Судњег дана да вреде да ће бити онако како ви одредите?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Упитај их ко је од њих јамац за то.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'Или, имају ли они саучеснике?! Па нека саучеснике своје доведу, ако говоре истину!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'На Дан када се потколеница открије и када буду позвани да падну лицем на тло, па не буду могли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Погледа оборених, прекриће их понижење! А били су позвани да падају лицем на тло док су били здрави.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Па, остави Мене и оне који овај Кур''ан поричу, Ми ћемо постепено, одакле се и не надају, патњи да их приближавамо', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'и времена ћу да им дајем, а обмана Моја је, заиста, чврста!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Или ти тражиш од њих награду, па су наметом оптерећени?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Или је код њих знање о невидљивом свету, па они записују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Ти стрпљиво чекај пресуду свога Господара и не буди као Јона у утроби кита, кад огорчен завапи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'и да га није стигла Аллахова милост, на пусто место би био избачен и прекор би заслужио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'али, његов Господар га је одабрао и учинио га једним од оних који су добри.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Готово да те неверници својим погледима оборе док Кур''ан слушају, говорећи: „Он је, уистину, луд!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'А Кур’ан је, заиста, свим световима опомена!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'Час обистињења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'шта је Час обистињења?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'И шта ти знаш шта је Час обистињења?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'Семуд и Ад су порицали застрашујући Судњи дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'па је Семуд уништен страховитим повиком,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'а Ад је уништен леденим ветром, силовитим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Ветру је Он власт над њима препустио седам ноћи и осам дана узастопних, па си у њима видео људе поваљане као шупља палмина дебла,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'и видиш ли да је ико од њих остао?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'А фараон, и они пре њега, и преврнута насеља су чинили грехе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'и били су непослушни посланику свога Господара, па их је Он казнио жестоком казном.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Ми смо вас, кад је вода све преплавила, носили у лађи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'да вам је учинимо поуком и да то од заборава сачува уво које памти.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'А кад једном у рог буде дувнуто,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'па Земља и брда буду дигнута и од једног удара здробљена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'тог дана ће Догађај страховити да се догоди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'и небо ће да се раздвоји - тада ће да буде лабаво.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'И анђели ће на његовим крајевима да стоје, а Престо твога Господара ће тог дана изнад њих да држе осморица.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'Тог дана бићете изложени, и ниједна ваша тајна неће скривена да остане.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'Онај коме се његова књига у његову десну руку да, рећи ће: „Ево вам, читајте моју књигу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'ја сам заиста и мислио да ћу свој рачун да полажем.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'И он ће живети задовољним животом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'у узвишеном Рају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'чији ће плодови да буду надохват руке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, '„Једите и пијте радосни, за оно што сте у данима минулим зарадили!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'А онај коме се књига да у његову леву руку, рећи ће: „Камо среће да ми моја књига ни дата није', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'и да ни сазнао нисам за свој обрачун!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Камо среће да ме је смрт докрајчила,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'богатство моје ми није од користи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'снаге моје нема више!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, '„Зграбите га и окујте у окове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'затим га само у ватри пржите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'а онда га у ланце седамдесет лаката дуге вежите;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'заиста, он у Аллаха Великог није веровао', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'и да се нахрани сиромах није подстицао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'зато он овде данас нема присног пријатеља', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'ни другог јела осим смрдљиве капљевине', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'коју ће само несретни да једу.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'А Ја се кунем оним што видите', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'и оним што не видите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'Кур''ан је, заиста, говор објављен племенитом Посланику,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'а није говор никаквог песника - како ви мало верујете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'И нису речи никаквог пророка - како ви мало размишљате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'Објава је он од Господара светова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'А да је он о Нама износио којекакве речи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'Ми бисмо га десницом дохватили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'а онда му жилу куцавицу пресекли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'и нико између вас не би могао од тога да га одбрани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Заиста је он богобојазнима опомена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'а Ми сигурно знамо да ће међу вама да буде порицатеља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'И он ће, заиста, бити разлог туге неверницима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'а он је, заиста, сама Истина.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Зато ти слави и величај име свога Господара, Величанственога!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'Неко је затражио да се казна одмах догоди', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'неверницима, а њу нико не може да спречи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'од Аллаха, Господара узвишености и степена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Њему се пењу анђели и анђео Гаврило у дану који педесет хиљада година траје.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Па ти лепо буди стрпљив.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Они, заиста, мисле да је Судњи дан далеко - да се неће догодити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'А ми знамо да је близу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'На дан када небо буде као талог од уља,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'а брда као вуна рашчупана,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'када ближњи неће ближњег ништа да пита,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'иако ће једни друге да виде. Неверник ће желети да се од патње тог дана искупи својим синовима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'и својом супругом, и својим братом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'и својом породицом која га штити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'и свима осталима на Земљи, само да се спаси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'Никад! Она је, заиста, жестока буктиња', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'која ће коже да гули,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'зваће онога ко се окретао од истине и избегавао је', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'и гомилао иметак и скривао га.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Човек је, уистину, створење лакомислено:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'када га снађе невоља - очајан је,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'а када га задеси добро, он га ускраћује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'осим оних који обављају молитву', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'који су у својим молитвама устрајни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'и они у чијим имовинама има одређени део за милостињу', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'за оног који проси и за онога који је у потреби али не проси,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'и они који у Судњи дан верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'и они који од казне Аллахове страхују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'а од казне свога Господара нико није сигуран,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'и они који своја стидна места чувају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'осим од својих супруга или оних које су у њиховом власништву - они, заиста, прекор не заслужују.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'А они који и поред тога нешто траже, они заиста прелазе границу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'и они који чувају преузете обавезе и уговоре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'и они који иза својих сведочења чврсто стоје,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'и они који на своје молитве пазе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'они ће у рајским баштама да буду почашћени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Па шта је онима који не верују а око тебе се журе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, 'здесна и слева, у гомилама?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Зар се сваки од њих нада да ће у Рај уживања ући?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'Напротив! Ми смо их створили од онога што они знају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'И Ја се кунем Господаром истока и запада да можемо', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'бољим од њих да их заменимо и нико у томе не може да Нас спречи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Зато их остави нека се у беспослице удубљују и забављају док Дан којим им се прети не дочекају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'Дан у коме ће журно, као да идолима хрле, из гробова да изађу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'оборених погледа и понижењем опхрвани. То ће да буде Дан којим им се претило!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'Ми смо послали Ноја његовом народу: „Упозоравај свој народ пре него што га стигне болна патња!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, '„О народе мој“, говорио је он, „ја сам вам заиста јасни опомињач!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Аллаха обожавајте и бојте Га се, а мени будите послушни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'Он ће ваше грехе да вам опрости и у животу до одређеног часа да вас остави, а када дође Аллахов час, заиста неће, нека знате, да се одгоди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'Он рече: „Господару мој, ја сам свој народ и ноћу и дању, заиста, позивао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'али га је позивање моје још више удаљило.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'И кад год сам их позивао да им опростиш, своје су прсте у уши стављали и својим хаљинама су се покривали - били су упорни и претерано охоли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Затим сам их ја отворено позивао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'а онда сам им јавно објављивао и у поверењу им шапутао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'и говорио: ''Тражите од свога Господара опрост. Он, заиста, много прашта;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Он ће да вам шаље обилату кишу', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'и много имања и синова да вам подари. И даће вам баште, а и реке ће да вам подари.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Шта вам је, па се Аллахове величине не бојите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'а Он вас постепено ствара?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Зар не видите како је Аллах седам небеса, једно изнад другог, створио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'и на њима Месец светлим дао, а Сунце светиљком учинио?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Аллах вас од земље ствара,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'затим вас у њу враћа и из ње ће сигурно да вас изведе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Аллах вам је Земљу учинио равном,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'да бисте по њој ходали пространим путевима.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Ноје рече: „Господару мој, они ме не слушају и поводе се за онима чија богатства и деца само њихову пропаст увећавају', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'и сплетке велике спремају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'И говоре: ''Никако своја божанства не остављајте, и никако, ни Веда, ни Сува''а, а ни Јегуса, ни Јеука, ни Несра не напуштајте!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'а већ су многе довели у заблуду, па Ти неправеднима само заблуду повећај!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'И они су због својих греха потопљени и у Ватру ће да буду уведени и никога себи, мимо Аллаха, као помагача неће наћи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'И Ноје рече: „Господару мој, не остави на Земљи ниједног неверника,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'јер ако их оставиш, они ће Твоје слуге у заблуду да заводе и само ће грешника и неверника да рађају!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'Господару мој, опрости мени, и родитељима мојим, и ономе који као верник у дом мој уђе, и верницима и верницама, а неверницима само пропаст повећај!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'Реци: „Мени је објављено да је неколико духова прислушкивало и казало: ''Ми смо, заиста, Кур''ан дивни слушали;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'који на оно што је исправно упућује - и ми смо у њега поверовали и више никога нећемо поред нашег Господара обожавати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'а Он - узвишена је моћ нашег Господара! - Није узео Себи ни супругу ни дете!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Један наш малоумник је говорио велику лаж о Аллаху,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'а ми смо мислили да ни људи ни духови о Аллаху лажи не говоре;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'и било је људи који су заштиту од духова тражили, па су им још више страх повећали;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'и они мисле, као што и ви мислите, да Аллах никога неће да оживи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'И ми смо на небу увидели и утврдили да је моћних чувара и пламтећих светлица пуно;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'и ми бисмо по њему заузимали разне положаје како бисмо нешто чули, али ће онај, ко сада прислушкује, на пламтећу светлицу која вреба да наиђе;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'и ми не знамо да ли се онима на Земљи жели зло или им њихов Господар жели добро.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'А међу нама има и добрих и оних који то нису, има нас врста различитих;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'и ми знамо да не можемо да се супротставимо Аллаху на Земљи, нити да Му умакнемо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'И ми смо, чим смо Кур''ан чули, у њега поверовали; а ко верује у свога Господара, не треба да се боји ни умањивања добрих, ни додавања лоших дела;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'и има нас муслимана, а има нас и залуталих, они који прихвате ислам одабрали су оно што је исправно,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'а они који су скренули, биће гориво у Паклу.''“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'А када би устрајали на путу истине, Ми бисмо им дали обилну воду,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'да бисмо их тиме ставили на искушење; а оног ко се окрене од Опомене свога Господара - Он ће у тешку патњу да уведе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Џамије су ради Аллаха, и не молите се, поред Аллаха, никоме!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'А када је Аллахов слуга устао да Му се помоли, они су се скоро сви на њега у гомилама окомили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'Реци: „Ја се само своме Господару молим и никога поред Њега не обожавам.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'Реци: „Ја нисам у стању да од вас какву штету отклоним нити неком од вас неку корист да прибавим.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'Реци: „Мене нико од Аллаха не може да заштити; само код Њега могу уточиште да нађем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'и само могу да доставим оно што је од Аллаха и Његове поруке.“ А онога који Аллаху и Његовом Посланику не буде послушан - сигурно чека ватра Пакла; у њој ће вечно, заувек да остане.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'А када они виде оно чиме им се прети, сазнаће ко је слабији и малобројнији.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'Реци: „Ја не знам да ли ће ускоро да буде оно чиме вам се прети, или је мој Господар одредио да ће то после дуго времена бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, 'Познавалац је Он онога што је недокучиво чулима, и Он то не открива никоме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'осим ономе за кога је задовољан да посланик буде; Он, заиста, и испред њега и иза њега поставља оне који ће да га чувају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'да би знао да су доставили поруке свога Господара; а обухватио је оно што је код њих и заисте све побројао.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'О ти умотани!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'Пробдиј ноћ, осим малог дела;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'половину њену и мало мање од ње;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'или мало више од ње, и учи Кур''ан разговетно.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Ми ћемо, заиста, да ти објављујемо тежак говор.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Устајање ноћу, заиста, јаче делује и изговор је разборитији,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'а ти дању, заиста, имаш много времена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'И спомињи име свога Господара и Њему у потпуности буди одан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, 'Он је Господар истока и запада, нема истинског бога осим Њега, па само Њега узми за заштитника!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'И издржи оно што они говоре и избегавај их на леп начин,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'а препусти Мени оне који те у лаж утерују, који раскошно живе, и дај им мало времена;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'биће код Нас, заиста, окова и огња,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'и јела које у грлу застаје, и несносне патње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'на Дан када се Земља и планине затресу и планине меке пешчане дине постану.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Ми смо вам заиста послали Посланика да би сведочио против вас, исто онако као што смо и фараону послали посланика,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'али фараон није послушао посланика, па смо га тешком казном казнили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Како ћете, ако останете неверници, да се сачувате Дана који ће децу да учини седом?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'Небо ће тада да се расцепи, и обећање Његово биће испуњено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Ово је, заиста, поука; и ко хоће, пут ка своме Господару прихватиће!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'Господар твој сигурно зна да ти клањајући проводиш мање од две трећине ноћи, њену половину, или њену трећину, а и група оних који су уз тебе. Аллах одређује дужину ноћи и дана, Он зна да ви то нећете моћи да издржите па вам прашта, а ви из Кур''ана учите оно што знате. Он зна да ће међу вама да буде болесних, и оних који ће по свету да путују, и Аллахове благодати да траже, и оних који ће на Аллаховом путу да се боре. Па учите из њега оно што је лако, и обављајте молитву, и дајте милостињу, и Аллаху леп зајам дајте! А добро које за себе унапред припремите наћи ћете код Аллаха да је још боље и са наградом већом. И молите Аллаха да вам опрости. Аллах, уистину, опрашта грехе и милостив је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'О ти покривени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Устани и упозоравај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'и свога Господара величај!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'И одећу своју очисти!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'И кипова се клони!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'И не даруј нешто надајући се да ће да ти буде узвраћено више!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'И трпи ради свога Господара!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'А када у рог буде дувнуто,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'то ће тада да буде тежак дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'неверницима нимало лак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Остави Мене и онога кога сам Ја самог створио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'и богатство му огромно дао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'и синове који су са њим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'и живот му угодним учинио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'и жуди да му још увећам!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Никако! Он, заиста, пркоси Нашим речима и доказима', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'а оптеретићу га Ја тешком казном,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'јер је смишљао и рачунао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'и, проклет био, како је прорачунао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'и још једном, проклет био, како је прорачунао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Затим је сагледао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'па се онда смркнуо и намрштио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'и потом се окренуо и узохолио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'и рекао: „Ово није ништа друго до враџбина која се наслеђује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'ово су само човекове речи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'У Секар ћу ја њега да бацим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'А знаш ли ти шта је Секар?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'Ништа он неће да поштеди,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'коже ће да пржи, па црним да учини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'над њим су деветнаесторица.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'Ми смо чуварима Ватре само анђеле поставили и одредили смо њихов број као искушење онима који не верују - да се увере они којима је дата Књига, и да се онима који верују повећа веровање, и да они којима је дата Књига и они који су верници не сумњају, и да они чија су срца болесна и они који су неверници кажу: „Шта је Аллах хтео овим примером?“ Тако Аллах коме хоће даје да је у заблуди, и на Прави пут упућује кога хоће. А војске твога Господара зна само Он. А Ватра је људима само опомена.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'И тако Ми Месеца', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'и ноћи када нестане,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'и зоре када сване,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'то је, заиста, једна од највећих невоља,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'људима је опомена;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'ономе између вас који хоће напред да иде или заостане!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Свака душа ће за своја дела да одговара,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'осим оних на десној страни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'они ће се у рајским баштама распитивати', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'о неверницима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, '„Шта вас је довело у Секар?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, '„Нисмо“, рећи ће, „били од оних који су молитву обављали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'нити смо хранили сиромашне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'И у беспослице смо се упуштали са беспослењацима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'и Судњи дан смо порицали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'све док нам смрт није дошла.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Њима неће да користи посредовање посредника.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Па зашто се они окрећу од опомене?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'Као да су дивљи магарци преплашени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'који беже од лавова!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Напротив, сваки би човек међу њима хтео да му се дају раширени листови.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Никада, јер они се оног света не плаше!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'Уистину! Кур''ан је опомена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'и ко хоће, на уму ће да га има,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'а на уму ће да га има само ако Аллах буде хтео, Он је једини достојан да Га се боје и достојан је да опрашта.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Кунем се Судњим даном', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'и кунем се душом која себе кори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Зар човек мисли да његове кости нећемо да сакупимо?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Хоћемо, Ми можемо да вратимо јагодице прста његових поново.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Али, човек хоће да негира оно што је пред њим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'па пита: “Када ће Судњи дан бити?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'Када се поглед збуни', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'и Месец помрачи', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'и Сунце и Месец смотају, па сјај изгубе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'тог дана човек ће да повиче: „Где да се бежи?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'Не, нема спаса!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'Тог дана твоме је Господару повратак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'Тог дана човек ће о ономе што је припремио, а што је пропустио, да буде обавештен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Штавише, човек себе добро зна - сам ће против себе сведочити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'макар износио своја оправдања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'Не изговарај Кур''ан језиком својим да би га што пре запамтио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Ми смо дужни да га сакупимо да би га ти читао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'А када га читамо, ти прати читање његово,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'а после, Ми смо дужни да га објаснимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Али, напротив, ви овај пролазни свет волите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'а онај други свет запостављате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'Тог дана нека лица ће да буду блистава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'у Господара свога ће да гледају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Тог дана нека лица ће бити смркнута,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'уверена да ће их снаћи велика несрећа!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'Пази, када душа допре до кључних костију', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'и викне се: „ Има ли лекара да га излечи?!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'И он се увери да је то час смрти', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'и нога се уз ногу савије.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'Тог дана ће твоме Господару бити приведен.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'Није веровао и није молитву обављао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'него је порицао и окретао се,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'а онда је својим охоло одлазио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'Тешко теби! Тешко теби!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'и још једном: Тешко теби! Тешко теби!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Зар човек мисли да ће сам себи препуштен да буде, да неће да одговара?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Зар није био кап семена која се убаци,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'затим заквачак коме Он онда размер одреди и складним му лик учини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'и од њега две врсте, мушкарца и жену, створи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'и зар Тај није способан мртве да оживи?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Зар је то давно било кад човек није био помена вредан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Ми човека од смесе семена стварамо да бисмо га ставили на искушење и чинимо да он чује и види.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'Ми му на Прави пут указујемо, па или је захвалан или незахвалан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Ми смо за невернике окове и ланце и огањ разбуктали припремили.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'Заиста ће честити из пехара камфором зачињено пиће да пију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, 'са извора из ког ће само Аллахове слуге да пију, и који ће куда желе без муке да разводе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Они су завет испунили и плашили се дана чија ће коб да буде свуда присутна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'и храну су давали, мада су је и сами желели, сиромаху, сирочету и заробљенику.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, '„Ми вас само због Аллаховог Лица хранимо, од вас ни признања ни захвалности не тражимо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Ми се бојимо нашег Господара, на Дан када ће лица да буду смркнута и намргођена.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Њих ће тог дана Аллах да сачува страхоте и дароваће им блиставост и радост,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'за оно што су трпели наградиће их Рајом и свилом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Наслоњени на диване, они у њему ни Сунце ни велику хладноћу неће да осете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'у близини ће да им буде његова хладовина, а плодови његови надохват руке ће да им стају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'Биће услуживани из сребрених посуда и чаша које ће прозирне бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Прозирне од сребра, чија ће се мера по њиховим жељама одређивати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'У њему ће из чаше пити пиће зачињено ђумбиром,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, 'са извора у Рају, који се зове Селсебил.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Служиће их вечно млада послуга; да их видиш, помислио би да су просути бисер.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'И куд год погледаш, видећеш благостање и пространо царство.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'На њима биће одела од танке зелене свиле и од броката, накићени наруквицама од сребра, и даће им њихов Господар да пију чисто пиће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, '„То вам је награда; ваш труд је био хвале достојан!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'Ми ти објављујемо Кур''ан у етапама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Зато, издржи до одлуке твога Господара, и не слушај ни њиховог грешника ни неверника!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'И спомињи име свога Господара ујутру и предвече,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'и у једном делу ноћи Њему падај ничице и дуго Га ноћу величај.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Заиста они живот пролазни воле, а ништа их се не тиче Дан тегобни који их чека.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Ми их чврстог тела стварамо и зглобове им повезујемо, а ако хоћемо, заменићемо их њима сличним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Ово је опомена, па ко хоће држаће се пута који његовом Господару води,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'а ви ћете хтети само оно што Аллах хоће. Аллах, уистину, све зна и мудар је.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'Он кога хоће уводи у милост Своју, а неверницима је припремио велику патњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'Тако ми оних који се шаљу један за другим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'и оних што жестоко дувају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'и оних који распростиру,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'и оних што раздвајају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'и оних што достављају Опомену,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'као оправдање или упозорење,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'сигурно ће се остварити оно чиме вам се прети!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Када звезде изгубе сјај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'и када се отвори небо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'и када се планине здробе у прах,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'и када се посланици окупе у одређено време.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'До којег је то дана одложено?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'До Судњег дана!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'А знаш ли ти шта је Судњи дан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Тешко тога дана порицатељима истине!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Зар Ми нисмо уништили древне народе', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'и после њих и оне који су за њима долазили?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Тако ћемо са свим преступницима да поступимо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Зар вас од незнатне текућине не стварамо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'коју на поуздано место стављамо', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'до одређенога рока?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Тако смо одредили, а дивно ли то Ми чинимо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Зар Ми нисмо учинили Земљу сабиралиштем', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'живих и мртвих', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'и на њој смо поставили непомичне високе планине, и зар вам Ми не дајемо да слатку воду пијете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'А тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, 'Идите према ономе што сте сматрали неистином.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Идите према диму у три прама раздвојеном,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'који хлада неће да даје и који од пламена неће да заклања.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'Он ће као куле искре да баца', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'као да су риђе камиле.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Дан је то у коме они неће ни да проговоре', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'и правдање неће да им буде дозвољено.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'То је Судњи дан, и вас и древне народе ћемо да сакупимо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'па ако имате какву сплетку, изведите је против Мене!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Тешко тога дана порицатељима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'Они који су се бојали Аллаха биће међу изворима, у густим баштама.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'И међу воћем које буду желели.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, '„Једите и пијте, пријатно нек вам је, због оног што сте радили.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Тако ћемо Ми оне који чине добра дела да наградимо.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, '„Једите и наслађујте се, али на кратко! - Ви сте, заиста, злочинци!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'А кад им се каже: „Молитву обављајте!“ Они молитву не обављају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Тешко тога дана порицатељима!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Па у који ће говор, ако не у Кур''ан, да верују?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, 'О чему они једни друге питају?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, 'О великој вести - Судњем дану', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'о којој се они разилазе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'А није тако, сазнаће они сигурно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'И поново - није тако, сазнаће они сигурно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Зар Земљу колевком нисмо учинили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'и планине као клинове', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'и вас створили као парове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'и ваш сан учинили смирајем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'и ноћ учинили прекривачем,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'и дан одредили за привређивање,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'и изнад вас седам чврстих небеса саздали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'и поставили пламтећу светиљку?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Ми из кишних облака спуштамо воду обилну', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'да њоме изведемо жито и биље,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'и густе баште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Судњи дан је, заиста, већ одређен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'Дан када ће у рог да буде дувнуто, па ћете ви, све група по група, да долазите,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'и небо ће да буде отворено и много ће капија да има,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'и планине ће да буду покренуте и привиђење ће да постане.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Пакао ће, заиста, да буде заседа,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'неправедницима место повратка,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'у коме ће да остану заувек,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'у њему никакве свежине неће да осете, ни пића да окусе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'осим вреле воде и смрдљиве капљевине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'казне прикладне.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Заиста се они нису надали полагању рачуна', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'и потпуно лажним сматрали су Наше речи и доказе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'а Ми смо све побројали и записали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, '„Па зато кушајте, а Ми ћемо патњу само да вам повећавамо!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'Заиста богобојазнима припада место спаса и уживања:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'баште и виногради,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'и девојке младе, истих година,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'и пехари пуни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Тамо неће да слушају празне беседе и лажи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'то им је награда од твога Господара, довољан дар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'Од Господара небеса и Земље и онога што је између њих, Свемилоснога, коме неће моћи зборити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'На Дан када анђео Гаврило и сви анђели буду поређани у редове, неће проговорити. Говориће само онај коме Свемилосни дозволи, а истину ће рећи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'То је дан истине, па ко хоће, кренуће путем повратка своме Господару.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Ми вас, заиста, упозоравамо на блиску патњу, на Дан у коме ће човек дела својих руку да види, а неверник да узвикне: „Камо среће да сам у прашину претворен!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'Тако Ми анђела који душе чупају грубо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'и анђела који душе узимају нежно,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'и анђела који се крећући плове', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'и оних који једни друге претичу', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'и оних који извршавају наредбе.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'На Дан када ће се Земља потрести,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'за којим ће доћи следећи потрес,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'Људска срца ће тог дана бити престрављена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'а погледи њихови уплашени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Они говоре: „Зар ћемо, заиста, из гробова да будемо проживљени?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Зар кад постанемо труле кости?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'И још кажу: „То је, онда, штетан повратак.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'А биће то само једна наредба,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'а они већ на површини Земље.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Да ли ти је дошла вест о Мојсију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'кад га је његов Господар позвао у благословљеној, чистој долини Тува?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, 'Иди код фараона, он се, заиста, осилио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'и реци: „Да ли би ти да се очистиш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'да те упутим твоме Господару, па да Га се бојиш?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'И онда му је показао највеће чудо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'али је он порекао и није послушао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'већ се окренуо и пожурио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'и сабрао и повикао:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'И рече: „Ја сам господар ваш највећи!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Па га је Аллах казнио као пример за Будући а и овај свет.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'У томе има поука за свакога који се буде Аллаха бојао!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'А шта је теже: вас или небо створити? Он га је саздао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'његов свод високо дигао и усавршио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'његове ноћи учинио мрачним, а дане светлим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'После тога је Земљу распростро,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'из ње је воду и пашњаке извео,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'и планине непомичним учинио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'на уживање вама и вашој стоци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'А кад дође највећа невоља - Судњи дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'тада ће човек да се присети онога што је радио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'и Огањ ће свакоме ко види да буде указан.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'Па, оном ко се охолио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'и живот на овом свету више волео,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Огањ ће сигурно да буде пребивалиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'А оном ко је од стајања пред својим Господаром стрепео и душу од прохтева уздржао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'Рај ће сигурно да буде боравиште.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'Питају те о Судњем часу: „Када ће да се догоди?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Шта ти о његовом спомену знаш!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'Знање о њему је само код твога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Твоје упозорење на њега прихвата само онај који Га се боји,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'а њима ће да се учини, тог дана, када га доживе, да су само једно послеподне или једно јутро на овом свету остали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'Намрштио се и окренуо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'зато што му је слепи човек пришао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'А шта ти знаш, можда он жели да се греха очисти,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'или опомене, па да му опомена користи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'А што се тиче онога који је богат,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'ти се њему окрећеш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'а ти ниси одговоран ако се он не очисти греха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'А што се тиче онога који ти је дошао журећи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'и боји се,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'ти њега занемарујеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Не чини тако! Заиста је ово опомена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'па ко хоће, имаће Га на уму,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'на листовима је цењеним', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'узвишеним, чистим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'у рукама анђела', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'часних, честитих.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Проклет нека је човек! Колико је само његово порицање!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'Од чега га Он ствара?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Од капи семена га ствара, па му одређује.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'И Прави пут му олакшао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'затим му живот одузме и учини да буде сахрањен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'и после ће, када Он буде хтео, да га проживи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'Не, још није извршио оно што је Он наредио!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Нека човек погледа у своју храну.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'Ми обилну кишу проливамо,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'затим земљу пукотинама цепамо', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'и чинимо да из ње израста жито,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'и грожђе и поврће,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'и маслине и палме,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'и густе баште,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'и воће и траве', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'на корист вама и вашој стоци.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'А кад дође снажан глас,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'на Дан када ће човек од свога брата да побегне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'и од своје мајке, и од свога оца,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'и од своје супруге и својих синова,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'тог Дана сваки човек ће само о себи бринути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'нека лица тог Дана биће блистава,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'насмејана, радосна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'а неким лицима тог Дана биће прашина,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'тама ће их прекривати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'то ће, заиста, да буду неверници, развратници.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Када Сунце буде скупљено и изгуби сјај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'и када раштркане звезде попадају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'и када планине буду покренуте и смрвљене', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'и када стеоне камиле буду остављене', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'и када дивље животиње буду сабране,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'и када мора буду распаљена', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'и када душе буду спарене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'и када девојчица која је жива закопана буде упитана', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'због којег је греха убијена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'и када листови буду раширени,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'и када небо буде уклоњено,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'и када Огањ буде разбуктан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'и када Рај буде приближен,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'свако ће да сазна оно што је припремио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'И кунем се оним што се скрива,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'што се креће и склања,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'и ноћи кад долази,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'и зором кад дише,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Кур''ан је, заиста, казивање племенитог анђела', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'моћног, код Господара Престола, цењеног.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'Коме се други покоравају, поверљивог!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'А ваш друг Мухаммед није луд,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'он је анђела на обзорју јасном видео,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'и, када је у питању оно што је недокучиво чулима, он није шкрт,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'и Кур''ан није говор проклетог ђавола,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'па куда онда идете?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'Он је само опомена световима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'ономе од вас који жели да је на правом путу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'а ви не можете ништа хтети ако то Аллах, Господар светова, неће!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Када се небо расцепи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'и када раштркане звезде попадају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'и када мора буду прокључала па се прелију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'и када гробови буду преврнути,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, 'свако ће да сазна шта је припремио, а шта пропустио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'О човече, шта те је обмануло у вези са твојим Господаром Племенитим!?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'Који те је створио, па учинио да си складан и да си усправан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'и какав је хтео лик ти дао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'Напротив! Ви још и Судњи дан поричете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'а над вама бдију анђели чувари,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'племенити писари', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'који знају и записују оно што радите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Честити ће сигурно у Рај,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'а развратници сигурно у Пакао.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'На Судњем дану у њему ће да горе', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'и никад из њега изаћи неће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'А шта ти знаш шта је Судњи дан?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'И још једном: шта знаш шта је Судњи дан?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'Дан када нико никоме неће моћи нимало да помогне, тог Дана власт ће једино Аллах да има.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Тешко онима који закидају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'који пуну меру узимају кад од других купују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'а кад другима мере на литар или на кантар закидају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Зар не мисле такви да ће да буду оживљени', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'на велики Дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'на Дан када ће људи Господару светова да се дигну?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'Уистину! Записано је развратницима да су у Сиџџину,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'а знаш ли ти шта је Сиџџин?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'Књига је исписана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Тешко тога дана порицатељима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'који су порицали Судњи дан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'а њега не пориче осим сваки преступник, грешник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'који је, када су му Наше речи и докази казивани, говорио: „Измишљотине древних народа!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'Не, напротив! Оно што су радили је прекрило њихова срца.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'Напротив! Заиста ће они тог дана да буду спречени да виде свога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Затим ће сигурно у Пакао да уђу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'па ће им бити речено: „То је оно што сте порицали!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'Уистину! Записано је честитима да су у Иллијјуну,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'а знаш ли ти шта је Иллијјун?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'Књига је исписана!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Уз њу су присутни они који су блиски.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Честити ће, заиста, уживати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'са дивана прекривених да гледају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'на лицима њиховим препознаћеш озареност ужитком,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'пићем запечаћеним биће напајани,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'на чијем крају мошус ће да буде, и нека се за то такмиче они који хоће да се такмиче!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'А мешавина му је из извора Тесним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, 'врело из којег ће они блиски да пију.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Заиста су неверници исмејавали оне који верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'и када су поред њих пролазили, једни другима су намигивали.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'А кад су се враћали својим породицама, враћали су се шале збијајући.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'А кад би их видели, говорили би: „Ови су, заиста, у заблуди“,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'а они нису послати да их чувају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'Тог дана ће они који су веровали неверницима да се смеју,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, 'са дивана ће да гледају.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, 'Зар ће неверници бити другачије кажњени него према ономе како су поступали!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Кад се небо расцепи', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'и послуша свога Господара, а оно је обавезно да то учини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'И када Земља буде растегнута', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'и избаци оно што је у њој, и потпуно се испразни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'и послуша свога Господара, а она је обавезна да то учини.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'О човече, ти се трудиш идући своме Господару, па ћеш свој труд да нађеш.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'Онај коме буде његова књига у његову десну руку дата,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'Лак ће обрачун полагати', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'и својима ће радостан да се врати;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'а онај коме буде његова књига иза његових леђа дата,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'пропаст ће да призива,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'и у Огњу ће да гори.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Заиста је он са својом породицом био радостан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'и мислио је да се никада неће Аллаху вратити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Напротив! Заиста његов Господар о њему све зна!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Па кунем се вечерњим руменилом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'и ноћи, и оним што она сакупља,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'и Месецом пуним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'ви ћете сигурно из стања у стање да прелазите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Па шта им је па не верују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'и кад им се Кур''ан учи на тло лицем не падају?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Напротив, они који не верују поричу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'а Аллах најбоље зна шта они у себи крију,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'зато им наговести болну патњу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Осим онима који буду веровали и добра дела чинили, таквима припада непрекидна награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'Тако ми неба са великим звездама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'и Дана већ обећаног,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'и сведока и посведоченог,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'проклети били они који су ровове ископали', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'и ватру са горивом,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'када су око ње седели', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'и били сведоци онога што су верницима радили!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'А светили су им се само зато што су у Аллаха, Силнога и Хваљенога, веровали,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'Чија је власт и на небесима и на Земљи, а Аллах је свему сведок.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Заиста онима који су мучили вернике и вернице, а затим се нису покајали, припада кажњавање у Паклу, и припада им кажњавање у Огњу.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'Заиста онима који су веровали и радили добра дела припадају рајске баште кроз које теку реке, а то је велики успех.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Заиста је освета твога Господара жестока!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'Он, заиста, ни из чега ствара, и поново ће то да учини;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'Он је Опроститељ греха, Онај који пуно воли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'Господар Престола, Величанствени.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Он ради шта хоће.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Да ли је до тебе допрла вест о војскама,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'о фараону и Семуду?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Међутим, они који не верују стално поричу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'а Аллах је иза њих, окружује их.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Напротив! Ово је величанствени Кур''ан', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'на помно чуваној Плочи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'Тако ми неба и звезде која се појављује ноћу!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'А знаш ли ти шта је то ноћни посетилац?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, 'Продирућа звезда!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Нема човека а да над њим није анђео чувар.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Па нека човек погледа од чега је створен!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'Створен је од течности која избија у млазу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'која између кичме и груди излази,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'и Он је, заиста, у стању поновно да га створи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'на дан када тајне буду откривене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'када човек ни снаге ни помагача неће да има.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'И тако ми неба пуног кише која се враћа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'и Земље пуне распукнућа,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Кур''ан је, заиста, говор који раставља истину од неистине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'није никаква лакрдија.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Они, заиста, праве сплетке,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'а Ја им узвраћам на сплетке,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'зато неверницима дај још времена, остави их још који тренутак.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Слави и узвисуј име свога Господара, Свевишњег', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Који све ствара и чини складним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'и Који одређује, па упућује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'и Који чини да изникне растиње,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'а потом чини да постане суво, потамнело,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'Ми ћемо да те научимо да учиш па ништа нећеш да заборавиш,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'осим онога што Аллах хоће. Он, заиста, зна и оно што на јаву износите и оно што кријете.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'И Ми ћемо ти у свему олакшати;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'па ти опомињи док опомена буде користила,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'а опоменуће се онај који се боји Аллаха,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'а избегаваће је онај најгори,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'који ће у великој ватри да гори,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'па у њој неће ни да умире ни да живи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Успео је онај који се греха очисти', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'и слави име свога Господара па молитву обави!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Међутим, ви више волите пролазан живот,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'а Будући свет је бољи и вечан је,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Ово се, заиста, налази у пријашњим листовима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'листовима Аврамовим и Мојсијевим.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Да ли је дошла до тебе вест о Дану који ће све прекрити?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'Нека лица ће тог Дана бити потиштена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'преморена, напаћена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'гореће у ужареној ватри,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'напајана са прокључалог извора,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'када другог јела осим трња неће да има,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'које неће ни да угоји ни глад да утоли.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'Нека лица тог Дана биће радосна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'својим трудом задовољна,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'у узвишеном Рају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'у коме неће да слушају празан говор!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'У њему су извори воде које теку,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'у њему су уздигнути дивани,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'и постављени пехари,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'и поређани јастуци', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'и раширени ћилими.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Па, зашто они не погледају камилу како је створена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'и небо како је уздигнуто,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'и планине како су постављене,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'и Земљу како је прострта?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Па ти опомињи, јер ти и јеси само опомињач,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'ти ниси онај који их присиљава на веровање!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'А онога који се окрене и не верује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'њега ће Аллах да казни највећом патњом.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'Нама ће, заиста, сви да се врате.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'А затим ћемо Ми, њихова дела да обрачунамо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'Тако ми зоре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'и десет ноћи', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'и парног и непарног,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'и ноћи када настаје,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'зар то паметном заклетва није?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Зар не знаш шта је твој Господар урадио са народом Ад,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'са становницима Ирема, пуног палата на ступовима', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'којима није било равних ни у једној земљи;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'и са Семудом, који су клесали стене у долини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'а и са фараоном, који је имао војску,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'који су на Земљи били охоли,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'и смутње на њој умножили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'па је твој Господар бич патње на њих спустио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'а твој Господар, заиста, све надгледа.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'А човек, када га његов Господар искуша па му почаст укаже и благодатима га обаспе, каже: „Мој Господар ме је почаствовао!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'А кад га искуша и његову опскрбу учини оскудном, онда каже: „Мој Господар ме је понизио!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'А није тако! Ви пажњу сирочету не указујете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'и да се нахрани сиромах – један другога не подстичете,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'и наследство похлепно једете', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'и богатство претерано волите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'Уистину, када Земља буде здробљена у комадиће,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'и када дође твој Господар, а анђели буду све ред до реда,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'и када тај дан Пакао буде примакнут, тада ће човек да се сети - а на шта му је сећање?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'И рећи ће: „Камо среће да сам се за овај живот припремио!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'А тог Дана нико неће као Он кажњавати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'и нико неће као Он у окове окивати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, 'А ти, о душо смирена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'врати се Господару своме задовољна, а и Он тобом задовољан', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'па уђи и буди међу Мојим слугама', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'и уђи у Мој Рај!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Кунем се градом овим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'а ти си у овом граду ослобођен ограничења,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'и родитељем и оним кога је родио.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Човека смо створили да се труди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Мисли ли он да му нико ништа не може?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'Он говори: „Утрошио сам огромно богатство!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Зар мисли да га нико није видео?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Зар му нисмо дали два ока', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'и језик и две усне,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'и добро и зло му објаснили?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Па зашто он није на благодатима захвалан био?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'А шта ти мислиш: како се на благодатима захвалан може бити?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'Роба ропства ослободити,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'или, у време глади нахранити', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'сироче блиског рода,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'или јадног сиромаха.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'А потом да је био од оних који верују, који једни другима препоручују стрпљивост и који једни другима препоручују милосрђе;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'они ће да буду срећници!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'А они који не верују у Наше речи и доказе, они ће да буду несретни.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'изнад њих ће да буде затворена ватра.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'Тако ми Сунца и његовог светла!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'и Месеца када га прати,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'и дана када га видљивим учини,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'и ноћи када га заклони,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'и неба и Онога Који га сазда,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'и Земље и Онога Који је распростре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'и душе и Онога Који је исправном створи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'па је надахнуо да разликује грехе од богобојазности;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'успео је онај ко је греха очисти,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'а изгубио је онај ко је запостави!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'Народ Семуд је због своје охолости порицао:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 12, 'Кад се један несрећник између њих подигао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 13, 'Па им је Аллахов посланик довикнуо: „Пазите на Аллахову камилу и њен ред појења!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 14, 'Али су га у лаж утерали, и камилу заклали - и њихов Господар их је, због њихових греха уништио и казном све обухватио', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 15, 'не бојећи се последице тога.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 1, 'Тако ми ноћи када све прекрије,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 2, 'и дана кад сване,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 3, 'мушко и женско које створи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 4, 'ваш труд је, заиста, различит.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 5, 'Па ономе који удељује и богобојазан је', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 6, 'и оно најлепше сматра истинитим,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 7, 'oлакшаћемо му чињење добрих дела;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 8, 'а ономе који тврдичи и осећа се независним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 9, 'и оно најлепше сматра лажним,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 10, 'oлакшаћемо му чињење греха;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'и његово богатство, кад се стровали, неће да му користи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Ми смо дужни да укажемо на Прави пут', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'и једино Нама припада и Будући и овај свет.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'Зато вас упозоравам на разбукталу ватру', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'у коју ће да уђе само највећи несрећник,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 16, 'онај који буде порицао и окретао се,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 17, 'а од ње ће да буде одстрањен богобојазни,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 18, 'онај који иметак свој удељује, да би се греха очистио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 19, 'не очекујући да му се узврати захвалношћу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 20, 'Већ једино жудећи за Лицем Господара свога Свевишњег,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 21, 'и он ће, заиста, да буде задовољан!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 1, 'Тако ми јутра', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 2, 'и ноћи кад се утиша,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 3, 'твој Господар није те ни напустио ни омрзнуо!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 4, 'Будући свет је, заиста, бољи за тебе од овог света,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 5, 'а твој Господар ће ти сигурно подарити, па ћеш задовољан бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 6, 'Зар ниси био сироче, па ти је Он уточиште пружио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 7, 'и залутао си био, па те је упутио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 8, 'и сиромах си био, па те је богатим учинио?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 9, 'Зато, сироче не уцвили,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 10, 'и онога ко тражи не одбиј,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 11, 'и о благодати свога Господара казуј!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 1, 'Зар твоје груди нисмо учинили пространим', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 2, 'и твоје бреме скинули,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 3, 'које је твоја плећа притискало,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 4, 'и спомен на тебе високо уздигли!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 5, 'Па, заиста, са муком је олакшање,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 6, 'заиста, са муком је олакшање!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 7, 'А кад завршиш, предај се молитви,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 8, 'и тежи своме Господару!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 1, 'Тако ми смокве и маслине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 2, 'и Синајске горе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 3, 'и града овог сигурног,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 4, 'Ми човека стварамо у најлепшем облику,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 5, 'затим ћемо да га вратимо у најниже низине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 6, 'само не оне који буду веровали и радили добра дела, њима припада непрекидна награда.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 7, 'Па, шта те онда наводи да поричеш Судњи дан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 8, 'Зар Аллах није судија најправеднији?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 1, 'Читај са именом твога Господара Који ствара,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 2, 'ствара човека од заквачка.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 3, 'Читај, племенит је твој Господар,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 4, 'Који подучава перу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 5, 'Који човека подучава ономе што не зна.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 6, 'Уистину, човек се узохоли', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 7, 'чим се независним осети,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 8, 'а твоме Господару ће сви, заиста, да се врате!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 9, 'Реци ми о оном који спречава', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 10, 'слугу док молитву обавља.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 11, 'Реци ми ако он мисли да је на Правом путу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 12, 'или мисли да богобојазност наређује?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 13, 'Шта мислиш, ако он пориче и окреће се,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 14, 'зар он не зна да Аллах све види?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 15, 'Напротив! Ако се не окани, оцрнићемо му чело,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 16, 'чело лажно и грешно,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 17, 'па нека он позове своје друштво.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 18, 'Ми ћемо да позовемо анђеле Пакла.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 19, 'Напротив! Ти му се не покоравај, већ падај ничице и приближи се своме Господару!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 1, 'Ми смо га објавили у Ноћ одредбе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 2, 'а шта ти мислиш шта је Ноћ одредбе?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 3, 'Ноћ одредбе боља је од хиљаду месеци;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 4, 'анђели и анђео Гаврило, сa дозволом свога Господара, се спуштају у њој због одлуке сваке.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 5, 'Мир је у њој све док зора не сване.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Нису се неверници између следбеника Књиге и незнанобожаца одвојили, све док им није дошао јасни доказ:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, 'Посланик од Аллаха који учи чисте листове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 3, 'у којима су исправни прописи.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'А подвојили су се они којима је дата Књига баш онда кад им је дошао јасни доказ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'а наређено им је да само Аллаха обожавају, да Му искрено, као правоверни, веру исповедају, и да обављају молитву, и да обавезну милостињу удељују; а то је исправна вера.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Они следбеници Књиге који не верују и незнанобошци, биће, сигурно, у ватри Пакла, у њој ће вечно да остану: они су најгора створења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'А они који верују и чине добра дела - они су, заиста, најбоља створења.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Награда за њих од Њиховог Господара су вртови Едена кроз које теку реке, у којима ће вечно, заувек да бораве; Аллах ће да буде задовољан њима, а и они ће да буду задовољни Њиме. То ће да буде за онога који се буде бојао свога Господара.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Кад се Земља најжешћим потресом својим затресе,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 2, 'и када Земља избаци своје терете', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 3, 'и човек узвикне: „Шта јој је?“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 4, 'Тог дана ће она своје вести да казује,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 5, 'јер ће твој Господар да јој нареди.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 6, 'Тог дана људи ће се раздвојени појавити да им се покажу њихова дела:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 7, 'Онај ко буде урадио колико трун добра - видеће га,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 8, 'а онај ко буде урадио и колико трун зла - видеће га.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 1, 'Тако ми оних који дахћући јуре,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 2, 'па варнице севају', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 3, 'и зором нападају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 4, 'и ту дижу прашину', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 5, 'па ту сви заједно у средину продиру,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 6, 'човек је, заиста, своме Господару незахвалан,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 7, 'и сам је он, заиста, томе сведок,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 8, 'и он је, заиста, у љубави према овосветским добрима безобзиран.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 9, 'А зар он не зна да ће, када гробови буду преврнути сa оним што је у њима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 10, 'и када изађе на видело оно што је у срцима,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 11, 'њихов Господар ће тог Дана, сигурно, све о њима да зна?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 1, 'Застрашујући Удар!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 2, 'Шта је застрашујући Удар?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 3, 'И шта ти знаш шта је застрашујући Удар?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 4, 'Тог Дана људи ће да буду као раштркани лептири,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 5, 'а планине као шарена вуна ишчупана.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 6, 'Онај чија добра дела буду тешка,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 7, 'у угодном животу ће да живи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 8, 'а онај чија добра дела буду лака,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 9, 'боравиште ће му бездан бити.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 10, 'А знаш ли ти шта ће то да буде?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 11, 'Ужарена Ватра!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 1, 'Заокупља вас настојање да што имућнији будете', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 2, 'све док гробове не населите.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 3, 'А не треба тако, сазнаћете свакако!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 4, 'И још једном, не треба тако! Сазнаћете сигурно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 5, 'Не ваља тако, кад бисте ви знали поуздано,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 6, 'Пакао ћете, заиста, да видите!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 7, 'И још једном, заиста ћете да га видите сасвим јасно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 8, 'Затим ћете тог Дана о благодатима да будете питани сигурно!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 1, 'Тако ми времена,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 2, 'заиста је човек на губитку,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 3, 'само нису они који верују и раде добра дела, и који једни другима препоручују истину и који једни другима препоручују стрпљење.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 1, 'Тешко сваком клеветнику подругљивцу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 2, 'који гомила благо и пребројава га,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 3, 'и мисли да ће његово благо да га учини бесмртним.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 4, 'Напротив! Он ће сигурно да буде бачен у Хутаму!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 5, 'А знаш ли ти шта је Хутама?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 6, 'Аллахова разбуктала Ватра,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 7, 'која ће да допире до срца.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 8, 'Она ће над њима да буде затворена', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 9, 'пламеним издуженим стубовима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 1, 'Зар ниси чуо шта је урадио твој Господар сa власницима слона?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 2, 'Зар није упропастио њихово лукавство', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 3, 'и послао на њих јата птица,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 4, 'које су на њих бацале грумење од печене глине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 5, 'па их учинио као поједено лишће?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 1, 'Због навике Курејшија,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 2, 'њихове навике да зими и лети путују,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 3, 'нека они Господара ове Куће обожавају,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 4, 'Који их гладне храни и од страха брани.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 1, 'Знаш ли ти онога који пориче Судњи дан?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 2, 'Па то је онај који грубо одбија сироче,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 3, 'и који да се нахрани сиромах - не подстиче.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 4, 'Па тешко онима који обављају молитву,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 5, 'онима који су немарни према својој молитви,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 6, 'који се само приказују људима.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 7, 'И најмању помоћ ускраћују!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 1, 'Ми смо ти, уистину, дали Кевсер,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 2, 'зато свога Господара обожавај, и жртвеницу приноси.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 3, 'Онај који тебе Мухаммеде мрзи - сигурно ће он без спомена остати.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 1, 'Реци: „О ви неверници,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 2, 'ја не обожавам оно што ви обожавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 3, 'нити ви обожавате Онога Кога ја обожавам,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 4, 'нити ја обожавам оно што ви обожавате,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 5, 'нити ви обожавате Онога Кога ја обожавам,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 6, 'вама ваша вера, а мени моја.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 1, 'Када Аллахова помоћ и победа дођу,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 2, 'и видиш људе како у скупинама улазе у Аллахову веру,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 3, 'ти слави и величај свога Господара хвалећи Га и моли Га да ти опрости, Он заиста стално прима покајање.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 1, 'Нека пропадну руке Ебу Лехебове, и пропао је!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 2, 'Неће да му буде од користи његово богатство, а ни оно што је стекао,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 3, 'ући ће он сигурно у распламсалу ватру,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 4, 'и његова жена што носи гране;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 5, 'око њеног врата биће уже од усукане личине.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 1, 'Реци: „Он је Аллах - Један!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 2, 'Аллах је Уточиште сваком.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 3, 'Није родио и рођен није,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 4, 'и нико Му раван није!“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 1, 'Реци: „Тражим уточиште код Господара свитања,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 2, 'од зла онога што је Он стварио,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 3, 'и од зла мркле ноћи кад разастре тмине,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 4, 'и од зла оних које дувају у чворове,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 5, 'и од зла завидника кад завиди.“', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 1, 'Реци: „Тражим уточиште код Господара људи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'Владара људи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'Бога људи,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'од зла оног који уноси зле мисли па се сакрије,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'који зле мисли уноси у срца људи;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'од духова и људи.“', '');
